// Dias entre hoje e uma data ISO (negativo = venceu ha N dias).
const diasAte = iso => {
  if (!iso) return null;
  const alvo = new Date(iso + "T00:00:00");
  if (isNaN(alvo)) return null;
  const hoje = new Date(); hoje.setHours(0, 0, 0, 0);
  return Math.round((alvo - hoje) / 86400000);
};

