// 
// Dashboard
// 

// 
// HELPERS FINANCEIROS
// 

// Reconstrói a obra de lotação do funcionário em qualquer data usando o
// histórico de transferências. Registros de ponto novos têm prioridade porque
// podem representar empréstimo temporário sem alteração do cadastro principal.
const getEmployeeObraIdOnDate = (data, employee, dateIso) => {
  if (!employee) return "";

  // Empréstimos e ajustes pontuais ficam gravados no próprio ponto e têm
  // prioridade sobre a lotação cadastral e sobre o histórico de transferências.
  const attendanceObra = getAtt(data, employee.id, dateIso)?.obraId || "";
  if (attendanceObra) return attendanceObra;

  const transfers = (data.changeLog || [])
    .filter(t => t.type === "transfer" && t.empId === employee.id && t.date)
    .sort((a, b) => b.date.localeCompare(a.date));

  let obraId = employee.obra || employee.lastObra || "";

  for (const t of transfers) {
    if (t.date > dateIso) {
      if (t.fromId) {
        obraId = t.fromId;
      } else {
        const found = (data.obras || []).find(o => o.name === t.from);
        if (found) obraId = found.id;
      }
    } else {
      break;
    }
  }

  return obraId;
};

//  Cache de cálculos pesados 
// calcObraLaborCost é chamada dezenas de vezes por render com os mesmos
// argumentos (DRE, Relatórios, Dashboard, Financeiro). O cache evita
// recalcular o mesmo período/obra repetidamente. É invalidado sempre que
// o objeto `data` muda de referência (imutabilidade garante correção).
let _laborCacheData = null;
let _laborCache = new Map();

const calcObraLaborCost = (data, obraId, days) => {
  // Invalida o cache quando `data` muda (nova referência de objeto)
  if (_laborCacheData !== data) {
    _laborCacheData = data;
    _laborCache = new Map();
  }
  const key = `${obraId}|${days[0]||""}|${days[days.length-1]||""}|${days.length}`;
  const hit = _laborCache.get(key);
  if (hit) return hit;

  const result = _calcObraLaborCostRaw(data, obraId, days);
  _laborCache.set(key, result);
  return result;
};

const _calcObraLaborCostRaw = (data, obraId, days) => {
  const year = days[0] ? Number(days[0].slice(0,4)) : new Date().getFullYear();
  const holidays = getPayrollHolidays(data, year);
  const holidaysInPeriod = days.filter(d => holidays.includes(d) && prIsWeekdayIso(d));
  let laborCost = 0, benefitCost = 0;

  // A obra de um dia trabalhado vem do PRÓPRIO PONTO. Registros antigos, de
  // antes desta mudança, não têm obraId - para eles caímos na obra de lotação,
  // que era o comportamento anterior. Assim o histórico não muda de valor.
  const obraDoDia = (e, d) => {
    const reg = data.attendance?.[e.id]?.[d];
    return reg?.obraId || getEmployeeObraIdOnDate(data, e, d);
  };

  data.employees.forEach(e => {
    // Não filtramos mais pelo cadastro: um funcionário pode ter trabalhado
    // nesta obra em alguns dias mesmo estando lotado em outra.
    days.forEach(d => {
      if (obraDoDia(e, d) !== obraId) return;
      if (!isEmployeeEmployedOnDate(e, d)) return;
      if (holidaysInPeriod.includes(d)) return;
      const st = attStatus(data, e.id, d);
      if (st === "P") { laborCost += Number(e.dailyRate||0); benefitCost += Number(e.vtDaily||0)+Number(e.vrDaily||0); }
      else if (st === "M") { laborCost += Number(e.dailyRate||0)*.5; benefitCost += (Number(e.vtDaily||0)+Number(e.vrDaily||0))*.5; }
    });
    // Feriado segue a MESMA regra: a obra do dia, não o cadastro. Deixar o
    // feriado amarrado à lotação faria o DSR cair numa obra e os dias
    // trabalhados em outra.
    holidaysInPeriod.forEach(h => {
      if (!isEmployeeEmployedOnDate(e, h)) return;
      if (obraDoDia(e, h) !== obraId) return;
      laborCost += Number(getHolidayPayRule(data, e, h, holidays).amount||0);
    });
  });
  return { laborCost, benefitCost, totalCost: laborCost + benefitCost };
};

const calcObraRevenue = (obra, laborCost) => {
  const ct = obra.contractType || "fixed_labor";
  const cv = Number(obra.contractValue||0);
  const ap = Number(obra.adminPercentage||0)/100;
  let revenue = 0;
  if (ct === "fixed_labor")       revenue = cv;
  else if (ct === "fixed_labor_admin") revenue = cv + laborCost * ap;
  else if (ct === "admin_only")   revenue = laborCost * ap;
  const margin = revenue - laborCost;
  const marginPct = revenue > 0 ? (margin/revenue)*100 : 0;
  const commitment = cv > 0 ? (laborCost/cv)*100 : null;
  return { revenue, margin, marginPct, commitment };
};

// 
// DASHBOARD - redesenhado
// 

function Dashboard({ data, onTab, ultimaSync, currentUser }) {
  const { cols } = useBreakpoint();
  const now = new Date();
  // Período analisado - interativo. Começa no mês corrente; o usuário navega.
  const [periodo, setPeriodo] = useState({ y: now.getFullYear(), m: now.getMonth() });
  const year = periodo.y;
  const month = periodo.m;
  const ehMesCorrente = year === now.getFullYear() && month === now.getMonth();
  const passoMes = (delta) => setPeriodo(p => {
    const d = new Date(p.y, p.m + delta, 1);
    // não deixa navegar para o futuro além do mês corrente
    if (d.getFullYear() > now.getFullYear() || (d.getFullYear() === now.getFullYear() && d.getMonth() > now.getMonth())) return p;
    return { y: d.getFullYear(), m: d.getMonth() };
  });
  const day = now.getDate();
  const { q1, q2 } = getQ(now.getFullYear(), now.getMonth());
  const refAnterior = new Date(now.getFullYear(), now.getMonth()-1, 1);
  const qDays = day <= 5 ? getQ(refAnterior.getFullYear(),refAnterior.getMonth()).q2 : day <= 20 ? q1 : q2;
  const todayIso = today();
  const activeEmps = data.employees.filter(e => e.active !== false);
  const activeObras = data.obras.filter(o => o.status !== "done");

  const presentes = activeEmps.filter(e => attStatus(data, e.id, todayIso) === "P").length;
  const faltas    = activeEmps.filter(e => attStatus(data, e.id, todayIso) === "F").length;
  const meiodia   = activeEmps.filter(e => attStatus(data, e.id, todayIso) === "M").length;
  const semReg    = Math.max(0, activeEmps.length - presentes - faltas - meiodia);
  const checkPending  = activeEmps.length > 0 && data.dailyCheckDate !== todayIso;
  const todayCompletion = activeEmps.length
    ? Math.round(((presentes+faltas+meiodia)/activeEmps.length)*100) : 0;

  const qTotal = activeEmps.reduce((sum,e) => sum + qDays.reduce((s,d) => {
    const st = attStatus(data,e.id,d);
    if(st==="P") return s+Number(e.dailyRate||0);
    if(st==="M") return s+Number(e.dailyRate||0)*.5;
    return s;
  },0), 0);

  // DRE do mês - memoizado
  const dre = useMemo(() => calcDREConsolidado(data, year, month), [data, year, month]);
  const exec = useMemo(() => calcResumoExecutivo(data, year, month), [data, year, month]);
  const alertas = useMemo(() => calcAlertas(data, year, month), [data, year, month]);

  // Alertas - memoizados (buildQuickAlerts percorre todas as obras/medições)
  const quickAlerts = useMemo(() => buildQuickAlerts(data, currentUser), [data, currentUser]);
  const alertMsg    = useMemo(() => buildAlertMessage(data), [data]);

  const last7 = [];
  for(let i=6;i>=0;i--){
    const dt=new Date(); dt.setDate(dt.getDate()-i);
    const iso=toLocalISODate(dt);
    last7.push({
      d: fmtDate(iso),
      P: activeEmps.filter(e=>attStatus(data,e.id,iso)==="P").length,
      M: activeEmps.filter(e=>attStatus(data,e.id,iso)==="M").length,
      F: activeEmps.filter(e=>attStatus(data,e.id,iso)==="F").length,
    });
  }

  const pieData = [
    {name:"Presente",    value:presentes, color:C.green},
    {name:"Meio dia",    value:meiodia,   color:C.yellow},
    {name:"Falta",       value:faltas,    color:C.red},
    {name:"Sem registro",value:semReg,    color:C.muted},
  ].filter(i=>i.value>0);

  const KpiCard = ({label,value,sub,color,icon,tab}) => (
    <button onClick={()=>tab&&onTab(tab)} style={{
      background:C.card,
      border:`1px solid ${C.border}`,
      padding:"12px 13px",borderRadius:8,textAlign:"left",color:C.text,
      cursor:tab?"pointer":"default",transition:"border-color .12s, background .12s",
      display:"flex",flexDirection:"column",gap:7,
    }}
    onMouseEnter={e=>{if(tab){e.currentTarget.style.borderColor=color;}}}
    onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{color:C.muted,fontSize:9.5,fontWeight:800,textTransform:"uppercase",letterSpacing:.6}}>{label}</span>
        <Ic n={icon} s={13} color={color}/>
      </div>
      <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,color:C.text,fontSize:22,letterSpacing:-.3,lineHeight:1}}>{value}</p>
      {sub&&<p style={{color:C.muted,fontSize:10,marginTop:-1}}>{sub}</p>}
      {/* traço fino de acento na base, no lugar da borda-topo grossa */}
      <div style={{height:2,background:color,borderRadius:99,opacity:.85,marginTop:1}}/>
    </button>
  );

  return (
    <div className="anim" style={{display:"flex",flexDirection:"column",gap:16}}>

      {/* Barra de comando: minimalista e técnica. Saudação curta, período
          analisado (interativo) e o pulso do dia. Sem banner decorativo. */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        <div style={{minWidth:0}}>
          <h2 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(18px,3.5vw,23px)",color:C.text,letterSpacing:-.3,lineHeight:1.1}}>
            Central de operações
          </h2>
          <p style={{fontSize:11,color:C.muted,marginTop:2}}>
            {ultimaSync
              ? `Atualizado ${ultimaSync.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}`
              : "Painel executivo"} · {activeObras.length} obra(s) ativa(s)
          </p>
        </div>
        {/* Seletor de período: navega meses. Recalcula todos os indicadores. */}
        <div style={{display:"flex",alignItems:"center",gap:2,border:`1px solid ${C.border}`,borderRadius:8,background:C.card,padding:2,flexShrink:0}}>
          <button onClick={()=>passoMes(-1)} title="Mês anterior"
            style={{border:0,background:"transparent",color:C.muted,cursor:"pointer",padding:"5px 8px",borderRadius:6,fontSize:13,lineHeight:1}}>←</button>
          <span style={{fontSize:11.5,fontWeight:700,color:C.text,minWidth:96,textAlign:"center"}}>{fullMonth(month)} {year}</span>
          <button onClick={()=>passoMes(1)} disabled={ehMesCorrente} title="Próximo mês"
            style={{border:0,background:"transparent",color:ehMesCorrente?C.line:C.muted,cursor:ehMesCorrente?"default":"pointer",padding:"5px 8px",borderRadius:6,fontSize:13,lineHeight:1}}>→</button>
        </div>
      </div>

      {/* Pulso do dia: barra fina de progresso do ponto, clicável. */}
      <button onClick={()=>onTab("ponto")} style={{border:`1px solid ${C.border}`,background:C.card,borderRadius:8,padding:"10px 12px",cursor:"pointer",textAlign:"left",display:"flex",alignItems:"center",gap:12}}>
        <div style={{flex:1,minWidth:0}}>
          <div style={{display:"flex",justifyContent:"space-between",marginBottom:5}}>
            <span style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:"uppercase",letterSpacing:.6}}>Ponto de hoje</span>
            <span style={{fontSize:11,fontWeight:800,color:todayCompletion===100?C.green:C.yellowD}}>{todayCompletion}% · {presentes}/{activeEmps.length}</span>
          </div>
          <div style={{height:5,background:C.surface,borderRadius:99,overflow:"hidden"}}>
            <div style={{height:"100%",width:`${todayCompletion}%`,background:todayCompletion===100?C.green:C.yellow,borderRadius:99,transition:"width .4s ease"}}/>
          </div>
        </div>
        <span style={{fontSize:16,color:C.muted}}>→</span>
      </button>


      {checkPending && (
        <button onClick={()=>onTab("ponto")} className="lift-card" style={{
          background:`${C.yellow}12`,border:`1px solid ${C.yellow}`,borderLeft:`5px solid ${C.yellow}`,
          color:C.yellow,borderRadius:10,padding:"12px 14px",cursor:"pointer",textAlign:"left",
        }}>
          <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontSize:16,fontWeight:900,textTransform:"uppercase"}}> Verificação diária pendente</p>
          <p style={{color:C.subtle,fontSize:12,marginTop:2}}>Confirme ou movimente a equipe antes de lançar o ponto.</p>
        </button>
      )}

      {/* Central de alertas: as decisões pendentes de hoje, por severidade.
          Transforma o dashboard de painel de números em lista de ações. */}
      {alertas.length > 0 && (
        <div style={{ border:`1px solid ${C.border}`, borderRadius:8, background:C.card, overflow:"hidden" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"9px 12px", borderBottom:`1px solid ${C.line}` }}>
            <span style={{ fontSize:10, fontWeight:800, color:C.muted, textTransform:"uppercase", letterSpacing:.6 }}>Precisa de atenção hoje</span>
            <span style={{ fontSize:10.5, fontWeight:800, color: alertas.some(a=>a.sev===3)?C.red:C.orange }}>{alertas.length}</span>
          </div>
          <div style={{ maxHeight:220, overflowY:"auto" }}>
            {alertas.slice(0,10).map((a,i) => {
              const cor = a.sev===3?C.red : a.sev===2?C.orange : C.muted;
              return (
                <button key={i} onClick={()=>onTab(a.tab)} style={{
                  display:"flex", alignItems:"center", gap:9, width:"100%", textAlign:"left",
                  background:"transparent", border:0, borderTop: i? `1px solid ${C.line}`:"none",
                  borderLeft:`3px solid ${cor}`, padding:"9px 12px", cursor:"pointer" }}>
                  <span style={{ width:6, height:6, borderRadius:99, background:cor, flexShrink:0 }}/>
                  <span style={{ fontSize:12, color:C.text, flex:1, minWidth:0 }}>{a.texto}</span>
                  <span style={{ fontSize:14, color:C.muted }}>›</span>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Indicadores de leitura rápida: responde "como está a empresa" em 1 olhada.
          Só números reais do app. Cada card leva ao aprofundamento. */}
      <div>
        <p style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:"uppercase",letterSpacing:1,marginBottom:8}}>Visão executiva - {fullMonth(month)} {year}</p>
        <div style={{display:"grid",gridTemplateColumns:cols(2,3,4),gap:8}}>
          <KpiCard label="Obras ativas" value={exec.obrasAtivas}
            sub={exec.obrasCriticas>0?`${exec.obrasCriticas} crítica(s)`:exec.obrasAtencao>0?`${exec.obrasAtencao} em atenção`:"todas saudáveis"}
            color={exec.obrasCriticas>0?C.red:exec.obrasAtencao>0?C.orange:C.green} icon="building" tab="obras"/>
          <KpiCard label="Carteira contratada" value={fmtCompact(exec.contratoTotalCarteira)}
            sub={`backlog ${fmtCompact(exec.dre.backlog)}`} color={C.blue} icon="fileText" tab="obras"/>
          <KpiCard label="Recebido no mês" value={fmtCompact(exec.dre.recebido)}
            sub={`faturado ${fmtCompact(exec.dre.faturamento)}`} color={C.green} icon="wallet" tab="dre"/>
          <KpiCard label="Custo no mês" value={fmtCompact(exec.dre.totalCustos)}
            sub={`resultado ${fmtCompact(exec.dre.lucroBruto)}`} color={exec.dre.lucroBruto>=0?C.purple:C.red} icon="receipt" tab="dre"/>
          <KpiCard label="Margem consolidada" value={`${exec.dre.margemBruta.toFixed(1)}%`}
            sub={exec.dre.margemBruta>=20?"saudável":exec.dre.margemBruta>=10?"atenção":"baixa"}
            color={exec.dre.margemBruta>=20?C.green:exec.dre.margemBruta>=10?C.orange:C.red} icon="trending" tab="dre"/>
          <KpiCard label="Saldo de caixa (mês)" value={fmtCompact(exec.dre.saldoCaixa)}
            sub="recebido − custos" color={exec.dre.saldoCaixa>=0?C.green:C.red} icon="dollar" tab="dre"/>
          <KpiCard label="Pipeline comercial" value={fmtCompact(exec.pipeline)}
            sub={`ponderado ${fmtCompact(exec.pipelinePonderado)}`} color={C.green} icon="funnel" tab="com_funil"/>
          <KpiCard label="Compras pendentes" value={exec.comprasPendentes}
            sub={`${exec.solicitacoesAbertas} solicitação(ões)`} color={exec.comprasPendentes>0?C.orange:C.muted} icon="cart" tab="cmp"/>
        </div>
      </div>

      {/* Resumo das obras: um card por obra com semáforo físico×financeiro. É o
          coração do "por exceção" - a cor diz onde olhar primeiro. */}
      {exec.obras.length>0 && (
        <div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"baseline",marginBottom:8}}>
            <p style={{fontSize:10,fontWeight:800,color:C.muted,textTransform:"uppercase",letterSpacing:1}}>Obras</p>
            <button onClick={()=>onTab("obras")} style={{background:"transparent",border:0,color:C.blue,fontSize:10.5,fontWeight:700,cursor:"pointer"}}>ver todas →</button>
          </div>
          <div style={{display:"grid",gridTemplateColumns:cols(1,2,2),gap:8}}>
            {[...exec.obras]
              .sort((a,b)=>({critica:0,atencao:1,saudavel:2}[a.exec.k]-{critica:0,atencao:1,saudavel:2}[b.exec.k]))
              .slice(0,6).map(o=>(
              <button key={o.id} onClick={()=>onTab("obras")} className="lift-card" style={{
                background:C.card,border:`1px solid ${C.border}`,borderLeft:`3px solid ${o.exec.cor}`,
                borderRadius:8,padding:"11px 13px",textAlign:"left",cursor:"pointer",color:C.text}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8,marginBottom:8}}>
                  <div style={{minWidth:0}}>
                    <p style={{fontSize:13,fontWeight:800,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{o.nome}</p>
                    {o.cliente&&<p style={{fontSize:9.5,color:C.muted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{o.cliente}</p>}
                  </div>
                  <span style={{fontSize:8.5,fontWeight:800,color:o.exec.cor,background:`${o.exec.cor}14`,padding:"2px 7px",borderRadius:99,flexShrink:0,textTransform:"uppercase",letterSpacing:.4}}>{o.exec.l}</span>
                </div>
                {/* barras físico × financeiro */}
                <div style={{display:"flex",flexDirection:"column",gap:5}}>
                  {[["Físico",o.pctFisico,C.blue],["Financeiro",o.pctFinanceiro,C.yellowD]].map(([lb,pct,cor])=>(
                    <div key={lb}>
                      <div style={{display:"flex",justifyContent:"space-between",fontSize:8.5,color:C.muted,marginBottom:2}}>
                        <span>{lb}</span><span style={{fontWeight:700,color:cor}}>{pct}%</span>
                      </div>
                      <div style={{height:4,background:C.surface,borderRadius:99,overflow:"hidden"}}>
                        <div style={{height:"100%",width:`${Math.min(100,pct)}%`,background:cor,borderRadius:99}}/>
                      </div>
                    </div>
                  ))}
                </div>
                <div style={{display:"flex",justifyContent:"space-between",marginTop:8,fontSize:9}}>
                  <span style={{color:C.muted}}>Margem <b style={{color:o.margem>=15?C.green:o.margem>=8?C.orange:C.red}}>{o.margem.toFixed(1)}%</b></span>
                  <span style={{color:C.muted}}>Backlog <b style={{color:C.text}}>{fmtCompact(o.backlog)}</b></span>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* KPIs operacionais */}
      <div>
        <p style={{fontSize:10,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:1,marginBottom:8}}>Operacional - hoje</p>
        <div style={{display:"grid",gridTemplateColumns:cols(2,4,4),gap:8}}>
          <KpiCard label="Trabalhadores" value={activeEmps.length} sub={`${activeObras.length} obras ativas`} color={C.yellow} icon="users" tab="equipe"/>
          <KpiCard label="Presentes hoje" value={presentes} sub={`${semReg} sem registro`} color={C.green} icon="check" tab="ponto"/>
          <KpiCard label="Custo quinzena" value={fmt(qTotal)} sub={`${qDays.length} dias`} color={C.purple} icon="dollar" tab="folha"/>
          <KpiCard label="Faltas hoje" value={faltas} sub={`${meiodia} meio período`} color={faltas>0?C.red:C.muted} icon="alert" tab="ponto"/>
        </div>
      </div>

      {/* KPIs financeiros - DRE do mês */}
      <div>
        <p style={{fontSize:10,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:1,marginBottom:8}}>Financeiro - {fullMonth(month)} {year}</p>
        <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden",marginBottom:8}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)"}}>
            {[
              ["Faturamento",  dre.faturamento,  C.green,  "dre"],
              ["Recebido",     dre.recebido,     C.blue,   "dre"],
              ["Custos",       dre.totalCustos,  C.red,    "dre"],
              ["Lucro Bruto",  dre.lucroBruto,   dre.lucroBruto>=0?C.green:C.red, "dre"],
            ].map(([l,v,c,t],i)=>(
              <button key={l} onClick={()=>onTab(t)} style={{
                background:"transparent",border:0,borderRight:i%2===0?`1px solid ${C.line}`:"none",
                borderBottom:i<2?`1px solid ${C.line}`:"none",
                color:C.text,cursor:"pointer",padding:"12px 14px",textAlign:"left",
              }}>
                <p style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:.8}}>{l}</p>
                <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,color:c,fontSize:22,letterSpacing:.5,lineHeight:1.1,marginTop:3}}>{fmt(v)}</p>
              </button>
            ))}
          </div>
          {dre.faturamento>0&&(
            <div style={{padding:"8px 14px",borderTop:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <p style={{fontSize:11,color:C.muted}}>Margem bruta: <span style={{color:dre.lucroBruto>=0?C.green:C.red,fontWeight:900}}>{dre.margemBruta.toFixed(1)}%</span></p>
              <p style={{fontSize:11,color:C.muted}}>A receber: <span style={{color:dre.aReceber>0?C.orange:C.muted,fontWeight:700}}>{fmt(dre.aReceber)}</span></p>
              <button onClick={()=>onTab("dre")} style={{background:"transparent",border:`1px solid ${C.border}`,color:C.muted,padding:"3px 10px",borderRadius:6,cursor:"pointer",fontSize:10,fontWeight:700}}>Ver DRE →</button>
            </div>
          )}
        </div>
      </div>

      {/* Gráfico 7 dias */}
      <div className="lift-card" style={{background:`linear-gradient(180deg,${C.card2},${C.card})`,border:`1px solid ${C.border}`,padding:14,borderRadius:12}}>
        <h3 style={{fontFamily:"'Inter Display','Inter',sans-serif",color:C.yellow,textTransform:"uppercase",letterSpacing:1,marginBottom:8,fontSize:16}}>
          Presença - últimos 7 dias
        </h3>
        <div style={{height:200}}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={last7} barSize={18}>
              <CartesianGrid stroke={C.border} vertical={false}/>
              <XAxis dataKey="d" stroke={C.muted} fontSize={11}/>
              <YAxis stroke={C.muted} fontSize={11} allowDecimals={false}/>
              <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text,borderRadius:8}}/>
              <Bar dataKey="P" name="Presente" stackId="a" fill={C.green} radius={[6,6,0,0]}/>
              <Bar dataKey="M" name="Meio dia" stackId="a" fill={C.yellow}/>
              <Bar dataKey="F" name="Falta"    stackId="a" fill={C.red} radius={[6,6,0,0]}/>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Distribuição do dia */}
      {pieData.length > 0 && (
        <div className="lift-card" style={{background:`linear-gradient(180deg,${C.card2},${C.card})`,border:`1px solid ${C.border}`,padding:14,borderRadius:12}}>
          <h3 style={{fontFamily:"'Inter Display','Inter',sans-serif",color:C.yellow,textTransform:"uppercase",letterSpacing:1,marginBottom:8,fontSize:16}}>Distribuição de hoje</h3>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",alignItems:"center",gap:12}}>
            <div style={{height:180}}>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={pieData} dataKey="value" nameKey="name" innerRadius={40} outerRadius={68} paddingAngle={3}>
                    {pieData.map((e,i)=><Cell key={e.name} fill={e.color||CHART_COLORS[i]}/>)}
                  </Pie>
                  <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text}}/>
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div style={{display:"flex",flexDirection:"column",gap:8}}>
              {pieData.map(i=>(
                <div key={i.name} style={{display:"flex",alignItems:"center",gap:8}}>
                  <div style={{width:10,height:10,borderRadius:3,background:i.color,flexShrink:0}}/>
                  <div>
                    <p style={{fontSize:11,fontWeight:700,color:C.text}}>{i.name}</p>
                    <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:20,color:i.color,lineHeight:1}}>{i.value}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Alertas ativos */}
      {(() => {
        const alerts = quickAlerts;
        if (alerts.length === 0) return null;
        const msg = alertMsg;
        const phone = data.config.hrPhone || "";
        const waUrl = phone
          ? `https://wa.me/${phone.replace(/\D/g,"")}?text=${encodeURIComponent(msg)}`
          : `https://wa.me/?text=${encodeURIComponent(msg)}`;
        return (
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
            <div style={{padding:"10px 14px",borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.text,textTransform:"uppercase",letterSpacing:.5}}> {alerts.length} alerta(s) ativo(s)</p>
              <a href={waUrl} target="_blank" rel="noreferrer" style={{
                background:"#25D366",color:"#fff",border:"none",padding:"6px 12px",
                fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:12,letterSpacing:.5,
                cursor:"pointer",borderRadius:6,textDecoration:"none",display:"inline-flex",alignItems:"center",gap:5,
              }}> Enviar WhatsApp</a>
            </div>
            {alerts.map((a,i)=>(
              <div key={i} onClick={()=>a.tab&&onTab(a.tab)} style={{padding:"9px 14px",borderBottom:i<alerts.length-1?`1px solid ${C.line}`:"none",borderLeft:`4px solid ${a.color}`,display:"flex",gap:10,alignItems:"flex-start",cursor:a.tab?"pointer":"default"}}>
                <span style={{fontSize:16,flexShrink:0}}>{a.icon}</span>
                <div>
                  <p style={{fontWeight:700,fontSize:13,color:C.text}}>{a.title}</p>
                  <p style={{fontSize:11,color:C.muted,marginTop:2}}>{a.sub}</p>
                </div>
              </div>
            ))}
          </div>
        );
      })()}

      {/* Widget terceirizados - esta sexta */}
      {(() => {
        const fri = getFridayOfWeek(0);
        const { start: ws } = getWeekRange(fri);
        const activeTerc = (data.terceirizados||[]).filter(t => t.active !== false);
        const pending = activeTerc.filter(t => !(data.pagsTerceiros||[]).some(p=>p.tercId===t.id&&p.date>=ws&&p.date<=fri));
        if(activeTerc.length === 0) return null;
        return (
          <button onClick={()=>onTab("terc")} className="lift-card" style={{
            background:`${C.orange}12`, border:`1px solid ${C.orange}55`,
            borderLeft:`5px solid ${C.orange}`, padding:"12px 14px",
            borderRadius:10, textAlign:"left", color:C.text, cursor:"pointer",
          }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:900, fontSize:16, textTransform:"uppercase", color:C.orange }}>
                   Pagamentos desta sexta - {fmtDateFull(fri)}
                </p>
                {pending.length > 0 ? (
                  <p style={{ fontSize:12, color:C.subtle, marginTop:3 }}>
                    {pending.length} pendente(s)  {fmt(pending.reduce((s,t)=>s+Number(t.weeklyRate||0),0))} a pagar
                  </p>
                ) : (
                  <p style={{ fontSize:12, color:C.green, marginTop:3 }}>ok Todos os {activeTerc.length} terceirizados já foram pagos</p>
                )}
              </div>
              <div style={{ background:pending.length>0?C.orange:C.green, color:C.ink, borderRadius:999, padding:"4px 10px", fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize:18, letterSpacing:1 }}>
                {pending.length>0?pending.length:"ok"}
              </div>
            </div>
          </button>
        );
      })()}

      {/* Feed cronológico de edições: quem mexeu em quê e quando. Lê do
          changeLog, que agora recebe autor e hora a cada alteração. Mostra as
          mais recentes primeiro. */}
      {(() => {
        const log = [...(data.changeLog || [])]
          .filter(e => e && e.message)
          .sort((a,b) => {
            const ta = a.at ? new Date(a.at).getTime() : (a.date ? new Date(a.date).getTime() : 0);
            const tb = b.at ? new Date(b.at).getTime() : (b.date ? new Date(b.date).getTime() : 0);
            return tb - ta;
          })
          .slice(0, 12);
        if (!log.length) return null;
        const corAcao = t => t==="criou"||t==="created"?C.green : t==="removeu"||t==="dismissal"?C.red : t==="bulk"?C.purple : C.blue;
        const quando = e => {
          const iso = e.at || e.date;
          if (!iso) return "";
          const d = new Date(iso);
          const hoje = new Date();
          const mesmoDia = d.toDateString() === hoje.toDateString();
          const ontem = new Date(hoje); ontem.setDate(hoje.getDate()-1);
          const foiOntem = d.toDateString() === ontem.toDateString();
          const hora = e.at ? d.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}) : "";
          if (mesmoDia) return hora ? `hoje ${hora}` : "hoje";
          if (foiOntem) return hora ? `ontem ${hora}` : "ontem";
          return fmtDateFull(e.date || iso.slice(0,10)) + (hora?` ${hora}`:"");
        };
        return (
          <div style={{ background:C.card, border:`1px solid ${C.border}`, borderRadius:8, overflow:"hidden" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"10px 12px", borderBottom:`1px solid ${C.line}` }}>
              <p style={{ fontSize:11, fontWeight:800, color:C.text, textTransform:"uppercase", letterSpacing:.5 }}>Atividade recente</p>
              <span style={{ fontSize:9.5, color:C.muted }}>quem editou o quê</span>
            </div>
            <div style={{ maxHeight:280, overflowY:"auto" }}>
              {log.map(e => (
                <div key={e.id} style={{ display:"flex", gap:9, padding:"8px 12px", borderTop:`1px solid ${C.line}`, alignItems:"flex-start" }}>
                  <span style={{ width:6, height:6, borderRadius:99, background:corAcao(e.type), marginTop:5, flexShrink:0 }}/>
                  <div style={{ minWidth:0, flex:1 }}>
                    <p style={{ fontSize:11.5, color:C.text, lineHeight:1.35 }}>{e.message}</p>
                    <p style={{ fontSize:9, color:C.muted, marginTop:1 }}>{quando(e)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })()}

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Btn onClick={()=>onTab("ponto")} full><Ic n="clock"/> Registrar ponto</Btn>
        <Btn onClick={()=>onTab("dre")} v="ghost" full><Ic n="chart"/> Ver DRE</Btn>
      </div>
    </div>
  );
}

// 
// MEDIÇÕES / FATURAMENTO - por obra
// 

// 
// DRE GERENCIAL - helpers e componente
// 

const OUTRAS_CATEGORIAS = [
  { v:"material",       l:"Material / Insumos"     },
  { v:"equipamento",    l:"Equipamentos / Locação"  },
  { v:"subempreitada",  l:"Subempreitada"           },
  { v:"taxa",           l:"Taxa / Licença / Imposto"},
  { v:"overhead",       l:"Overhead / Administrativo"},
  { v:"outros",         l:"Outros"                  },
];

// Categorias efetivas: as que o operador cadastrou, ou as padrao se ainda
// nao mexeu. "Outros" fica sempre disponivel como rede de seguranca, mesmo
// que o operador apague tudo - senao uma despesa antiga ficaria sem rotulo.
const categoriasDesp = (data) => {
  const custom = (data?.categoriasDesp || []);
  if (custom.length === 0) return OUTRAS_CATEGORIAS;
  const temOutros = custom.some(c => c.v === "outros");
  return temOutros ? custom : [...custom, { v: "outros", l: "Outros" }];
};

// Rotulo de uma categoria por chave (cai na propria chave se nao achar).
const rotuloCategoria = (data, v) =>
  (categoriasDesp(data).find(c => c.v === v)?.l) || v;

// Custo de locação de equipamentos numa OBRA, no mês. É o que a obra "paga"
// para usar os equipamentos alocados a ela — a diária cobrada, líquida de
// desconto, somada por dia dentro do período. Vale tanto para equipamento
// próprio quanto de terceiro: do ponto de vista da obra, é custo de locação.
const calcEquipCustoObra = (data, obraId, ym) => {
  const [y,m] = ym.split("-").map(Number);
  const pi = `${ym}-01`;
  const pf = `${ym}-${String(new Date(y, m, 0).getDate()).padStart(2,"0")}`;
  return (data.locacoesEquip||[])
    .filter(l => l.obraId === obraId)
    .reduce((s,l) => {
      const dias = diasLocacaoNoPeriodo(l, pi, pf);
      if (!dias) return s;
      const bruto = dias * Number(l.valorDiaria||0);
      const desc  = Number(l.descontoValor||0) + bruto * Number(l.descontoPct||0)/100;
      return s + Math.max(0, bruto - desc);
    }, 0);
};

// Faturamento da EMPRESA com locação de equipamentos no mês. A empresa presta
// o serviço de locação: fatura a receita cobrada. Para equipamento próprio, o
// custo direto é só a manutenção. Para equipamento de terceiro, a empresa também
// paga o dono — então informamos receita e custo separadamente para o DRE poder
// reconhecer o líquido corretamente.
const calcEquipFaturamentoEmpresa = (data, ym) => {
  const rel = calcEquipamentosMes(data, ym);
  return {
    receita:   rel.total.receita,     // tudo que a empresa fatura de locação
    custoDono: rel.total.custoDono,   // repasse aos donos terceiros
    manut:     rel.total.manut,       // manutenção bancada pela empresa
    lucro:     rel.total.lucro,       // receita − custoDono − manut
    receitaProprios: rel.proprios.reduce((s,l)=>s+l.receita,0),
    receitaTerceiros: rel.terceiros.reduce((s,l)=>s+l.receita,0),
  };
};

const calcDREObra = (data, obraId, year, month) => {
  const ym      = `${year}-${String(month+1).padStart(2,"0")}`;
  const days    = getDays(year, month);
  const per0  = days[0] || "";
  const perF  = days[days.length - 1] || "";
  const obra    = data.obras.find(o => o.id === obraId);

  //  FATURAMENTO (emissão de medições) 
  const medDoMes   = (data.medicoes||[]).filter(m => m.obraId===obraId && m.competencia===ym);
  const faturamento = medDoMes.reduce((s,m) => s+m.valorPrevisto, 0);

  //  RECEBIMENTO (caixa) 
  const recMed   = medDoMes.filter(m=>m.recebido).reduce((s,m)=>s+m.valorRecebido, 0);
  const recLivre = (data.payments||[]).filter(p=>p.obraId===obraId&&p.date?.startsWith(ym)).reduce((s,p)=>s+Number(p.amount||0),0);
  const recebido = recMed + recLivre;
  const aReceber = faturamento - recMed;

  //  CUSTOS DIRETOS 
  const moData      = calcObraLaborCost(data, obraId, days);
  const tercCost    = calcObraTercCost(data, obraId, per0, perF);
  const rescTotal   = (data.rescisoes||[]).filter(r =>
    r.obraName===(obra?.name||"") && r.demissao?.startsWith(ym)
  ).reduce((s,r)=>s+Number(r.totalLiquido||0), 0);
  const outrasTotal = (data.outrasDesp||[]).filter(d=>d.obraId===obraId&&d.competencia===ym)
    .reduce((s,d)=>s+Number(d.valor||0), 0);
  const outrasDesp  = (data.outrasDesp||[]).filter(d=>d.obraId===obraId&&d.competencia===ym);

  // Custo de locação de equipamentos alocados a esta obra no mês.
  const equipCost   = calcEquipCustoObra(data, obraId, ym);

  const totalCustos = moData.laborCost + moData.benefitCost + tercCost + rescTotal + outrasTotal + equipCost;

  //  RESULTADO 
  const lucroBruto   = faturamento - totalCustos;
  const margemBruta  = faturamento > 0 ? (lucroBruto/faturamento)*100 : 0;
  const saldoCaixa   = recebido - totalCustos;
  const margemCaixa  = recebido > 0 ? (saldoCaixa/recebido)*100 : 0;

  //  POSIÇÃO ACUMULADA DO CONTRATO 
  const contratoTotal   = Number(obra?.contractValue||0);
  const faturadoAcum    = (data.medicoes||[]).filter(m=>m.obraId===obraId).reduce((s,m)=>s+m.valorPrevisto,0);
  const recebidoAcum    = (data.medicoes||[]).filter(m=>m.obraId===obraId&&m.recebido).reduce((s,m)=>s+m.valorRecebido,0)
    + (data.payments||[]).filter(p=>p.obraId===obraId).reduce((s,p)=>s+Number(p.amount||0),0);
  const aReceberAcum    = Math.max(0, faturadoAcum - recebidoAcum);
  const backlog         = Math.max(0, contratoTotal - faturadoAcum);
  const pctFaturado     = contratoTotal>0 ? (faturadoAcum/contratoTotal)*100 : 0;
  const pctRecebido     = contratoTotal>0 ? (recebidoAcum/contratoTotal)*100 : 0;
  const pctAvanco       = (() => {
    const meds = (data.medicoes||[]).filter(m=>m.obraId===obraId&&m.tipo==="percentual");
    return meds.length ? Math.max(...meds.map(m=>m.percentualAcumulado)) : 0;
  })();

  return {
    obra, ym,
    // Faturamento
    faturamento, recebido, aReceber, medDoMes,
    // Custos
    moData, tercCost, rescTotal, outrasTotal, outrasDesp, equipCost, totalCustos,
    // Resultado
    lucroBruto, margemBruta, saldoCaixa, margemCaixa,
    // Posição
    contratoTotal, faturadoAcum, recebidoAcum, aReceberAcum, backlog, pctFaturado, pctRecebido, pctAvanco,
  };
};

// Calcula DRE consolidado (todas as obras)
const calcDREConsolidado = (data, year, month) => {
  const days = getDays(year, month);
  const per0 = days[0] || "", perF = days[days.length-1] || "";
  const rows = data.obras.map(o => calcDREObra(data, o.id, year, month));
  const sum  = (key, sub) => rows.reduce((s,r) => s+(sub ? r[sub][key]||0 : r[key]||0), 0);
  // Terceiros bancados pela empresa: não estão em nenhuma obra, entram aqui.
  const tercEmpresa = calcTercEmpresaCost(data, per0, perF);
  const ym = `${year}-${String(month+1).padStart(2,"0")}`;

  // LOCAÇÃO DE EQUIPAMENTOS - a empresa presta o serviço de locação.
  // Contabilidade do consolidado (evita dupla contagem):
  //  - O custo que cada OBRA registra pela locação (equipCost) é, do ponto de
  //    vista do GRUPO, uma transferência interna: a obra paga, a empresa recebe.
  //    No consolidado essas duas pernas se anulam.
  //  - O que sobra de verdade para o grupo é o LUCRO da atividade de locação:
  //    receita cobrada − repasse aos donos terceiros − manutenção da empresa.
  //    Para equipamento próprio, é a receita menos manutenção; para o de
  //    terceiro, é só o spread. Reconhecemos isso como faturamento líquido.
  const equipEmpresa   = calcEquipFaturamentoEmpresa(data, ym);
  const equipCostObras = sum("equipCost");   // custo interno somado nas obras
  const equipLucro     = equipEmpresa.lucro; // resultado real da locação

  // Custos consolidados: soma os custos das obras, MENOS o custo interno de
  // locação (que se anula com a receita interna), mais os terceiros da empresa.
  const totalCustos = sum("totalCustos") - equipCostObras + tercEmpresa;
  // Faturamento: o das obras, mais o LUCRO líquido da atividade de locação
  // (a receita bruta de locação contra as obras é interna e não infla o grupo).
  const faturamento = sum("faturamento") + equipLucro;
  const recebido    = sum("recebido");
  const lucroBruto  = faturamento - totalCustos;
  const saldoCaixa  = recebido - totalCustos;
  return {
    obras: rows,
    faturamento,
    recebido,
    aReceber:     sum("aReceber"),
    laborCost:    sum("laborCost","moData"),
    benefitCost:  sum("benefitCost","moData"),
    tercCost:     sum("tercCost"),
    tercEmpresa,
    rescTotal:    sum("rescTotal"),
    outrasTotal:  sum("outrasTotal"),
    equipCostObras,                          // custo de locação nas obras (interno)
    equipReceita: equipEmpresa.receita,      // receita bruta de locação
    equipLucro,                              // resultado líquido da locação (entra no faturamento)
    totalCustos,
    lucroBruto,
    saldoCaixa,
    faturadoAcum: sum("faturadoAcum"),
    recebidoAcum: sum("recebidoAcum"),
    backlog:      sum("backlog"),
    margemBruta:  faturamento>0 ? (lucroBruto/faturamento)*100 : 0,
    margemCaixa:  recebido>0    ? (saldoCaixa/recebido)*100    : 0,
  };
};

// Série histórica para gráficos (últimos N meses)
const calcDREHistorico = (data, year, month, nMeses=6) => {
  return Array.from({length:nMeses},(_,i)=>{
    const d = new Date(year, month-nMeses+1+i, 1);
    const y = d.getFullYear(), m = d.getMonth();
    const c = calcDREConsolidado(data, y, m);
    return { mes:`${monthName(m)}/${String(y).slice(2)}`, ...c, y, m };
  });
};

// RESUMO EXECUTIVO - agrega, só com dados reais do app, o retrato da empresa
// para o painel do dashboard. Cada obra ganha um status calculado (saudável /
// atenção / crítica) a partir do desvio entre avanço físico e financeiro e da
// margem. Nada aqui é inventado: se o dado não existe, o campo fica zero e a
// UI simplesmente não mostra.
const statusObraExec = (o) => {
  // Regra por exceção: crítico se margem negativa OU desembolso muito à frente
  // da execução; atenção se margem baixa ou pequeno descolamento; senão saudável.
  const desalinho = o.pctFinanceiro - o.pctFisico;   // + = gastando/faturando à frente do que executa
  if (o.margem < 0 || desalinho > 20) return { k:"critica",  l:"Crítica",  cor:C.red };
  if (o.margem < 10 || desalinho > 10) return { k:"atencao",  l:"Atenção",  cor:C.orange };
  return { k:"saudavel", l:"Saudável", cor:C.green };
};

// CENTRAL DE ALERTAS - agrega as decisões pendentes de hoje, por severidade.
// Só usa dado que existe. Cada alerta sabe para onde levar (tab), então o
// dashboard vira uma lista de ações, não só de números.
const calcAlertas = (data, year, month) => {
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const A = [];
  const push = (sev, texto, tab, obraId="") => A.push({ sev, texto, tab, obraId });
  // sev: 3=crítico, 2=alto, 1=médio

  // Obras estourando custo (margem negativa).
  (data.obras||[]).forEach(o => {
    const d = calcDREObra(data, o.id, year, month);
    if (d.margemBruta < 0 && d.faturadoAcum > 0)
      push(3, `${o.name}: margem negativa (${d.margemBruta.toFixed(0)}%)`, "dre", o.id);
  });

  // Pedidos de compra atrasados (previsão passou e não entregue).
  (data.pedidos||[]).forEach(p => {
    if (!p.previsao) return;
    if (["entregue","recebido","cancelado"].includes(p.status)) return;
    const prev = new Date(p.previsao+"T00:00:00");
    if (prev < hoje) {
      const dias = Math.floor((hoje - prev)/86400000);
      push(dias>=5?3:2, `Pedido ${p.numero||""} atrasado ha ${dias} dia(s)${p.fornecedor?` - ${p.fornecedor}`:""}`, "cmp");
    }
  });

  // Solicitacoes de compra aguardando acao.
  const solPend = (data.solicitacoesCompra||[]).filter(s=>s.status==="enviada").length;
  if (solPend > 0) push(1, `${solPend} solicitacao(oes) de compra aguardando`, "cmp");

  // Contratos aguardando assinatura.
  (data.comercial?.contratos||[]).forEach(k => {
    if (["rascunho","aguardando","aguardando_assinatura","pendente"].includes(k.status))
      push(2, `Contrato ${k.numero||""} aguardando assinatura`, "com_contratos");
  });

  // Leads sem proxima atividade ou com atividade vencida.
  const leadsAtivos = (data.comercial?.leads||[]).filter(l => !["perdido","arquivado","transferido"].includes(l.etapa) && l.status!=="perdido");
  let leadsSemRetorno = 0, leadsVencidos = 0;
  leadsAtivos.forEach(l => {
    if (!l.proximaAtividadeEm) { leadsSemRetorno++; return; }
    if (new Date(l.proximaAtividadeEm) < hoje) leadsVencidos++;
  });
  if (leadsVencidos > 0) push(2, `${leadsVencidos} lead(s) com follow-up vencido`, "com_funil");
  if (leadsSemRetorno > 0) push(1, `${leadsSemRetorno} lead(s) sem proxima atividade`, "com_leads");

  // Documentos de terceiros vencidos.
  let docVencidos = 0;
  (data.terceirizados||[]).forEach(t => (t.documentos||[]).forEach(doc => {
    if (doc.validade && new Date(doc.validade) < hoje) docVencidos++;
  }));
  if (docVencidos > 0) push(2, `${docVencidos} documento(s) de terceiro vencido(s)`, "terc");

  return A.sort((a,b) => b.sev - a.sev);
};

const calcResumoExecutivo = (data, year, month) => {
  const dre = calcDREConsolidado(data, year, month);
  const obrasAtivas = data.obras.filter(o => o.status !== "done" && o.status !== "paused");

  const obras = data.obras.map(o => {
    const d = calcDREObra(data, o.id, year, month);
    // Avanço físico: prioridade para boletins de medição confirmados; senão o
    // percentual das medições; senão zero.
    const boletins = (data.medicoesObra||[]).filter(m => m.obraId===o.id);
    const fisico = boletins.length
      ? boletins.reduce((mx,b)=>Math.max(mx, b.avancoFisico||0), 0)
      : d.pctAvanco || 0;
    const pctFinanceiro = d.pctFaturado || 0;
    const linha = {
      id:o.id, nome:o.name, cliente:o.client||o.engineer||"", cidade:o.address||"",
      status:o.status,
      contrato:d.contratoTotal, faturadoAcum:d.faturadoAcum, recebidoAcum:d.recebidoAcum,
      backlog:d.backlog, custoMes:d.totalCustos, margem:d.margemBruta,
      pctFisico:Math.round(fisico), pctFinanceiro:Math.round(pctFinanceiro),
      aReceber:d.aReceberAcum,
    };
    linha.exec = statusObraExec(linha);
    return linha;
  });

  const comercial = data.comercial || {};
  const leadsAtivos = (comercial.leads||[]).filter(l => !["perdido","arquivado","transferido"].includes(l.etapa));
  const pipeline = leadsAtivos.reduce((s,l)=>s+Number(l.orcamentoEstimado||0),0);
  const pipelinePonderado = leadsAtivos.reduce((s,l)=>s+Number(l.orcamentoEstimado||0)*Number(l.probabilidade||0)/100,0);
  const contratosComerciais = (comercial.contratos||[]).reduce((s,k)=>s+Number(k.valor||0),0);

  // Compras pendentes (todas as obras)
  const pedidos = (data.pedidos||[]).filter(p => p.status && !["cancelado","entregue","recebido"].includes(p.status));
  const comprasPendentes = pedidos.length;
  const solicitacoesAbertas = (data.solicitacoesCompra||[]).filter(s=>s.status==="enviada").length;

  return {
    dre,
    obrasAtivas: obrasAtivas.length,
    contratoTotalCarteira: data.obras.reduce((s,o)=>s+Number(o.contractValue||0),0),
    obras,
    obrasAtencao: obras.filter(o=>o.exec.k==="atencao").length,
    obrasCriticas: obras.filter(o=>o.exec.k==="critica").length,
    pipeline, pipelinePonderado, contratosComerciais,
    leadsAtivos: leadsAtivos.length,
    comprasPendentes, solicitacoesAbertas,
  };
};

function DRE({ data, update, showToast }) {
  const { cols } = useBreakpoint();
  const now   = new Date();
  const [year,  setYear]   = useState(now.getFullYear());
  const [month, setMonth]  = useState(now.getMonth());
  const [view,  setView]   = useState("consolidado"); // "consolidado" | "obra" | "historico"
  const [selObra, setSelObra] = useState(data.obras[0]?.id||"");
  const [despModal, setDespModal] = useState(false);
  const [despForm,  setDespForm]  = useState({ obraId:"", competencia:"", categoria:"material", descricao:"", valor:"" });
  const DF = k => v => setDespForm(f=>({...f,[k]:v}));

  const dre   = useMemo(()=>calcDREConsolidado(data,year,month), [data,year,month]);
  const dreObra = useMemo(()=>calcDREObra(data,selObra,year,month), [data,selObra,year,month]);
  const hist  = useMemo(()=>calcDREHistorico(data,year,month,6), [data,year,month]);

  const years = Array.from({length:4},(_,i)=>now.getFullYear()-2+i).map(y=>({v:String(y),l:String(y)}));
  const period = `${fullMonth(month)} ${year}`;
  const fmt2 = n=>Number(n||0).toFixed(2).replace(".",",");

  const saveDesp = () => {
    if(!despForm.obraId||!despForm.competencia||!despForm.valor) { showToast("Preencha obra, competência e valor.","error"); return; }
    const item = { id:uid(), ...despForm, valor:Number(despForm.valor||0) };
    update({...data, outrasDesp:[...(data.outrasDesp||[]),item]});
    setDespModal(false);
    setDespForm({obraId:"",competencia:"",categoria:"material",descricao:"",valor:""});
    showToast("Despesa registrada.");
  };

  const delDesp = id => {
    if(!window.confirm("Remover despesa?")) return;
    update({...data,outrasDesp:(data.outrasDesp||[]).filter(d=>d.id!==id)});
    showToast("Despesa removida.");
  };

  //  Linha DRE reutilizável
  const DRERow = ({label,value,color=C.text,bold=false,indent=0,pct=null}) => (
    <div style={{
      display:"flex",justifyContent:"space-between",alignItems:"center",
      padding:`${bold?"8px":"5px"} ${indent*12}px 5px ${12+indent*12}px`,
      borderBottom:`1px solid ${C.line}22`,
      background:bold?`${color}08`:"transparent",
    }}>
      <p style={{fontSize:bold?13:12,color:bold?color:C.muted,fontWeight:bold?900:400}}>{label}</p>
      <div style={{textAlign:"right",flexShrink:0}}>
        <p style={{fontSize:bold?15:12,color,fontWeight:bold?900:700}}>{fmt(value)}</p>
        {pct!==null&&<p style={{fontSize:9,color:color+"99",marginTop:1}}>{pct.toFixed(1)}%</p>}
      </div>
    </div>
  );
  const DRESection = ({title,color=C.yellow}) => (
    <div style={{background:`${color}15`,borderLeft:`4px solid ${color}`,padding:"5px 12px",marginTop:6}}>
      <p style={{fontSize:9,fontWeight:900,color,textTransform:"uppercase",letterSpacing:1}}>{title}</p>
    </div>
  );
  const DRESeparator = () => <div style={{height:1,background:`linear-gradient(90deg,transparent,${C.line},transparent)`,margin:"4px 0"}}/>;

  //  DRE de uma obra (card)
  const renderObraDRE = (d, compact=false) => {
    if(!d.obra) return null;
    const lucroCor = d.lucroBruto>=0?C.green:C.red;
    const caixaCor = d.saldoCaixa>=0?C.blue:C.red;
    return (
      <div key={d.obra.id} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`4px solid ${lucroCor}`,borderRadius:10,overflow:"hidden"}}>
        {/* Header obra */}
        <div style={{background:`${lucroCor}10`,padding:"10px 14px",borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8}}>
          <div>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:17}}>{d.obra.name}</p>
            <p style={{fontSize:11,color:C.muted,marginTop:2}}>
              {CONTRACT_LABELS[d.obra.contractType]||"Contrato"}
              {d.obra.contractValue>0&&`  ${fmt(d.obra.contractValue)}`}
              {d.pctAvanco>0&&`  ${d.pctAvanco}% executado`}
            </p>
          </div>
          <div style={{textAlign:"right",flexShrink:0}}>
            <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>Lucro Bruto</p>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:22,color:lucroCor,letterSpacing:.5}}>{fmt(d.lucroBruto)}</p>
            <p style={{fontSize:10,color:lucroCor+"99"}}>{d.margemBruta.toFixed(1)}%</p>
          </div>
        </div>

        {/* DRE */}
        <div style={{padding:"8px 0"}}>
          <DRESection title="Receitas" color={C.green}/>
          <DRERow label="Faturamento emitido" value={d.faturamento} color={C.green} bold/>
          {d.equipReceita>0&&<DRERow label="↳ inclui locação de equip. (líq.)" value={d.equipLucro} color={C.blue} indent={1}/>}
          <DRERow label="Recebido em caixa"   value={d.recebido}    color={C.blue}  indent={1}/>
          <DRERow label="A receber"            value={d.aReceber}    color={d.aReceber>0?C.orange:C.muted} indent={1}/>

          <DRESection title="Custos Diretos" color={C.red}/>
          <DRERow label="(-) MO própria"       value={d.moData.laborCost}   color={C.orange}  indent={1}/>
          <DRERow label="(-) Benefícios VT/VR" value={d.moData.benefitCost} color={C.muted}   indent={1}/>
          <DRERow label="(-) Terceirizados (obra)" value={d.tercCost}          color={C.purple}  indent={1}/>
          {d.rescTotal>0&&<DRERow label="(-) Rescisões" value={d.rescTotal} color={C.red} indent={1}/>}
          {d.equipCost>0&&<DRERow label="(-) Locação de equipamentos" value={d.equipCost} color={C.blue} indent={1}/>}
          {d.outrasTotal>0&&<DRERow label="(-) Outras despesas" value={d.outrasTotal} color={C.orange} indent={1}/>}
          <DRERow label="Total custos" value={d.totalCustos} color={C.red} bold/>

          <DRESeparator/>
          <DRERow label="Lucro Bruto" value={d.lucroBruto} color={lucroCor} bold pct={d.margemBruta}/>
          <DRERow label="Saldo de Caixa" value={d.saldoCaixa} color={caixaCor} bold pct={d.margemCaixa}/>

          {!compact && d.obra.contractValue>0&&(<>
            <DRESection title="Posição do Contrato (Acumulado)" color={C.blue}/>
            <DRERow label="Contrato total"    value={d.contratoTotal}  color={C.subtle}/>
            <DRERow label="Faturado acumulado" value={d.faturadoAcum} color={C.blue}  pct={d.pctFaturado}/>
            <DRERow label="Recebido acumulado" value={d.recebidoAcum} color={C.green} pct={d.pctRecebido}/>
            <DRERow label="A receber (acum.)"  value={d.aReceberAcum} color={d.aReceberAcum>0?C.orange:C.muted}/>
            <DRERow label="Backlog disponível"  value={d.backlog}      color={d.backlog>0?C.yellow:C.muted}/>
            {/* Barra de progresso do contrato */}
            <div style={{padding:"8px 14px 4px"}}>
              <div style={{height:5,background:C.surface,borderRadius:99,overflow:"hidden",marginBottom:2}}>
                <div style={{height:"100%",width:`${Math.min(d.pctFaturado,100)}%`,background:C.blue,borderRadius:99}}/>
              </div>
              <div style={{height:3,background:C.surface,borderRadius:99,overflow:"hidden"}}>
                <div style={{height:"100%",width:`${Math.min(d.pctRecebido,100)}%`,background:C.green,borderRadius:99}}/>
              </div>
              <p style={{fontSize:9,color:C.muted,marginTop:3}}> Faturado {d.pctFaturado.toFixed(0)}%  <span style={{color:C.green}}></span> Recebido {d.pctRecebido.toFixed(0)}%</p>
            </div>
          </>)}

          {/* Outras despesas detalhadas */}
          {!compact && d.outrasDesp.length>0&&(
            <div style={{padding:"6px 14px 8px"}}>
              <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:900,marginBottom:4}}>Detalhamento outras despesas</p>
              {d.outrasDesp.map(x=>(
                <div key={x.id} style={{display:"flex",justifyContent:"space-between",fontSize:11,color:C.muted,padding:"2px 0"}}>
                  <span>{x.descricao||x.categoria} <span style={{color:C.muted,fontSize:9}}>({fmtDateFull(x.competencia+"-01")})</span></span>
                  <div style={{display:"flex",gap:8,alignItems:"center"}}>
                    <span style={{color:C.orange,fontWeight:700}}>{fmt(x.valor)}</span>
                    <button onClick={()=>delDesp(x.id)} style={{background:"transparent",border:0,color:C.muted,cursor:"pointer",fontSize:11,padding:0}}>x</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  };

  //  PDF do DRE
  const gerarPDF = () => {
    const isConsolidado = view==="consolidado"||view==="historico";
    const titulo = isConsolidado ? `DRE Consolidado - ${period}` : `DRE ${dreObra.obra?.name||""} - ${period}`;

    const dreTableRows = (obj) => `
      <tr class="sec"><td colspan="2">RECEITAS</td></tr>
      <tr class="entry"><td>Faturamento emitido (medições)</td><td class="val pos">R$ ${fmt2(obj.faturamento)}</td></tr>
      <tr class="entry sub"><td>&nbsp;&nbsp;Recebido em caixa</td><td class="val">R$ ${fmt2(obj.recebido||0)}</td></tr>
      <tr class="entry sub"><td>&nbsp;&nbsp;A receber</td><td class="val warn">R$ ${fmt2(obj.aReceber||0)}</td></tr>
      ${(obj.equipReceita||0)>0?`<tr class="entry sub"><td>&nbsp;&nbsp;↳ inclui locação de equip. (líq.)</td><td class="val">R$ ${fmt2(obj.equipLucro||0)}</td></tr>`:""}
      <tr class="sec"><td colspan="2">CUSTOS DIRETOS</td></tr>
      <tr class="entry"><td>(-) Mão de obra própria</td><td class="val neg">R$ ${fmt2(obj.laborCost||obj.moData?.laborCost||0)}</td></tr>
      <tr class="entry sub"><td>&nbsp;&nbsp;(-) Benefícios (VT/VR)</td><td class="val">R$ ${fmt2(obj.benefitCost||obj.moData?.benefitCost||0)}</td></tr>
      <tr class="entry"><td>(-) Terceirizados${obj.tercEmpresa!==undefined?" (obras)":""}</td><td class="val neg">R$ ${fmt2(obj.tercCost||0)}</td></tr>
      ${(obj.tercEmpresa||0)>0?`<tr class="entry"><td>(-) Terceirizados (empresa)</td><td class="val neg">R$ ${fmt2(obj.tercEmpresa)}</td></tr>`:""}
      ${(obj.rescTotal||0)>0?`<tr class="entry"><td>(-) Rescisões</td><td class="val neg">R$ ${fmt2(obj.rescTotal)}</td></tr>`:""}
      ${(obj.equipCost||0)>0?`<tr class="entry"><td>(-) Locação de equipamentos</td><td class="val neg">R$ ${fmt2(obj.equipCost)}</td></tr>`:""}
      ${(obj.outrasTotal||0)>0?`<tr class="entry"><td>(-) Outras despesas</td><td class="val neg">R$ ${fmt2(obj.outrasTotal)}</td></tr>`:""}
      <tr class="subtotal"><td>Total Custos</td><td class="val neg">R$ ${fmt2(obj.totalCustos||0)}</td></tr>
      <tr class="result ${(obj.lucroBruto||0)>=0?"pos":"neg"}">
        <td><strong>LUCRO BRUTO</strong></td>
        <td class="val"><strong>R$ ${fmt2(obj.lucroBruto||0)} (${(obj.margemBruta||0).toFixed(1)}%)</strong></td>
      </tr>
      <tr class="result ${(obj.saldoCaixa||0)>=0?"caixa":"neg"}">
        <td>Saldo de Caixa</td>
        <td class="val">R$ ${fmt2(obj.saldoCaixa||0)} (${(obj.margemCaixa||0).toFixed(1)}%)</td>
      </tr>`;

    const obrasSect = isConsolidado ? dre.obras.map(o=>`
      <h3 style="font-size:13px;margin:18px 0 6px;border-bottom:1px solid #ddd;padding-bottom:4px">${escapeHtml(o.obra?.name||"")}</h3>
      <table class="dre-table"><tbody>${dreTableRows(o)}</tbody></table>`).join("") : "";

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>${escapeHtml(titulo)}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;color:#111;background:#fff;padding:28px;font-size:11px}
.print-btn{position:fixed;top:10px;right:10px;background:#080808;color:#f6d833;border:none;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer}
.page-header{display:flex;align-items:center;gap:16px;padding-bottom:14px;border-bottom:3px solid #080808;margin-bottom:20px}
.logo-box{background:#080808;color:#f6d833;padding:10px 16px;font-family:Georgia,serif;font-size:24px;font-weight:900;letter-spacing:2px;flex-shrink:0}
.company h1{font-size:16px;font-weight:900}.company p{font-size:10px;color:#666;margin-top:2px}
.period{font-size:18px;font-weight:900;text-align:right;flex:1}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0;page-break-inside:avoid}
.kpi{border:1px solid #ddd;padding:10px 12px;border-top:3px solid #999}
.kpi.green{border-top-color:#16a34a}.kpi.blue{border-top-color:#2563eb}.kpi.red{border-top-color:#dc2626}.kpi.purple{border-top-color:#9333ea}
.kpi-l{font-size:9px;font-weight:700;text-transform:uppercase;color:#777;letter-spacing:.5px}
.kpi-v{font-size:16px;font-weight:900;margin-top:4px}
.dre-table{width:100%;border-collapse:collapse;margin:10px 0}
.dre-table td{padding:5px 8px;border-bottom:1px solid #f0f0f0;font-size:11px}
.dre-table td.val{text-align:right;font-weight:700;min-width:120px}
.dre-table .pos{color:#16a34a}.dre-table .neg{color:#dc2626}.dre-table .warn{color:#d97706}.dre-table .caixa{color:#2563eb}
.dre-table .sec td{background:#f3f4f6;font-weight:700;font-size:9px;text-transform:uppercase;letter-spacing:.7px;color:#555;padding:4px 8px}
.dre-table .sub td{color:#888;font-style:italic}
.dre-table .subtotal td{font-weight:900;background:#fef2f2;border-top:2px solid #fca5a5}
.dre-table .result td{font-size:13px;font-weight:900;border-top:2px solid #111}
.dre-table .result.pos td{color:#16a34a}.dre-table .result.neg td{color:#dc2626}.dre-table .result.caixa td{color:#2563eb}
h2{font-size:14px;font-weight:900;margin:20px 0 8px;text-transform:uppercase;letter-spacing:.8px;border-bottom:1.5px solid #111;padding-bottom:5px}
h3{font-size:12px;font-weight:900;color:#2563eb}
.footer{margin-top:28px;text-align:center;font-size:9px;color:#bbb;border-top:1px solid #eee;padding-top:8px}
@media print{.print-btn{display:none!important}}
</style></head>
<body>
<button class="print-btn" onclick="window.print()"> Imprimir / PDF</button>
<div class="page-header">
  <div class="logo-box">ArcD</div>
  <div class="company">
    <h1>${escapeHtml(data.config.companyName||"ArcD Construtora")}</h1>
    ${data.config.cnpj?`<p>CNPJ: ${escapeHtml(data.config.cnpj)}</p>`:""}
    <p>DRE Gerencial - Demonstrativo de Resultado</p>
  </div>
  <div class="period">${escapeHtml(titulo.split("-").pop())}</div>
</div>

<div class="kpis">
  <div class="kpi green"><p class="kpi-l">Faturamento</p><p class="kpi-v">R$ ${fmt2(dre.faturamento)}</p></div>
  <div class="kpi blue"><p class="kpi-l">Recebido</p><p class="kpi-v">R$ ${fmt2(dre.recebido)}</p></div>
  <div class="kpi red"><p class="kpi-l">Total Custos</p><p class="kpi-v">R$ ${fmt2(dre.totalCustos)}</p></div>
  <div class="kpi ${dre.lucroBruto>=0?"green":"red"}"><p class="kpi-l">Lucro Bruto</p><p class="kpi-v">R$ ${fmt2(dre.lucroBruto)}</p></div>
</div>

<h2>${isConsolidado?"DRE Consolidado":"DRE - "+escapeHtml(dreObra.obra?.name||"")}</h2>
<table class="dre-table"><tbody>${dreTableRows(isConsolidado?dre:dreObra)}</tbody></table>

${isConsolidado&&dre.obras.length>1?`<h2>Detalhamento por Obra</h2>${obrasSect}`:""}

<div class="footer">Gerado por ArcD Ponto PRO  ${new Date().toLocaleString("pt-BR")}</div>
</body></html>`;
    const w=window.open("","_blank"); w.document.write(html); w.document.close();
  };

  //  Excel do DRE
  const exportXLS = () => {
    const wb = XLSX.utils.book_new();
    const dreRows = (obj) => [
      ["RECEITAS"],
      ["Faturamento emitido", obj.faturamento],
      ["Recebido em caixa",   obj.recebido||0],
      ["A receber",           obj.aReceber||0],
      ["CUSTOS DIRETOS"],
      ["(-) MO própria",      obj.laborCost||obj.moData?.laborCost||0],
      ["(-) Benefícios",      obj.benefitCost||obj.moData?.benefitCost||0],
      ["(-) Terceirizados",   obj.tercCost||0],
      ...((obj.tercEmpresa||0)>0 ? [["(-) Terceirizados (empresa)", obj.tercEmpresa]] : []),
      ["(-) Rescisões",       obj.rescTotal||0],
      ["(-) Outras despesas", obj.outrasTotal||0],
      ["Total Custos",        obj.totalCustos||0],
      ["LUCRO BRUTO",         obj.lucroBruto||0],
      ["Margem Bruta %",      (obj.margemBruta||0).toFixed(1)+"%"],
      ["Saldo de Caixa",      obj.saldoCaixa||0],
      ["Margem de Caixa %",   (obj.margemCaixa||0).toFixed(1)+"%"],
    ];
    const ws1=XLSX.utils.aoa_to_sheet([[`DRE Consolidado - ${period}`],[],["Linha","Valor"],...dreRows(dre)]);
    ws1["!cols"]=[30,14].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb,ws1,"DRE Consolidado");

    // Uma aba por obra
    dre.obras.forEach(o=>{
      if(!o.obra) return;
      const ws=XLSX.utils.aoa_to_sheet([[`DRE - ${o.obra.name} - ${period}`],[],["Linha","Valor"],...dreRows(o)]);
      ws["!cols"]=[30,14].map(w=>({wch:w}));
      XLSX.utils.book_append_sheet(wb,ws,(o.obra.name||"Obra").slice(0,30));
    });

    // Histórico
    const histHeader=["Mês","Faturamento","Recebido","Custos","Lucro Bruto","Margem %"];
    const histBody=hist.map(h=>[h.mes,h.faturamento,h.recebido,h.totalCustos,h.lucroBruto,h.margemBruta.toFixed(1)+"%"]);
    const wsH=XLSX.utils.aoa_to_sheet([["Histórico 6 meses"],[],histHeader,...histBody]);
    wsH["!cols"]=[14,14,12,12,14,10].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb,wsH,"Histórico");

    XLSX.writeFile(wb,`arcd-dre-${year}-${String(month+1).padStart(2,"0")}.xlsx`);
    showToast("Excel DRE gerado!");
  };

  //  RENDER 
  return (
    <div className="anim" style={{display:"flex",flexDirection:"column",gap:14}}>

      {/* Header */}
      <div style={{background:`linear-gradient(135deg,${C.green}22 0%,${C.card} 65%)`,border:`1px solid ${C.green}44`,borderLeft:`5px solid ${C.green}`,padding:"16px 18px",borderRadius:12}}>
        <p style={{fontSize:11,fontWeight:900,color:C.green,textTransform:"uppercase",letterSpacing:1.2,marginBottom:4}}>Demonstrativo Gerencial</p>
        <h2 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(19px,5vw,34px)",letterSpacing:2,color:C.text,lineHeight:1}}>DRE por Obra</h2>
        <p style={{color:C.muted,fontSize:13,marginTop:4}}>Faturamento  Custos  Lucro  Caixa  Posição de Contrato</p>
      </div>

      {/* Período */}
      <div style={{display:"grid",gridTemplateColumns:cols("1fr 1fr","1fr 1fr","240px 240px"),gap:8}}>
        <Sel value={String(year)} onChange={v=>setYear(Number(v))} options={years}/>
        <Sel value={String(month)} onChange={v=>setMonth(Number(v))} options={Array.from({length:12},(_,i)=>({v:String(i),l:fullMonth(i)}))}/>
      </div>

      {/* View toggle */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6}}>
        {[["consolidado"," Consolidado"],["obra"," Por Obra"],["historico"," Histórico"]].map(([v,l])=>(
          <button key={v} onClick={()=>setView(v)} style={{
            padding:"9px 4px",border:`2px solid ${view===v?C.green:C.line}`,
            background:view===v?`${C.green}18`:"transparent",
            color:view===v?C.green:C.muted,
            fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:13,cursor:"pointer",borderRadius:8,
          }}>{l}</button>
        ))}
      </div>

      {/* KPI cards sempre visíveis */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8}}>
        {[
          ["Faturamento",  dre.faturamento,  C.green,  `${period}`],
          ["Recebido",     dre.recebido,     C.blue,   `a receber: ${fmt(dre.aReceber)}`],
          ["Total Custos", dre.totalCustos,  C.red,    `MO+Terc+Outros`],
          ["Lucro Bruto",  dre.lucroBruto,   dre.lucroBruto>=0?C.green:C.red, `margem ${dre.margemBruta.toFixed(1)}%`],
        ].map(([l,v,c,s])=>(
          <div key={l} style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${c}`,padding:"12px 14px",borderRadius:10}}>
            <p style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:.8}}>{l}</p>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,color:c,fontSize:26,lineHeight:1.1,marginTop:4}}>{fmt(v)}</p>
            <p style={{fontSize:10,color:C.muted,marginTop:3}}>{s}</p>
          </div>
        ))}
      </div>

      {/*  VIEW: CONSOLIDADO  */}
      {view==="consolidado"&&(
        <div style={{display:"flex",flexDirection:"column",gap:6}}>
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
            <div style={{padding:"8px 14px",background:`${C.green}10`,borderBottom:`1px solid ${C.line}`}}>
              <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.green,textTransform:"uppercase"}}>DRE Consolidado - {period}</p>
            </div>
            <DRESection title="Receitas" color={C.green}/>
            <DRERow label="Faturamento total" value={dre.faturamento} color={C.green} bold/>
            <DRERow label="Recebido em caixa"  value={dre.recebido}    color={C.blue}  indent={1}/>
            <DRERow label="A receber"           value={dre.aReceber}    color={dre.aReceber>0?C.orange:C.muted} indent={1}/>
            <DRESection title="Custos Diretos" color={C.red}/>
            <DRERow label="(-) MO própria"       value={dre.laborCost}    color={C.orange} indent={1}/>
            <DRERow label="(-) Benefícios VT/VR" value={dre.benefitCost}  color={C.muted}  indent={1}/>
            <DRERow label="(-) Terceirizados (obras)" value={dre.tercCost}     color={C.purple} indent={1}/>
            {dre.tercEmpresa>0&&<DRERow label="(-) Terceirizados (empresa)" value={dre.tercEmpresa} color={C.purple} indent={1}/>}
            {dre.rescTotal>0&&<DRERow label="(-) Rescisões" value={dre.rescTotal} color={C.red} indent={1}/>}
            {dre.outrasTotal>0&&<DRERow label="(-) Outras despesas" value={dre.outrasTotal} color={C.orange} indent={1}/>}
            <DRERow label="Total custos" value={dre.totalCustos} color={C.red} bold/>
            <DRESeparator/>
            <DRERow label="LUCRO BRUTO" value={dre.lucroBruto} color={dre.lucroBruto>=0?C.green:C.red} bold pct={dre.margemBruta}/>
            <DRERow label="Saldo de Caixa" value={dre.saldoCaixa} color={dre.saldoCaixa>=0?C.blue:C.red} bold pct={dre.margemCaixa}/>
            <DRESection title="Posição Acumulada (Todas as Obras)" color={C.blue}/>
            <DRERow label="Faturado acumulado" value={dre.faturadoAcum} color={C.blue}/>
            <DRERow label="Recebido acumulado" value={dre.recebidoAcum} color={C.green}/>
            <DRERow label="Backlog disponível"  value={dre.backlog}      color={dre.backlog>0?C.yellow:C.muted}/>
          </div>

          {/* Gráfico: Faturamento vs Lucro 6 meses */}
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:14}}>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.yellow,textTransform:"uppercase",marginBottom:8}}>Evolução - Faturamento x Lucro</p>
            <div style={{height:200}}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={hist} barSize={18}>
                  <CartesianGrid stroke={C.border} vertical={false}/>
                  <XAxis dataKey="mes" stroke={C.muted} fontSize={10}/>
                  <YAxis stroke={C.muted} fontSize={10} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v}/>
                  <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text,borderRadius:8}} formatter={v=>fmt(v)}/>
                  <Bar dataKey="faturamento" name="Faturamento" fill={C.green} radius={[4,4,0,0]}/>
                  <Bar dataKey="recebido"    name="Recebido"    fill={C.blue}  radius={[4,4,0,0]}/>
                  <Bar dataKey="lucroBruto"  name="Lucro Bruto" fill={C.yellow} radius={[4,4,0,0]}/>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Distribuição de custos */}
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:14}}>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.yellow,textTransform:"uppercase",marginBottom:8}}>Distribuição de Custos</p>
            <div style={{height:180}}>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={[
                    {name:"MO Própria",    value:Math.round(dre.laborCost),   fill:C.orange},
                    {name:"Benefícios",    value:Math.round(dre.benefitCost), fill:C.muted},
                    {name:"Terceiros",     value:Math.round(dre.tercCost),    fill:C.purple},
                    {name:"Rescisões",     value:Math.round(dre.rescTotal),   fill:C.red},
                    {name:"Outras Desp.",  value:Math.round(dre.outrasTotal), fill:C.yellow},
                  ].filter(d=>d.value>0)} dataKey="value" nameKey="name" innerRadius={40} outerRadius={70} paddingAngle={2}>
                    {[C.orange,C.muted,C.purple,C.red,C.yellow].map((c,i)=><Cell key={i} fill={c}/>)}
                  </Pie>
                  <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text}} formatter={v=>fmt(v)}/>
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Por obra compact */}
          <p style={{fontSize:10,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:1}}>Resumo por obra</p>
          {dre.obras.map(o=>renderObraDRE(o,true))}
        </div>
      )}

      {/*  VIEW: POR OBRA  */}
      {view==="obra"&&(
        <div style={{display:"flex",flexDirection:"column",gap:10}}>
          <Sel value={selObra} onChange={setSelObra} options={data.obras.map(o=>({v:o.id,l:o.name}))}/>
          {renderObraDRE(dreObra,false)}
        </div>
      )}

      {/*  VIEW: HISTÓRICO  */}
      {view==="historico"&&(
        <div style={{display:"flex",flexDirection:"column",gap:10}}>
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
            <div style={{padding:"8px 14px",borderBottom:`1px solid ${C.line}`,display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr 1fr",gap:4}}>
              {["Mês","Faturamento","Recebido","Lucro","Margem"].map(h=>(
                <p key={h} style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase"}}>{h}</p>
              ))}
            </div>
            {hist.map((h,i)=>(
              <div key={i} style={{
                padding:"8px 14px",borderBottom:i<hist.length-1?`1px solid ${C.line}22`:"none",
                display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr 1fr",gap:4,
                background:h.m===month&&h.y===year?`${C.yellow}0a`:"transparent",
              }}>
                <p style={{fontSize:12,fontWeight:h.m===month&&h.y===year?900:500,color:h.m===month&&h.y===year?C.yellow:C.text}}>{h.mes}{h.m===month&&h.y===year?" ":""}</p>
                <p style={{fontSize:12,color:C.green,fontWeight:700}}>{fmt(h.faturamento)}</p>
                <p style={{fontSize:12,color:C.blue}}>{fmt(h.recebido)}</p>
                <p style={{fontSize:12,color:h.lucroBruto>=0?C.green:C.red,fontWeight:700}}>{fmt(h.lucroBruto)}</p>
                <p style={{fontSize:12,color:h.margemBruta>=0?C.green:C.red,fontWeight:900}}>{h.margemBruta.toFixed(1)}%</p>
              </div>
            ))}
          </div>
          {/* Gráfico margem */}
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:14}}>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.yellow,textTransform:"uppercase",marginBottom:8}}>Evolução da Margem</p>
            <div style={{height:180}}>
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={hist}>
                  <CartesianGrid stroke={C.border} vertical={false}/>
                  <XAxis dataKey="mes" stroke={C.muted} fontSize={10}/>
                  <YAxis stroke={C.muted} fontSize={10} tickFormatter={v=>v.toFixed(0)+"%"}/>
                  <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text}} formatter={v=>v.toFixed(1)+"%"}/>
                  <Line type="monotone" dataKey="margemBruta" name="Margem Bruta" stroke={C.green} strokeWidth={2.5} dot={{r:4,fill:C.green}}/>
                  <Line type="monotone" dataKey="margemCaixa" name="Margem Caixa" stroke={C.blue}  strokeWidth={2} dot={{r:3,fill:C.blue}} strokeDasharray="4 2"/>
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}

      {/* Botão: lançar outras despesas */}
      <button onClick={()=>{setDespForm({obraId:selObra||data.obras[0]?.id||"",competencia:`${year}-${String(month+1).padStart(2,"0")}`,categoria:"material",descricao:"",valor:""});setDespModal(true);}} style={{
        background:`${C.orange}10`,border:`1px dashed ${C.orange}66`,borderRadius:8,
        color:C.orange,padding:"10px 14px",cursor:"pointer",fontFamily:"'Inter Display','Inter',sans-serif",
        fontWeight:900,fontSize:13,letterSpacing:.5,textAlign:"left",display:"flex",alignItems:"center",gap:8,
      }}>
        <Ic n="plus" color={C.orange}/> Lançar outras despesas (materiais, equipamentos, taxas...)
      </button>

      {/* Outras despesas do mês */}
      {(data.outrasDesp||[]).filter(d=>d.competencia===`${year}-${String(month+1).padStart(2,"0")}`).length>0&&(
        <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
          <div style={{padding:"8px 14px",borderBottom:`1px solid ${C.line}`,background:`${C.orange}10`}}>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:14,color:C.orange,textTransform:"uppercase"}}>Outras despesas - {period}</p>
          </div>
          {(data.outrasDesp||[]).filter(d=>d.competencia===`${year}-${String(month+1).padStart(2,"0")}`).map(d=>(
            <div key={d.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"9px 14px",borderBottom:`1px solid ${C.line}22`}}>
              <div>
                <p style={{fontSize:13,fontWeight:700}}>{d.descricao||d.categoria}</p>
                <p style={{fontSize:11,color:C.muted}}>{rotuloCategoria(data, d.categoria)}  {data.obras.find(o=>o.id===d.obraId)?.name||"-"}</p>
              </div>
              <div style={{display:"flex",gap:8,alignItems:"center"}}>
                <p style={{color:C.orange,fontWeight:900}}>{fmt(d.valor)}</p>
                <Btn size="sm" v="danger" onClick={()=>delDesp(d.id)}><Ic n="trash"/></Btn>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Exportações */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Btn onClick={gerarPDF} v="danger" full><Ic n="file"/> DRE PDF</Btn>
        <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Excel Completo</Btn>
      </div>

      {/* Modal: outras despesas */}
      {despModal&&(
        <Modal title="Lançar Outras Despesas" onClose={()=>setDespModal(false)}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <Sel label="Obra *" value={despForm.obraId} onChange={DF("obraId")} options={[{v:"",l:"Selecione"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>
            <div>
              <p style={{fontSize:11,fontWeight:700,color:C.subtle,textTransform:"uppercase",marginBottom:5}}>Competência (mês/ano) *</p>
              <input type="month" value={despForm.competencia} onChange={e=>DF("competencia")(e.target.value)} style={{width:"100%",background:C.card,border:`1px solid ${C.border}`,color:C.text,padding:"11px 13px",borderRadius:10,fontSize:14,outline:"none"}}/>
            </div>
            <Sel label="Categoria *" value={despForm.categoria} onChange={DF("categoria")} options={categoriasDesp(data)}/>
            <Inp label="Descrição" value={despForm.descricao} onChange={DF("descricao")} placeholder="Ex.: Concreto fck 25 - 20m, Andaime locado..."/>
            <Inp label="Valor (R$) *" type="number" value={despForm.valor} onChange={DF("valor")} placeholder="0,00"/>
            <div style={{display:"flex",gap:8}}>
              <Btn v="ghost" onClick={()=>setDespModal(false)} full>Cancelar</Btn>
              <Btn v="warning" onClick={saveDesp} full><Ic n="check"/> Lançar</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}


const BILLING_LABELS = {
  mensal_fixo: "Parcela mensal fixa",
  percentual:  "Por % de avanço",
  livre:       "Livre",
};

function MedicoesView({ data, update, showToast }) {
  const { cols } = useBreakpoint();
  const now   = new Date();
  const [selObra,  setSelObra]  = useState(data.obras[0]?.id || "");
  const [modal,    setModal]    = useState(false);
  const [editId,   setEditId]   = useState(null);
  const [gerarModal, setGerarModal] = useState(false);
  const [gerarOpts,  setGerarOpts]  = useState({ sobreescrever: false });
  // Ao confirmar uma medicao vencida, perguntamos a DATA DE PAGAMENTO em vez
  // de assumir hoje - o pagamento quinzenal costuma cair em data especifica.
  const [pagarModal, setPagarModal] = useState(null);   // {m, data}
  // Fila de conciliacao das parcelas vencidas geradas agora:
  // {fila:[ids], idx, modo:"vencimento"|"outra"|"aberto", dataOutra}
  const [conciliar,  setConciliar]  = useState(null);

  const emptyM = {
    competencia: `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`,
    tipo: "mensal_fixo", percentualAcumulado: "", valorPrevisto: "",
    valorRecebido: "", dataPagamento: today(), descricao: "", recebido: false,
  };
  const [form, setForm] = useState(emptyM);
  const F = k => v => setForm(f => ({ ...f, [k]: v }));

  const obra = data.obras.find(o => o.id === selObra);
  const medicoes = (data.medicoes||[])
    .filter(m => m.obraId === selObra)
    .sort((a,b) => a.competencia.localeCompare(b.competencia));

  // % acumulado anterior (para calcular período)
  const prevAcumulado = (competencia, excludeId) => {
    const sorted = medicoes.filter(m => m.tipo==="percentual" && m.competencia < competencia && m.id !== excludeId);
    return sorted.length ? sorted[sorted.length-1].percentualAcumulado : 0;
  };

  const calcPrevisto = (f, o) => {
    if (!o) return 0;
    if (f.tipo === "mensal_fixo") return Number(o.parcelaMensal || f.valorPrevisto || 0);
    if (f.tipo === "percentual") {
      const prev = prevAcumulado(f.competencia, editId || undefined);
      const periodo = Math.max(0, Number(f.percentualAcumulado||0) - prev);
      return (periodo / 100) * Number(o.contractValue || 0);
    }
    return Number(f.valorPrevisto || 0);
  };

  //  Totais 
  const totalPrevisto = medicoes.reduce((s,m) => s+m.valorPrevisto, 0);
  const totalRecebido = medicoes.filter(m=>m.recebido).reduce((s,m) => s+m.valorRecebido, 0);
  const totalPendente = medicoes.filter(m=>!m.recebido).reduce((s,m) => s+m.valorPrevisto, 0);
  const saldo         = Number(obra?.contractValue||0) - totalRecebido;
  const pctRecebido   = obra?.contractValue>0 ? (totalRecebido/obra.contractValue)*100 : 0;
  const pctFaturado   = obra?.contractValue>0 ? (totalPrevisto/obra.contractValue)*100 : 0;

  //  Abrir nova medição com defaults inteligentes 
  const openNew = () => {
    const defaultTipo = obra?.billingType || "mensal_fixo";
    const pctAtual = defaultTipo === "percentual"
      ? Math.min(100, (prevAcumulado("9999-99")||0) + 10) : 0;
    // Próxima competência após a última medição
    const ultimaComp = medicoes.length ? medicoes[medicoes.length-1].competencia : null;
    let proximaComp = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;
    if (ultimaComp) {
      const [y,m] = ultimaComp.split("-").map(Number);
      const d = new Date(y, m, 1); // próximo mês
      proximaComp = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
    }
    setForm({
      ...emptyM,
      competencia: proximaComp,
      tipo: defaultTipo,
      percentualAcumulado: defaultTipo === "percentual" ? String(pctAtual) : "",
      valorPrevisto: obra?.parcelaMensal>0 ? String(obra.parcelaMensal) : "",
    });
    setEditId(null);
    setModal(true);
  };

  const openEdit = m => {
    setForm({
      competencia: m.competencia, tipo: m.tipo,
      percentualAcumulado: String(m.percentualAcumulado||""),
      valorPrevisto: String(m.valorPrevisto||""), valorRecebido: String(m.valorRecebido||""),
      dataPagamento: m.dataPagamento||today(), descricao: m.descricao||"", recebido: m.recebido,
    });
    setEditId(m.id);
    setModal(true);
  };

  const saveMedicao = () => {
    if (!selObra) { showToast("Selecione uma obra.","error"); return; }
    if (!form.competencia) { showToast("Informe a competência.","error"); return; }
    const previsto = calcPrevisto(form, obra);
    const periodo  = form.tipo==="percentual"
      ? Math.max(0, Number(form.percentualAcumulado||0) - prevAcumulado(form.competencia, editId||undefined)) : 0;
    const payload = {
      id: editId || uid(), obraId: selObra,
      competencia: form.competencia, tipo: form.tipo,
      percentualAcumulado: Number(form.percentualAcumulado||0), percentualPeriodo: periodo,
      valorPrevisto: previsto,
      valorRecebido: form.recebido ? Number(form.valorRecebido||previsto) : 0,
      dataPagamento: form.recebido ? (form.dataPagamento||today()) : "",
      descricao: form.descricao, recebido: form.recebido,
    };
    const medicoes = editId
      ? (data.medicoes||[]).map(m => m.id===editId ? payload : m)
      : [...(data.medicoes||[]), payload];
    update({ ...data, medicoes });
    setModal(false);
    showToast(editId ? "Medição atualizada." : "Medição registrada.");
  };

  //  Geração automática de parcelas fixas 
  // Calcula a data de vencimento de uma parcela
  // Os dias vem da obra (diaVenc1/diaVenc2), nao mais fixos em 1 e 15.
  const calcDataVencimento = (contractStart, parcelaIdx, freq, dia1, dia2) => {
    const [y, m] = contractStart.split("-").map(Number);
    const d1 = Number(dia1 || DIA_VENC_1_PADRAO);
    const d2 = Number(dia2 || DIA_VENC_2_PADRAO);
    if (freq === "quinzenal") {
      const mesOffset = Math.floor(parcelaIdx / 2);
      const isSecond  = parcelaIdx % 2 === 1;
      const mesIdx    = m - 1 + mesOffset;
      // Ano/mes reais depois do offset, para o clamp usar o mes certo.
      const ref  = new Date(y, mesIdx, 1);
      const dia  = clampDiaNoMes(ref.getFullYear(), ref.getMonth(), isSecond ? d2 : d1);
      return toLocalISODate(new Date(ref.getFullYear(), ref.getMonth(), dia));
    } else {
      const ref = new Date(y, m - 1 + parcelaIdx, 1);
      const dia = clampDiaNoMes(ref.getFullYear(), ref.getMonth(), d1);
      return toLocalISODate(new Date(ref.getFullYear(), ref.getMonth(), dia));
    }
  };

  // Calcula competência (mês) de uma parcela
  const calcCompetencia = (contractStart, parcelaIdx, freq) => {
    const [y, m] = contractStart.split("-").map(Number);
    const mesOffset = freq==="quinzenal" ? Math.floor(parcelaIdx/2) : parcelaIdx;
    const d = new Date(y, m-1+mesOffset, 1);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
  };

  const gerarParcelasFixas = () => {
    if (!obra?.contractStart) {
      showToast("Configure a data de início do contrato na obra.","error"); return;
    }
    const tipo = obra.contractType || "fixed_labor";
    const freq = obra.billingFrequency || "mensal";
    const total = obra.totalParcelas || 12;
    const novas = [];

    //  Entrada (somente para MO fixo e Misto) 
    if (tipo !== "admin_only" && Number(obra.entrada||0) > 0 && obra.entradaDate) {
      const existeEntrada = (data.medicoes||[]).some(x=>x.obraId===selObra && x.numeroParcela==="E");
      if (!existeEntrada || gerarOpts.sobreescrever) {
        novas.push({
          id: uid(), obraId: selObra,
          competencia: obra.contractStart.slice(0,7),
          dataVencimento: obra.entradaDate,
          numeroParcela: "E",
          tipo: "mensal_fixo",
          percentualAcumulado: 0, percentualPeriodo: 0,
          valorMOFixo: Number(obra.entrada), valorAdminPct: 0,
          valorPrevisto: Number(obra.entrada),
          valorRecebido: 0, dataPagamento: "",
          descricao: "Entrada do contrato",
          recebido: false,
        });
      }
    }

    //  Parcelas regulares 
    for (let i=0; i<total; i++) {
      const dataVenc = calcDataVencimento(obra.contractStart, i, freq, obra.diaVenc1, obra.diaVenc2);
      const comp     = calcCompetencia(obra.contractStart, i, freq);
      const numParcela = i+1;
      const isQuinzenaSegunda = freq==="quinzenal" && i%2===1;
      const descPrefix = freq==="quinzenal"
        ? `${isQuinzenaSegunda?"2ª":"1ª"} quinzena`
        : `Parcela ${numParcela}/${total}`;

      // Componentes por tipo
      // O componente de MO é fixo e conhecido já na geração. O de Administração
      // depende do custo real de mão de obra do período, que só existe depois do
      // ponto lançado - por isso nasce zerado e é calculado mês a mês pelo botão
      // "Calcular Admin %" na própria medição.
      const valorMOFixo   = (tipo==="fixed_labor"||tipo==="fixed_labor_admin") ? Number(obra.parcelaMensal||0) : 0;
      const valorAdminPct = 0;

      // Verifica duplicata por dataVencimento
      const existe = (data.medicoes||[]).some(x=>x.obraId===selObra && x.dataVencimento===dataVenc);
      if (existe && !gerarOpts.sobreescrever) continue;

      novas.push({
        id: uid(), obraId: selObra, competencia: comp,
        dataVencimento: dataVenc,
        numeroParcela: numParcela,
        tipo: tipo==="admin_only" ? "admin_pct" : "mensal_fixo",
        percentualAcumulado: 0, percentualPeriodo: 0,
        valorMOFixo, valorAdminPct,
        valorPrevisto: valorMOFixo,
        valorRecebido: 0, dataPagamento: "",
        descricao: `${descPrefix}  ${compLabel(comp)}`,
        recebido: false,
      });
    }

    if (novas.length === 0) { showToast("Todas as parcelas já estão lançadas.","warn"); return; }

    let medicoesList = gerarOpts.sobreescrever
      ? (data.medicoes||[]).filter(x=>x.obraId!==selObra)
      : (data.medicoes||[]);
    medicoesList = [...medicoesList, ...novas]
      .sort((a,b)=>(a.dataVencimento||a.competencia).localeCompare(b.dataVencimento||b.competencia));
    update({...data, medicoes: medicoesList});
    setGerarModal(false);
    showToast(`${novas.length} parcelas geradas!${tipo==="admin_only"||tipo==="fixed_labor_admin"?" Calcule o valor Admin % mês a mês conforme executado.":""}`);

    // Parcelas que ja nasceram vencidas (contrato retroativo): em vez de
    // deixa-las todas em aberto, perguntamos uma a uma se o pagamento saiu
    // na data do contrato. Quem gera parcela de um contrato que comecou em
    // marco normalmente ja recebeu as primeiras.
    const hoje = today();
    const vencidas = novas
      .filter(n => n.dataVencimento && n.dataVencimento < hoje && Number(n.valorPrevisto||0) > 0)
      .sort((a,b) => a.dataVencimento.localeCompare(b.dataVencimento));
    if (vencidas.length) {
      setConciliar({
        fila: vencidas.map(v => v.id),
        idx: 0,
        // decisao pendente da parcela atual: "" (nao escolhido) | "vencimento" | "outra" | "aberto"
        modo: "vencimento",
        dataOutra: today(),
      });
    }
  };

  //  Conciliacao das parcelas vencidas recem-geradas 
  // Aplica a decisao da parcela atual e avanca a fila. Se acabar, fecha.
  const conciliarAplicar = (base) => {
    if (!conciliar) return;
    const id  = conciliar.fila[conciliar.idx];
    const med = (data.medicoes||[]).find(x => x.id === id);
    let lista = data.medicoes || [];

    if (med && conciliar.modo !== "aberto") {
      const dataPg = conciliar.modo === "vencimento"
        ? med.dataVencimento
        : (conciliar.dataOutra || med.dataVencimento);
      const upd = { ...med, recebido:true, valorRecebido: Number(med.valorPrevisto||0), dataPagamento: dataPg };
      lista = lista.map(x => x.id === id ? upd : x);
      update({ ...(base||data), medicoes: lista });
    }

    const prox = conciliar.idx + 1;
    if (prox >= conciliar.fila.length) {
      setConciliar(null);
      showToast("Parcelas vencidas conciliadas.");
    } else {
      setConciliar(c => ({ ...c, idx: prox, modo:"vencimento", dataOutra: today() }));
    }
  };

  // Marca TODAS as parcelas restantes da fila como pagas no proprio vencimento.
  const conciliarTodasNoVencimento = () => {
    if (!conciliar) return;
    const restantes = conciliar.fila.slice(conciliar.idx);
    const lista = (data.medicoes||[]).map(m => restantes.includes(m.id)
      ? { ...m, recebido:true, valorRecebido: Number(m.valorPrevisto||0), dataPagamento: m.dataVencimento }
      : m);
    update({ ...data, medicoes: lista });
    setConciliar(null);
    showToast(`${restantes.length} parcela(s) marcadas como pagas no vencimento.`);
  };

  const toggleRecebido = (m) => {
    const updated = { ...m, recebido: !m.recebido, valorRecebido: !m.recebido ? m.valorPrevisto : 0, dataPagamento: !m.recebido ? today() : "" };
    update({...data, medicoes:(data.medicoes||[]).map(x=>x.id===m.id?updated:x)});
    showToast(!m.recebido ? "ok Marcado como recebido." : "Desmarcado.");
  };

  const deleteMedicao = id => {
    if (!window.confirm("Remover esta medição?")) return;
    update({...data, medicoes:(data.medicoes||[]).filter(m=>m.id!==id)});
    showToast("Medição removida.");
  };

  const formPrevisto = calcPrevisto(form, obra);

  //  Info do período do contrato 
  const contratoInfo = (() => {
    if (!obra?.contractStart) return null;
    const start = new Date(obra.contractStart+"T12:00:00");
    const end   = obra.contractEnd ? new Date(obra.contractEnd+"T12:00:00") : null;
    const hoje  = new Date();
    const mesesDecorridos = Math.max(0, (hoje.getFullYear()-start.getFullYear())*12 + (hoje.getMonth()-start.getMonth()));
    const total = obra.totalParcelas || (end ? Math.round((end-start)/(1000*60*60*24*30.4)) : 0);
    const pctTempo = total>0 ? Math.min((mesesDecorridos/total)*100,100) : 0;
    return { start, end, mesesDecorridos, total, pctTempo };
  })();

  return (
    <div className="anim" style={{display:"flex",flexDirection:"column",gap:14}}>

      {/* Header */}
      <div style={{background:C.surface,border:`1.5px solid ${C.border}`,borderLeft:`4px solid ${C.blue}`,padding:"16px 18px",borderRadius:8}}>
        <p style={{fontSize:11,fontWeight:700,color:C.blue,textTransform:"uppercase",letterSpacing:1.2,marginBottom:4}}>Faturamento estruturado</p>
        <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontSize:22,fontWeight:800,color:C.text,lineHeight:1}}>Medições por Obra</p>
        <p style={{color:C.muted,fontSize:13,marginTop:4}}>Parcela fixa automática  Avanço %  Lançamento livre</p>
      </div>

      {/* Painel de vencimentos - todas as obras */}
      {(() => {
        const todayDate = new Date();
        const proximasAll = (data.medicoes||[]).filter(m => {
          if (m.recebido || !m.dataVencimento) return false;
          const venc = new Date(m.dataVencimento+"T12:00:00");
          const diff = Math.round((venc-todayDate)/(1000*60*60*24));
          return diff <= 7;
        }).map(m => {
          const o = data.obras.find(x=>x.id===m.obraId);
          const venc = new Date(m.dataVencimento+"T12:00:00");
          const diff = Math.round((venc-todayDate)/(1000*60*60*24));
          return {...m, obraName:o?.name||"-", diff};
        }).sort((a,b)=>a.dataVencimento.localeCompare(b.dataVencimento));

        if (proximasAll.length===0) return null;
        const totalPendente = proximasAll.reduce((s,m)=>s+m.valorPrevisto,0);
        const vencidas = proximasAll.filter(m=>m.diff<0);

        return (
          <div style={{background:vencidas.length>0?`${C.red}06`:`${C.orange}06`,border:`1.5px solid ${vencidas.length>0?C.red:C.orange}`,borderRadius:8,overflow:"hidden"}}>
            <div style={{padding:"10px 14px",borderBottom:`1px solid ${vencidas.length>0?C.red+"33":C.orange+"33"}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <p style={{fontWeight:800,fontSize:14,color:vencidas.length>0?C.red:C.orange}}>
                {vencidas.length>0?` ${vencidas.length} vencida(s) + `:""}{proximasAll.length-vencidas.length} vencendo em até 7 dias
              </p>
              <p style={{fontSize:13,fontWeight:800,color:C.text}}>{fmt(totalPendente)}</p>
            </div>
            {proximasAll.map(m=>(
              <div key={m.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 14px",borderBottom:`1px solid ${C.line}33`}}>
                <div>
                  <p style={{fontSize:13,fontWeight:700,color:C.text}}>{m.obraName}</p>
                  <p style={{fontSize:11,color:m.diff<0?C.red:m.diff<=3?C.orange:C.muted}}>
                    {m.diff<0?`Venceu há ${Math.abs(m.diff)}d`:m.diff===0?"Vence HOJE":`Vence em ${m.diff}d`}
                    {" - "}{fmtDateFull(m.dataVencimento)}
                    {m.descricao?`  ${m.descricao}`:""}
                  </p>
                </div>
                <div style={{display:"flex",gap:8,alignItems:"center",flexShrink:0}}>
                  <p style={{fontSize:14,fontWeight:800,color:m.diff<0?C.red:C.text}}>{fmt(m.valorPrevisto)}</p>
                  <Btn size="sm" v="success" onClick={()=>setPagarModal({ m, data: today() })}>ok</Btn>
                </div>
              </div>
            ))}
          </div>
        );
      })()}

      {/* Seletor de obra */}
      <Sel value={selObra} onChange={v=>{setSelObra(v);}} options={data.obras.map(o=>({v:o.id,l:o.name+"  "+BILLING_LABELS[o.billingType]}))}/>

      {obra && (<>
        {/* Card da obra com período do contrato */}
        <div style={{background:C.bg,border:`1.5px solid ${C.border}`,borderRadius:8,overflow:"hidden",boxShadow:`0 1px 4px ${C.shadow}`}}>
          <div style={{background:C.surface,borderBottom:`1.5px solid ${C.border}`,padding:"12px 16px",display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8}}>
            <div style={{flex:1}}>
              <p style={{fontWeight:800,fontSize:16,color:C.text}}>{obra.name}</p>
              <p style={{fontSize:12,color:C.muted,marginTop:2}}>
                {CONTRACT_LABELS[obra.contractType]}  {BILLING_LABELS[obra.billingType]}
                {obra.billingType==="mensal_fixo" && obra.parcelaMensal>0 && `  ${fmt(obra.parcelaMensal)}/mês`}
              </p>
              {/* Período do contrato */}
              {obra.contractStart && (
                <p style={{fontSize:11,color:C.muted,marginTop:4}}>
                   {fmtDateFull(obra.contractStart)}{obra.contractEnd && ` → ${fmtDateFull(obra.contractEnd)}`}
                  {obra.totalParcelas>0 && `  ${obra.totalParcelas} parcelas`}
                </p>
              )}
            </div>
            <div style={{display:"flex",gap:6,flexShrink:0}}>
              {/* Botão gerar parcelas - só para mensal fixo */}
              {obra.billingType==="mensal_fixo" && obra.parcelaMensal>0 && obra.contractStart && (
                <Btn size="sm" v="primary" onClick={()=>setGerarModal(true)}> Gerar parcelas</Btn>
              )}
              <Btn size="sm" onClick={openNew}><Ic n="plus"/> Nova</Btn>
            </div>
          </div>

          {/* Timeline do contrato */}
          {contratoInfo && (
            <div style={{padding:"10px 16px",borderBottom:`1px solid ${C.line}`}}>
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:10}}>
                {[
                  ["Decorrido",    `${contratoInfo.mesesDecorridos} meses`, C.blue],
                  ["Total prev.",  `${contratoInfo.total||"-"} meses`,     C.muted],
                  ["Prazo",        `${contratoInfo.pctTempo.toFixed(0)}%`,  contratoInfo.pctTempo>90?C.red:C.green],
                ].map(([l,v,c])=>(
                  <div key={l} style={{background:C.surface,borderRadius:6,padding:"6px 10px"}}>
                    <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>{l}</p>
                    <p style={{fontSize:13,fontWeight:800,color:c,marginTop:2}}>{v}</p>
                  </div>
                ))}
              </div>
              {/* Barra dupla: tempo x financeiro */}
              <div style={{display:"flex",flexDirection:"column",gap:4}}>
                <div style={{display:"flex",justifyContent:"space-between",marginBottom:1}}>
                  <p style={{fontSize:9,color:C.muted,fontWeight:600}}>PRAZO {contratoInfo.pctTempo.toFixed(0)}%</p>
                  <p style={{fontSize:9,color:C.muted,fontWeight:600}}>FINANCEIRO {pctFaturado.toFixed(0)}%</p>
                </div>
                <div style={{height:5,background:C.surface,borderRadius:99,overflow:"hidden"}}>
                  <div style={{height:"100%",width:`${Math.min(contratoInfo.pctTempo,100)}%`,background:contratoInfo.pctTempo>100?C.red:C.blue,borderRadius:99}}/>
                </div>
                <div style={{height:4,background:C.surface,borderRadius:99,overflow:"hidden"}}>
                  <div style={{height:"100%",width:`${Math.min(pctFaturado,100)}%`,background:C.yellow,borderRadius:99}}/>
                </div>
                <div style={{height:3,background:C.surface,borderRadius:99,overflow:"hidden"}}>
                  <div style={{height:"100%",width:`${Math.min(pctRecebido,100)}%`,background:C.green,borderRadius:99}}/>
                </div>
                <p style={{fontSize:9,color:C.muted}}>
                  <span style={{color:C.blue}}></span> Prazo  
                  <span style={{color:C.yellow}}></span> Faturado {pctFaturado.toFixed(0)}%  
                  <span style={{color:C.green}}></span> Recebido {pctRecebido.toFixed(0)}%
                </p>
              </div>
            </div>
          )}

          {/* KPIs */}
          <div style={{display:"grid",gridTemplateColumns:cols(2,4,4),padding:"10px 16px",gap:8}}>
            {[
              ["Faturado",   fmt(totalPrevisto), C.yellow],
              ["Recebido",   fmt(totalRecebido), C.green],
              ["Pendente",   fmt(totalPendente), totalPendente>0?C.orange:C.muted],
              ["Saldo cto.", fmt(saldo),         saldo>=0?C.blue:C.red],
            ].map(([l,v,c])=>(
              <div key={l} style={{background:C.surface,padding:"7px 10px",borderRadius:6}}>
                <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>{l}</p>
                <p style={{fontSize:13,fontWeight:800,color:c,marginTop:2}}>{v}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Lista de medições */}
        {medicoes.length===0 && (
          <div style={{background:C.surface,border:`1.5px solid ${C.border}`,borderRadius:6,padding:20,textAlign:"center"}}>
            <p style={{color:C.muted,fontSize:13,marginBottom:8}}>Nenhuma medição registrada.</p>
            {obra.billingType==="mensal_fixo" && obra.parcelaMensal>0 && obra.contractStart && (
              <Btn onClick={()=>setGerarModal(true)} v="primary"> Gerar todas as parcelas automaticamente</Btn>
            )}
          </div>
        )}

        {medicoes.map((m,idx) => {
          const prevMeds = medicoes.slice(0,idx).filter(x=>x.tipo==="percentual");
          const prevPct  = prevMeds.length ? prevMeds[prevMeds.length-1].percentualAcumulado : 0;
          // Status de vencimento
          const venc = m.dataVencimento ? new Date(m.dataVencimento+"T12:00:00") : null;
          const diffDias = venc ? Math.round((venc - new Date())/(1000*60*60*24)) : null;
          const statusVenc = m.recebido ? "pago"
            : diffDias === null ? "sem_data"
            : diffDias < 0 ? "vencido"
            : diffDias <= 3 ? "alerta"
            : "normal";
          const statusColor = {pago:C.green,vencido:C.red,alerta:C.orange,normal:C.border,sem_data:C.border}[statusVenc];
          const statusLabel = {pago:"ok RECEBIDO",vencido:`VENCIDO (${Math.abs(diffDias)}d)`,alerta:`VENCE ${diffDias===0?"HOJE":`EM ${diffDias}d`}`,normal:`Vence ${fmtDateFull(m.dataVencimento)}`,sem_data:"Pendente"}[statusVenc];

          // Calcular Admin % real para o período
          const calcAdminPct = () => {
            if (!m.competencia) return 0;
            const [y,mo] = m.competencia.split("-").map(Number);
            const mdays = getDays(y,mo-1);
            const {laborCost} = calcObraLaborCost(data,selObra,mdays);
            return laborCost * Number(obra?.adminPercentage||0)/100;
          };

          const contemAdmin = obra?.contractType==="admin_only"||obra?.contractType==="fixed_labor_admin";

          return (
            <div key={m.id} style={{
              background:m.recebido?`${C.green}06`:C.bg,
              border:`1.5px solid ${statusColor}`,
              borderLeft:`4px solid ${statusColor}`,
              borderRadius:6, padding:"12px 14px",
              boxShadow:`0 1px 3px ${C.shadow}`,
            }}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
                <div style={{flex:1}}>
                  <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap",marginBottom:4}}>
                    {m.numeroParcela && <span style={{fontSize:11,fontWeight:800,color:C.muted}}>#{m.numeroParcela}</span>}
                    <p style={{fontWeight:800,fontSize:15,color:C.text}}>{compLabel(m.competencia)}</p>
                    <span style={{
                      fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:4,
                      background:`${statusColor}18`,color:statusColor,
                    }}>{statusLabel}</span>
                    {m.tipo==="percentual"&&<span style={{fontSize:10,color:C.blue,fontWeight:600,background:`${C.blue}10`,padding:"2px 8px",borderRadius:4}}>{prevPct}%→{m.percentualAcumulado}% (+{m.percentualPeriodo.toFixed(1)}%)</span>}
                  </div>
                  {m.descricao&&<p style={{fontSize:11,color:C.muted,marginBottom:4}}>{m.descricao}</p>}

                  <div style={{display:"flex",gap:14,flexWrap:"wrap"}}>
                    {/* Componente MO fixo */}
                    {m.valorMOFixo>0&&(
                      <div><p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:600}}>MO Fixo</p><p style={{fontSize:14,fontWeight:800,color:C.yellow}}>{fmt(m.valorMOFixo)}</p></div>
                    )}
                    {/* Componente Admin % */}
                    {m.valorAdminPct>0&&(
                      <div><p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:600}}>Admin {obra?.adminPercentage||0}%</p><p style={{fontSize:14,fontWeight:800,color:C.purple}}>{fmt(m.valorAdminPct)}</p></div>
                    )}
                    {/* Total previsto */}
                    {m.valorPrevisto>0&&(
                      <div><p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:600}}>Total previsto</p><p style={{fontSize:14,fontWeight:800,color:C.text}}>{fmt(m.valorPrevisto)}</p></div>
                    )}
                    {/* Recebido */}
                    {m.recebido&&<><div><p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:600}}>Recebido</p><p style={{fontSize:14,fontWeight:800,color:C.green}}>{fmt(m.valorRecebido)}</p></div>
                    <div><p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:600}}>Data pgto</p><p style={{fontSize:12,color:C.muted}}>{fmtDateFull(m.dataPagamento)}</p></div></>}
                  </div>

                  {/* Botão calcular Admin % (se não calculado) */}
                  {contemAdmin && m.valorAdminPct===0 && m.competencia && !m.recebido && (
                    <button onClick={()=>{
                      const adminVal = calcAdminPct();
                      if (adminVal===0) { showToast("Lance o ponto do período para calcular.","error"); return; }
                      const novoTotal = Number(m.valorMOFixo||0) + adminVal;
                      const updated = {...m, valorAdminPct:adminVal, valorPrevisto:novoTotal};
                      update({...data,medicoes:(data.medicoes||[]).map(x=>x.id===m.id?updated:x)});
                      showToast(`Admin ${fmt(adminVal)} calculado com base na MO do período.`);
                    }} style={{
                      marginTop:8,background:"transparent",border:`1px solid ${C.purple}`,
                      color:C.purple,padding:"3px 10px",borderRadius:4,fontSize:11,cursor:"pointer",fontWeight:700,
                    }}>
                       Calcular Admin {obra?.adminPercentage||0}% sobre MO real
                    </button>
                  )}
                </div>

                <div style={{display:"flex",flexDirection:"column",gap:5,flexShrink:0}}>
                  <Btn size="sm" v={m.recebido?"ghost":"success"} onClick={()=>toggleRecebido(m)}>
                    {m.recebido?"Desfazer":"ok Receber"}
                  </Btn>
                  <Btn size="sm" v="ghost" onClick={()=>openEdit(m)}><Ic n="edit"/></Btn>
                  <Btn size="sm" v="danger" onClick={()=>deleteMedicao(m.id)}><Ic n="trash"/></Btn>
                </div>
              </div>
            </div>
          );
        })}

        {obra.contractValue>0&&(
          <div style={{background:C.bg,border:`1.5px solid ${C.border}`,borderRadius:6,padding:"10px 14px",display:"flex",justifyContent:"space-between",alignItems:"center",boxShadow:`0 1px 3px ${C.shadow}`}}>
            <p style={{fontSize:12,color:C.muted}}>Saldo do contrato: <strong style={{color:C.text}}>{fmt(saldo)}</strong></p>
            <p style={{fontSize:12,color:C.muted}}>Recebido: <strong style={{color:C.green}}>{pctRecebido.toFixed(1)}%</strong></p>
          </div>
        )}
      </>)}

      {/* Modal: nova/editar medição */}
      {modal && obra && (
        <Modal title={editId?"Editar medição":"Nova medição"} onClose={()=>setModal(false)}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            {/* Tipo */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6}}>
              {[["mensal_fixo"," Fixo"],["percentual"," % Avanço"],["livre"," Livre"]].map(([v,l])=>(
                <button key={v} onClick={()=>F("tipo")(v)} style={{
                  padding:"8px 4px",border:`2px solid ${form.tipo===v?C.yellow:C.border}`,
                  background:form.tipo===v?`${C.yellow}15`:"transparent",
                  color:form.tipo===v?C.text:C.muted,
                  fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:700,fontSize:12,
                  cursor:"pointer",borderRadius:6,textAlign:"center",
                }}>{l}</button>
              ))}
            </div>

            {/* Competência */}
            <div>
              <p style={{fontSize:11,fontWeight:700,color:C.text,textTransform:"uppercase",marginBottom:5,letterSpacing:.7}}>Mês de competência *</p>
              <input type="month" value={form.competencia} onChange={e=>F("competencia")(e.target.value)} style={{width:"100%",background:C.bg,border:`1.5px solid ${C.border}`,color:C.text,padding:"10px 12px",borderRadius:6,fontSize:14,outline:"none",fontFamily:"'Inter','Inter Display',sans-serif"}}/>
            </div>

            {/* Fixo */}
            {form.tipo==="mensal_fixo"&&(
              <div style={{background:C.surface,border:`1.5px solid ${C.border}`,borderRadius:6,padding:"10px 14px"}}>
                <p style={{fontSize:12,color:C.text,fontWeight:700,marginBottom:6}}>
                  Parcela mensal fixa
                  {obra.parcelaMensal>0&&<span style={{color:C.yellow,marginLeft:8}}>→ {fmt(obra.parcelaMensal)}</span>}
                </p>
                <Inp label="Valor da parcela (R$)" type="number" value={form.valorPrevisto} onChange={F("valorPrevisto")} placeholder={obra.parcelaMensal>0?String(obra.parcelaMensal):"0,00"}/>
                {!form.valorPrevisto && obra.parcelaMensal>0 && (
                  <button onClick={()=>F("valorPrevisto")(String(obra.parcelaMensal))} style={{marginTop:6,background:"transparent",border:`1px solid ${C.yellow}`,color:C.yellow,padding:"4px 10px",borderRadius:4,fontSize:11,cursor:"pointer",fontWeight:700}}>
                    Usar parcela configurada ({fmt(obra.parcelaMensal)})
                  </button>
                )}
              </div>
            )}

            {/* % Avanço */}
            {form.tipo==="percentual"&&(
              <div style={{background:C.surface,border:`1.5px solid ${C.border}`,borderRadius:6,padding:"10px 14px",display:"flex",flexDirection:"column",gap:8}}>
                <p style={{fontSize:12,fontWeight:700,color:C.text}}>
                  % acumulado da obra até este mês
                  {obra.contractValue>0&&<span style={{color:C.muted,marginLeft:4,fontWeight:400}}> (Contrato: {fmt(obra.contractValue)})</span>}
                </p>
                <Inp label="% acumulado *" type="number" value={form.percentualAcumulado} onChange={F("percentualAcumulado")} placeholder="Ex.: 35"/>
                {Number(form.percentualAcumulado)>0 && obra.contractValue>0 && (() => {
                  const prev = prevAcumulado(form.competencia, editId||undefined);
                  const periodo = Math.max(0, Number(form.percentualAcumulado||0) - prev);
                  const val = (periodo/100)*Number(obra.contractValue||0);
                  return (
                    <div style={{background:`${C.yellow}15`,borderRadius:6,padding:"8px 12px"}}>
                      <p style={{fontSize:11,color:C.muted}}>Anterior: <strong>{prev}%</strong> → Este período: <strong>+{periodo.toFixed(1)}%</strong></p>
                      <p style={{fontSize:16,fontWeight:800,color:C.yellow,marginTop:2}}>{fmt(val)}</p>
                    </div>
                  );
                })()}
              </div>
            )}

            {/* Livre */}
            {form.tipo==="livre"&&(
              <Inp label="Valor previsto (R$)" type="number" value={form.valorPrevisto} onChange={F("valorPrevisto")} placeholder="0,00"/>
            )}

            {/* Recebido? */}
            <label style={{display:"flex",alignItems:"center",gap:10,cursor:"pointer",padding:"8px 12px",background:form.recebido?`${C.green}10`:"transparent",borderRadius:6,border:`1.5px solid ${form.recebido?C.green+"55":C.border}`}}>
              <div onClick={()=>F("recebido")(!form.recebido)} style={{width:20,height:20,border:`2px solid ${form.recebido?C.green:C.muted}`,background:form.recebido?C.green:"transparent",borderRadius:4,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,cursor:"pointer"}}>
                {form.recebido&&<span style={{color:"#fff",fontSize:13,fontWeight:900}}>ok</span>}
              </div>
              <p style={{fontSize:13,fontWeight:700,color:form.recebido?C.green:C.muted}}>Valor já recebido</p>
            </label>

            {form.recebido&&(<>
              <Inp label="Valor efetivamente recebido (R$)" type="number" value={form.valorRecebido} onChange={F("valorRecebido")} placeholder={String(formPrevisto||"")}/>
              <Inp label="Data de recebimento" type="date" value={form.dataPagamento} onChange={F("dataPagamento")}/>
            </>)}

            <Inp label="Descrição / observação" value={form.descricao} onChange={F("descricao")} placeholder="Ex.: Medição #3, Parcela março..."/>

            {formPrevisto>0&&(
              <div style={{background:`${C.yellow}15`,border:`1px solid ${C.yellow}44`,borderRadius:6,padding:"8px 14px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <p style={{fontSize:11,color:C.muted}}>Valor que será registrado</p>
                <p style={{fontSize:18,fontWeight:800,color:C.yellow}}>{fmt(formPrevisto)}</p>
              </div>
            )}

            <div style={{display:"flex",gap:8}}>
              <Btn v="ghost" onClick={()=>setModal(false)} full>Cancelar</Btn>
              <Btn onClick={saveMedicao} full><Ic n="check"/> Salvar medição</Btn>
            </div>
          </div>
        </Modal>
      )}

      {/* Modal: conciliar parcelas que nasceram vencidas */}
      {conciliar && (() => {
        const m = (data.medicoes||[]).find(x => x.id === conciliar.fila[conciliar.idx]);
        if (!m) return null;
        const diasAtraso = Math.max(0, Math.round(
          (new Date(today()) - new Date(m.dataVencimento)) / 86400000));
        const Opcao = ({ v, titulo, sub, cor }) => (
          <label onClick={()=>setConciliar(c=>({...c,modo:v}))}
                 style={{display:"flex",alignItems:"flex-start",gap:10,cursor:"pointer",padding:"10px 12px",
                         background: conciliar.modo===v ? `${cor}12` : C.surface,
                         border:`1.5px solid ${conciliar.modo===v ? cor : C.border}`,borderRadius:6}}>
            <div style={{width:18,height:18,borderRadius:"50%",flexShrink:0,marginTop:1,
                         border:`2px solid ${conciliar.modo===v?cor:C.muted}`,display:"flex",alignItems:"center",justifyContent:"center"}}>
              {conciliar.modo===v && <div style={{width:9,height:9,borderRadius:"50%",background:cor}}/>}
            </div>
            <div>
              <p style={{fontSize:13,fontWeight:700,color:conciliar.modo===v?cor:C.text}}>{titulo}</p>
              <p style={{fontSize:11,color:C.muted,marginTop:2,lineHeight:1.5}}>{sub}</p>
            </div>
          </label>
        );
        return (
          <Modal title={`Parcela vencida ${conciliar.idx+1} de ${conciliar.fila.length}`} onClose={()=>setConciliar(null)}>
            <div style={{display:"flex",flexDirection:"column",gap:12}}>
              <div style={{background:C.surface,border:`1px solid ${C.border}`,borderLeft:`3px solid ${C.red||"#C62828"}`,borderRadius:6,padding:"11px 13px"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"baseline",gap:8}}>
                  <p style={{fontSize:13,fontWeight:800,color:C.text}}>{obra?.name}</p>
                  <p style={{fontSize:15,fontWeight:800,color:C.yellow}}>{fmt(m.valorPrevisto)}</p>
                </div>
                <p style={{fontSize:11.5,color:C.muted,marginTop:3,lineHeight:1.5}}>
                  {m.descricao || "Parcela"}<br/>
                  Venceu em <b>{fmtDate(m.dataVencimento)}</b>{diasAtraso>0 && ` - há ${diasAtraso} dia(s)`}
                </p>
              </div>

              <p style={{fontSize:12.5,fontWeight:700,color:C.text}}>
                O pagamento foi realizado no dia do contrato?
              </p>

              <Opcao v="vencimento" cor={C.green}
                     titulo={`Sim - pago em ${fmtDate(m.dataVencimento)}`}
                     sub="Registra o recebimento na própria data de vencimento do contrato."/>
              <Opcao v="outra" cor={C.yellow}
                     titulo="Pago, mas em outra data"
                     sub="Use quando o dinheiro entrou fora do dia combinado."/>
              {conciliar.modo === "outra" && (
                <Inp label="Data real do pagamento *" type="date" value={conciliar.dataOutra}
                     onChange={v=>setConciliar(c=>({...c,dataOutra:v}))}/>
              )}
              <Opcao v="aberto" cor={C.muted}
                     titulo="Ainda não foi paga"
                     sub="A parcela continua em aberto e aparece como vencida no painel."/>

              <div style={{display:"flex",gap:8}}>
                <Btn v="ghost" onClick={()=>setConciliar(null)} full>Decidir depois</Btn>
                <Btn onClick={()=>conciliarAplicar()} full><Ic n="check"/> Confirmar</Btn>
              </div>
              {conciliar.fila.length - conciliar.idx > 1 && (
                <button onClick={conciliarTodasNoVencimento}
                        style={{background:"transparent",border:0,color:C.muted,fontSize:11,fontWeight:600,cursor:"pointer",textDecoration:"underline",padding:0}}>
                  Todas as {conciliar.fila.length - conciliar.idx} restantes foram pagas no vencimento
                </button>
              )}
            </div>
          </Modal>
        );
      })()}

      {/* Modal: gerar parcelas automáticas */}
      {/* Confirmar recebimento perguntando a DATA DE PAGAMENTO */}
      {pagarModal && (
        <Modal title="Confirmar recebimento" onClose={()=>setPagarModal(null)}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,padding:"11px 13px"}}>
              <p style={{fontSize:13,fontWeight:700,color:C.text}}>{pagarModal.m.obraName}</p>
              <p style={{fontSize:12,color:C.muted,marginTop:2}}>
                {fmt(pagarModal.m.valorPrevisto)}
                {pagarModal.m.descricao ? ` - ${pagarModal.m.descricao}` : ""}
              </p>
            </div>
            <Inp label="Data do pagamento *" type="date" value={pagarModal.data}
                 onChange={v=>setPagarModal(p=>({...p,data:v}))}/>
            {/* Atalho: o caso mais comum e o pagamento ter saido no dia combinado. */}
            {pagarModal.m.dataVencimento && pagarModal.data !== pagarModal.m.dataVencimento && (
              <button onClick={()=>setPagarModal(p=>({...p,data:p.m.dataVencimento}))}
                      style={{alignSelf:"flex-start",background:"transparent",border:`1px solid ${C.yellow}`,color:C.yellow,
                              padding:"4px 10px",borderRadius:4,fontSize:11,fontWeight:700,cursor:"pointer"}}>
                Pagou no dia do contrato ({fmtDate(pagarModal.m.dataVencimento)})
              </button>
            )}
            <p style={{fontSize:10.5,color:C.muted,lineHeight:1.5}}>
              Informe quando o valor efetivamente entrou. Costuma ser diferente do dia
              em que voce confirma aqui.
            </p>
            <div style={{display:"flex",gap:8}}>
              <Btn v="ghost" onClick={()=>setPagarModal(null)} full>Cancelar</Btn>
              <Btn v="success" onClick={()=>{
                const m = pagarModal.m;
                const updated = { ...m, recebido:true, valorRecebido:m.valorPrevisto, dataPagamento: pagarModal.data || today() };
                update({ ...data, medicoes:(data.medicoes||[]).map(x=>x.id===m.id?updated:x) });
                showToast(`${m.obraName} - ${fmt(m.valorPrevisto)} recebido em ${fmtDate(pagarModal.data||today())}.`);
                setPagarModal(null);
              }} full><Ic n="check"/> Confirmar</Btn>
            </div>
          </div>
        </Modal>
      )}

      {gerarModal && obra && (
        <Modal title="Gerar parcelas automaticamente" onClose={()=>setGerarModal(false)}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div style={{background:C.surface,border:`1.5px solid ${C.border}`,borderRadius:6,padding:"12px 14px"}}>
              <p style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:6}}>{obra.name}</p>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>
                {[
                  ["Parcela mensal",  fmt(obra.parcelaMensal)],
                  ["Total parcelas",  `${obra.totalParcelas||"-"}`],
                  ["Início",          fmtDateFull(obra.contractStart)],
                  ["Fim previsto",    obra.contractEnd?fmtDateFull(obra.contractEnd):"-"],
                ].map(([l,v])=>(
                  <div key={l}>
                    <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>{l}</p>
                    <p style={{fontSize:13,fontWeight:700,color:C.text,marginTop:1}}>{v}</p>
                  </div>
                ))}
              </div>
              <div style={{marginTop:10,padding:"8px 0",borderTop:`1px solid ${C.line}`}}>
                <p style={{fontSize:13,color:C.text,fontWeight:700}}>
                  Total gerado: {fmt(Number(obra.parcelaMensal)*(obra.totalParcelas||12))}
                </p>
                <p style={{fontSize:11,color:C.muted,marginTop:2}}>
                  {obra.totalParcelas||12} parcelas de {fmt(obra.parcelaMensal)}
                </p>
              </div>
            </div>

            <label style={{display:"flex",alignItems:"center",gap:10,cursor:"pointer",padding:"10px 12px",background:C.surface,borderRadius:6,border:`1.5px solid ${C.border}`}}>
              <div onClick={()=>setGerarOpts(o=>({...o,sobreescrever:!o.sobreescrever}))} style={{width:18,height:18,border:`2px solid ${gerarOpts.sobreescrever?C.red:C.muted}`,background:gerarOpts.sobreescrever?C.red:"transparent",borderRadius:4,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",flexShrink:0}}>
                {gerarOpts.sobreescrever&&<span style={{color:"#fff",fontSize:11,fontWeight:900}}>ok</span>}
              </div>
              <div>
                <p style={{fontSize:13,fontWeight:700,color:gerarOpts.sobreescrever?C.red:C.muted}}>Substituir medições existentes</p>
                <p style={{fontSize:11,color:C.muted}}>Se desmarcado, pula meses que já têm medição</p>
              </div>
            </label>

            <div style={{display:"flex",gap:8}}>
              <Btn v="ghost" onClick={()=>setGerarModal(false)} full>Cancelar</Btn>
              <Btn v="primary" onClick={gerarParcelasFixas} full> Gerar {obra.totalParcelas||12} parcelas</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// 
// FINANCEIRO - KPIs por obra, receitas e contratos
// 

function Financeiro({ data, update, showToast }) {
  const now = new Date();
  const [year,  setYear]  = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth());
  const [filterObra, setFilterObra] = useState("all");
  const [expanded, setExpanded] = useState(null);
  const [payModal, setPayModal] = useState(false);
  const [payForm, setPayForm] = useState({ obraId:"", date:today(), amount:"", description:"" });
  const PF = k => v => setPayForm(f=>({...f,[k]:v}));

  const days = getDays(year, month);
  const years = Array.from({length:4},(_,i)=>now.getFullYear()-1+i).map(y=>({v:String(y),l:String(y)}));

  // Calcula KPIs por obra - inclui terceirizados
  const periodStart = days[0] || "";
  const periodEnd   = days[days.length-1] || "";

  const obraRows = useMemo(() => data.obras
    .filter(o => filterObra==="all" || o.id===filterObra)
    .map(o => {
      const {laborCost, benefitCost, totalCost} = calcObraLaborCost(data, o.id, days);
      const tercCost = calcObraTercCost(data, o.id, periodStart, periodEnd);
      const totalLaborAll = laborCost + tercCost;
      const {revenue, margin: marginMO, marginPct: marginPctMO, commitment} = calcObraRevenue(o, laborCost);
      const marginReal = revenue - totalLaborAll;
      const marginRealPct = revenue > 0 ? (marginReal/revenue)*100 : 0;
      const received = (data.payments||[])
        .filter(p => p.obraId===o.id && p.date && p.date.slice(0,7)===`${year}-${String(month+1).padStart(2,"0")}`)
        .reduce((s,p)=>s+Number(p.amount||0), 0);
      const receivedTotal = (data.payments||[])
        .filter(p => p.obraId===o.id)
        .reduce((s,p)=>s+Number(p.amount||0), 0);
      const activeEmps = data.employees.filter(e=>e.active!==false&&e.obra===o.id).length;
      const activeTercCount = (data.terceirizados||[]).filter(t=>t.active!==false&&t.obraId===o.id).length;
      return {
        ...o, laborCost, benefitCost, totalCost, tercCost, totalLaborAll,
        revenue, margin: marginReal, marginPct: marginRealPct, marginMO, marginPctMO,
        commitment, received, receivedTotal, activeEmps, activeTercCount,
      };
    }), [data, filterObra, days, year, month, periodStart, periodEnd]);

  const T = useMemo(() => ({
    revenue:  obraRows.reduce((s,r)=>s+r.revenue,      0),
    labor:    obraRows.reduce((s,r)=>s+r.laborCost,     0),
    terc:     obraRows.reduce((s,r)=>s+r.tercCost,      0),
    margin:   obraRows.reduce((s,r)=>s+r.margin,        0),
    received: obraRows.reduce((s,r)=>s+r.received,      0),
  }), [obraRows]);
  const totalMarginPct = T.revenue>0 ? (T.margin/T.revenue)*100 : 0;

  // Receitas do período filtrado
  const allPayments = (data.payments||[])
    .filter(p => (filterObra==="all"||p.obraId===filterObra))
    .sort((a,b)=>b.date.localeCompare(a.date));

  // Gráfico: receita vs custo MO por obra
  const chartData = obraRows.map(r=>({
    name: r.name.length>12 ? r.name.slice(0,12)+"..." : r.name,
    Receita: Math.round(r.revenue),
    CustoMO: Math.round(r.laborCost),
    Margem:  Math.round(r.margin),
  }));

  // Grafico: recebimentos e custos por QUINZENA (ultimos 4 meses = 8 quinzenas).
  // Como o pagamento e quinzenal, o grafico segue a mesma cadencia - cada ponto
  // e a 1a ou 2a quinzena de um mes. Recebido e Terceiros entram pela data real
  // do lancamento; o custo de MO e rateado por dias trabalhados na quinzena.
  const quinzenalChart = useMemo(() => {
    const pontos = [];
    for (let i = 3; i >= 0; i--) {
      const d = new Date(year, month - i, 1);
      const y = d.getFullYear(), m = d.getMonth();
      const { q1, q2 } = getQ(y, m);
      [["1", q1], ["2", q2]].forEach(([qn, dias]) => {
        const datasDoCiclo=new Set(dias);
        const naQuinzena = iso => !!iso && datasDoCiclo.has(iso);
        const rec = (data.payments||[])
          .filter(p => (filterObra==="all"||p.obraId===filterObra) && naQuinzena(p.date))
          .reduce((s,p)=>s+Number(p.amount||0),0);
        const terc = (data.pagsTerceiros||[])
          .filter(p => (filterObra==="all"||p.obraId===filterObra) && naQuinzena(p.date))
          .reduce((s,p)=>s+Number(p.amount||0),0);
        const cost = data.obras
          .filter(o => filterObra==="all"||o.id===filterObra)
          .reduce((s,o)=>s+calcObraLaborCost(data,o.id,dias).laborCost,0);
        pontos.push({
          mes: `${qn}a ${monthName(m)}/${String(y).slice(2)}`,
          Recebido: Math.round(rec), CustoMO: Math.round(cost), Terceiros: Math.round(terc),
        });
      });
    }
    return pontos;
  }, [data, year, month, filterObra]);

  const savePayment = () => {
    if(!payForm.obraId||!payForm.amount||isNaN(Number(payForm.amount))){
      showToast("Preencha obra, data e valor.","error"); return;
    }
    const payments=[...(data.payments||[]),{id:uid(),obraId:payForm.obraId,date:payForm.date,amount:Number(payForm.amount),description:payForm.description||"Recebimento"}];
    update({...data,payments});
    setPayModal(false);
    setPayForm({obraId:"",date:today(),amount:"",description:""});
    showToast("Recebimento registrado.");
  };

  const removePayment = id => {
    if(!window.confirm("Remover recebimento?")) return;
    update({...data,payments:(data.payments||[]).filter(p=>p.id!==id)});
    showToast("Removido.");
  };

  const exportXLS = () => {
    const wb=XLSX.utils.book_new();
    // Aba KPIs
    const h1=["Obra","Tipo Contrato","Valor Contrato","Custo MO","Custo MO+Ben","Receita Esperada","Margem","Margem %","Recebido (mês)","Comprometimento %"];
    const b1=obraRows.map(r=>[r.name,CONTRACT_LABELS[r.contractType]||r.contractType,r.contractValue,r.laborCost,r.totalCost,r.revenue,r.margin,r.marginPct.toFixed(1)+"%",r.received,r.commitment!=null?r.commitment.toFixed(1)+"%":"-"]);
    const ws1=XLSX.utils.aoa_to_sheet([[`KPIs Financeiros - ${fullMonth(month)} ${year}`],[],h1,...b1,["TOTAL","","",T.labor,"",T.revenue,T.margin,(totalMarginPct).toFixed(1)+"%",T.received,""]]);
    ws1["!cols"]=[22,16,14,12,14,16,12,10,14,14].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb,ws1,"KPIs por Obra");
    // Aba recebimentos
    const h2=["Data","Obra","Valor","Descrição"];
    const b2=allPayments.map(p=>[p.date,data.obras.find(o=>o.id===p.obraId)?.name||"-",p.amount,p.description]);
    const ws2=XLSX.utils.aoa_to_sheet([["Recebimentos registrados"],[],h2,...b2]);
    ws2["!cols"]=[12,22,12,30].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb,ws2,"Recebimentos");
    XLSX.writeFile(wb,`arcd-financeiro-${year}-${String(month+1).padStart(2,"0")}.xlsx`);
    showToast("Excel exportado.");
  };

  const obraName = id => data.obras.find(o=>o.id===id)?.name||"-";

  const StatusBar = ({pct, color=C.green}) => (
    <div style={{height:6,background:C.surface,borderRadius:99,overflow:"hidden",marginTop:6}}>
      <div style={{height:"100%",width:`${Math.min(pct,100)}%`,background:pct>100?C.red:color,borderRadius:99,transition:"width .3s"}}/>
    </div>
  );

  return (
    <div className="anim" style={{display:"flex",flexDirection:"column",gap:14}}>
      {/* Header */}
      <div style={{
        background:`linear-gradient(135deg,${C.green}22 0%,${C.card} 60%)`,
        border:`1px solid ${C.green}44`,borderLeft:`5px solid ${C.green}`,
        padding:"16px 18px",borderRadius:12,
      }}>
        <p style={{fontSize:11,fontWeight:900,color:C.green,textTransform:"uppercase",letterSpacing:1.2,marginBottom:4}}>Gestão financeira</p>
        <h2 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(19px,5vw,34px)",letterSpacing:2,color:C.text,lineHeight:1}}>Financeiro por Obra</h2>
        <p style={{color:C.muted,fontSize:13,marginTop:4}}>KPIs de margem, contrato, custo MO e recebimentos.</p>
      </div>

      {/* Filtros */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Sel value={String(year)} onChange={v=>setYear(Number(v))} options={years}/>
        <Sel value={String(month)} onChange={v=>setMonth(Number(v))} options={Array.from({length:12},(_,i)=>({v:String(i),l:fullMonth(i)}))}/>
      </div>
      <Sel value={filterObra} onChange={setFilterObra} options={[{v:"all",l:"Todas as obras"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>

      {/* KPI totais */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8}}>
        {[
          ["Receita esperada", fmt(T.revenue),                C.green,  "dollar"],
          ["Recebido",         fmt(T.received),               C.blue,   "check"],
          ["Custo MO própria", fmt(T.labor),                  C.orange, "users"],
          ["Custo terceiros",  fmt(T.terc),                   C.purple, "terc"],
          ["Total trabalho",   fmt(T.labor+T.terc),           C.red,    "users"],
          ["Margem real",      `${fmt(T.margin)} (${totalMarginPct.toFixed(0)}%)`, T.margin>=0?C.green:C.red, "chart"],
        ].map(([l,v,c,ic])=>(
          <div key={l} style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${c}`,padding:"12px 14px",borderRadius:10}}>
            <p style={{fontSize:10,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:.8}}>{l}</p>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,color:c,fontSize:22,lineHeight:1.1,marginTop:4,letterSpacing:.5}}>{v}</p>
          </div>
        ))}
      </div>

      {/* Gráfico receita vs custo */}
      {chartData.length>0 && (
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:14,borderRadius:12}}>
          <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.yellow,textTransform:"uppercase",marginBottom:10}}>Receita vs Custo MO por obra</p>
          <div style={{height:220}}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} barSize={14}>
                <CartesianGrid stroke={C.border} vertical={false}/>
                <XAxis dataKey="name" stroke={C.muted} fontSize={10}/>
                <YAxis stroke={C.muted} fontSize={10} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v}/>
                <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text,borderRadius:8}} formatter={v=>fmt(v)}/>
                <Bar dataKey="Receita" fill={C.green} radius={[6,6,0,0]}/>
                <Bar dataKey="CustoMO" fill={C.orange} radius={[6,6,0,0]}/>
                <Bar dataKey="Margem"  fill={C.blue}   radius={[6,6,0,0]}/>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* Gráfico mensal recebimentos vs custo */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,padding:14,borderRadius:12}}>
        <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:15,color:C.yellow,textTransform:"uppercase",marginBottom:10}}>Recebimentos x Custos - por quinzena</p>
        <div style={{height:200}}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={quinzenalChart}>
              <CartesianGrid stroke={C.border} vertical={false}/>
              <XAxis dataKey="mes" stroke={C.muted} fontSize={10}/>
              <YAxis stroke={C.muted} fontSize={10} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v}/>
              <Tooltip contentStyle={{background:C.card,border:`1px solid ${C.border}`,color:C.text,borderRadius:8}} formatter={v=>fmt(v)}/>
              <Line type="monotone" dataKey="Recebido"   stroke={C.green}  strokeWidth={2} dot={{r:3,fill:C.green}}/>
              <Line type="monotone" dataKey="CustoMO"    stroke={C.orange} strokeWidth={2} dot={{r:3,fill:C.orange}}/>
              <Line type="monotone" dataKey="Terceiros"  stroke={C.purple} strokeWidth={2} dot={{r:3,fill:C.purple}} strokeDasharray="4 2"/>
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Fluxo de caixa */}
      <FluxoCaixa data={data}/>

      {/* Cards por obra */}
      <p style={{fontSize:10,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:1}}>Análise por obra - {fullMonth(month)} {year}</p>
      {obraRows.map(r => {
        const exp = expanded===r.id;
        const marginColor = r.margin>=0 ? C.green : C.red;
        const commitColor = r.commitment!=null&&r.commitment>100 ? C.red : r.commitment!=null&&r.commitment>80 ? C.orange : C.green;
        return (
          <div key={r.id} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
            <button onClick={()=>setExpanded(exp?null:r.id)} style={{
              width:"100%",background:"transparent",border:0,color:C.text,
              padding:"14px 16px",textAlign:"left",cursor:"pointer",
              borderLeft:`5px solid ${marginColor}`,
            }}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
                <div style={{flex:1}}>
                  <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:18,letterSpacing:.3}}>{r.name}</p>
                  <div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:4}}>
                    <Badge color={C.yellow}>{CONTRACT_LABELS[r.contractType]||r.contractType}</Badge>
                    {r.contractValue>0 && <Badge color={C.subtle}>Contrato: {fmt(r.contractValue)}</Badge>}
                    <Badge color={C.muted}>{r.activeEmps} MO  {r.activeTercCount} terceiros</Badge>
                  </div>
                </div>
                <div style={{textAlign:"right",flexShrink:0}}>
                  <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:22,color:r.margin>=0?C.green:C.red,letterSpacing:.5,lineHeight:1}}>{fmt(r.margin)}</p>
                  <p style={{fontSize:10,color:C.muted,marginTop:2}}>margem real {r.marginPct.toFixed(0)}%</p>
                </div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6,marginTop:10}}>
                {[
                  ["Receita",fmt(r.revenue),C.green],
                  ["Custo MO",fmt(r.laborCost),C.orange],
                  ["Recebido",fmt(r.received),C.blue],
                ].map(([l,v,c])=>(
                  <div key={l} style={{background:C.surface,padding:"6px 8px",borderRadius:8}}>
                    <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>{l}</p>
                    <p style={{fontSize:13,fontWeight:900,color:c}}>{v}</p>
                  </div>
                ))}
              </div>
              {r.commitment!=null && (
                <div style={{marginTop:8}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}>
                    <p style={{fontSize:10,color:C.muted}}>Comprometimento do contrato</p>
                    <p style={{fontSize:10,fontWeight:900,color:commitColor}}>{r.commitment.toFixed(1)}%</p>
                  </div>
                  <StatusBar pct={r.commitment} color={commitColor}/>
                </div>
              )}

              {/* Prazo da obra + evolucao financeira (% recebido do contrato) */}
              {(() => {
                const prz = prazoObra(r);
                const evoFin = r.contractValue > 0 ? (r.receivedTotal / r.contractValue) * 100 : null;
                if (!prz && evoFin == null) return null;
                return (
                  <div style={{marginTop:8,display:"flex",flexDirection:"column",gap:8}}>
                    {prz && (
                      <div>
                        <div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}>
                          <p style={{fontSize:10,color:C.muted}}>Prazo da obra</p>
                          <p style={{fontSize:10,fontWeight:900,color:prz.cor}}>{prz.rotulo}</p>
                        </div>
                        <StatusBar pct={prz.pct} color={prz.cor}/>
                        <p style={{fontSize:9,color:C.muted,marginTop:2}}>
                          {fmtDate(r.contractStart)}{r.contractEnd ? ` a ${fmtDate(r.contractEnd)}` : ""}
                        </p>
                      </div>
                    )}
                    {evoFin != null && (
                      <div>
                        <div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}>
                          <p style={{fontSize:10,color:C.muted}}>Evolucao financeira (recebido / contrato)</p>
                          <p style={{fontSize:10,fontWeight:900,color:C.green}}>{evoFin.toFixed(1)}%</p>
                        </div>
                        <StatusBar pct={Math.min(evoFin,100)} color={C.green}/>
                        <p style={{fontSize:9,color:C.muted,marginTop:2}}>
                          {fmt(r.receivedTotal)} de {fmt(r.contractValue)}
                          {prz && Math.abs(evoFin - prz.pct) >= 12 && (
                            <span style={{color: evoFin < prz.pct ? C.red : C.orange, fontWeight:700}}>
                              {" - "}{evoFin < prz.pct ? "recebimento atras do prazo" : "recebimento adiantado"}
                            </span>
                          )}
                        </p>
                      </div>
                    )}
                  </div>
                );
              })()}
            </button>

            {exp && (
              <div style={{borderTop:`1px solid ${C.line}`,padding:"14px 16px",background:C.surface,display:"flex",flexDirection:"column",gap:10}}>
                <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
                  {[
                    ["Contrato",fmt(r.contractValue),C.subtle],
                    ["Admin %",r.adminPercentage>0?`${r.adminPercentage}%`:"-",C.subtle],
                    ["Área",r.areaM2>0?`${r.areaM2.toLocaleString("pt-BR")} m`:"-",C.subtle],
                    ["Custo MO própria",fmt(r.laborCost),C.orange],
                    ["Custo terceiros",fmt(r.tercCost),C.purple],
                    ["Total trabalho",fmt(r.totalLaborAll),C.red],
                    ["Benefícios",fmt(r.benefitCost),C.muted],
                    ["Total recebido",fmt(r.receivedTotal),C.blue],
                    ["Margem s/ terc",fmt(r.marginMO),r.marginMO>=0?C.yellow:C.red],
                    ["Receita",fmt(r.revenue),C.green],
                    ["Margem real",fmt(r.margin),r.margin>=0?C.green:C.red],
                    ["Saldo contrato",fmt(r.contractValue-r.laborCost),r.contractValue-r.laborCost>=0?C.green:C.red],
                  ].map(([l,v,c])=>(
                    <div key={l} style={{background:C.card,border:`1px solid ${C.border}`,padding:"8px 10px",borderRadius:8}}>
                      <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700,marginBottom:3}}>{l}</p>
                      <p style={{fontSize:13,fontWeight:900,color:c}}>{v}</p>
                    </div>
                  ))}
                </div>
                {r.contractType==="fixed_labor_admin"&&<p style={{fontSize:11,color:C.muted,fontStyle:"italic"}}>Receita = Contrato ({fmt(r.contractValue)}) + {r.adminPercentage}% sobre MO ({fmt(r.laborCost)})</p>}
                {r.contractType==="admin_only"&&<p style={{fontSize:11,color:C.muted,fontStyle:"italic"}}>Receita = {r.adminPercentage}% sobre MO total ({fmt(r.laborCost)})</p>}
                {r.contractType==="fixed_labor"&&<p style={{fontSize:11,color:C.muted,fontStyle:"italic"}}>Receita = valor fixo do contrato ({fmt(r.contractValue)})</p>}
              </div>
            )}
          </div>
        );
      })}
      {obraRows.length===0&&<div style={{textAlign:"center",padding:"32px 0",color:C.muted}}>Nenhuma obra com dados no período.</div>}

      {/* Recebimentos */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:4}}>
        <p style={{fontSize:10,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:1}}>Recebimentos registrados</p>
        <Btn onClick={()=>setPayModal(true)} size="sm"><Ic n="plus"/> Novo</Btn>
      </div>

      {allPayments.length===0&&<div style={{background:C.card,border:`1px solid ${C.border}`,padding:"20px",textAlign:"center",color:C.muted,borderRadius:10}}>Nenhum recebimento registrado ainda.</div>}
      {allPayments.map(p=>(
        <div key={p.id} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`4px solid ${C.green}`,padding:"12px 14px",borderRadius:10,display:"flex",justifyContent:"space-between",alignItems:"center",gap:10}}>
          <div>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:16}}>{p.description}</p>
            <p style={{color:C.muted,fontSize:12}}>{obraName(p.obraId)}  {fmtDateFull(p.date)}</p>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:20,color:C.green,letterSpacing:.5}}>{fmt(p.amount)}</p>
            <Btn v="danger" size="sm" onClick={()=>removePayment(p.id)}><Ic n="trash"/></Btn>
          </div>
        </div>
      ))}

      <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Exportar Excel (KPIs + Recebimentos)</Btn>

      {payModal&&(
        <Modal title="Registrar recebimento" onClose={()=>setPayModal(false)}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <Sel label="Obra *" value={payForm.obraId} onChange={PF("obraId")} options={[{v:"",l:"Selecione a obra"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>
            <Inp label="Data *" type="date" value={payForm.date} onChange={PF("date")}/>
            <Inp label="Valor recebido (R$) *" type="number" value={payForm.amount} onChange={PF("amount")} placeholder="0,00"/>
            <Inp label="Descrição" value={payForm.description} onChange={PF("description")} placeholder="Ex.: Medição #1, parcela 50%..."/>
            <div style={{display:"flex",gap:8}}>
              <Btn v="ghost" onClick={()=>setPayModal(false)} full>Cancelar</Btn>
              <Btn v="success" onClick={savePayment} full><Ic n="check"/> Salvar</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// 
// Obras
// 

function Obras({ data, update, showToast, onAbrirObra }) {
  const { formGrid } = useBreakpoint();
  const empty = { id: "", name: "", cliente: "", address: "", engineer: "", startDate: "", faseId: "", status: "active", areaM2: "", contractType: "fixed_labor", contractValue: "", adminPercentage: "", billingType: "mensal_fixo", parcelaMensal: "", contractStart: "", contractEnd: "", totalParcelas: "", billingFrequency: "mensal", diaVenc1: String(DIA_VENC_1_PADRAO), diaVenc2: String(DIA_VENC_2_PADRAO), entrada: "", entradaDate: "", hasCaixa: false };
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState(empty);
  const [search, setSearch] = useState("");

  //  Kanban 
  const [vista,      setVista]      = useState("lista");   // "lista" | "quadro"
  const [faseModal,  setFaseModal]  = useState(null);      // {modo:"nova"|"editar", fase}
  const [faseNome,   setFaseNome]   = useState("");
  const [faseCor,    setFaseCor]    = useState(CORES_FASE[0]);
  const [arrastando, setArrastando] = useState(null);      // id da obra em arraste
  const [sobreFase,  setSobreFase]  = useState(null);      // id da coluna sob o cursor
  const [menuCard,   setMenuCard]   = useState(null);      // id da obra c/ menu aberto

  const fases = useMemo(
    () => [...(data.fases || [])].sort((a, b) => a.ordem - b.ordem),
    [data.fases]
  );

  // Obras agrupadas por fase. Quem não tem fase (ou aponta pra uma fase
  // apagada) cai na primeira coluna - nenhuma obra some do quadro.
  const porFase = useMemo(() => {
    const idsValidos = new Set(fases.map(f => f.id));
    const primeira = fases[0]?.id || "";
    const mapa = {};
    fases.forEach(f => { mapa[f.id] = []; });
    (data.obras || []).forEach(o => {
      const alvo = idsValidos.has(o.faseId) ? o.faseId : primeira;
      if (mapa[alvo]) mapa[alvo].push(o);
    });
    // Ordena cada coluna pela data de finalizacao prevista (contractEnd).
    // Obras sem data prevista vao para o fim da coluna.
    Object.keys(mapa).forEach(k => {
      mapa[k].sort((a, b) => {
        const fa = a.contractEnd || "9999-12-31";
        const fb = b.contractEnd || "9999-12-31";
        return fa.localeCompare(fb);
      });
    });
    return mapa;
  }, [data.obras, fases]);

  // Total efetivamente renderizado no quadro. Se divergir de data.obras.length,
  // alguma obra ficou de fora - e o resumo acusa em vermelho.
  const somaQuadro = useMemo(
    () => Object.values(porFase).reduce((s, arr) => s + arr.length, 0),
    [porFase]
  );

  const moverObra = (obraId, faseId) => {
    const obra = (data.obras || []).find(o => o.id === obraId);
    if (!obra || obra.faseId === faseId) return;
    const fase = fases.find(f => f.id === faseId);
    update({
      ...data,
      obras: data.obras.map(o => o.id === obraId ? { ...o, faseId } : o),
    });
    setMenuCard(null);
    showToast(`"${obra.name}" movida para ${fase?.nome || "-"}.`);
  };

  //  Fases: criar / renomear / excluir / reordenar 
  const abrirNovaFase = () => {
    setFaseModal({ modo: "nova", fase: null });
    setFaseNome("");
    setFaseCor(CORES_FASE[fases.length % CORES_FASE.length]);
  };
  const abrirEditarFase = (fase) => {
    setFaseModal({ modo: "editar", fase });
    setFaseNome(fase.nome);
    setFaseCor(fase.cor);
  };

  const salvarFase = () => {
    if (!faseNome.trim()) { showToast("Informe o nome da fase.", "error"); return; }
    const { modo, fase } = faseModal;
    if (modo === "editar") {
      update({ ...data, fases: (data.fases || []).map(f =>
        f.id === fase.id ? { ...f, nome: faseNome.trim(), cor: faseCor } : f) });
      showToast("Fase atualizada.");
    } else {
      const ordem = fases.length ? Math.max(...fases.map(f => f.ordem)) + 1 : 0;
      update({ ...data, fases: [...(data.fases || []),
        { id: uid(), nome: faseNome.trim(), cor: faseCor, ordem }] });
      showToast("Fase criada.");
    }
    setFaseModal(null); setFaseNome("");
  };

  const excluirFase = (fase) => {
    if (fases.length <= 1) { showToast("O quadro precisa de ao menos uma fase.", "error"); return; }
    const dentro = (porFase[fase.id] || []).length;
    const destino = fases.find(f => f.id !== fase.id);
    const aviso = dentro
      ? `Excluir "${fase.nome}"?\n\nAs ${dentro} obra(s) desta coluna vão para "${destino.nome}". Nenhuma obra é apagada.`
      : `Excluir a fase "${fase.nome}"?`;
    if (!window.confirm(aviso)) return;
    update({
      ...data,
      fases: (data.fases || []).filter(f => f.id !== fase.id),
      // Reaponta as obras órfãs em vez de deixá-las sem coluna
      obras: data.obras.map(o => o.faseId === fase.id ? { ...o, faseId: destino.id } : o),
    });
    showToast("Fase removida.");
  };

  const moverFase = (faseId, dir) => {
    const i = fases.findIndex(f => f.id === faseId);
    const j = i + dir;
    if (i < 0 || j < 0 || j >= fases.length) return;
    const nova = [...fases];
    [nova[i], nova[j]] = [nova[j], nova[i]];
    update({ ...data, fases: nova.map((f, k) => ({ ...f, ordem: k })) });
  };


  const setField = key => value => setForm(f => ({ ...f, [key]: value }));

  const save = () => {
    if (!form.name.trim()) {
      showToast("Nome da obra obrigatório.", "error");
      return;
    }

    const areaM2 = Number(form.areaM2 || 0);

    if (areaM2 < 0) {
      showToast("A metragem quadrada não pode ser negativa.", "error");
      return;
    }

    const payload = {
      ...form,
      id: form.id || uid(),
      areaM2,
      contractValue: Number(form.contractValue || 0),
      adminPercentage: Number(form.adminPercentage || 0),
      parcelaMensal:     Number(form.parcelaMensal     || 0),
      contractStart:     form.contractStart     || "",
      contractEnd:       form.contractEnd       || "",
      totalParcelas:     Number(form.totalParcelas     || 0),
      billingFrequency:  form.billingFrequency  || "mensal",
      diaVenc1:          Number(form.diaVenc1 || DIA_VENC_1_PADRAO),
      diaVenc2:          Number(form.diaVenc2 || DIA_VENC_2_PADRAO),
      entrada:           Number(form.entrada    || 0),
      entradaDate:       form.entradaDate       || "",
      hasCaixa:          !!form.hasCaixa,
      // Obra nova sem fase escolhida entra na primeira coluna do quadro
      faseId:            form.faseId || fases[0]?.id || "",
    };

    const obras = form.id ? data.obras.map(o => (o.id === form.id ? payload : o)) : [...data.obras, payload];
    update({ ...data, obras });
    setModal(false);
    showToast(form.id ? "Obra atualizada." : "Obra cadastrada.");
  };

  const remove = id => {
    if (data.employees.some(e => e.obra === id || e.lastObra === id)) {
      showToast("Não é possível apagar obra com histórico de funcionários.", "error");
      return;
    }
    if (!window.confirm("Remover obra?")) return;
    update({ ...data, obras: data.obras.filter(o => o.id !== id) });
    showToast("Obra removida.");
  };

  const list = data.obras.filter(o => o.name.toLowerCase().includes(search.toLowerCase()));
  const statusMap = {
    active: { l: "Ativa", c: C.green },
    paused: { l: "Pausada", c: C.yellow },
    done: { l: "Concluída", c: C.muted },
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
        <div>
          <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 30, letterSpacing: 2, color: C.yellow }}>Obras</h2>
          <p style={{ color: C.muted, fontSize: 13 }}>{data.obras.length} cadastradas</p>
        </div>
        <Btn onClick={() => { setForm(empty); setModal(true); }}><Ic n="plus" /> Nova</Btn>
      </div>

      {/* Alternador Lista / Quadro */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>
        {[["lista","Lista"],["quadro","Quadro"]].map(([v,l])=>(
          <button key={v} onClick={()=>setVista(v)} style={{
            padding:"8px 4px",
            border:`2px solid ${vista===v?C.yellow:C.border}`,
            background:vista===v?`${C.yellow}12`:"transparent",
            color:vista===v?C.text:C.muted,
            fontFamily:"'Inter Display','Inter',sans-serif",
            fontWeight:700,fontSize:12,cursor:"pointer",borderRadius:6,
          }}>{l}</button>
        ))}
      </div>

      {/*  QUADRO (KANBAN)  */}
      {vista === "quadro" && (<>

        {/* Conferência: a soma das colunas TEM que bater com o total de obras.
            O contador dentro de cada coluna é só daquela coluna - sem este
            resumo, não dá pra saber se alguma obra sumiu ou só está fora da
            tela, numa coluna que exige rolar. */}
        <div style={{
          background:C.surface, border:`1px solid ${C.border}`, borderRadius:6,
          padding:"9px 12px", display:"flex", justifyContent:"space-between",
          alignItems:"center", gap:8, flexWrap:"wrap",
        }}>
          <div>
            <p style={{fontSize:12.5,fontWeight:800,color:C.text,
                       fontFamily:"'Inter Display','Inter',sans-serif"}}>
              {(data.obras||[]).length} obra{(data.obras||[]).length===1?"":"s"} no quadro
            </p>
            <p style={{fontSize:10.5,color:C.muted,marginTop:2}}>
              {fases.filter(f => (porFase[f.id]||[]).length > 0)
                    .map(f => `${(porFase[f.id]||[]).length} em ${f.nome}`)
                    .join("  ") || "nenhuma posicionada"}
            </p>
          </div>
          {somaQuadro !== (data.obras||[]).length && (
            <span style={{fontSize:10.5,fontWeight:800,color:C.red,
                          background:`${C.red}12`,padding:"4px 8px",borderRadius:6}}>
              ! {somaQuadro} exibidas de {(data.obras||[]).length}
            </span>
          )}
        </div>

        <div style={{...KB.scroll, margin:"0 -14px", padding:"0 14px 10px"}}>
          {fases.map((fase, fi) => {
            const obrasDaFase = porFase[fase.id] || [];
            const alvo = sobreFase === fase.id;
            return (
              <div key={fase.id}
                onDragOver={e => { e.preventDefault(); setSobreFase(fase.id); }}
                onDragLeave={() => setSobreFase(s => s===fase.id ? null : s)}
                onDrop={e => {
                  e.preventDefault();
                  if (arrastando) moverObra(arrastando, fase.id);
                  setArrastando(null); setSobreFase(null);
                }}
                style={KB.coluna(fase.cor, alvo)}>

                {/* Cabeçalho da coluna */}
                <div style={{padding:"8px 10px", borderTop:`3px solid ${fase.cor}`, borderTopLeftRadius:8, borderTopRightRadius:8, borderBottom:`1px solid ${C.line}`, position:"sticky", top:0, zIndex:1, background:"inherit"}}>
                  <div style={{display:"flex",alignItems:"center",gap:6}}>
                    <span style={{width:9,height:9,borderRadius:2,background:fase.cor,flexShrink:0}}/>
                    <p style={{
                      flex:1, minWidth:0, fontSize:11, fontWeight:800,
                      textTransform:"uppercase", letterSpacing:.6, color:C.text,
                      overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
                    }}>{fase.nome}</p>
                    <div style={{display:"flex",gap:1,flexShrink:0}}>
                      <button onClick={()=>moverFase(fase.id,-1)} disabled={fi===0} title="Mover coluna p/ esquerda"
                        style={{background:"transparent",border:0,cursor:fi===0?"default":"pointer",
                                color:fi===0?C.line:C.muted,fontSize:10,padding:"0 2px"}}></button>
                      <button onClick={()=>moverFase(fase.id,+1)} disabled={fi===fases.length-1} title="Mover coluna p/ direita"
                        style={{background:"transparent",border:0,cursor:fi===fases.length-1?"default":"pointer",
                                color:fi===fases.length-1?C.line:C.muted,fontSize:10,padding:"0 2px"}}></button>
                      <button onClick={()=>abrirEditarFase(fase)} title="Renomear / cor"
                        style={{background:"transparent",border:0,cursor:"pointer",color:C.muted,fontSize:11,padding:"0 2px"}}></button>
                      <button onClick={()=>excluirFase(fase)} title="Excluir fase"
                        style={{background:"transparent",border:0,cursor:"pointer",color:C.muted,fontSize:14,padding:"0 2px",lineHeight:1}}>x</button>
                    </div>
                  </div>
                  <p style={{fontSize:10,color:C.muted,marginTop:3}}>
                    {obrasDaFase.length} obra{obrasDaFase.length===1?"":"s"}
                  </p>
                </div>

                {/* Cards */}
                <div style={KB.colBody}>
                  {obrasDaFase.map(o => {
                    const st    = statusMap[o.status] || statusMap.active;
                    const count = data.employees.filter(e => e.active!==false && e.obra===o.id).length;
                    const menu  = menuCard === o.id;
                    return (
                      <div key={o.id}
                        draggable
                        onDragStart={() => setArrastando(o.id)}
                        onDragEnd={() => { setArrastando(null); setSobreFase(null); }}
                        style={{
                          ...KB.card(null),
                          borderLeft:`3px solid ${fase.cor}`,
                          opacity: arrastando===o.id ? .4 : 1,
                          position:"relative",
                        }}>
                        <div style={{display:"flex",justifyContent:"space-between",gap:6,alignItems:"flex-start"}}>
                          <p style={{
                            flex:1, minWidth:0,
                            fontFamily:"'Inter Display','Inter',sans-serif",
                            fontSize:12.5, fontWeight:700, color:C.text, lineHeight:1.3,
                          }}>{o.name}</p>
                          <button onClick={()=>setMenuCard(menu ? null : o.id)}
                            style={{background:"transparent",border:0,color:C.muted,cursor:"pointer",
                                    fontSize:13,lineHeight:1,padding:"0 2px",flexShrink:0}}></button>
                        </div>

                        {o.cliente && (
                          <p style={{fontSize:10.5,color:C.subtle,fontWeight:600,marginTop:2}}>{o.cliente}</p>
                        )}
                        {o.engineer && (
                          <p style={{fontSize:10,color:C.muted,marginTop:2}}>Eng. {o.engineer}</p>
                        )}

                        <div style={{display:"flex",alignItems:"center",gap:5,marginTop:6,flexWrap:"wrap"}}>
                          <Badge color={st.c}>{st.l}</Badge>
                          <span style={{fontSize:9.5,color:C.muted,background:C.surface,borderRadius:4,padding:"1px 5px"}}>
                            {CONTRACT_LABELS[o.contractType]||o.contractType}
                          </span>
                          {Number(o.areaM2)>0 && (
                            <span style={{fontSize:9.5,color:C.muted}}>{o.areaM2} m2</span>
                          )}
                          {count>0 && (
                            <span style={{fontSize:9.5,color:C.muted}}>{count} func.</span>
                          )}
                        </div>

                        {Number(o.contractValue)>0 && (
                          <p style={{fontSize:12,fontWeight:800,color:C.yellow,marginTop:6}}>
                            {fmt(o.contractValue)}
                          </p>
                        )}

                        {/* Datas: inicio e finalizacao prevista, com prazo restante */}
                        {(o.contractStart || o.contractEnd) && (() => {
                          const prz = prazoObra(o);
                          return (
                            <div style={{marginTop:5,display:"flex",flexDirection:"column",gap:2}}>
                              <div style={{display:"flex",alignItems:"center",gap:5,fontSize:9.5,color:C.muted}}>
                                <Ic n="calendar" s={11} color={C.muted}/>
                                <span>
                                  {o.contractStart ? fmtDate(o.contractStart) : "?"}
                                  {" a "}
                                  {o.contractEnd ? fmtDate(o.contractEnd) : "?"}
                                </span>
                              </div>
                              {prz && (
                                <span style={{fontSize:9.5,fontWeight:700,color:prz.cor}}>{prz.rotulo}</span>
                              )}
                            </div>
                          );
                        })()}

                        {/* Menu "Mover para" - é o caminho que funciona no celular,
                            onde arrastar (HTML5 drag) simplesmente não existe. */}
                        {menu && (
                          <div style={{
                            position:"absolute", top:28, right:8, zIndex:20,
                            background:C.bg, border:`1.5px solid ${C.border}`,
                            borderRadius:6, boxShadow:`0 6px 20px ${C.shadow}`,
                            minWidth:180, padding:5,
                          }}>
                            <p style={{fontSize:9,fontWeight:800,color:C.muted,textTransform:"uppercase",
                                       letterSpacing:.6,padding:"4px 7px"}}>Mover para</p>
                            {fases.filter(f=>f.id!==fase.id).map(f=>(
                              <button key={f.id} onClick={()=>moverObra(o.id, f.id)} style={{
                                width:"100%", textAlign:"left", display:"flex", alignItems:"center", gap:6,
                                padding:"6px 7px", background:"transparent", border:0,
                                borderRadius:5, cursor:"pointer", fontSize:11.5, color:C.text,
                                fontFamily:"'Inter',sans-serif",
                              }}>
                                <span style={{width:7,height:7,borderRadius:2,background:f.cor,flexShrink:0}}/>
                                {f.nome}
                              </button>
                            ))}
                            <div style={{height:1,background:C.line,margin:"4px 0"}}/>
                            <button onClick={()=>{ setForm({...o, areaM2:String(o.areaM2||""), diaVenc1:String(o.diaVenc1||DIA_VENC_1_PADRAO), diaVenc2:String(o.diaVenc2||DIA_VENC_2_PADRAO)}); setModal(true); setMenuCard(null); }}
                              style={{width:"100%",textAlign:"left",padding:"6px 7px",background:"transparent",
                                      border:0,borderRadius:5,cursor:"pointer",fontSize:11.5,color:C.text,
                                      fontFamily:"'Inter',sans-serif"}}>
                               Editar obra
                            </button>
                          </div>
                        )}
                      </div>
                    );
                  })}

                  {obrasDaFase.length === 0 && (
                    <p style={{fontSize:10.5,color:C.muted,textAlign:"center",padding:"14px 6px"}}>
                      Arraste uma obra pra cá
                    </p>
                  )}
                </div>
              </div>
            );
          })}

          {/* Nova coluna */}
          <div style={{flex:"0 0 168px",minWidth:168}}>
            <button onClick={abrirNovaFase} style={{
              width:"100%", padding:"14px 10px",
              background:"transparent", border:`1.5px dashed ${C.border}`,
              borderRadius:8, cursor:"pointer", color:C.muted,
              fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:700, fontSize:12,
            }}>+ Nova fase</button>
          </div>
        </div>
      </>)}

      {/*  LISTA  */}
      {vista === "lista" && <>
      <Inp value={search} onChange={setSearch} placeholder="Buscar obra..." />

      {list.map(o => {
        const count = data.employees.filter(e => e.active !== false && e.obra === o.id).length;
        const st = statusMap[o.status] || statusMap.active;
        const area = Number(o.areaM2 || 0);
        return (
          <div key={o.id} style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${st.c}`, padding: 14 }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>
              <div>
                <p onClick={() => onAbrirObra && onAbrirObra(o.id)}
                   style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900,
                            fontSize: 18, cursor: onAbrirObra ? "pointer" : "default" }}>{o.name}</p>
                <Badge color={st.c}>{st.l}</Badge>
                {o.contractValue > 0 && <Badge color={C.green}>{CONTRACT_LABELS[o.contractType]||"Contrato"}: {fmt(o.contractValue)}</Badge>}
                {(o.contractType==="fixed_labor_admin"||o.contractType==="admin_only") && o.adminPercentage > 0 && <Badge color={C.purple}>{o.adminPercentage}% admin</Badge>}
                <p style={{ color: C.muted, fontSize: 12, marginTop: 6 }}>{count} trabalhador{count !== 1 ? "es" : ""} ativo{count !== 1 ? "s" : ""}</p>
                {area > 0 && <p style={{ color: C.yellow, fontSize: 12, marginTop: 4 }}>Área: {area.toLocaleString("pt-BR")} m</p>}
                {o.address && <p style={{ color: C.subtle, fontSize: 12, marginTop: 4 }}>{o.address}</p>}
                {o.engineer && <p style={{ color: C.subtle, fontSize: 12 }}>Responsável: {o.engineer}</p>}
                {o.startDate && <p style={{ color: C.subtle, fontSize: 12 }}>Início: {fmtDateFull(o.startDate)}</p>}
              </div>
              <div style={{ display: "flex", gap: 5, alignItems: "flex-start" }}>
                <Btn v="ghost" size="sm" onClick={() => { setForm({ ...o, areaM2: String(o.areaM2 || ""), diaVenc1: String(o.diaVenc1 || DIA_VENC_1_PADRAO), diaVenc2: String(o.diaVenc2 || DIA_VENC_2_PADRAO) }); setModal(true); }}><Ic n="edit" /></Btn>
                <Btn v="danger" size="sm" onClick={() => remove(o.id)}><Ic n="trash" /></Btn>
              </div>
            </div>

            {onAbrirObra && (
              <Btn v="ghost" size="sm" full onClick={() => onAbrirObra(o.id)}
                   style={{ marginTop: 10 }}>
                Abrir painel da obra →
              </Btn>
            )}
          </div>
        );
      })}
      </>}

      {/* Modal: nova fase / editar fase */}
      {faseModal && (
        <Modal title={faseModal.modo==="editar" ? "Editar fase" : "Nova fase"}
               onClose={()=>{setFaseModal(null);setFaseNome("");}}>
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <Inp label="Nome da fase *" value={faseNome} onChange={setFaseNome}
              placeholder="Ex.: Análise da Prefeitura"/>

            <div>
              <p style={{fontSize:11,fontWeight:600,color:C.text,marginBottom:6}}>Cor</p>
              <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
                {CORES_FASE.map(c=>(
                  <button key={c} onClick={()=>setFaseCor(c)} style={{
                    width:30,height:30,borderRadius:7,background:c,cursor:"pointer",
                    border: faseCor===c ? `3px solid ${C.text}` : `1px solid ${C.border}`,
                  }}/>
                ))}
              </div>
            </div>

            {/* Prévia da coluna */}
            <div style={{background:C.surface,border:`1.5px solid ${C.border}`,borderRadius:6,padding:"9px 11px"}}>
              <div style={{display:"flex",alignItems:"center",gap:6}}>
                <span style={{width:9,height:9,borderRadius:2,background:faseCor}}/>
                <p style={{fontSize:11,fontWeight:800,textTransform:"uppercase",letterSpacing:.6,color:C.text}}>
                  {faseNome || "Nome da fase"}
                </p>
              </div>
            </div>

            <div style={{display:"flex",gap:8}}>
              <Btn v="ghost" onClick={()=>{setFaseModal(null);setFaseNome("");}} full>Cancelar</Btn>
              <Btn onClick={salvarFase} full><Ic n="check"/> Salvar</Btn>
            </div>
          </div>
        </Modal>
      )}

      {modal && (
        <Modal title={form.id ? "Editar obra" : "Nova obra"} onClose={() => setModal(false)} wide>
          {/* Grid de verdade: 1 coluna no celular, 2 no resto. Os separadores de
              seção usam gridColumn:"1/-1", que só funciona em container grid -
              dentro do flex antigo eram CSS morto. */}
          <div style={{ display: "grid", gridTemplateColumns: formGrid(2), gap: 12 }}>
            <Inp label="Nome *" value={form.name} onChange={setField("name")} />
            <Inp label="Metragem quadrada (m)" type="number" value={form.areaM2} onChange={setField("areaM2")} placeholder="Ex.: 250" />
            <Inp label="Endereço" value={form.address} onChange={setField("address")} />
            <Inp label="Responsável" value={form.engineer} onChange={setField("engineer")} />
            <Inp label="Cliente" value={form.cliente} onChange={setField("cliente")} placeholder="Nome do contratante" />
            <Inp label="Data de início" type="date" value={form.startDate} onChange={setField("startDate")} />
            <Sel label="Fase (quadro)" value={form.faseId || (fases[0]?.id||"")} onChange={setField("faseId")}
              options={fases.map(f=>({v:f.id,l:f.nome}))}/>
            <Sel label="Status" value={form.status} onChange={setField("status")} options={[
              { v: "active", l: "Ativa" },
              { v: "paused", l: "Pausada" },
              { v: "done", l: "Concluída" },
            ]} />
            <div style={{ gridColumn:"1/-1", height:1, background:`linear-gradient(90deg,transparent,${C.line},transparent)`, margin:"4px 0" }}/>
            <div style={{ gridColumn:"1/-1" }}>
              <p style={{ fontSize:11, fontWeight:700, color:C.yellow, textTransform:"uppercase", letterSpacing:.7, marginBottom:8 }}>Contrato financeiro</p>
            </div>
            <Sel label="Modalidade do contrato *" value={form.contractType} onChange={setField("contractType")} options={CONTRACT_TYPES}/>
            <Inp label="Valor total do contrato (R$)" type="number" value={form.contractValue} onChange={setField("contractValue")} placeholder="0,00"/>
            {(form.contractType === "fixed_labor_admin" || form.contractType === "admin_only") && (
              <Inp label="% Administração sobre custo MO" type="number" value={form.adminPercentage} onChange={setField("adminPercentage")} placeholder="Ex.: 12"/>
            )}
            {(form.contractType === "fixed_labor" || form.contractType === "fixed_labor_admin") && (
              <Inp label="Valor parcela MO fixo (R$)" type="number" value={form.parcelaMensal} onChange={setField("parcelaMensal")} placeholder="Ex.: 15.000"/>
            )}
            <div style={{gridColumn:"1/-1",height:1,background:C.line,margin:"4px 0"}}/>
            <p style={{gridColumn:"1/-1",fontSize:11,fontWeight:700,color:C.yellow,textTransform:"uppercase",letterSpacing:.7}}>Cronograma de cobrança</p>
            <Sel label="Frequência de cobrança *" value={form.billingFrequency} onChange={setField("billingFrequency")} options={FREQ_OPTS}/>
            <Inp label="Total de parcelas" type="number" value={form.totalParcelas} onChange={setField("totalParcelas")} placeholder={form.billingFrequency==="quinzenal"?"Ex.: 24":"Ex.: 12"}/>

            {/* Dias de vencimento - perguntados aqui, na hora de lancar a obra.
                O padrao segue o contrato (15 e 30), mas cada obra pode fugir dele. */}
            {form.billingFrequency === "quinzenal" ? (
              <>
                <Sel label="Vencimento da 1ª quinzena *" value={String(form.diaVenc1||DIA_VENC_1_PADRAO)} onChange={setField("diaVenc1")} options={DIA_OPTS}/>
                <Sel label="Vencimento da 2ª quinzena *" value={String(form.diaVenc2||DIA_VENC_2_PADRAO)} onChange={setField("diaVenc2")} options={DIA_OPTS}/>
              </>
            ) : (
              <Sel label="Dia de vencimento *" value={String(form.diaVenc1||DIA_VENC_1_PADRAO)} onChange={setField("diaVenc1")} options={DIA_OPTS}/>
            )}
            <div style={{gridColumn:"1/-1",background:`${C.yellow}12`,border:`1px solid ${C.yellow}44`,borderRadius:6,padding:"9px 12px"}}>
              <p style={{fontSize:11,color:C.subtle,lineHeight:1.6}}>
                {form.billingFrequency === "quinzenal"
                  ? <>Cada mês gera 2 parcelas: uma no dia <b>{form.diaVenc1||DIA_VENC_1_PADRAO}</b> e outra no dia <b>{form.diaVenc2||DIA_VENC_2_PADRAO}</b>. Padrão do contrato: 15 e 30.</>
                  : <>Cada mês gera 1 parcela, vencendo no dia <b>{form.diaVenc1||DIA_VENC_1_PADRAO}</b>.</>}
                {" "}Em meses mais curtos, o dia 29/30/31 cai no último dia do mês (fev → 28).
              </p>
            </div>
            <div style={{gridColumn:"1/-1",height:1,background:C.line,margin:"4px 0"}}/>
            <p style={{gridColumn:"1/-1",fontSize:11,fontWeight:700,color:C.yellow,textTransform:"uppercase",letterSpacing:.7}}>Período e entrada</p>
            <Inp label="Início do contrato *" type="date" value={form.contractStart} onChange={setField("contractStart")}/>
            <Inp label="Fim previsto" type="date" value={form.contractEnd} onChange={setField("contractEnd")}/>
            {form.contractType !== "admin_only" && (<>
              <Inp label="Entrada (R$)" type="number" value={form.entrada} onChange={setField("entrada")} placeholder="0,00"/>
              <Inp label="Data da entrada" type="date" value={form.entradaDate} onChange={setField("entradaDate")}/>
            </>)}
            {form.contractValue && form.totalParcelas && Number(form.totalParcelas)>0 && form.contractType !== "admin_only" && !form.parcelaMensal && (
              <div style={{gridColumn:"1/-1",background:`${C.yellow}12`,border:`1px solid ${C.yellow}44`,borderRadius:6,padding:"8px 12px"}}>
                <p style={{fontSize:11,color:C.muted}}>Parcela MO sugerida: <strong style={{color:C.yellow}}>{(((Number(form.contractValue)-Number(form.entrada||0))/Number(form.totalParcelas))).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}</strong></p>
                <button type="button" onClick={()=>setField("parcelaMensal")(String(Math.round((Number(form.contractValue)-Number(form.entrada||0))/Number(form.totalParcelas))))} style={{marginTop:4,background:C.yellow,border:"none",color:"#fff",padding:"3px 10px",borderRadius:4,fontSize:11,cursor:"pointer",fontWeight:700}}>
                  Usar este valor →
                </button>
              </div>
            )}
            {/* Caixa de obra */}
            <div style={{gridColumn:"1/-1",height:1,background:C.line,margin:"4px 0"}}/>
            <label style={{gridColumn:"1/-1",display:"flex",alignItems:"center",gap:10,cursor:"pointer",padding:"10px 12px",background:form.hasCaixa?`${C.green}08`:C.surface,borderRadius:6,border:`1.5px solid ${form.hasCaixa?C.green+"55":C.border}`}}>
              <div onClick={()=>setField("hasCaixa")(!form.hasCaixa)} style={{width:20,height:20,border:`2px solid ${form.hasCaixa?C.green:C.muted}`,background:form.hasCaixa?C.green:"transparent",borderRadius:4,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,cursor:"pointer"}}>
                {form.hasCaixa&&<span style={{color:"#fff",fontSize:13,fontWeight:900}}>ok</span>}
              </div>
              <div>
                <p style={{fontSize:13,fontWeight:700,color:form.hasCaixa?C.green:C.text}}> Esta obra possui caixa de obra</p>
                <p style={{fontSize:11,color:C.muted,marginTop:1}}>Cliente faz aportes para compra de materiais - controle separado de entradas e gastos</p>
              </div>
            </label>
            <div style={{ gridColumn:"1/-1", display: "flex", gap: 8, marginTop: 4 }}>
              <Btn v="ghost" onClick={() => setModal(false)} full>Cancelar</Btn>
              <Btn onClick={save} full><Ic n="check" /> Salvar</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// 
// Equipe
// 

function Equipe({ data, update, showToast }) {
  const { formGrid } = useBreakpoint();
  const emptyEmp = {
    id: "",
    name: "",
    role: "",
    cpf: "",
    phone: "",
    pixKey: "",
    pixType: "",
    pixHolder: "",
    dailyRate: "",
    vtDaily: "",
    vrDaily: "",
    obra: "",
    active: true,
    startDate: "",
    endDate: "",
    terminationReason: "",
    lastObra: "",
  };

  const [modal, setModal] = useState(false);
  const [advModal, setAdvModal] = useState(null);
  const [form, setForm] = useState(emptyEmp);
  const [search, setSearch] = useState("");
  const [filterObra, setFilterObra] = useState("all");
  const [showInactive, setShowInactive] = useState(false);
  const [expandedId, setExpandedId] = useState(null);
  const [advForm, setAdvForm] = useState({ amount: "", description: "", date: today() });

  const F = key => value => setForm(f => ({ ...f, [key]: value }));
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";
  const empAdvances = id => (data.advances||[]).filter(a => a.empId === id);

  const saveEmp = () => {
    if (!form.name.trim() || !form.dailyRate || !form.startDate || !form.obra) {
      showToast("Nome, admissão, diária e obra são obrigatórios.", "error");
      return;
    }

    if (form.active === false && !form.endDate) {
      showToast("Informe a data de término para inativar/demitir.", "error");
      return;
    }

    const before = data.employees.find(e => e.id === form.id);
    const payload = {
      ...form,
      id: form.id || uid(),
      dailyRate: Number(form.dailyRate || 0),
      vtDaily: Number(form.vtDaily || 0),
      vrDaily: Number(form.vrDaily || 0),
      active: form.active !== false,
      endDate: form.active === false ? form.endDate : "",
      terminationReason: form.active === false ? (form.terminationReason || "Inativado") : "",
      lastObra: form.active === false ? (before?.obra || form.obra) : (form.lastObra || ""),
    };

    const changeLog = [...data.changeLog];

    if (!form.id) {
      changeLog.push({ id: uid(), date: today(), type: "created", empId: payload.id, empName: payload.name, message: `Funcionário cadastrado: ${payload.name}` });
    }

    if (before && before.obra !== payload.obra) {
      changeLog.push({
        id: uid(),
        date: today(),
        type: "transfer",
        empId: payload.id,
        empName: payload.name,
        from: obraName(before.obra),
        to: obraName(payload.obra),
        fromId: before.obra,   // ← ID gravado
        toId: payload.obra,    // ← ID gravado
        message: `${payload.name} transferido de ${obraName(before.obra)} para ${obraName(payload.obra)}`,
      });
    }

    if (before && before.active !== false && payload.active === false) {
      changeLog.push({ id: uid(), date: payload.endDate || today(), type: "dismissal", empId: payload.id, empName: payload.name, from: obraName(before.obra), message: `${payload.name} inativado/demitido em ${fmtDateFull(payload.endDate)}` });
    }

    const employees = form.id ? data.employees.map(e => (e.id === form.id ? payload : e)) : [...data.employees, payload];
    update({ ...data, employees, changeLog });
    setModal(false);
    showToast(form.id ? "Funcionário atualizado." : "Funcionário cadastrado.");
  };

  const archiveEmp = id => {
    const emp = data.employees.find(e => e.id === id);
    if (!emp) return;
    if (!window.confirm(`Inativar ${emp.name}? O histórico será preservado.`)) return;
    const endDate = window.prompt("Data de término no formato AAAA-MM-DD:", today());
    if (!endDate) {
      showToast("Data de término obrigatória.", "error");
      return;
    }

    const employees = data.employees.map(e => e.id === id ? { ...e, active: false, endDate, terminationReason: "Inativado", lastObra: e.obra } : e);
    const changeLog = [...data.changeLog, { id: uid(), date: endDate, type: "dismissal", empId: emp.id, empName: emp.name, from: obraName(emp.obra), message: `${emp.name} inativado em ${fmtDateFull(endDate)}` }];
    update({ ...data, employees, changeLog });
    showToast("Funcionário inativado com histórico preservado.");
  };

  const saveAdv = () => {
    if (!advForm.amount || isNaN(Number(advForm.amount))) {
      showToast("Valor do adiantamento inválido.", "error");
      return;
    }
    const advances = [...data.advances, { id: uid(), empId: advModal, date: advForm.date || today(), amount: Number(advForm.amount), description: advForm.description || "Adiantamento" }];
    update({ ...data, advances });
    setAdvModal(null);
    setAdvForm({ amount: "", description: "", date: today() });
    showToast("Adiantamento registrado.");
  };

  const removeAdv = id => {
    if (!window.confirm("Remover adiantamento?")) return;
    update({ ...data, advances: (data.advances||[]).filter(a => a.id !== id) });
  };

  const list = data.employees
    .filter(e => showInactive || e.active !== false)
    .filter(e => filterObra === "all" || e.obra === filterObra || e.lastObra === filterObra)
    .filter(e => [e.name, e.role, e.cpf, e.phone].join(" ").toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => a.name.localeCompare(b.name));

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
        <div>
          <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 30, letterSpacing: 2, color: C.yellow }}>Equipe</h2>
          <p style={{ color: C.muted, fontSize: 13 }}>{data.employees.length} cadastrados  {data.employees.filter(e => e.active !== false).length} ativos</p>
        </div>
        <Btn onClick={() => { setForm({ ...emptyEmp, obra: data.obras[0]?.id || "" }); setModal(true); }}><Ic n="plus" /> Novo</Btn>
      </div>

      <Inp value={search} onChange={setSearch} placeholder="Buscar por nome, função, CPF ou telefone..." />
      <div className="fluid-grid" style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 8 }}>
        <Sel value={filterObra} onChange={setFilterObra} options={[{ v: "all", l: "Todas as obras" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]} />
        <Btn v={showInactive ? "warning" : "ghost"} onClick={() => setShowInactive(v => !v)}>{showInactive ? "Com inativos" : "Só ativos"}</Btn>
      </div>

      {list.length === 0 && <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 20, textAlign: "center", color: C.muted }}>Nenhum funcionário encontrado.</div>}

      {list.map(e => {
        const advs = empAdvances(e.id);
        const totalAdv = advs.reduce((s, a) => s + Number(a.amount || 0), 0);
        const exp = expandedId === e.id;
        return (
          <div key={e.id} style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${e.active === false ? C.muted : C.yellow}` }}>
            <div style={{ padding: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>
                <button onClick={() => setExpandedId(exp ? null : e.id)} style={{ flex: 1, background: "transparent", border: 0, color: C.text, textAlign: "left", cursor: "pointer" }}>
                  <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 18 }}>{e.name}</p>
                  <p style={{ color: C.muted, fontSize: 12 }}>{obraName(e.obra)}{e.role ? `  ${e.role}` : ""}</p>
                  <div style={{ marginTop: 4 }}>
                    {e.active === false && <Badge color={C.muted}>Inativo</Badge>}
                    <Badge color={C.yellow}>{fmt(e.dailyRate)}/dia</Badge>
                    {totalAdv > 0 && <Badge color={C.red}>Adiant. {fmt(totalAdv)}</Badge>}
                  </div>
                </button>
                <div style={{ display: "flex", gap: 5, alignItems: "flex-start" }}>
                  <Btn v="ghost" size="sm" onClick={() => { setForm({ ...e, dailyRate: String(e.dailyRate || ""), vtDaily: String(e.vtDaily || ""), vrDaily: String(e.vrDaily || "") }); setModal(true); }}><Ic n="edit" /></Btn>
                  {e.active !== false && <Btn v="danger" size="sm" onClick={() => archiveEmp(e.id)}><Ic n="x" /></Btn>}
                </div>
              </div>
            </div>

            {exp && (
              <div style={{ borderTop: `1px solid ${C.border}`, padding: 14, background: C.surface }}>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                  <p style={{ color: C.subtle, fontSize: 12 }}>CPF: {e.cpf || "-"}</p>
                  <p style={{ color: C.subtle, fontSize: 12 }}>Telefone: {e.phone || "-"}</p>
                  <p style={{ color: C.subtle, fontSize: 12 }}>PIX: {e.pixKey || "-"}</p>
                  <p style={{ color: C.subtle, fontSize: 12 }}>Admissão: {fmtDateFull(e.startDate)}</p>
                  {e.endDate && <p style={{ color: C.red, fontSize: 12 }}>Término: {fmtDateFull(e.endDate)}</p>}
                </div>

                <Divider />
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                  <p style={{ color: C.yellow, fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, textTransform: "uppercase" }}>Adiantamentos</p>
                  <Btn v="warning" size="sm" onClick={() => setAdvModal(e.id)}><Ic n="plus" /> Novo</Btn>
                </div>
                {advs.length === 0 && <p style={{ color: C.muted, fontSize: 12 }}>Nenhum adiantamento.</p>}
                {advs.map(a => (
                  <div key={a.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: `1px solid ${C.border}`, padding: "7px 0" }}>
                    <div>
                      <p style={{ fontWeight: 800, fontSize: 13 }}>{a.description}</p>
                      <p style={{ color: C.muted, fontSize: 11 }}>{fmtDateFull(a.date)}</p>
                    </div>
                    <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                      <span style={{ color: C.red, fontWeight: 900 }}>{fmt(a.amount)}</span>
                      <Btn v="danger" size="sm" onClick={() => removeAdv(a.id)}><Ic n="trash" /></Btn>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      })}

      {modal && (
        <Modal title={form.id ? "Editar funcionário" : "Novo funcionário"} onClose={() => setModal(false)} wide>
          <div style={{ display: "grid", gridTemplateColumns:formGrid(2), gap: 12 }}>
            <div style={{ gridColumn: "1/-1" }}><Inp label="Nome completo *" value={form.name} onChange={F("name")} /></div>
            <Inp label="Função" value={form.role} onChange={F("role")} />
            <Inp label="Admissão *" type="date" value={form.startDate} onChange={F("startDate")} />
            <Inp label="Diária *" type="number" value={form.dailyRate} onChange={F("dailyRate")} />
            <Sel label="Obra *" value={form.obra} onChange={F("obra")} options={[{ v: "", l: "Selecione" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]} />
            <Sel label="Status" value={String(form.active !== false)} onChange={v => F("active")(v === "true")} options={[{ v: "true", l: "Ativo" }, { v: "false", l: "Inativo / Demitido" }]} />
            <Inp label="VT diário" type="number" value={form.vtDaily} onChange={F("vtDaily")} />
            <Inp label="VR diário" type="number" value={form.vrDaily} onChange={F("vrDaily")} />
            <Inp label="CPF" value={form.cpf} onChange={v => F("cpf")(fmtCPF(v))} />
            <Inp label="Telefone" value={form.phone} onChange={v => F("phone")(fmtPhone(v))} />
            <Inp label="Tipo PIX" value={form.pixType} onChange={F("pixType")} />
            <Inp label="Titular PIX" value={form.pixHolder} onChange={F("pixHolder")} />
            <div style={{ gridColumn: "1/-1" }}><Inp label="Chave PIX" value={form.pixKey} onChange={F("pixKey")} /></div>

            {form.active === false && (
              <>
                <Inp label="Data de término *" type="date" value={form.endDate} onChange={F("endDate")} />
                <Inp label="Motivo" value={form.terminationReason} onChange={F("terminationReason")} />
              </>
            )}
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
            <Btn v="ghost" onClick={() => setModal(false)} full>Cancelar</Btn>
            <Btn onClick={saveEmp} full><Ic n="check" /> Salvar</Btn>
          </div>
        </Modal>
      )}

      {advModal && (
        <Modal title="Novo adiantamento" onClose={() => setAdvModal(null)}>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <Inp label="Valor *" type="number" value={advForm.amount} onChange={v => setAdvForm(f => ({ ...f, amount: v }))} />
            <Inp label="Descrição" value={advForm.description} onChange={v => setAdvForm(f => ({ ...f, description: v }))} />
            <Inp label="Data" type="date" value={advForm.date} onChange={v => setAdvForm(f => ({ ...f, date: v }))} />
            <div style={{ display: "flex", gap: 8 }}>
              <Btn v="ghost" onClick={() => setAdvModal(null)} full>Cancelar</Btn>
              <Btn v="warning" onClick={saveAdv} full><Ic n="check" /> Registrar</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// 
// Modal de movimentação individual
// 

function WorkerMovementModal({ data, update, showToast, employee, initialMode = "transfer", onClose }) {
  const { formGrid } = useBreakpoint();
  const [mode, setMode] = useState(initialMode);
  const [newObra, setNewObra] = useState("");
  const [endDate, setEndDate] = useState(today());
  const [reason, setReason] = useState("Demitido");

  const activeObras = data.obras.filter(o => o.status !== "done");
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";

  const saveTransfer = () => {
    if (!newObra) {
      showToast("Selecione a nova obra.", "error");
      return;
    }
    if (!employee.obra) {
      showToast("Este trabalhador não tem obra atual definida. Edite o cadastro dele na aba Equipe.", "error");
      return;
    }
    if (newObra === employee.obra) {
      showToast("Selecione uma obra diferente da atual.", "error");
      return;
    }
    const obraDestino = data.obras.find(o => o.id === newObra);
    if (!obraDestino) {
      showToast("Obra de destino não encontrada. Atualize a página.", "error");
      return;
    }

    const from = obraName(employee.obra);
    const to = obraName(newObra);
    const employees = data.employees.map(emp => emp.id === employee.id ? {
      ...emp,
      obra: newObra,
      lastObra: emp.obra,
      active: true,
      endDate: "",
      terminationReason: "",
    } : emp);

    const changeLog = [...data.changeLog, {
      id: uid(),
      date: today(),
      type: "transfer",
      empId: employee.id,
      empName: employee.name,
      from,
      to,
      fromId: employee.obra,  // ← ID gravado para busca confiável
      toId: newObra,          // ← ID gravado para busca confiável
      message: `${employee.name} transferido de ${from} para ${to}`,
    }];
    update({ ...data, employees, changeLog, dailyCheckDate: today() });
    showToast(`${employee.name} transferido para ${to}.`);
    onClose();
  };

  const saveDismissal = () => {
    if (!endDate) {
      showToast("Informe a data de término.", "error");
      return;
    }

    const from = obraName(employee.obra);
    const employees = data.employees.map(emp => emp.id === employee.id ? {
      ...emp,
      active: false,
      endDate,
      terminationReason: reason || "Demitido",
      lastObra: emp.obra,
    } : emp);

    const changeLog = [...data.changeLog, { id: uid(), date: endDate, type: "dismissal", empId: employee.id, empName: employee.name, from, message: `${employee.name} demitido/inativado em ${fmtDateFull(endDate)}` }];
    update({ ...data, employees, changeLog, dailyCheckDate: today() });
    showToast(`${employee.name} demitido/inativado.`);
    onClose();
  };

  return (
    <Modal title={mode === "transfer" ? "Transferir trabalhador" : "Demitir trabalhador"} onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${mode === "transfer" ? C.yellow : C.red}`, padding: 12 }}>
          <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 18 }}>{employee.name}</p>
          <p style={{ color: C.muted, fontSize: 12 }}>Obra atual: {obraName(employee.obra)}{employee.role ? `  ${employee.role}` : ""}</p>
        </div>
        <div style={{ display: "grid", gridTemplateColumns:formGrid(2), gap: 8 }}>
          <Btn v={mode === "transfer" ? "warning" : "ghost"} onClick={() => setMode("transfer")} full>Transferir</Btn>
          <Btn v={mode === "dismiss" ? "danger" : "ghost"} onClick={() => setMode("dismiss")} full>Demitir</Btn>
        </div>
        {mode === "transfer" ? (
          <Sel label="Nova obra *" value={newObra} onChange={setNewObra} options={[{ v: "", l: "Selecione" }, ...activeObras.filter(o => o.id !== employee.obra).map(o => ({ v: o.id, l: o.name }))]} />
        ) : (
          <>
            <Inp label="Data de término *" type="date" value={endDate} onChange={setEndDate} />
            <Inp label="Motivo" value={reason} onChange={setReason} />
          </>
        )}
        <div style={{ display: "flex", gap: 8 }}>
          <Btn v="ghost" onClick={onClose} full>Cancelar</Btn>
          <Btn v={mode === "transfer" ? "warning" : "danger"} onClick={mode === "transfer" ? saveTransfer : saveDismissal} full>
            <Ic n="check" /> {mode === "transfer" ? "Confirmar transferência" : "Confirmar demissão"}
          </Btn>
        </div>
      </div>
    </Modal>
  );
}

// 
// Ponto
// 

function PontoGeral({ data, update, showToast }) {
  const agora = new Date();
  const refInicial = agora.getDate() <= 5 ? new Date(agora.getFullYear(), agora.getMonth()-1, 1) : agora;
  const [year,setYear]=useState(refInicial.getFullYear());
  const [month,setMonth]=useState(refInicial.getMonth());
  const [q,setQ]=useState(agora.getDate()>=6&&agora.getDate()<=20?"1":"2");
  const [filterObra,setFilterObra]=useState("all");
  const [busca,setBusca]=useState("");
  const [obraCell,setObraCell]=useState(null);   // "empId::date" da célula com troca de obra aberta
  const {q1,q2}=getQ(year,month);
  const diasCiclo=q==="1"?q1:q2;
  // A gestao mostra somente segunda a sexta. Feriados em dias uteis
  // permanecem sempre visiveis e destacados, mesmo sem lancamento.
  const days=diasCiclo.filter(prIsWeekdayIso);
  const feriados=prUniqueDates([...new Set(diasCiclo.map(d=>Number(d.slice(0,4))))].flatMap(ano=>getPayrollHolidays(data,ano)));
  const obraName=id=>(data.obras||[]).find(o=>o.id===id)?.name||"-";

  // Funcionários desligados continuam na Gestão do Ponto enquanto houver
  // vínculo com o ciclo selecionado. Isso permite fechar presença, faltas,
  // feriados, adiantamentos e o valor que ainda será pago, sem reativá-los
  // nas demais telas operacionais.
  const periodoIni=diasCiclo[0]||"";
  const periodoFim=diasCiclo[diasCiclo.length-1]||"";
  const temVinculoNoCiclo=e=>days.some(d=>isEmployeeEmployedOnDate(e,d));
  const temPontoNoCiclo=e=>days.some(d=>{
    const a=getAtt(data,e.id,d);
    return !!(a?.status||a?.ot||a?.note||a?.holidayPayOverride);
  });
  const temAdiantamentoNoCiclo=e=>(data.advances||[]).some(a=>
    a.empId===e.id&&periodoIni&&periodoFim&&a.date>=periodoIni&&a.date<=periodoFim
  );
  const deveAparecerNaGestao=e=>
    e.active!==false||temVinculoNoCiclo(e)||temPontoNoCiclo(e)||temAdiantamentoNoCiclo(e);

  const employees=(data.employees||[])
    .filter(deveAparecerNaGestao)
    .filter(e=>filterObra==="all"||e.obra===filterObra||e.lastObra===filterObra||days.some(d=>{
      const a=getAtt(data,e.id,d);
      return getEmployeeObraIdOnDate(data,e,d)===filterObra;
    }))
    .filter(e=>[e.name,e.role,obraName(e.obra||e.lastObra),e.active===false?"desligado demitido receber":""].join(" ").toLowerCase().includes(busca.toLowerCase()))
    .sort((a,b)=>a.name.localeCompare(b.name));
  const diaLabel=iso=>{const d=prParseIso(iso);return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}`;};
  const semana=iso=>["DOM","SEG","TER","QUA","QUI","SEX","SÁB"][prParseIso(iso).getDay()];
  const corStatus=st=>st==="P"?C.green:st==="M"?C.yellow:st==="F"?C.red:C.muted;
  const proxStatus=st=>st==="P"?"M":st==="M"?"F":st==="F"?null:"P";

  const salvarCelula=(emp,date,patch)=>{
    const anterior=getAtt(data,emp.id,date)||{status:null,ot:0,note:"",obraId:""};
    const novo={...anterior,...patch};
    const obraId=novo.obraId||getEmployeeObraIdOnDate(data,emp,date)||"";
    update({...data,attendance:{...(data.attendance||{}),[emp.id]:{...(data.attendance?.[emp.id]||{}),[date]:{...novo,obraId:novo.status?obraId:(novo.obraId||obraId)}}}});
  };

  const salvarFeriado=(emp,date,override)=>{
    const anterior=getAtt(data,emp.id,date)||{status:null,ot:0,note:"",obraId:""};
    const descricao=override==="paid"?"pago manualmente":override==="lost"?"não pago manualmente":"regra automática";
    update({
      ...data,
      attendance:{
        ...(data.attendance||{}),
        [emp.id]:{
          ...(data.attendance?.[emp.id]||{}),
          [date]:{
            ...anterior,
            holidayPayOverride:override||null,
            holidayPayOverrideAt:new Date().toISOString(),
          },
        },
      },
      changeLog:[...(data.changeLog||[]),{
        id:uid(),date:today(),type:"holiday_pay_override",empId:emp.id,
        message:`Feriado de ${fmtDateFull(date)} para ${emp.name}: ${descricao}.`,
      }],
    });
    showToast(`Feriado definido como ${descricao}.`);
  };

  const preencherLinha=emp=>{
    const attendance={...(data.attendance||{})},mapa={...(attendance[emp.id]||{})};
    days.forEach(date=>{const d=prParseIso(date),obraId=filterObra!=="all"?filterObra:getEmployeeObraIdOnDate(data,emp,date);if(d.getDay()===0||feriados.includes(date)||!isEmployeeEmployedOnDate(emp,date))return;const ant=getAtt(data,emp.id,date)||{};mapa[date]={...ant,status:"P",obraId};});
    attendance[emp.id]=mapa;update({...data,attendance});showToast("Período preenchido para o funcionário.");
  };

  const limparLinha=emp=>{
    if(!window.confirm(`Limpar os lançamentos visíveis de ${emp.name}?`))return;
    const attendance={...(data.attendance||{})},mapa={...(attendance[emp.id]||{})};
    days.forEach(date=>{const ant=getAtt(data,emp.id,date);if(!ant)return;delete mapa[date];});attendance[emp.id]=mapa;update({...data,attendance});showToast("Lançamentos do período removidos.");
  };

  const preencherVisiveis=()=>{
    if(!employees.length||!window.confirm(`Marcar presença nos dias de trabalho para ${employees.length} funcionário(s) visível(is)?`))return;
    const attendance={...(data.attendance||{})};
    employees.forEach(emp=>{const mapa={...(attendance[emp.id]||{})};days.forEach(date=>{const d=prParseIso(date),obraId=filterObra!=="all"?filterObra:getEmployeeObraIdOnDate(data,emp,date);if(d.getDay()===0||feriados.includes(date)||!isEmployeeEmployedOnDate(emp,date))return;mapa[date]={...(getAtt(data,emp.id,date)||{}),status:"P",obraId};});attendance[emp.id]=mapa;});update({...data,attendance});showToast("Equipe preenchida no período.");
  };

  const periodo=`${fmtDateFull(diasCiclo[0])} a ${fmtDateFull(diasCiclo[diasCiclo.length-1])}`;
  const rotuloCurto=st=>st==="P"?"P":st==="M"?"½":st==="F"?"F":"·";
  return <div className="anim" style={{display:"flex",flexDirection:"column",gap:12}}>
    {/* Cabeçalho enxuto: título, período e a ação principal numa linha. */}
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end",gap:12,flexWrap:"wrap"}}>
      <div>
        <p style={{fontSize:10,fontWeight:800,color:C.muted,letterSpacing:.8,textTransform:"uppercase"}}>Gestão do ponto</p>
        <h2 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(19px,3.5vw,24px)",color:C.text,letterSpacing:-.3}}>Ponto da quinzena</h2>
        <p style={{fontSize:11,color:C.muted,marginTop:2}}>{periodo} · {employees.length} funcionário(s)</p>
      </div>
      <Btn onClick={preencherVisiveis} v="success" size="sm"><Ic n="check"/> Preencher visíveis</Btn>
    </div>

    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:8}}>
      <Sel label="Ciclo" value={q} onChange={setQ} options={[{v:"1",l:"1ª quinzena · 06 a 20"},{v:"2",l:"2ª quinzena · 21 a 05"}]}/>
      <Sel label="Mês" value={String(month)} onChange={v=>setMonth(Number(v))} options={MONTHS.map((m,i)=>({v:String(i),l:m}))}/>
      <Inp label="Ano" type="number" value={year} onChange={v=>setYear(Number(v)||agora.getFullYear())}/>
      <Sel label="Obra" value={filterObra} onChange={setFilterObra} options={[{v:"all",l:"Todas as obras"},...(data.obras||[]).map(o=>({v:o.id,l:o.name}))]}/>
      <Inp label="Buscar" value={busca} onChange={setBusca} placeholder="Nome, cargo ou obra..."/>
    </div>

    <div style={{display:"flex",gap:12,flexWrap:"wrap",fontSize:10.5,color:C.muted,padding:"0 2px"}}>
      <span>Toque na célula para alternar <b style={{color:C.green}}>P</b> presente, <b style={{color:C.yellowD}}>½</b> meio dia, <b style={{color:C.red}}>F</b> falta, <b>·</b> sem registro.</span>
      <span>Nos feriados: <b>AUTO</b> aplica a regra anterior/posterior; <b style={{color:C.green}}>FP</b> paga manualmente; <b style={{color:C.red}}>FD</b> não paga manualmente.</span>
      <span style={{color:C.subtle}}>Trabalhou em outra obra? Toque no nome da obra sob a célula.</span>
      <span style={{color:C.orange}}>Funcionários desligados aparecem no ciclo em que ainda possuem ponto, vínculo ou valores a receber.</span>
    </div>

    <div style={{overflow:"auto",border:`1px solid ${C.border}`,borderRadius:8,background:C.card,maxHeight:"70vh"}}>
      <table style={{borderCollapse:"separate",borderSpacing:0,minWidth:Math.max(760,300+days.length*54),width:"100%",fontSize:10}}>
        <thead style={{position:"sticky",top:0,zIndex:5}}><tr>
          <th style={{position:"sticky",left:0,zIndex:7,minWidth:172,background:C.surface,color:C.text,padding:"8px 10px",textAlign:"left",fontSize:9.5,fontWeight:800,letterSpacing:.4,borderBottom:`1px solid ${C.border}`}}>FUNCIONÁRIO</th>
          <th style={{minWidth:48,background:C.surface,color:C.text,padding:8,fontSize:9.5,fontWeight:800,borderBottom:`1px solid ${C.border}`}}>DIAS</th>
          {days.map(date=>{const feriado=feriados.includes(date);return <th key={date} title={feriado?"Feriado cadastrado":""} style={{minWidth:54,background:feriado?`${C.red}14`:C.surface,color:feriado?C.red:C.text,padding:"6px 4px",borderLeft:`1px solid ${C.line}`,borderBottom:`1px solid ${C.border}`}}><div style={{fontSize:10,fontWeight:800}}>{diaLabel(date)}</div><div style={{fontSize:7.5,fontWeight:feriado?900:600,opacity:feriado?1:.6}}>{feriado?"FER":semana(date)}</div></th>;})}
        </tr></thead>
        <tbody>{employees.map(emp=>{const equivalentes=days.reduce((s,d)=>{if(feriados.includes(d))return s;const st=attStatus(data,emp.id,d);return s+(st==="P"?1:st==="M"?.5:0);},0);return <tr key={emp.id} style={{borderTop:`1px solid ${C.line}`}}>
          <td style={{position:"sticky",left:0,zIndex:2,background:C.card,padding:"7px 10px",borderTop:`1px solid ${C.line}`,minWidth:172}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:6}}>
              <div style={{minWidth:0}}>
                <div style={{display:"flex",alignItems:"center",gap:5,minWidth:0}}>
                  <b style={{fontSize:11,color:C.text,display:"block",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{emp.name}</b>
                  {emp.active===false&&<span title={emp.endDate?`Desligado em ${fmtDateFull(emp.endDate)}; mantido neste ciclo para fechamento e pagamento.`:"Funcionário desligado mantido para fechamento e pagamento."} style={{fontSize:7.5,fontWeight:900,letterSpacing:.35,color:C.orange,border:`1px solid ${C.orange}66`,background:`${C.orange}10`,borderRadius:999,padding:"2px 4px",whiteSpace:"nowrap"}}>DESLIGADO</span>}
                </div>
                <div style={{fontSize:8.5,color:C.muted,marginTop:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{emp.role||"Funcionário"} · {obraName(emp.obra||emp.lastObra)}{emp.active===false&&emp.endDate?` · saída ${fmtDate(emp.endDate)}`:""}</div>
              </div>
              <div style={{display:"flex",gap:2,flexShrink:0}}>
                <button title="Preencher a linha inteira como presente" onClick={()=>preencherLinha(emp)} style={{border:`1px solid ${C.green}`,background:`${C.green}10`,color:C.green,borderRadius:4,fontSize:9,cursor:"pointer",padding:"2px 5px",lineHeight:1}}>✓</button>
                <button title="Limpar a linha" onClick={()=>limparLinha(emp)} style={{border:`1px solid ${C.border}`,background:"transparent",color:C.muted,borderRadius:4,fontSize:9,cursor:"pointer",padding:"2px 5px",lineHeight:1}}>✕</button>
              </div>
            </div>
          </td>
          <td style={{textAlign:"center",fontWeight:800,fontSize:13,color:C.blue,borderTop:`1px solid ${C.line}`,fontFamily:"'Inter Display','Inter',sans-serif"}}>{equivalentes.toFixed(1).replace(".0","")}</td>
          {days.map(date=>{
            const att=getAtt(data,emp.id,date),st=att?.status,obraId=att?.obraId||emp.obra||"",fora=!isEmployeeEmployedOnDate(emp,date),feriado=feriados.includes(date);
            const regraFeriado=feriado?getHolidayPayRule(data,emp,date,feriados):null;
            const overrideFeriado=regraFeriado?.manualOverride||null;
            const proxOverride=overrideFeriado===null?"paid":overrideFeriado==="paid"?"lost":null;
            const corFeriado=regraFeriado?.losesHoliday?C.red:C.green;
            const foraDeLotacao=st&&obraId&&obraId!==emp.obra;   // trabalhou em obra diferente da lotação
            const cellKey=`${emp.id}::${date}`;
            const aberto=obraCell===cellKey;
            return <td key={date} style={{padding:3,borderTop:`1px solid ${C.line}`,borderLeft:`1px solid ${C.line}`,background:feriado?`${corFeriado}08`:fora?C.surface:C.card,verticalAlign:"middle"}}>
              {fora?<div style={{textAlign:"center",color:C.muted,fontSize:11}}>—</div>:feriado?(
                <button onClick={()=>salvarFeriado(emp,date,proxOverride)}
                  title={overrideFeriado?`Definição manual: ${regraFeriado.losesHoliday?"não pagar":"pagar"}. Clique para alterar.`:`Regra automática: ${regraFeriado.losesHoliday?"não paga":"paga"}. Falta anterior: ${regraFeriado.missedBefore?"sim":"não"}; falta posterior: ${regraFeriado.missedAfter?"sim":"não"}.`}
                  style={{width:"100%",minHeight:36,border:`1.5px solid ${corFeriado}`,borderRadius:5,
                          background:overrideFeriado?corFeriado:`${corFeriado}12`,color:overrideFeriado?"#fff":corFeriado,
                          fontWeight:800,cursor:"pointer",fontSize:10,fontFamily:"'Inter Display','Inter',sans-serif",lineHeight:1.05}}>
                  <span style={{display:"block",fontSize:11}}>{regraFeriado.losesHoliday?"FD":"FP"}</span>
                  <span style={{display:"block",fontSize:7,marginTop:2,opacity:.85}}>{overrideFeriado?"MANUAL":"AUTO"}</span>
                </button>
              ):<>
                <button onClick={()=>salvarCelula(emp,date,{status:proxStatus(st)})}
                  title={st==="P"?"Presente":st==="M"?"Meio dia":st==="F"?"Falta":"Sem registro"}
                  style={{width:"100%",height:30,border:`1.5px solid ${st?corStatus(st):C.border}`,borderRadius:5,
                          background:st?corStatus(st):C.bg,color:st?"#fff":C.muted,
                          fontWeight:800,cursor:"pointer",fontSize:12,fontFamily:"'Inter Display','Inter',sans-serif"}}>
                  {rotuloCurto(st)}
                </button>
                {/* Obra: escondida por padrão. Mostra um chip discreto só quando a
                    obra do dia difere da lotação; toque abre a troca. */}
                {aberto ? (
                  <select autoFocus value={obraId} onChange={e=>{salvarCelula(emp,date,{obraId:e.target.value});setObraCell(null);}} onBlur={()=>setObraCell(null)}
                    style={{width:"100%",marginTop:2,border:`1px solid ${C.blue}`,borderRadius:4,background:C.bg,color:C.text,fontSize:8,padding:"2px 1px"}}>
                    <option value="">Sem obra</option>
                    {(data.obras||[]).map(o=><option key={o.id} value={o.id}>{o.name}</option>)}
                  </select>
                ) : foraDeLotacao ? (
                  <button onClick={()=>setObraCell(cellKey)} title={`Obra do dia: ${obraName(obraId)}`}
                    style={{width:"100%",marginTop:2,border:`1px solid ${C.orange}55`,background:`${C.orange}12`,color:C.orange,borderRadius:4,fontSize:7.5,fontWeight:700,cursor:"pointer",padding:"2px 1px",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                    {obraName(obraId)}
                  </button>
                ) : st ? (
                  <button onClick={()=>setObraCell(cellKey)} title="Trocar a obra deste dia"
                    style={{width:"100%",marginTop:2,border:0,background:"transparent",color:C.muted,borderRadius:4,fontSize:7.5,cursor:"pointer",padding:"1px",opacity:.55}}>
                    trocar obra
                  </button>
                ) : null}
              </>}
            </td>;})}
        </tr>;})}</tbody>
      </table>
      {!employees.length&&<div style={{padding:24,textAlign:"center",color:C.muted}}>Nenhum funcionário encontrado para os filtros selecionados.</div>}
    </div>
  </div>;
}

function Ponto({ data, update, showToast }) {
  const [selDate, setSelDate] = useState(today());
  const [filterObra, setFilterObra] = useState("all");
  const [noteModal, setNoteModal] = useState(null);
  const [noteText, setNoteText] = useState("");
  const [otModal, setOtModal] = useState(null);
  const [otHours, setOtHours] = useState("0");
  const [movementModal, setMovementModal] = useState(null);
  const [lastAllDoneNotification, setLastAllDoneNotification] = useState("");
  const [expandedCard, setExpandedCard] = useState(null);   // card com "mais opções" aberto

  const employeesOnSelectedDate = (data.employees || []).filter(e => isEmployeeEmployedOnDate(e, selDate));
  const dailyCheckPending = selDate === today() && employeesOnSelectedDate.length > 0 && data.dailyCheckDate !== today();
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";
  const selectedObra = filterObra !== "all" ? data.obras.find(o => o.id === filterObra) : null;
  const obraAttendanceSummary = getObraAttendanceSummary(data, selDate);
  const attendanceCompletion = getAttendanceCompletionMessage(obraAttendanceSummary);
  const selectedHolidayList = getPayrollHolidays(data, Number(selDate.slice(0,4)));
  const selectedIsHoliday = selectedHolidayList.includes(selDate) && prIsWeekdayIso(selDate);

  useEffect(() => {
    const notificationKey = `${selDate}__all_done`;

    if (attendanceCompletion.allDone && lastAllDoneNotification !== notificationKey) {
      showToast("Todos os pontos de todas as obras foram cadastrados!", "success");
      setLastAllDoneNotification(notificationKey);
    }
  }, [selDate, attendanceCompletion.allDone, lastAllDoneNotification, showToast]);

  const list = employeesOnSelectedDate
    .filter(e => filterObra === "all" || getEmployeeObraIdOnDate(data, e, selDate) === filterObra)
    .sort((a, b) => a.name.localeCompare(b.name));


  const confirmTeamWithoutChanges = () => {
    update({
      ...data,
      dailyCheckDate: today(),
      changeLog: [...data.changeLog, { id: uid(), date: today(), type: "daily_check", message: "Verificação diária concluída: equipe sem alterações." }],
    });
    showToast("Equipe confirmada sem alterações.");
  };

  const setHolidayOverride = (employee, override) => {
    const prev = getAtt(data, employee.id, selDate) || { status: null, ot: 0, note: "", obraId: "" };
    const descricao = override === "paid" ? "pago manualmente" : override === "lost" ? "não pago manualmente" : "regra automática";
    update({
      ...data,
      attendance: {
        ...(data.attendance || {}),
        [employee.id]: {
          ...(data.attendance?.[employee.id] || {}),
          [selDate]: {
            ...prev,
            holidayPayOverride: override || null,
            holidayPayOverrideAt: new Date().toISOString(),
          },
        },
      },
      changeLog: [...(data.changeLog || []), {
        id: uid(), date: today(), type: "holiday_pay_override", empId: employee.id,
        message: `Feriado de ${fmtDateFull(selDate)} para ${employee.name}: ${descricao}.`,
      }],
    });
    showToast(`Feriado definido como ${descricao}.`);
  };

  const setAtt = (empId, status) => {
    const emp = data.employees.find(e => e.id === empId);
    const prev = getAtt(data, empId, selDate) || { status: null, ot: 0, note: "" };
    const nextStatus = prev.status === status ? null : status;

    // Grava EM QUAL OBRA o dia foi trabalhado.
    //
    // Antes, o custo da mão de obra era atribuído pela obra CADASTRADA no
    // funcionário. Se o pedreiro está lotado na Terras Alpha mas passou a
    // semana na Reserva, o custo inteiro dele ia para Terras Alpha - e você
    // cobrava do cliente errado. Numa empresa de administração, onde a mão de
    // obra é o maior custo e é repassada ao cliente, isso é dinheiro real
    // saindo do lugar errado.
    //
    // Agora o dia carrega a obra. Se o ponto está filtrado por uma obra, é
    // essa; senão, a obra de lotação do funcionário.
    // Se o ponto está filtrado por uma obra específica, o dia é dela.
    // Em "todas as obras", cai na lotação do funcionário - que continua sendo
    // o caso comum: cada um no seu canteiro.
    const obraDoDia = (filterObra && filterObra !== "all")
      ? filterObra
      : getEmployeeObraIdOnDate(data, emp, selDate);

    update({
      ...data,
      attendance: {
        ...data.attendance,
        [empId]: {
          ...(data.attendance[empId] || {}),
          [selDate]: {
            ...prev,
            status: nextStatus,
            // Só carimba a obra se o dia foi efetivamente marcado
            obraId: nextStatus ? obraDoDia : (prev.obraId || ""),
          },
        },
      },
    });
  };

  const saveNote = () => {
    const prev = getAtt(data, noteModal, selDate) || { status: null, ot: 0, note: "" };
    update({
      ...data,
      attendance: {
        ...data.attendance,
        [noteModal]: {
          ...(data.attendance[noteModal] || {}),
          [selDate]: { ...prev, note: noteText },
        },
      },
    });
    setNoteModal(null);
    showToast("Observação salva.");
  };

  const saveOT = () => {
    const prev = getAtt(data, otModal, selDate) || { status: null, ot: 0, note: "" };
    update({
      ...data,
      attendance: {
        ...data.attendance,
        [otModal]: {
          ...(data.attendance[otModal] || {}),
          [selDate]: { ...prev, ot: Number(otHours || 0) },
        },
      },
    });
    setOtModal(null);
    showToast("Hora extra registrada.");
  };

  const markAll = status => {
    if (filterObra === "all") {
      showToast("Selecione uma obra específica para marcar todos.", "error");
      return;
    }

    const attendance = { ...data.attendance };
    list.forEach(e => {
      attendance[e.id] = {
        ...(attendance[e.id] || {}),
        [selDate]: { ...(getAtt(data, e.id, selDate) || {}), status, obraId: filterObra },
      };
    });
    update({ ...data, attendance });
    showToast("Ponto marcado para todos.");
  };

  const counts = { P: 0, M: 0, F: 0 };
  list.forEach(e => {
    const st = attStatus(data, e.id, selDate);
    if (st) counts[st] = (counts[st] || 0) + 1;
  });
  const holidayRulesToday = selectedIsHoliday ? list.map(e => getHolidayPayRule(data, e, selDate, selectedHolidayList)) : [];
  const holidayPaidToday = holidayRulesToday.filter(r => !r.losesHoliday).length;
  const holidayLostToday = holidayRulesToday.filter(r => r.losesHoliday).length;
  const holidayManualToday = holidayRulesToday.filter(r => r.isManual).length;
  const semReg = selectedIsHoliday ? 0 : Math.max(0, list.length - counts.P - counts.M - counts.F);
  const registeredCount = selectedIsHoliday ? list.length : counts.P + counts.M + counts.F;
  const completionPct = list.length ? Math.round((registeredCount / list.length) * 100) : 0;

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      {/* Cabeçalho técnico enxuto: identifica a tela, a data e o progresso numa
          linha só. Sem marca d'água nem gradiente - isto é uma ferramenta de
          lançamento diário, não uma capa. */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", gap: 12, flexWrap: "wrap" }}>
        <div>
          <p style={{ fontSize: 10, fontWeight: 800, textTransform: "uppercase", letterSpacing: .8, color: C.muted }}>Registro de ponto</p>
          <h2 style={{ fontFamily: "'Inter Display','Inter',sans-serif", fontWeight: 800, fontSize: "clamp(20px,4vw,26px)", color: C.text, letterSpacing: -.3 }}>
            {selectedObra?.name || "Todas as obras"}
          </h2>
          <p style={{ fontSize: 11.5, color: C.muted, marginTop: 2 }}>{fmtDateFull(selDate)} · {registeredCount}/{list.length} lançados</p>
        </div>
        <div style={{ textAlign: "right", flexShrink: 0 }}>
          <p style={{ fontFamily: "'Inter Display','Inter',sans-serif", fontWeight: 800, fontSize: 30, lineHeight: 1, color: completionPct === 100 ? C.green : C.yellowD }}>{completionPct}%</p>
          <p style={{ fontSize: 9, fontWeight: 800, textTransform: "uppercase", letterSpacing: .6, color: C.muted }}>cadastrado</p>
        </div>
      </div>
      <div style={{ height: 5, background: C.surface, borderRadius: 99, overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${completionPct}%`, background: completionPct === 100 ? C.green : C.yellow, borderRadius: 99, transition: "width .25s ease" }} />
      </div>

      {/* Data e obra lado a lado: a primeira decisão de quem vai lançar. */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Inp label="Data" type="date" value={selDate} onChange={setSelDate} max={today()} />
        <Sel label="Obra" value={filterObra} onChange={setFilterObra} options={[{ v: "all", l: "Todas as obras" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]} />
      </div>

      {/* Status das pendências: uma linha quando tudo pronto; quando falta,
          lista enxuta de obras clicáveis. Sem caixas empilhadas. */}
      {selectedIsHoliday ? (
        <div style={{ display: "flex", alignItems: "center", gap: 7, background: `${C.blue}10`, border: `1px solid ${C.blue}44`, borderRadius: 8, padding: "9px 11px" }}>
          <Ic n="calendar" s={14} color={C.blue} />
          <p style={{ color: C.blue, fontSize: 12, fontWeight: 700 }}>Feriado: pagamento automático, com possibilidade de ajuste manual por funcionário.</p>
        </div>
      ) : attendanceCompletion.allDone ? (
        <div style={{ display: "flex", alignItems: "center", gap: 7, background: `${C.green}12`, border: `1px solid ${C.green}44`, borderRadius: 8, padding: "9px 11px" }}>
          <Ic n="check" s={14} color={C.green} />
          <p style={{ color: C.green, fontSize: 12, fontWeight: 700 }}>Todos os pontos de {fmtDateFull(selDate)} estão lançados.</p>
        </div>
      ) : attendanceCompletion.pendingObras.length > 0 && (
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 8, overflow: "hidden" }}>
          <p style={{ fontSize: 10, fontWeight: 800, color: C.muted, textTransform: "uppercase", letterSpacing: .6, padding: "8px 11px", borderBottom: `1px solid ${C.line}` }}>
            {attendanceCompletion.pendingObras.length} obra(s) com ponto pendente
          </p>
          {attendanceCompletion.pendingObras.map(o => (
            <button key={o.obraId} onClick={() => setFilterObra(o.obraId)}
              style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, width: "100%",
                       background: filterObra === o.obraId ? `${C.yellow}10` : "transparent", border: 0,
                       borderTop: `1px solid ${C.line}`, borderLeft: `3px solid ${C.red}`,
                       padding: "8px 11px", textAlign: "left", cursor: "pointer" }}>
              <span style={{ fontSize: 12, fontWeight: 700, color: C.text, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{o.obraName}</span>
              <span style={{ fontSize: 10.5, color: C.muted, flexShrink: 0 }}>{o.missingCount} sem ponto</span>
            </button>
          ))}
        </div>
      )}

      {dailyCheckPending && (
        <div style={{ background: `${C.yellow}12`, border: `1px solid ${C.yellow}55`, borderRadius: 8, padding: "10px 12px" }}>
          <p style={{ color: C.yellowD, fontWeight: 800, fontSize: 11.5, marginBottom: 4 }}>Verificação diária opcional</p>
          <p style={{ color: C.muted, fontSize: 11, marginBottom: 9, lineHeight: 1.5 }}>Use esta confirmação apenas para registrar que a equipe foi conferida. Ela não impede o lançamento ou a correção do ponto.</p>
          <Btn v="ghost" size="sm" onClick={confirmTeamWithoutChanges} full>Confirmar equipe sem alterações</Btn>
        </div>
      )}

      {filterObra === "all" && (
        <p style={{ fontSize: 11, color: C.muted, lineHeight: 1.5, padding: "0 2px" }}>
          Em todas as obras, a equipe e a obra do ponto são determinadas pela data selecionada, considerando transferências, desligamentos e a obra já gravada no lançamento. Para um empréstimo pontual, filtre a obra de destino antes de marcar.
        </p>
      )}

      {selectedObra && (
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap",
                      background: `${C.green}0c`, border: `1px solid ${C.green}44`,
                      borderRadius: 8, padding: "9px 11px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 7, minWidth: 0 }}>
            <Ic n="edit" s={13} color={C.green} />
            <span style={{ fontSize: 12, fontWeight: 700, color: C.green }}>
              Ponto sempre aberto para edição
            </span>
          </div>
          <span style={{ fontSize: 10.5, color: C.muted }}>Sem bloqueio e sem autorização prévia</span>
        </div>
      )}

      {/* Resumo do dia: contadores compactos numa faixa única. */}
      <div style={{ display: "flex", gap: 6 }}>
        {(selectedIsHoliday ? [
          ["Feriados pagos", holidayPaidToday, C.green],
          ["Feriados perdidos", holidayLostToday, C.red],
          ["Ajustes manuais", holidayManualToday, C.blue],
        ] : [
          ["Presentes", counts.P, C.green],
          ["Sem registro", semReg, C.muted],
          ["Meio dia", counts.M, C.yellowD],
          ["Faltas", counts.F, C.red],
        ]).map(([label, n, col]) => (
          <div key={label} style={{ flex: 1, background: C.card, border: `1px solid ${C.border}`, borderTop: `2px solid ${col}`, borderRadius: 6, padding: "7px 4px", textAlign: "center" }}>
            <p style={{ fontFamily: "'Inter Display','Inter',sans-serif", fontWeight: 800, fontSize: 20, color: col }}>{n}</p>
            <p style={{ color: C.muted, fontSize: 9, marginTop: 1 }}>{label}</p>
          </div>
        ))}
      </div>

      {!selectedIsHoliday && <div style={{ display: "flex", gap: 8 }}>
        <Btn v="success" size="sm" onClick={() => markAll("P")} full><Ic n="check" /> Todos presentes</Btn>
        <Btn v="danger" size="sm" onClick={() => markAll("F")} full><Ic n="x" /> Todos com falta</Btn>
      </div>}

      {list.length === 0 && <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 18, color: C.muted, textAlign: "center" }}>Nenhum trabalhador ativo nesta seleção.</div>}

      {list.map(e => {
        const att = getAtt(data, e.id, selDate);
        const status = att?.status;
        const ot = Number(att?.ot || 0);
        const note = att?.note || "";
        const holidayRule = selectedIsHoliday ? getHolidayPayRule(data, e, selDate, selectedHolidayList) : null;
        const borderCol = selectedIsHoliday ? (holidayRule?.losesHoliday ? C.red : C.green) : status === "P" ? C.green : status === "M" ? C.yellowD : status === "F" ? C.red : C.border;
        const aberto = expandedCard === e.id;

        return (
          <div key={e.id} style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `3px solid ${borderCol}`, padding: "10px 12px", borderRadius: 8 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, marginBottom: 9 }}>
              <div style={{ minWidth: 0 }}>
                <p style={{ fontWeight: 800, fontSize: 13.5, color: C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{e.name}</p>
                <p style={{ color: C.muted, fontSize: 10.5, marginTop: 1 }}>{obraName(e.obra)}{e.role ? ` · ${e.role}` : ""}</p>
              </div>
              <div style={{ display: "flex", gap: 4, flexShrink: 0, flexWrap: "wrap", justifyContent: "flex-end" }}>
                {ot > 0 && <Badge color={C.purple}>{ot}h extra</Badge>}
              </div>
            </div>

            {note && <p style={{ color: C.subtle, fontSize: 11, marginBottom: 8, fontStyle: "italic" }}>"{note}"</p>}

            <>
                {/* Em feriados a presença não é lançada. O operador escolhe entre
                    a regra automática ou uma decisão manual de pagar/não pagar. */}
                {selectedIsHoliday ? (
                  <>
                    <p style={{fontSize:10.5,color:C.muted,marginBottom:7,lineHeight:1.45}}>
                      Automático: paga por padrão; não paga se houver falta em <b>{fmtDateFull(holidayRule.before)}</b> ou <b>{fmtDateFull(holidayRule.after)}</b>.
                    </p>
                    <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 5 }}>
                      {[
                        [null, "calendar", C.blue, "Automático"],
                        ["paid", "check", C.green, "Pagar"],
                        ["lost", "x", C.red, "Não pagar"],
                      ].map(([ov, icon, col, label]) => {
                        const ativo = (holidayRule.manualOverride || null) === ov;
                        return <button key={String(ov)} onClick={() => setHolidayOverride(e, ov)} style={{
                          border: `1.5px solid ${ativo ? col : C.border}`,
                          background: ativo ? col : C.bg,
                          color: ativo ? "#fff" : C.subtle,
                          padding: "10px 4px", cursor: "pointer", fontFamily: "'Inter','Inter Display',sans-serif",
                          fontWeight: 700, fontSize: 11, display: "flex", flexDirection: "column",
                          alignItems: "center", gap: 4, borderRadius: 6, "--ic-color": ativo ? "#fff" : col,
                        }}><Ic n={icon} s={14} /> {label}</button>;
                      })}
                    </div>
                    <p style={{fontSize:10,marginTop:6,color:holidayRule.losesHoliday?C.red:C.green,fontWeight:700}}>
                      Resultado atual: {holidayRule.losesHoliday?"feriado não pago":"feriado pago"}{holidayRule.isManual?" · ajuste manual":" · regra automática"}.
                    </p>
                  </>
                ) : (
                  /* Ação principal: presença. Três botões grandes e claros. */
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 5 }}>
                    {[
                      ["P", "check", C.green, "Presente"],
                      ["M", "money", C.yellowD, "Meio dia"],
                      ["F", "x", C.red, "Falta"],
                    ].map(([st, icon, col, label]) => (
                      <button key={st} onClick={() => setAtt(e.id, st)} style={{
                        border: `1.5px solid ${status === st ? col : C.border}`,
                        background: status === st ? col : C.bg,
                        color: status === st ? "#fff" : C.subtle,
                        padding: "10px 4px",
                        cursor: "pointer",
                        fontFamily: "'Inter','Inter Display',sans-serif",
                        fontWeight: 700,
                        fontSize: 11.5,
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        gap: 4,
                        borderRadius: 6,
                        "--ic-color": status === st ? "#fff" : col,
                      }}>
                        <Ic n={icon} s={14} /> {label}
                      </button>
                    ))}
                  </div>
                )}

                {/* Ações secundárias recolhidas: raras no dia a dia, não competem
                    com a marcação de presença. */}
                <button onClick={() => setExpandedCard(aberto ? null : e.id)}
                  style={{ background: "transparent", border: 0, color: C.muted, cursor: "pointer",
                           fontSize: 10.5, fontWeight: 600, padding: "6px 0 0", display: "flex", alignItems: "center", gap: 4 }}>
                  {aberto ? "Menos opções" : "Mais opções"} <span style={{ fontSize: 9 }}>{aberto ? "▲" : "▼"}</span>
                </button>
                {aberto && (
                  <div style={{ display: "flex", flexDirection: "column", gap: 5, marginTop: 6 }}>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 5 }}>
                      <Btn v="ghost" size="sm" full onClick={() => { setOtModal(e.id); setOtHours(String(ot)); }}><Ic n="clock" /> Hora extra</Btn>
                      <Btn v="ghost" size="sm" full onClick={() => { setNoteModal(e.id); setNoteText(note); }}><Ic n="edit" /> Observação</Btn>
                    </div>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 5 }}>
                      <Btn v="warning" size="sm" full onClick={() => setMovementModal({ emp: e, mode: "transfer" })}><Ic n="building" /> Transferir</Btn>
                      <Btn v="danger" size="sm" full onClick={() => setMovementModal({ emp: e, mode: "dismiss" })}><Ic n="x" /> Demitir</Btn>
                    </div>
                  </div>
                )}
            </>
          </div>
        );
      })}

      {movementModal && <WorkerMovementModal data={data} update={update} showToast={showToast} employee={movementModal.emp} initialMode={movementModal.mode} onClose={() => setMovementModal(null)} />}

      {noteModal && (
        <Modal title="Observação" onClose={() => setNoteModal(null)}>
          <Inp label="Observação" value={noteText} onChange={setNoteText} multiline />
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <Btn v="ghost" onClick={() => setNoteModal(null)} full>Cancelar</Btn>
            <Btn onClick={saveNote} full><Ic n="check" /> Salvar</Btn>
          </div>
        </Modal>
      )}

      {otModal && (
        <Modal title="Horas extras" onClose={() => setOtModal(null)}>
          <Inp label="Quantidade de horas" type="number" value={otHours} onChange={setOtHours} />
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <Btn v="ghost" onClick={() => setOtModal(null)} full>Cancelar</Btn>
            <Btn v="info" onClick={saveOT} full><Ic n="check" /> Registrar</Btn>
          </div>
        </Modal>
      )}
    </div>
  );
}

// 
// Folha
// 

function Folha({ data, showToast, onTab }) {
  const now = new Date();
  const refInicial = now.getDate() <= 5 ? new Date(now.getFullYear(), now.getMonth()-1, 1) : now;
  const [year, setYear] = useState(refInicial.getFullYear());
  const [month, setMonth] = useState(refInicial.getMonth());
  const [q, setQ] = useState(now.getDate() >= 6 && now.getDate() <= 20 ? "1" : "2");
  const [filterObra, setFilterObra] = useState("all");
  const [expandedId, setExpandedId] = useState(null);
  const [relatorioPendente, setRelatorioPendente] = useState("");

  const { q1, q2 } = getQ(year, month);
  // Folha e espelho diario seguem a mesma grade da gestao: segunda a sexta.
  // Isso impede sabados e domingos de virarem "sem registro".
  const diasCiclo = q === "1" ? q1 : q2;
  const days = diasCiclo.filter(prIsWeekdayIso);
  const paymentHolidays = prUniqueDates([...new Set(diasCiclo.map(d=>Number(d.slice(0,4))))].flatMap(ano=>getPayrollHolidays(data,ano)));
  const holidaysInPeriod = days.filter(d => paymentHolidays.includes(d) && prIsWeekdayIso(d));
  const paymentInfo = getPayrollPaymentCalendar(year, month, q, data);
  const paymentDateLabel = fmtDateFull(paymentInfo.paymentDate);
  const paymentBaseLabel = fmtDateFull(paymentInfo.baseDate);
  const paymentObs = paymentInfo.adjusted ? `Ajustado de ${paymentBaseLabel} para ${paymentDateLabel}` : "Data normal de pagamento";
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";
  const periodLabel = `${q === "1" ? "1ª" : "2ª"} Quinzena de ${fullMonth(month)} ${year}`;

  // Folha, ponto diário e gestão usam a mesma fonte de lotação por data.
  const getEmpObraIdOnDate = (employee, dateIso) =>
    getEmployeeObraIdOnDate(data, employee, dateIso);

  const calcRow = employee => {
    let gross = 0;
    let presentes = 0;
    let meiodia = 0;
    let faltas = 0;
    let semRegistro = 0;
    let ot = 0;
    let vt = 0;
    let vr = 0;
    // Mapa por obra efetivamente registrada no ponto. Alem dos dias, guarda
    // os valores que podem ser atribuidos com seguranca a cada canteiro.
    const obrasPorDia = {};

    const addToObra = (obraId, tipo, valores = {}) => {
      const chave = obraId || "__sem_obra__";
      if (!obrasPorDia[chave]) obrasPorDia[chave] = {
        obraId: obraId || "", presentes: 0, meiodia: 0, faltas: 0,
        semRegistro: 0, feriadosPagos: 0, feriadosPerdidos: 0,
        valorDias: 0, valorFeriados: 0, vt: 0, vr: 0, ot: 0,
      };
      const o = obrasPorDia[chave];
      if (tipo === "P") o.presentes++;
      else if (tipo === "M") o.meiodia++;
      else if (tipo === "F") o.faltas++;
      else if (tipo === "S") o.semRegistro++;
      else if (tipo === "HP") o.feriadosPagos++;
      else if (tipo === "HD") o.feriadosPerdidos++;
      o.valorDias += Number(valores.valorDias || 0);
      o.valorFeriados += Number(valores.valorFeriados || 0);
      o.vt += Number(valores.vt || 0);
      o.vr += Number(valores.vr || 0);
      o.ot += Number(valores.ot || 0);
    };

    days.forEach(d => {
      if (!isEmployeeEmployedOnDate(employee, d)) return;
      if (holidaysInPeriod.includes(d)) return;

      const a = getAtt(data, employee.id, d);
      const st = a?.status;
      const extra = Number(a?.ot || 0);
      // Registro novo: usa a obra carimbada no proprio ponto. Registro antigo:
      // reconstrucao por lotacao/transferencia preserva o historico.
      const obraId = a?.obraId || getEmpObraIdOnDate(employee, d);

      if (st === "P") {
        const valorDia = Number(employee.dailyRate || 0);
        const valorVT = Number(employee.vtDaily || 0);
        const valorVR = Number(employee.vrDaily || 0);
        gross += valorDia;
        presentes++;
        ot += extra;
        vt += valorVT;
        vr += valorVR;
        addToObra(obraId, "P", { valorDias:valorDia, vt:valorVT, vr:valorVR, ot:extra });
      } else if (st === "M") {
        const valorDia = Number(employee.dailyRate || 0) * 0.5;
        const valorVT = Number(employee.vtDaily || 0) * 0.5;
        const valorVR = Number(employee.vrDaily || 0) * 0.5;
        gross += valorDia;
        meiodia++;
        ot += extra;
        vt += valorVT;
        vr += valorVR;
        addToObra(obraId, "M", { valorDias:valorDia, vt:valorVT, vr:valorVR, ot:extra });
      } else if (st === "F") {
        faltas++;
        addToObra(obraId, "F");
      } else {
        semRegistro++;
        addToObra(obraId, "S");
      }
    });

    const employeeHolidays = holidaysInPeriod.filter(h => isEmployeeEmployedOnDate(employee, h));
    const holidayRules = employeeHolidays.map(h => getHolidayPayRule(data, employee, h, paymentHolidays));
    const feriadosPagos = holidayRules.filter(h => !h.losesHoliday).length;
    const feriadosPerdidos = holidayRules.filter(h => h.losesHoliday).length;
    const holidayPay = holidayRules.reduce((s, h) => s + h.amount, 0);
    gross += holidayPay;
    holidayRules.forEach(h => {
      const obraId = getEmpObraIdOnDate(employee, h.holidayIso);
      addToObra(obraId, h.losesHoliday ? "HD" : "HP", {
        valorFeriados: Number(h.amount || 0),
      });
    });

    const periIni = diasCiclo.length > 0 ? diasCiclo[0] : "";
    const periFim = diasCiclo.length > 0 ? diasCiclo[diasCiclo.length - 1] : "";
    const advTotal = data.advances
      .filter(a => a.empId === employee.id && periIni && periFim && a.date >= periIni && a.date <= periFim)
      .reduce((s, a) => s + Number(a.amount || 0), 0);

    // Converte mapa para array ordenado por dias trabalhados desc
    const obrasPorDiaArr = Object.values(obrasPorDia)
      .map(v => ({
        ...v,
        obraName: data.obras.find(o => o.id === v.obraId)?.name || "Sem obra identificada",
        // Dia trabalhado equivalente: meio periodo vale 0,5; falta nao conta.
        diasTrabalhados: v.presentes + (v.meiodia * 0.5),
        totalRegistros: v.presentes + v.meiodia + v.faltas,
        bruto: v.valorDias + v.valorFeriados,
        custoDireto: v.valorDias + v.valorFeriados + v.vt + v.vr,
      }))
      .sort((a, b) => b.diasTrabalhados - a.diasTrabalhados || a.obraName.localeCompare(b.obraName));

    return {
      ...employee,
      gross,
      presentes,
      meiodia,
      faltas,
      semRegistro,
      ot,
      vt,
      vr,
      feriadosPagos,
      feriadosPerdidos,
      holidayPay,
      holidayRules,
      advances: advTotal,
      net: gross + vt + vr - advTotal,
      days: days.length,
      obrasPorDia: obrasPorDiaArr,
    };
  };

  const hasAttendanceInPeriod = e => days.some(d => {
    const a = getAtt(data, e.id, d);
    return a?.status || a?.ot || a?.note;
  });

  const belongsToSelectedObra = e => {
    if (filterObra === "all") return true;
    return days.some(d => {
      if (!isEmployeeEmployedOnDate(e, d)) return false;
      const a = getAtt(data, e.id, d);
      const temLancamento = !!a?.status || holidaysInPeriod.includes(d);
      const obraDoDia = a?.obraId || getEmpObraIdOnDate(e, d);
      return temLancamento && obraDoDia === filterObra;
    });
  };

  const rows = data.employees
    .filter(belongsToSelectedObra)
    .filter(e => e.active !== false || hasAttendanceInPeriod(e))
    .map(calcRow)
    .filter(r => r.presentes > 0 || r.meiodia > 0 || r.faltas > 0 || r.feriadosPagos > 0 || r.feriadosPerdidos > 0 || r.advances > 0 || r.gross > 0)
    .sort((a, b) => a.name.localeCompare(b.name));

  // Conferencia previa do relatorio. A validacao usa todos os funcionarios
  // vinculados ao periodo/obra, inclusive quem ainda nao aparece na folha por
  // nao possuir nenhum apontamento.
  const funcionariosParaConferencia = (data.employees || [])
    .filter(e => days.some(d => isEmployeeEmployedOnDate(e, d)))
    .filter(e => e.active !== false || hasAttendanceInPeriod(e) || (e.endDate && e.endDate >= (days[0] || "")))
    .filter(e => filterObra === "all" || e.obra === filterObra || e.lastObra === filterObra || days.some(d => {
      if (!isEmployeeEmployedOnDate(e, d)) return false;
      const a = getAtt(data, e.id, d);
      return (a?.obraId || getEmpObraIdOnDate(e, d)) === filterObra;
    }))
    .sort((a, b) => (a.name || "").localeCompare(b.name || ""));

  const hojeConferencia = today();
  const pendenciasRelatorio = funcionariosParaConferencia.map(e => {
    const datasEsperadas = days.filter(d => {
      if (d > hojeConferencia || !isEmployeeEmployedOnDate(e, d) || holidaysInPeriod.includes(d)) return false;
      if (filterObra === "all") return true;
      const a = getAtt(data, e.id, d);
      return (a?.obraId || getEmpObraIdOnDate(e, d)) === filterObra;
    });
    const semRegistro = datasEsperadas.filter(d => !["P", "M", "F"].includes(getAtt(data, e.id, d)?.status));
    const temObraNoPeriodo = datasEsperadas.some(d => {
      const a = getAtt(data, e.id, d);
      return !!(a?.obraId || getEmpObraIdOnDate(e, d));
    });
    const campos = [];
    if (!String(e.pixKey || "").trim()) campos.push("PIX");
    if (!temObraNoPeriodo && !e.obra && !e.lastObra) campos.push("obra");
    if (!(Number(e.dailyRate || 0) > 0)) campos.push("valor da diaria");
    return {
      id: e.id,
      nome: e.name || "Funcionario sem nome",
      semRegistro,
      nenhumRegistro: datasEsperadas.length > 0 && semRegistro.length === datasEsperadas.length,
      campos,
    };
  }).filter(p => p.semRegistro.length > 0 || p.campos.length > 0);

  const totalDiasSemRegistro = pendenciasRelatorio.reduce((s, p) => s + p.semRegistro.length, 0);
  const totalSemPix = pendenciasRelatorio.filter(p => p.campos.includes("PIX")).length;

  const T = {
    gross: rows.reduce((s, r) => s + r.gross, 0),
    vt: rows.reduce((s, r) => s + r.vt, 0),
    vr: rows.reduce((s, r) => s + r.vr, 0),
    advances: rows.reduce((s, r) => s + r.advances, 0),
    net: rows.reduce((s, r) => s + r.net, 0),
    holidayPay: rows.reduce((s, r) => s + r.holidayPay, 0),
    feriadosPagos: rows.reduce((s, r) => s + r.feriadosPagos, 0),
    feriadosPerdidos: rows.reduce((s, r) => s + r.feriadosPerdidos, 0),
  };

  // Linhas consolidadas: uma combinacao unica de funcionario + obra. Este e
  // o numero que responde quantos dias a pessoa efetivamente trabalhou em
  // cada canteiro, sem contar faltas e ponderando meio periodo como 0,5.
  const detalheObraFuncionario = rows.flatMap(r =>
    r.obrasPorDia
      .filter(o => filterObra === "all" || o.obraId === filterObra)
      .map(o => ({
        empId:r.id, funcionario:r.name, cargo:r.role || "", diaria:Number(r.dailyRate || 0),
        ...o,
      }))
  ).sort((a,b) => a.obraName.localeCompare(b.obraName) || a.funcionario.localeCompare(b.funcionario));

  // Resumo gerencial por obra, calculado a partir do mesmo detalhamento.
  const resumoPorObraMap = new Map();
  detalheObraFuncionario.forEach(l => {
    if (!resumoPorObraMap.has(l.obraId)) resumoPorObraMap.set(l.obraId, {
      obraId:l.obraId, obraName:l.obraName, funcionarios:new Set(), presentes:0,
      meiodia:0, diasTrabalhados:0, faltas:0, semRegistro:0, feriadosPagos:0,
      feriadosPerdidos:0, valorDias:0, valorFeriados:0, ot:0, vt:0, vr:0,
      bruto:0, custoDireto:0,
    });
    const o = resumoPorObraMap.get(l.obraId);
    if (l.diasTrabalhados > 0 || l.feriadosPagos > 0) o.funcionarios.add(l.empId);
    ["presentes","meiodia","diasTrabalhados","faltas","semRegistro","feriadosPagos",
     "feriadosPerdidos","valorDias","valorFeriados","ot","vt","vr","bruto","custoDireto"]
      .forEach(k => { o[k] += Number(l[k] || 0); });
  });
  const resumoPorObra = [...resumoPorObraMap.values()]
    .map(o => ({...o, funcionarios:o.funcionarios.size}))
    .sort((a,b) => a.obraName.localeCompare(b.obraName));

  // Espelho diario auditavel. Inclui sem registro e feriados para que o total
  // consolidado possa ser conferido data a data no Excel.
  const pontoDiario = rows.flatMap(r => days.map(d => {
    if (!isEmployeeEmployedOnDate(r, d)) return null;
    const feriado = holidaysInPeriod.includes(d);
    const regraFer = feriado ? (r.holidayRules || []).find(h => h.holidayIso === d) : null;
    const a = getAtt(data, r.id, d);
    const obraId = a?.obraId || getEmpObraIdOnDate(r, d);
    if (filterObra !== "all" && obraId !== filterObra) return null;
    const st = feriado ? `${regraFer?.losesHoliday ? "Feriado perdido" : "Feriado pago"}${regraFer?.isManual ? " (manual)" : " (automatico)"}`
      : a?.status === "P" ? "Presente" : a?.status === "M" ? "Meio periodo"
      : a?.status === "F" ? "Falta" : "Sem registro";
    const equivalente = a?.status === "P" ? 1 : a?.status === "M" ? 0.5 : 0;
    const valorDia = feriado ? Number(regraFer?.amount || 0) : Number(r.dailyRate || 0) * equivalente;
    const valorVT = feriado ? 0 : Number(r.vtDaily || 0) * equivalente;
    const valorVR = feriado ? 0 : Number(r.vrDaily || 0) * equivalente;
    return {
      data:d, diaSemana:["Domingo","Segunda","Terca","Quarta","Quinta","Sexta","Sabado"][new Date(d+"T00:00:00").getDay()],
      funcionario:r.name, cargo:r.role || "", obraId,
      obraName:data.obras.find(o => o.id === obraId)?.name || "Sem obra identificada",
      status:st, equivalente, ot:Number(a?.ot || 0), diaria:Number(r.dailyRate || 0),
      valorDia, vt:valorVT, vr:valorVR, totalDia:valorDia+valorVT+valorVR,
      observacao:a?.note || "",
    };
  }).filter(Boolean)).sort((a,b) => a.data.localeCompare(b.data) || a.obraName.localeCompare(b.obraName) || a.funcionario.localeCompare(b.funcionario));

  const printPDF = () => {
    // Monta a tabela de detalhe por obra para o PDF
    const detalheRows = detalheObraFuncionario.map(l =>
      `<tr><td>${escapeHtml(l.obraName)}</td><td>${escapeHtml(l.funcionario)}</td>`+
      `<td>${escapeHtml(l.cargo || "-")}</td><td>${l.presentes}</td><td>${l.meiodia}</td>`+
      `<td><b>${l.diasTrabalhados.toFixed(1).replace(".",",")}</b></td><td>${l.faltas}</td>`+
      `<td>${l.semRegistro}</td><td>${l.feriadosPagos}</td><td class="num">${escapeHtml(fmt(l.bruto))}</td></tr>`
    );

    const linhasFolha = rows.length ? rows.map(r => `
      <tr>
        <td>${escapeHtml(r.name)}</td><td>${escapeHtml(r.role || "-")}</td><td>${escapeHtml(obraName(r.obra))}</td>
        <td class="num">${r.presentes}</td><td class="num">${r.meiodia}</td><td class="num"><b>${(r.presentes + r.meiodia * 0.5).toFixed(1).replace(".", ",")}</b></td>
        <td class="num">${r.faltas}</td><td class="num">${r.semRegistro}</td><td class="num">${r.feriadosPagos}</td><td class="num">${r.feriadosPerdidos}</td>
        <td class="num">${escapeHtml(fmt(r.holidayPay))}</td><td class="num">${r.ot || 0}h</td><td class="num">${escapeHtml(fmt(Number(r.dailyRate || 0)))}</td>
        <td class="num">${escapeHtml(fmt(r.gross))}</td><td class="num">${escapeHtml(fmt(r.vt))}</td><td class="num">${escapeHtml(fmt(r.vr))}</td><td class="num">${escapeHtml(fmt(r.advances))}</td><td class="num"><b>${escapeHtml(fmt(r.net))}</b></td>
      </tr>`).join("") : `<tr><td colspan="18" class="vazio">Nenhum lançamento encontrado para o período selecionado.</td></tr>`;

    const html = `<!doctype html>
      <html lang="pt-BR">
        <head>
          <meta charset="utf-8">
          <title>Folha - ${escapeHtml(periodLabel)}</title>
          <style>
            @page{size:A4 landscape;margin:10mm}
            *{box-sizing:border-box}
            body{font-family:Arial,sans-serif;margin:0;color:#111;font-size:10px}
            h1,h2,h3{margin:0 0 8px 0}
            p{margin:4px 0}
            .cabecalho{border-bottom:3px solid #d4af37;padding-bottom:10px;margin-bottom:10px}
            .meta{display:flex;gap:18px;flex-wrap:wrap;color:#333}
            .kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:10px 0}
            .kpi{border:1px solid #bbb;border-top:3px solid #d4af37;padding:7px;background:#fafafa}
            .kpi span{display:block;font-size:8px;text-transform:uppercase;color:#666;font-weight:bold}
            .kpi b{display:block;font-size:14px;margin-top:2px}
            table{width:100%;border-collapse:collapse;margin-top:8px;font-size:8px;table-layout:auto}
            thead{display:table-header-group}
            tfoot{display:table-footer-group}
            tr{break-inside:avoid;page-break-inside:avoid}
            th,td{border:1px solid #aaa;padding:4px;text-align:left;vertical-align:middle}
            th{background:#e8e8e8;font-size:7.5px;text-transform:uppercase;white-space:nowrap}
            td.num{text-align:right;white-space:nowrap}
            .total{font-weight:bold;background:#fff8d6}
            .vazio{text-align:center;padding:16px;color:#666;font-style:italic}
            .section{margin-top:18px;padding-top:10px;border-top:3px solid #d4af37;break-before:page;page-break-before:always}
            .legenda{font-size:8px;color:#555;margin-top:5px}
            .signatures{margin-top:32px;display:flex;justify-content:space-between;gap:40px;break-inside:avoid}
            .signature{flex:1;border-top:1px solid #111;padding-top:8px;text-align:center}
            @media screen{body{padding:24px;max-width:1400px;margin:auto}}
          </style>
        </head>
        <body>
          <div class="cabecalho">
            <h1>${escapeHtml(data.config.companyName || "ArcD Obras")}</h1>
            ${data.config.cnpj ? `<p>CNPJ: ${escapeHtml(data.config.cnpj)}</p>` : ""}
            <h2>Folha de Pagamento - ${escapeHtml(periodLabel)}</h2>
            <div class="meta">
              <p><strong>Período:</strong> ${escapeHtml(fmtDateFull(days[0]))} a ${escapeHtml(fmtDateFull(days[days.length-1]))}</p>
              <p><strong>Pagamento:</strong> ${escapeHtml(paymentDateLabel)}</p>
              <p><strong>Regra:</strong> ${escapeHtml(paymentObs)}</p>
            </div>
          </div>

          <div class="kpis">
            <div class="kpi"><span>Funcionários</span><b>${rows.length}</b></div>
            <div class="kpi"><span>Dias trabalhados</span><b>${rows.reduce((s,r)=>s+r.presentes+r.meiodia*0.5,0).toFixed(1).replace(".",",")}</b></div>
            <div class="kpi"><span>Total bruto</span><b>${escapeHtml(fmt(T.gross))}</b></div>
            <div class="kpi"><span>Total líquido</span><b>${escapeHtml(fmt(T.net))}</b></div>
          </div>
          <p class="legenda">P = presença integral · M = meio período · F = falta · S/R = sem registro · FP = feriado pago · FD = feriado perdido</p>

          <!-- Tabela principal -->
          <table>
            <thead>
              <tr>
                <th>Funcionário</th><th>Cargo</th><th>Obra Atual</th><th>P</th><th>M</th><th>Dias Trab.</th><th>F</th><th>S/R</th><th>FP</th><th>FD</th><th>Valor Feriado</th><th>HE</th><th>Diária</th><th>Bruto</th><th>VT</th><th>VR</th><th>Adiant.</th><th>Líquido</th>
              </tr>
            </thead>
            <tbody>
              ${linhasFolha}
            </tbody>
            <tfoot>
              <tr class="total"><td colspan="13">TOTAL - ${rows.length} funcionário(s)</td><td class="num">${escapeHtml(fmt(T.gross))}</td><td class="num">${escapeHtml(fmt(T.vt))}</td><td class="num">${escapeHtml(fmt(T.vr))}</td><td class="num">${escapeHtml(fmt(T.advances))}</td><td class="num">${escapeHtml(fmt(T.net))}</td></tr>
            </tfoot>
          </table>

          <!-- Tabela de detalhe por obra -->
          <div class="section">
            <h3>Detalhe de Dias Trabalhados por Obra</h3>
            <p style="font-size:11px;color:#555">Período: ${escapeHtml(fmtDateFull(days[0]))} a ${escapeHtml(fmtDateFull(days[days.length - 1]))}</p>
            <table>
              <thead>
                <tr>
                  <th>Obra</th><th>Funcionário</th><th>Cargo</th><th>Presentes</th><th>Meio Dia</th><th>Dias Trabalhados</th><th>Faltas</th><th>Sem Registro</th><th>Feriados Pagos</th><th>Bruto Alocado</th>
                </tr>
              </thead>
              <tbody>
                ${detalheRows.join("") || `<tr><td colspan="10" class="vazio">Nenhum apontamento por obra encontrado para o período selecionado.</td></tr>`}
              </tbody>
            </table>
          </div>

          <div class="signatures"><div class="signature">Responsável RH: ${escapeHtml(data.config.hrName || "_______________________")}</div><div class="signature">Aprovado por</div></div>
          <p style="margin-top:30px;">Data: ___/___/_____</p>
        </body>
      </html>
    `;
    const w = window.open("", "_blank");
    if (!w) {
      showToast("Não foi possível abrir a impressão. Permita pop-ups para este aplicativo e tente novamente.", "error");
      return;
    }
    w.document.open();
    w.document.write(html);
    w.document.close();
    w.focus();
    window.setTimeout(() => w.print(), 300);
  };

  // Exportacao tecnica: folha financeira + consolidacao por obra +
  // funcionario/obra + espelho diario. Mantemos os valores numericos para que
  // o operador possa somar, filtrar e montar tabelas dinamicas no Excel.
  const exportXLSDetalhado = () => {
    const wb = XLSX.utils.book_new();

    const header1 = ["Funcionário", "Cargo", "Obra Atual", "Pres.", "Meio Dia", "Dias Trabalhados",
      "Faltas", "Sem Registro", "Feriados Pagos", "Feriados Perdidos", "Valor Feriado",
      "HE", "Diária", "Bruto", "VT", "VR", "Adiant.", "Líquido"];
    const body1 = rows.map(r => [r.name, r.role || "", obraName(r.obra), r.presentes, r.meiodia,
      r.presentes + r.meiodia * 0.5, r.faltas, r.semRegistro, r.feriadosPagos,
      r.feriadosPerdidos, r.holidayPay, r.ot, r.dailyRate, r.gross, r.vt, r.vr, r.advances, r.net]);
    const total1 = ["TOTAL", "", "",
      ...["presentes","meiodia"].map(k=>rows.reduce((s,r)=>s+Number(r[k]||0),0)),
      rows.reduce((s,r)=>s+Number(r.presentes||0)+Number(r.meiodia||0)*0.5,0),
      rows.reduce((s,r)=>s+Number(r.faltas||0),0), rows.reduce((s,r)=>s+Number(r.semRegistro||0),0),
      T.feriadosPagos, T.feriadosPerdidos, T.holidayPay, rows.reduce((s,r)=>s+Number(r.ot||0),0),
      "", T.gross, T.vt, T.vr, T.advances, T.net];
    const ws1 = XLSX.utils.aoa_to_sheet([
      ["Folha de Pagamento", periodLabel], ["Data de pagamento", paymentDateLabel],
      ["Regra aplicada", paymentObs], ["Critério de dias", "Presença = 1 dia; meio período = 0,5; falta e feriado = 0 dia trabalhado."],
      [], header1, ...body1, total1,
    ]);
    ws1["!cols"] = [24,18,20,8,10,16,8,13,15,17,15,8,12,14,12,12,12,14].map(w=>({wch:w}));
    if (body1.length) ws1["!autofilter"] = {ref:`A6:R${6+body1.length}`};
    XLSX.utils.book_append_sheet(wb, ws1, "Folha");

    const header2 = ["Obra", "Funcionários Alocados", "Presenças Integrais", "Meios Períodos",
      "Dias Trabalhados Equivalentes", "Faltas", "Sem Registro", "Feriados Pagos",
      "Feriados Perdidos", "HE", "Valor dos Dias", "Valor dos Feriados", "Bruto", "VT", "VR", "Custo Direto"];
    const body2 = resumoPorObra.map(o => [o.obraName, o.funcionarios, o.presentes, o.meiodia,
      o.diasTrabalhados, o.faltas, o.semRegistro, o.feriadosPagos, o.feriadosPerdidos,
      o.ot, o.valorDias, o.valorFeriados, o.bruto, o.vt, o.vr, o.custoDireto]);
    const total2 = ["TOTAL", resumoPorObra.reduce((s,o)=>s+o.funcionarios,0),
      ...["presentes","meiodia","diasTrabalhados","faltas","semRegistro","feriadosPagos",
          "feriadosPerdidos","ot","valorDias","valorFeriados","bruto","vt","vr","custoDireto"]
        .map(k => resumoPorObra.reduce((s,o)=>s+Number(o[k]||0),0))];
    const ws2 = XLSX.utils.aoa_to_sheet([
      ["Resumo da Folha por Obra", periodLabel],
      ["Período", `${fmtDateFull(days[0])} a ${fmtDateFull(days[days.length-1])}`],
      ["Critério", "Dia trabalhado equivalente = presença integral + 0,5 por meio período. Faltas não contam."],
      [], header2, ...body2, total2,
    ]);
    ws2["!cols"] = [26,18,18,16,24,9,13,15,17,8,15,17,14,12,12,15].map(w=>({wch:w}));
    if (body2.length) ws2["!autofilter"] = {ref:`A5:P${5+body2.length}`};
    XLSX.utils.book_append_sheet(wb, ws2, "Resumo por Obra");

    const header3 = ["Obra", "Funcionário", "Cargo", "Presenças Integrais", "Meios Períodos",
      "Dias Trabalhados Equivalentes", "Faltas", "Sem Registro", "Feriados Pagos",
      "Feriados Perdidos", "HE", "Diária", "Valor dos Dias", "Valor dos Feriados",
      "Bruto Alocado", "VT", "VR", "Custo Direto"];
    const body3 = detalheObraFuncionario.map(l => [l.obraName, l.funcionario, l.cargo,
      l.presentes, l.meiodia, l.diasTrabalhados, l.faltas, l.semRegistro,
      l.feriadosPagos, l.feriadosPerdidos, l.ot, l.diaria, l.valorDias,
      l.valorFeriados, l.bruto, l.vt, l.vr, l.custoDireto]);
    const ws3 = XLSX.utils.aoa_to_sheet([
      ["Folha por Obra e Funcionário", periodLabel],
      ["Período", `${fmtDateFull(days[0])} a ${fmtDateFull(days[days.length-1])}`],
      ["Observação", "Adiantamentos e líquido permanecem na aba Folha, pois o adiantamento não possui obra vinculada."],
      ["Critério", "Meio período equivale a 0,5 dia trabalhado; faltas e feriados não são dias trabalhados."],
      [], header3, ...body3,
    ]);
    ws3["!cols"] = [26,24,18,18,16,24,9,13,15,17,8,12,15,17,15,12,12,15].map(w=>({wch:w}));
    if (body3.length) ws3["!autofilter"] = {ref:`A6:R${6+body3.length}`};
    XLSX.utils.book_append_sheet(wb, ws3, "Funcionario por Obra");

    const header4 = ["Data", "Dia da Semana", "Funcionário", "Cargo", "Obra", "Status",
      "Dia Equivalente", "HE", "Diária", "Valor do Dia/Feriado", "VT", "VR", "Total Direto", "Observação"];
    const body4 = pontoDiario.map(l => [l.data, l.diaSemana, l.funcionario, l.cargo, l.obraName,
      l.status, l.equivalente, l.ot, l.diaria, l.valorDia, l.vt, l.vr, l.totalDia, l.observacao]);
    const ws4 = XLSX.utils.aoa_to_sheet([
      ["Espelho Diário por Obra e Funcionário", periodLabel],
      ["Período", `${fmtDateFull(days[0])} a ${fmtDateFull(days[days.length-1])}`],
      [], header4, ...body4,
    ]);
    ws4["!cols"] = [12,15,24,18,26,17,15,8,12,20,12,12,15,30].map(w=>({wch:w}));
    if (body4.length) ws4["!autofilter"] = {ref:`A4:N${4+body4.length}`};
    XLSX.utils.book_append_sheet(wb, ws4, "Ponto Diario");

    XLSX.writeFile(wb, `arcd-folha-${year}-${String(month+1).padStart(2,"0")}-Q${q}.xlsx`);
    showToast("Excel gerado com 4 abas: folha, obras, funcionários e ponto diário.");
  };

  const executarRelatorio = tipo => {
    if (tipo === "pdf") printPDF();
    else exportXLSDetalhado();
  };

  const solicitarRelatorio = tipo => {
    if (pendenciasRelatorio.length > 0) {
      setRelatorioPendente(tipo);
      return;
    }
    executarRelatorio(tipo);
  };

  const continuarComPendencias = () => {
    const tipo = relatorioPendente;
    setRelatorioPendente("");
    executarRelatorio(tipo);
  };

  const buildText = () => [
    "FOLHA DE PAGAMENTO - ARCD OBRAS",
    data.config.companyName || "",
    periodLabel,
    `Pagamento: ${paymentDateLabel}`,
    paymentObs,
    "",
    ...rows.map(r => `- ${r.name} (${obraName(r.obra)}): ${fmt(r.net)} | ${r.feriadosPagos}FP ${r.feriadosPerdidos}FD`),
    "",
    `TOTAL LÍQUIDO: ${fmt(T.net)}`,
    `FERIADOS PAGOS: ${T.feriadosPagos}`,
    `FERIADOS PERDIDOS: ${T.feriadosPerdidos}`,
    `VALOR TOTAL DE FERIADOS: ${fmt(T.holidayPay)}`,
    `${rows.length} funcionário(s)`,
    `Gerado em ${new Date().toLocaleDateString("pt-BR")}`,
  ].join("\n");

  const years = [];
  for (let i = now.getFullYear() - 1; i <= now.getFullYear() + 2; i++) years.push({ v: String(i), l: String(i) });

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div>
        <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 30, letterSpacing: 2, color: C.yellow }}>Folha de Pagamento</h2>
        <p style={{ color: C.muted, fontSize: 13 }}>Cálculo automático quinzenal com feriados e datas de pagamento.</p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Sel value={String(year)} onChange={v => setYear(Number(v))} options={years} />
        <Sel value={String(month)} onChange={v => setMonth(Number(v))} options={Array.from({ length: 12 }, (_, i) => ({ v: String(i), l: fullMonth(i) }))} />
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Sel value={q} onChange={setQ} options={[{ v: "1", l: "1ª quinzena" }, { v: "2", l: "2ª quinzena" }]} />
        <Sel value={filterObra} onChange={setFilterObra} options={[{ v: "all", l: "Todas as obras" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]} />
      </div>

      <div style={{ background: `linear-gradient(135deg, ${C.yellow}, ${C.yellowD})`, color: C.bg, padding: 18, border: `1px solid ${C.yellow}` }}>
        <p style={{ fontSize: 11, fontWeight: 900, letterSpacing: 1, textTransform: "uppercase", opacity: 0.78 }}>Total líquido</p>
        <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 38, letterSpacing: 2 }}>{fmt(T.net)}</p>
        <p style={{ fontSize: 12, fontWeight: 700 }}>{rows.length} funcionário(s)  {periodLabel}</p>
        <p style={{ fontSize: 14, fontWeight: 900, marginTop: 6 }}>Pagamento: {paymentDateLabel}</p>
        <p style={{ fontSize: 11, fontWeight: 700, opacity: 0.86 }}>{paymentObs}</p>
        {(T.feriadosPagos + T.feriadosPerdidos) > 0 && <p style={{ fontSize: 11, fontWeight: 700, opacity: 0.86, marginTop: 4 }}>Feriados: {T.feriadosPagos} pago(s), {T.feriadosPerdidos} perdido(s)  Valor: {fmt(T.holidayPay)}</p>}
        <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginTop: 8, fontSize: 12, fontWeight: 700 }}>
          <span>Bruto: {fmt(T.gross)}</span>
          {T.vt > 0 && <span>VT: {fmt(T.vt)}</span>}
          {T.vr > 0 && <span>VR: {fmt(T.vr)}</span>}
          {T.advances > 0 && <span>Adiant.: -{fmt(T.advances)}</span>}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Btn v="ghost" onClick={() => solicitarRelatorio("pdf")}><Ic n="file" /> PDF / Imprimir</Btn>
        <Btn v="success" onClick={() => solicitarRelatorio("excel")}><Ic n="download" /> Excel detalhado .xlsx</Btn>
        <Btn v="info" onClick={() => window.open(`mailto:${data.config.hrEmail || ""}?subject=${encodeURIComponent("Folha - " + periodLabel)}&body=${encodeURIComponent(buildText())}`)}><Ic n="mail" /> E-mail</Btn>
        <Btn v="success" onClick={() => navigator.clipboard.writeText(buildText()).then(() => showToast("Copiado.")).catch(() => showToast("Erro ao copiar.", "error"))}><Ic n="copy" /> WhatsApp</Btn>
      </div>

      {rows.length === 0 && <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 20, textAlign: "center", color: C.muted }}>Nenhum funcionário com movimentação nesta quinzena.</div>}

      {rows.map(r => (
        <div key={r.id}>
          <button onClick={() => setExpandedId(expandedId === r.id ? null : r.id)} style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${C.yellow}`, padding: 14, width: "100%", cursor: "pointer", color: C.text, textAlign: "left", display: "flex", justifyContent: "space-between", gap: 8 }}>
            <div>
              <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 17 }}>{r.name}</p>
              <p style={{ color: C.muted, fontSize: 12 }}>{obraName(r.obra)}  {(r.presentes+r.meiodia*0.5).toFixed(1).replace(".",",")} dia(s) trabalhado(s)  {r.presentes}P {r.meiodia}M {r.faltas}F {r.semRegistro}S/R  {r.feriadosPagos}FP {r.feriadosPerdidos}FD{r.ot > 0 ? `  ${r.ot}h` : ""}</p>
            </div>
            <div style={{ textAlign: "right" }}>
              <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 19, color: C.yellow }}>{fmt(r.net)}</p>
              {r.advances > 0 && <p style={{ color: C.red, fontSize: 11 }}>-{fmt(r.advances)}</p>}
            </div>
          </button>

          {expandedId === r.id && (
            <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderTop: 0, padding: 14 }}>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 12 }}>
                {[
                  ["Diária", fmt(r.dailyRate)], ["Bruto", fmt(r.gross)], ["VT+VR", fmt(r.vt + r.vr)], ["Adiant.", fmt(r.advances), C.red], ["Líquido", fmt(r.net), C.yellow], ["HE", `${r.ot}h`], ["Feriados pagos", r.feriadosPagos], ["Feriados perdidos", r.feriadosPerdidos, C.red], ["Valor feriado", fmt(r.holidayPay), C.green],
                ].map(([label, value, color]) => (
                  <div key={label} style={{ background: C.card, border: `1px solid ${C.border}`, padding: 8 }}>
                    <p style={{ color: C.muted, fontSize: 10, textTransform: "uppercase" }}>{label}</p>
                    <p style={{ color: color || C.text, fontWeight: 900 }}>{value}</p>
                  </div>
                ))}
              </div>

              {r.holidayRules.length > 0 && (
                <div style={{ marginBottom: 12 }}>
                  <p style={{ color: C.yellow, fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, textTransform: "uppercase", marginBottom: 6 }}>Regra de feriados</p>
                  {r.holidayRules.map(h => (
                    <p key={h.holidayIso} style={{ color: h.losesHoliday ? C.red : C.green, fontSize: 12, marginBottom: 3 }}>
                      {fmtDateFull(h.holidayIso)}: {h.losesHoliday ? "perdido" : "pago"}  anterior {fmtDateFull(h.before)}{h.missedBefore ? " faltou" : " ok"}  posterior {fmtDateFull(h.after)}{h.missedAfter ? " faltou" : " ok"}
                    </p>
                  ))}
                </div>
              )}

              {r.obrasPorDia.filter(o => filterObra === "all" || o.obraId === filterObra).length > 0 && (
                <div style={{ marginBottom:12 }}>
                  <p style={{ color:C.yellow, fontFamily:"'Inter Display','Inter',sans-serif",
                              fontWeight:900, textTransform:"uppercase", marginBottom:6 }}>
                    Dias trabalhados por obra
                  </p>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(190px,1fr))",gap:6}}>
                    {r.obrasPorDia.filter(o => filterObra === "all" || o.obraId === filterObra).map(o => (
                      <div key={o.obraId || "sem-obra"} style={{background:C.card,border:`1px solid ${C.border}`,padding:"8px 10px"}}>
                        <p style={{fontSize:11.5,fontWeight:800,color:C.text}}>{o.obraName}</p>
                        <p style={{fontSize:15,fontWeight:900,color:C.green,marginTop:2}}>
                          {o.diasTrabalhados.toFixed(1).replace(".",",")} dia(s)
                        </p>
                        <p style={{fontSize:9.5,color:C.muted}}>{o.presentes} integral(is) + {o.meiodia} meio(s) período(s) · {o.faltas} falta(s)</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {r.pixKey && <p style={{ color: C.subtle, fontSize: 12, marginBottom: 10 }}>PIX: {r.pixKey}</p>}

              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(43px, 1fr))", gap: 4 }}>
                {days.map(d => {
                  const a = getAtt(data, r.id, d);
                  const st = a?.status;
                  const isHoliday = holidaysInPeriod.includes(d) && isEmployeeEmployedOnDate(r, d);
                  const col = isHoliday ? C.blue : st === "P" ? C.green : st === "M" ? C.yellow : st === "F" ? C.red : C.muted;
                  return (
                    <div key={d} style={{ background: C.card, border: `1px solid ${C.border}`, padding: 5, textAlign: "center" }}>
                      <p style={{ color: C.muted, fontSize: 9 }}>{fmtDate(d)}</p>
                      <p style={{ color: col, fontWeight: 900 }}>{isHoliday ? "FER" : st || "-"}</p>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      ))}

      {relatorioPendente && (
        <Modal title="Conferencia antes de gerar o relatorio" onClose={() => setRelatorioPendente("")} wide>
          <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
            <div style={{ background:"rgba(220,38,38,.08)", border:`1px solid ${C.red}`, padding:12, borderRadius:6 }}>
              <p style={{ color:C.red, fontWeight:900, fontSize:14 }}>Existem dados pendentes nesta quinzena.</p>
              <p style={{ color:C.text, fontSize:12, marginTop:4 }}>
                {pendenciasRelatorio.length} funcionario(s) precisam de conferencia | {totalDiasSemRegistro} dia(s) sem registro | {totalSemPix} PIX ausente(s).
              </p>
              <p style={{ color:C.muted, fontSize:11, marginTop:4 }}>Sabados, domingos e feriados nao sao considerados como falta de registro.</p>
            </div>

            <div style={{ maxHeight:360, overflowY:"auto", display:"flex", flexDirection:"column", gap:7 }}>
              {pendenciasRelatorio.map(p => (
                <div key={p.id} style={{ background:C.card, border:`1px solid ${C.border}`, borderLeft:`4px solid ${C.red}`, padding:"9px 11px", borderRadius:6 }}>
                  <p style={{ fontWeight:900, color:C.text }}>{p.nome}</p>
                  {p.semRegistro.length > 0 && (
                    <p style={{ fontSize:11, color:C.red, marginTop:3 }}>
                      {p.nenhumRegistro ? "Nenhum ponto registrado" : `${p.semRegistro.length} dia(s) sem ponto`}: {p.semRegistro.slice(0,8).map(fmtDate).join(", ")}{p.semRegistro.length > 8 ? ` e mais ${p.semRegistro.length - 8}` : ""}
                    </p>
                  )}
                  {p.campos.length > 0 && <p style={{ fontSize:11, color:C.yellowD, marginTop:3 }}>Dados faltando: {p.campos.join(", ")}.</p>}
                </div>
              ))}
            </div>

            <p style={{ color:C.muted, fontSize:11 }}>Voce pode corrigir agora ou continuar e gerar o arquivo com as pendencias existentes.</p>
            <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))", gap:8 }}>
              <Btn v="danger" onClick={() => { setRelatorioPendente(""); onTab?.("ponto_geral"); }}>Corrigir ponto</Btn>
              <Btn v="ghost" onClick={() => { setRelatorioPendente(""); onTab?.("equipe"); }}>Preencher PIX / cadastro</Btn>
              <Btn v="success" onClick={continuarComPendencias}>Continuar mesmo assim</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

// 
// HELPER - custo de terceiros por obra/período
// 

const calcObraTercCost = (data, obraId, periodStart, periodEnd) => {
  // Custo direto da OBRA: só os pagamentos que o contrato define como pagos
  // pela obra. Os pagos pela empresa saem daqui e viram despesa administrativa
  // no consolidado - senão a margem da obra ficaria pior do que a realidade
  // por um custo que não é dela.
  return (data.pagsTerceiros || [])
    .filter(p => p.obraId === obraId && p.pagador !== "empresa" && p.date >= periodStart && p.date <= periodEnd)
    .reduce((s, p) => s + Number(p.amount || 0), 0);
};

// Terceiros bancados pela EMPRESA no período (todas as obras). Vai para o DRE
// consolidado como despesa administrativa, fora do custo de qualquer obra.
const calcTercEmpresaCost = (data, periodStart, periodEnd) => {
  return (data.pagsTerceiros || [])
    .filter(p => p.pagador === "empresa" && p.date >= periodStart && p.date <= periodEnd)
    .reduce((s, p) => s + Number(p.amount || 0), 0);
};

// 
// ALERTAS WHATSAPP - gerador de mensagens
// 

const buildAlertMessage = (data) => {
  const todayIso = today();
  const fri = getFridayOfWeek(0);
  const { start: ws } = getWeekRange(fri);
  const nowD = new Date();
  const day  = nowD.getDate();
  const lines = [
    ` *${data.config.companyName || "ArcD Obras"} - Alertas*`,
    ` ${fmtDateFull(todayIso)}`,
    "",
  ];

  // Terceirizados pendentes esta sexta
  const activeTerc = (data.terceirizados||[]).filter(t => t.active !== false);
  const pendingTerc = activeTerc.filter(t =>
    !(data.pagsTerceiros||[]).some(p => p.tercId===t.id && p.date>=ws && p.date<=fri)
  );
  if (pendingTerc.length > 0) {
    const total = pendingTerc.reduce((s,t) => s+Number(t.weeklyRate||0), 0);
    lines.push(` *PAGAMENTOS DESTA SEXTA (${fmtDateFull(fri)})*`);
    pendingTerc.forEach(t => {
      const on = data.obras.find(o=>o.id===t.obraId)?.name || "-";
      lines.push(`- ${t.name} (${on}) - ${fmt(t.weeklyRate)}`);
    });
    lines.push(`*Total: ${fmt(total)}*`);
    lines.push("");
  }

  // Ponto pendente hoje
  const summary = getObraAttendanceSummary(data, todayIso);
  const pendingPonto = summary.filter(o => o.hasTeam && !o.completed);
  if (pendingPonto.length > 0) {
    lines.push(` *PONTO PENDENTE HOJE*`);
    pendingPonto.forEach(o => {
      const names = o.missingEmployees.slice(0,3).map(e=>e.name).join(", ");
      const extra = o.missingEmployees.length > 3 ? ` +${o.missingEmployees.length-3}` : "";
      lines.push(`- ${o.obraName}: ${o.missingCount} sem registro (${names}${extra})`);
    });
    lines.push("");
  }

  // Alertas de contrato >80%
  const now2 = new Date();
  const mdays = getDays(now2.getFullYear(), now2.getMonth());
  const contractAlerts = data.obras
    .filter(o => o.status !== "done" && o.contractValue > 0)
    .map(o => {
      const { laborCost } = calcObraLaborCost(data, o.id, mdays);
      const pct = (laborCost / o.contractValue) * 100;
      return { name: o.name, pct, saldo: o.contractValue - laborCost };
    })
    .filter(o => o.pct > 80)
    .sort((a,b) => b.pct - a.pct);
  if (contractAlerts.length > 0) {
    lines.push(`! *CONTRATOS COM ATENÇÃO*`);
    contractAlerts.forEach(o =>
      lines.push(`- ${o.name}: ${o.pct.toFixed(0)}% comprometido - saldo ${fmt(o.saldo)}`)
    );
    lines.push("");
  }

  // Folha em breve
  if (day >= 14 && day <= 16) {
    lines.push(` *FOLHA EM BREVE - 1ª quinzena*`);
    lines.push(`- Pagamento previsto dia 20. Confirme todos os pontos.`);
    lines.push("");
  }
  if (day >= 29 || day <= 3) {
    lines.push(` *FOLHA EM BREVE - 2ª quinzena*`);
    lines.push(`- Pagamento previsto dia 05. Confirme todos os pontos.`);
    lines.push("");
  }

  if (lines.length <= 4) lines.push(" Nenhum alerta pendente no momento.");
  lines.push(`_Enviado via ArcD Obras_`);
  return lines.join("\n");
};

const buildQuickAlerts = (data, currentUser) => {
  const todayIso = today();
  const todayDate = new Date(todayIso+"T12:00:00");
  const fri = getFridayOfWeek(0);
  const { start: ws } = getWeekRange(fri);
  const alerts = [];

  //  Parcelas vencidas ou vencendo em até 3 dias 
  const alertaCobranca = (data.medicoes||[]).filter(m => {
    if (m.recebido || !m.dataVencimento) return false;
    const venc = new Date(m.dataVencimento+"T12:00:00");
    const diffDias = Math.round((venc - todayDate)/(1000*60*60*24));
    return diffDias <= 3; // vence nos próximos 3 dias ou já venceu
  }).map(m => {
    const obra = data.obras.find(o=>o.id===m.obraId);
    const venc = new Date(m.dataVencimento+"T12:00:00");
    const diffDias = Math.round((venc - todayDate)/(1000*60*60*24));
    return { m, obraName: obra?.name||"-", diffDias };
  });
  const vencidas  = alertaCobranca.filter(x=>x.diffDias<0);
  const vencendo  = alertaCobranca.filter(x=>x.diffDias>=0);

  if (vencidas.length > 0) {
    const total = vencidas.reduce((s,x)=>s+x.m.valorPrevisto,0);
    alerts.push({
      type:"vencido", color:"#B71C1C", icon:"",
      title:`${vencidas.length} parcela(s) VENCIDA(S) - ${fmt(total)}`,
      sub: vencidas.slice(0,3).map(x=>`${x.obraName}: ${fmt(x.m.valorPrevisto)} (${Math.abs(x.diffDias)}d atraso)`).join("  "),
      tab:"medicoes",
    });
  }
  if (vencendo.length > 0) {
    const total = vencendo.reduce((s,x)=>s+x.m.valorPrevisto,0);
    alerts.push({
      type:"vencendo", color:"#D84315", icon:"",
      title:`${vencendo.length} parcela(s) vencem em até 3 dias - ${fmt(total)}`,
      sub: vencendo.slice(0,3).map(x=>`${x.obraName}: ${fmt(x.m.valorPrevisto)} (${x.diffDias===0?"hoje":`em ${x.diffDias}d`})`).join("  "),
      tab:"medicoes",
    });
  }

  // Terceirizados pendentes
  const activeTerc = (data.terceirizados||[]).filter(t => t.active !== false);
  const pendingTerc = activeTerc.filter(t =>
    !(data.pagsTerceiros||[]).some(p => p.tercId===t.id && p.date>=ws && p.date<=fri)
  );
  if (pendingTerc.length > 0) {
    alerts.push({
      type: "payment", color: "#D84315", icon: "",
      title: `${pendingTerc.length} terceirizado(s) a pagar esta sexta`,
      sub: `${fmtDateFull(fri)}  Total ${fmt(pendingTerc.reduce((s,t)=>s+Number(t.weeklyRate||0),0))}`,
    });
  }

  // Ponto pendente
  const summary = getObraAttendanceSummary(data, todayIso);
  const pendingPonto = summary.filter(o => o.hasTeam && !o.completed);
  if (pendingPonto.length > 0) {
    alerts.push({
      type: "ponto", color: "#B71C1C", icon: "",
      title: `Ponto pendente em ${pendingPonto.length} obra(s)`,
      sub: pendingPonto.map(o=>`${o.obraName}: ${o.missingCount}`).join("  "),
    });
  }

  // Licenciamento: primeiro o que e do operador logado (acao direta dele),
  // depois a visao geral por obra.
  const licMinhas = pendenciasLicenca(data, currentUser?.id).filter(p=>p.meu);
  if (licMinhas.length > 0) {
    alerts.push({ type:"licenca", color:C.orange, icon:"!",
      title:`Você tem ${licMinhas.length} documento(s) de licenciamento pendente(s)`,
      sub:licMinhas.slice(0,3).map(p=>`${p.obraNome}: ${p.docNome}`).join("  ·  "),
      tab:"licenca" });
  }
  const licObras = obrasLicencaIncompleta(data);
  if (licObras.length > 0) {
    const protocoladas = licObras.filter(o=>o.protocolado).length;
    alerts.push({ type:"licenca_geral", color:C.blue, icon:"",
      title:`${licObras.length} obra(s) com licenciamento em aberto`,
      sub:licObras.slice(0,3).map(o=>`${o.obraNome}: faltam ${o.faltam}`).join("  ·  ")
          + (protocoladas?`  ·  ${protocoladas} já protocolada(s)`:""),
      tab:"licenca" });
  }

  const solicitacoesPendentes=(data.solicitacoesCompra||[]).filter(s=>s.status==="enviada");
  if(solicitacoesPendentes.length>0){
    alerts.push({type:"compras",color:C.orange,icon:"!",
      title:`${solicitacoesPendentes.length} solicitação(ões) de material aguardando Compras`,
      sub:solicitacoesPendentes.slice(0,3).map(s=>`${(data.obras||[]).find(o=>o.id===s.obraId)?.name||"Obra"}: ${s.itens.length} item(ns)${s.prioridade==="urgente"?" · URGENTE":""}`).join("  "),
      tab:"cmp"});
  }

  // Comercial: concentra as pendencias que exigem acao imediata.
  const comercial=data.comercial||{};
  const leadsAtivos=(comercial.leads||[]).filter(l=>!["perdido","arquivado","transferido"].includes(l.etapa)&&l.status!=="arquivado");
  const semAtendimento=leadsAtivos.filter(l=>!l.responsavelId||!l.proximaAtividadeEm).length;
  const tarefasVencidas=(comercial.atividades||[]).filter(a=>a.status!=="concluida"&&a.dataHora&&new Date(a.dataHora).getTime()<Date.now()).length;
  const reunioesAtrasadas=(comercial.reunioes||[]).filter(r=>r.status==="agendada"&&r.dataHora&&new Date(r.dataHora).getTime()<Date.now()).length;
  const contratosPendentes=(comercial.contratos||[]).filter(k=>["enviado","aguardando_assinatura"].includes(k.status)||(k.assinadoEm&&!k.entradaPaga)).length;
  const pendenciasComerciais=semAtendimento+tarefasVencidas+reunioesAtrasadas+contratosPendentes;
  if(pendenciasComerciais>0){
    alerts.push({type:"comercial",color:C.green,icon:"!",
      title:`${pendenciasComerciais} pendencia(s) no Comercial`,
      sub:[semAtendimento&&`${semAtendimento} lead(s) sem atendimento`,tarefasVencidas&&`${tarefasVencidas} tarefa(s) vencida(s)`,reunioesAtrasadas&&`${reunioesAtrasadas} reuniao(oes) atrasada(s)`,contratosPendentes&&`${contratosPendentes} contrato(s) pendente(s)`].filter(Boolean).join("  "),
      tab:"com_dash"});
  }

  // Contratos em alerta
  const now2 = new Date();
  const mdays = getDays(now2.getFullYear(), now2.getMonth());
  const contractAlerts = data.obras
    .filter(o => o.status !== "done" && o.contractValue > 0)
    .map(o => {
      const { laborCost } = calcObraLaborCost(data, o.id, mdays);
      return { name: o.name, pct: (laborCost/o.contractValue)*100 };
    })
    .filter(o => o.pct > 80);
  if (contractAlerts.length > 0) {
    alerts.push({
      type: "contract", color: "#D4AF37", icon: "!",
      title: `${contractAlerts.length} contrato(s) acima de 80% comprometido`,
      sub: contractAlerts.map(o=>`${o.name}: ${o.pct.toFixed(0)}%`).join("  "),
    });
  }
  return alerts;
};

// 
// FLUXO DE CAIXA
// 

function FluxoCaixa({ data }) {
  // Extrai primitivos: `new Date()` gera um objeto novo a cada render, então
  // usá-lo direto na lista de dependências faria o memo recalcular sempre.
  const _hoje = new Date();
  const nowY = _hoje.getFullYear();
  const nowM = _hoje.getMonth();
  const [months, setMonths] = useState(6);

  // Calcula histórico real + projeção futura
  const cashflow = useMemo(() => {
    const result = [];
    for (let i = -(months-1); i <= 3; i++) {
      const d = new Date(nowY, nowM+i, 1);
      const y = d.getFullYear();
      const m = d.getMonth();
      const ym = `${y}-${String(m+1).padStart(2,"0")}`;
      const mdays = getDays(y, m);
      const isFuture = d > new Date(nowY, nowM, 1);

      if (!isFuture) {
        // Real
        const received = (data.payments||[]).filter(p=>p.date?.startsWith(ym)).reduce((s,p)=>s+Number(p.amount||0),0);
        const laborCost = data.obras.reduce((s,o)=>s+calcObraLaborCost(data,o.id,mdays).laborCost,0);
        const tercCost = (data.pagsTerceiros||[]).filter(p=>p.date?.startsWith(ym)).reduce((s,p)=>s+Number(p.amount||0),0);
        const totalOut = laborCost + tercCost;
        result.push({ mes: monthName(m)+"/"+String(y).slice(2), received, laborCost, tercCost, totalOut, balance: received-totalOut, isProjection: false, isCurrent: i===0 });
      } else {
        // Projeção
        const workDays = mdays.filter(d=>{const wd=new Date(d+"T12:00:00").getDay();return wd>=1&&wd<=6;}).length;
        const activeEmps = data.employees.filter(e=>e.active!==false);
        const laborEst = activeEmps.reduce((s,e)=>s+Number(e.dailyRate||0)*workDays*0.82,0);
        const tercEst = (data.terceirizados||[]).filter(t=>t.active!==false).reduce((s,t)=>s+Number(t.weeklyRate||0)*4.3,0);
        const revenueEst = data.obras.filter(o=>o.status!=="done").reduce((s,o)=>{const{laborCost}=calcObraLaborCost(data,o.id,mdays);return s+calcObraRevenue(o,laborCost).revenue;},0);
        result.push({ mes: monthName(m)+"/"+String(y).slice(2), received: revenueEst, laborCost: laborEst, tercCost: tercEst, totalOut: laborEst+tercEst, balance: revenueEst-(laborEst+tercEst), isProjection: true, isCurrent: false });
      }
    }
    return result;
  }, [data, months, nowY, nowM]);

  const maxVal = Math.max(...cashflow.map(c=>Math.max(c.received,c.totalOut,1)));
  const totalReceived = cashflow.filter(c=>!c.isProjection).reduce((s,c)=>s+c.received,0);
  const totalOut = cashflow.filter(c=>!c.isProjection).reduce((s,c)=>s+c.totalOut,0);
  const projReceived = cashflow.filter(c=>c.isProjection).reduce((s,c)=>s+c.received,0);
  const projOut = cashflow.filter(c=>c.isProjection).reduce((s,c)=>s+c.totalOut,0);

  return (
    <div style={{display:"flex",flexDirection:"column",gap:12}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div>
          <p style={{fontSize:11,fontWeight:900,color:C.blue,textTransform:"uppercase",letterSpacing:1}}>Histórico + Projeção</p>
          <h3 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:26,letterSpacing:1.5,color:C.text}}>Fluxo de Caixa</h3>
        </div>
        <Sel value={String(months)} onChange={v=>setMonths(Number(v))} options={[{v:"3",l:"3 meses"},{v:"6",l:"6 meses"},{v:"12",l:"12 meses"}]}/>
      </div>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8}}>
        {[
          ["Recebido (real)", fmt(totalReceived),    C.green],
          ["Saída (real)",    fmt(totalOut),          C.red],
          ["Receita proj.",   fmt(projReceived),      C.blue],
          ["Saída proj.",     fmt(projOut),           C.orange],
        ].map(([l,v,c])=>(
          <div key={l} style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${c}`,padding:"10px 12px",borderRadius:10}}>
            <p style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase"}}>{l}</p>
            <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,color:c,fontSize:22,lineHeight:1.1,marginTop:3}}>{v}</p>
          </div>
        ))}
      </div>

      {/* Gráfico visual (barras CSS customizadas) */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,padding:14,borderRadius:12}}>
        <p style={{fontSize:11,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:.8,marginBottom:12}}>Receita x Saída por mês</p>
        <div style={{display:"flex",gap:6,alignItems:"flex-end",height:140}}>
          {cashflow.map((c,i)=>{
            const hRec = Math.round((c.received/maxVal)*120);
            const hOut = Math.round((c.totalOut/maxVal)*120);
            const isPos = c.balance >= 0;
            return (
              <div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
                <div style={{display:"flex",gap:2,alignItems:"flex-end",height:120}}>
                  <div style={{width:12,height:hRec||2,background:c.isProjection?C.blue+"88":C.green,borderRadius:"3px 3px 0 0",transition:"height .3s"}}/>
                  <div style={{width:12,height:hOut||2,background:c.isProjection?C.orange+"88":C.red,borderRadius:"3px 3px 0 0",transition:"height .3s"}}/>
                </div>
                <p style={{fontSize:8,color:c.isCurrent?C.yellow:c.isProjection?C.blue:C.muted,fontWeight:c.isCurrent?900:700,textAlign:"center",whiteSpace:"nowrap"}}>{c.mes}</p>
                <div style={{width:12,height:3,background:isPos?C.green:C.red,borderRadius:99}}/>
              </div>
            );
          })}
        </div>
        <div style={{display:"flex",gap:12,marginTop:10,flexWrap:"wrap"}}>
          {[[" Recebido/Proj",C.green],[" Saída/Proj",C.red],[" Projeção",C.blue+"88"]].map(([l,c])=>(
            <p key={l} style={{fontSize:10,color:c,fontWeight:700}}>{l}</p>
          ))}
          <p style={{fontSize:10,color:C.muted}}> Saldo (verde=positivo)</p>
        </div>
      </div>

      {/* Tabela mês a mês */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,overflow:"hidden"}}>
        <div style={{padding:"10px 14px",borderBottom:`1px solid ${C.line}`,display:"grid",gridTemplateColumns:"1.2fr 1fr 1fr 1fr 1fr",gap:4}}>
          {["Mês","Recebido","MO","Terceiros","Saldo"].map(h=>(
            <p key={h} style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase"}}>{h}</p>
          ))}
        </div>
        {cashflow.map((c,i)=>(
          <div key={i} style={{
            padding:"9px 14px",
            borderBottom:i<cashflow.length-1?`1px solid ${C.line}`:"none",
            display:"grid",gridTemplateColumns:"1.2fr 1fr 1fr 1fr 1fr",gap:4,
            background:c.isCurrent?`${C.yellow}0a`:c.isProjection?`${C.blue}07`:"transparent",
          }}>
            <p style={{fontSize:12,fontWeight:c.isCurrent?900:600,color:c.isCurrent?C.yellow:c.isProjection?C.blue:C.text}}>
              {c.mes}{c.isProjection?" *":""}{c.isCurrent?" ":""}
            </p>
            <p style={{fontSize:12,color:C.green,fontWeight:700}}>{fmt(c.received)}</p>
            <p style={{fontSize:12,color:C.orange}}>{fmt(c.laborCost)}</p>
            <p style={{fontSize:12,color:C.purple}}>{fmt(c.tercCost)}</p>
            <p style={{fontSize:12,color:c.balance>=0?C.green:C.red,fontWeight:900}}>{fmt(c.balance)}</p>
          </div>
        ))}
        <div style={{padding:"8px 14px",background:C.surface,borderTop:`2px solid ${C.line}`}}>
          <p style={{fontSize:9,color:C.muted}}>* Projeção: MO estimada com 82% de presença  Terceiros com 4,3 semanas/mês</p>
        </div>
      </div>
    </div>
  );
}

// 
// TERCEIROS - cadastro e pagamentos semanais
// 

function Terceiros({ data, update, showToast }) {
  const { formGrid } = useBreakpoint();
  const emptyT = { id:"", name:"", specialty:"eletricista", obraId:"", contractValue:"", weeklyRate:"", phone:"", pixKey:"", notes:"", startDate:today(),
    situacao:"andamento", endDate:"", tipoPessoa:"PJ", documento:"", razaoSocial:"", inscEstadual:"", inscMunicipal:"",
    email:"", responsavel:"", cep:"", endereco:"", cidade:"", ufEnd:"", tipoContrato:"medicao", pagador:"obra",
    banco:"", agencia:"", conta:"", retISS:"", retINSS:"", retISSQuem:"fonte", retINSSQuem:"fonte" };
  const [view,        setView]        = useState("kanban");
  const [weekOffset,  setWeekOffset]  = useState(0);
  const [modal,       setModal]       = useState(false);
  const [form,        setForm]        = useState(emptyT);
  const [payModal,    setPayModal]    = useState(null);
  const [payAmount,   setPayAmount]   = useState("");
  const [payDesc,     setPayDesc]     = useState("");
  const [filterObra,  setFilterObra]  = useState("all");
  const [filterSpec,  setFilterSpec]  = useState("all");
  const [expanded,    setExpanded]    = useState(null);
  const [tercSel,     setTercSel]     = useState("");     // contrato aberto em Medições
  const [arrastando,  setArrastando]  = useState(null);   // id do card em drag
  const [colunaAlvo,  setColunaAlvo]  = useState(null);   // coluna sob o card
  const [docForm,     setDocForm]     = useState({ tipo:"CND", numero:"", validade:"" });
  const [etapaForm,   setEtapaForm]   = useState({ id:"", nome:"", valor:"" });
  const [medModal,    setMedModal]    = useState(false);
  const [medForm,     setMedForm]     = useState({ data: today(), observacao:"", pcts:{} });

  const F = k => v => setForm(f => ({ ...f, [k]: v }));
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";

  // Abre o modal para editar: numeros viram string (os inputs sao de texto) e
  // os campos novos preservam o que ja existe.
  const editarTerc = t => {
    setForm({ ...emptyT, ...t,
      weeklyRate: String(t.weeklyRate || ""), contractValue: String(t.contractValue || ""),
      retISS: t.retISS ? String(t.retISS) : "", retINSS: t.retINSS ? String(t.retINSS) : "",
      documentos: (t.documentos || []).map(d => ({ ...d })) });
    setDocForm({ tipo: "CND", numero: "", validade: "" });
    setModal(true);
  };

  const friday     = getFridayOfWeek(weekOffset);
  const { start: weekStart, end: weekEnd } = getWeekRange(friday);
  const allTerc    = data.terceirizados || [];
  const activeTerc = allTerc.filter(t => t.active !== false);

  const wasPaidThisWeek = id =>
    (data.pagsTerceiros || []).some(p => p.tercId === id && p.date >= weekStart && p.date <= weekEnd);
  const thisWeekPay = id =>
    (data.pagsTerceiros || []).find(p => p.tercId === id && p.date >= weekStart && p.date <= weekEnd);

  // KPIs
  const totalWeekly     = activeTerc.reduce((s, t) => s + Number(t.weeklyRate || 0), 0);
  const totalContracts  = allTerc.reduce((s, t) => s + Number(t.contractValue || 0), 0);
  const totalPaidAll    = (data.pagsTerceiros || []).reduce((s, p) => s + Number(p.amount || 0), 0);
  const pendingCount    = activeTerc.filter(t => !wasPaidThisWeek(t.id)).length;
  const pendingTotal    = activeTerc.filter(t => !wasPaidThisWeek(t.id)).reduce((s,t) => s+Number(t.weeklyRate||0), 0);

  const filteredTerc = allTerc
    .filter(t => filterObra === "all" || t.obraId === filterObra)
    .filter(t => filterSpec === "all" || t.specialty === filterSpec)
    .sort((a, b) => a.name.localeCompare(b.name));

  const saveTerc = () => {
    if (!form.name.trim()) { showToast("Nome obrigatório.", "error"); return; }
    // Documento so trava se preenchido e invalido: cadastro parcial e comum,
    // mas CNPJ/CPF digitado errado vira dor de cabeca na nota fiscal.
    const docLimpo = soDigitos(form.documento);
    if (docLimpo && !validarDocumento(docLimpo, form.tipoPessoa)) {
      showToast(`${form.tipoPessoa === "PF" ? "CPF" : "CNPJ"} inválido - confira os dígitos.`, "error"); return;
    }
    const payload = {
      ...form, id: form.id || uid(),
      weeklyRate: Number(form.weeklyRate || 0),
      contractValue: Number(form.contractValue || 0),
      retISS: Number(form.retISS || 0), retINSS: Number(form.retINSS || 0),
      documento: docLimpo,
      cep: soDigitos(form.cep),
      // active espelha situacao para o resto do app continuar funcionando.
      active: form.situacao !== "concluido" && form.situacao !== "pausado",
      documentos: form.documentos || [],
    };
    const terceirizados = form.id ? allTerc.map(t => t.id === form.id ? payload : t) : [...allTerc, payload];
    update({ ...data, terceirizados });
    setModal(false);
    showToast(form.id ? "Terceirizado atualizado." : "Terceirizado cadastrado.");
  };

  // Adiciona/remove documento diretamente no form aberto (antes de salvar).
  const addDocNoForm = () => {
    if (!docForm.validade) { showToast("Informe a validade do documento.", "error"); return; }
    setForm(f => ({ ...f, documentos: [...(f.documentos || []),
      { id: uid(), tipo: docForm.tipo, numero: String(docForm.numero || "").trim(), validade: docForm.validade }] }));
    setDocForm({ tipo: "CND", numero: "", validade: "" });
  };
  const delDocNoForm = id => setForm(f => ({ ...f, documentos: (f.documentos || []).filter(d => d.id !== id) }));

  const removeTerc = id => {
    if (!window.confirm("Remover terceirizado? O histórico de pagamentos será mantido.")) return;
    update({ ...data, terceirizados: allTerc.filter(t => t.id !== id) });
    showToast("Terceirizado removido.");
  };

  const toggleActive = id => {
    const terceirizados = allTerc.map(t => t.id === id ? { ...t, active: !t.active } : t);
    update({ ...data, terceirizados });
    showToast("Status atualizado.");
  };

  const savePay = terc => {
    const amount = Number(payAmount || terc.weeklyRate || 0);
    if (!amount) { showToast("Informe o valor.", "error"); return; }
    const ret = calcRetencoes(amount, terc);
    const pagsTerceiros = [...(data.pagsTerceiros || []), {
      id: uid(), tercId: terc.id, tercName: terc.name, specialty: terc.specialty,
      obraId: terc.obraId, date: friday, amount, description: payDesc || `Pagamento semanal ${fmtDateFull(friday)}`,
      // Congela quem banca no momento do pagamento: mudar o contrato depois nao
      // deve reescrever DRE de meses ja fechados.
      pagador: terc.pagador === "empresa" ? "empresa" : "obra",
      issRetido: ret.issRetido, inssRetido: ret.inssRetido, liquido: ret.liquido,
    }];
    update({ ...data, pagsTerceiros });
    setPayModal(null); setPayAmount(""); setPayDesc("");
    showToast(ret.retido > 0
      ? `${terc.name} - ${fmt(amount)} bruto, ${fmt(ret.liquido)} líquido.`
      : `${terc.name} - pagamento registrado.`);
  };

  const removePay = id => {
    if (!window.confirm("Remover pagamento?")) return;
    // Se o pagamento veio de uma medicao, ela volta a constar como nao paga -
    // senao a medicao ficaria apontando para um pagamento inexistente.
    update({ ...data,
      pagsTerceiros: (data.pagsTerceiros || []).filter(p => p.id !== id),
      medicoesTerc: (data.medicoesTerc || []).map(m => m.pagamentoId === id ? { ...m, pagamentoId: "" } : m) });
    showToast("Pagamento removido.");
  };

  //  KANBAN DE CONTRATOS 

  // Cards visiveis no Kanban, ja filtrados por obra.
  // Avanco fisico de um contrato: medido / soma das etapas. Sem etapas, cai no
  // que ja existe (pago / valor do contrato) para o card nunca ficar mudo.
  const avancoContrato = useCallback(t => {
    const etapas = t.etapas || [];
    const meds = (data.medicoesTerc || []).filter(m => m.tercId === t.id);
    if (etapas.length) {
      const soma = etapas.reduce((s, e) => s + Number(e.valor || 0), 0);
      const medido = meds.reduce((s, m) => s + Number(m.total || 0), 0);
      return soma > 0 ? Math.min(100, medido / soma * 100) : 0;
    }
    const pago = (data.pagsTerceiros || []).filter(p => p.tercId === t.id).reduce((s, p) => s + Number(p.amount || 0), 0);
    const val = Number(t.contractValue || 0);
    return val > 0 ? Math.min(100, pago / val * 100) : 0;
  }, [data.medicoesTerc, data.pagsTerceiros]);

  // Kanban POR OBRA. Cada obra com pelo menos um terceirizado vira um quadro
  // próprio; obra sem terceiro não aparece. Ordem: primeiro as obras com MAIS
  // terceiros; no empate, a que está MAIS NO INÍCIO da execução (menor avanço
  // médio de contrato). Terceiros bancados pela empresa (sem obra) caem num
  // bloco próprio ao final, para não sumirem.
  const kanbansPorObra = useMemo(() => {
    const grupos = {};
    allTerc.forEach(t => {
      const chave = t.pagador === "empresa" && !t.obraId ? "__empresa__" : (t.obraId || "__sem_obra__");
      (grupos[chave] = grupos[chave] || []).push(t);
    });
    const avancoMedio = lista => lista.length
      ? lista.reduce((s,t)=>s+avancoContrato(t),0) / lista.length : 0;
    return Object.entries(grupos)
      .map(([obraId, lista]) => ({
        obraId,
        nome: obraId === "__empresa__" ? "Terceiros da empresa"
            : obraId === "__sem_obra__" ? "Sem obra vinculada"
            : obraName(obraId),
        especial: obraId === "__empresa__" || obraId === "__sem_obra__",
        lista,
        qtd: lista.length,
        avanco: avancoMedio(lista),
      }))
      .sort((a,b) => {
        // Blocos especiais (empresa / sem obra) sempre por último.
        if (a.especial !== b.especial) return a.especial ? 1 : -1;
        // Mais terceiros primeiro.
        if (b.qtd !== a.qtd) return b.qtd - a.qtd;
        // Empate: mais no início da execução (menor avanço) primeiro.
        return a.avanco - b.avanco;
      });
  }, [allTerc, avancoContrato, obraName]);

  // Distribui uma lista de terceiros nas 4 colunas de situação. Reutilizável:
  // cada quadro-por-obra chama com a sua própria lista.
  const distribuirColunas = useCallback(lista => {
    const mapa = Object.fromEntries(COLS_KANBAN.map(c => [c.v, []]));
    (lista || []).forEach(t => {
      const col = colKanban(t.situacao).v;
      (mapa[col] || mapa.andamento).push(t);
    });
    return mapa;
  }, []);

  // Dias em que cada terceirizado aparece como presente/meio nos diários de
  // obra (RDO). Fecha o ciclo: o que foi marcado no diário vira histórico de
  // presença no contrato, sem digitação dupla.
  const diasDiarioTerc = useMemo(() => {
    const mapa = {};
    (data.rdos || []).forEach(r => (r.terceirizados || []).forEach(t => {
      if (t.status === "falta") return;
      mapa[t.tercId] = mapa[t.tercId] || { dias: 0, meios: 0, datas: [] };
      if (t.status === "meio") mapa[t.tercId].meios += 1;
      else mapa[t.tercId].dias += 1;
      mapa[t.tercId].datas.push(r.data);
    }));
    return mapa;
  }, [data.rdos]);

  // Move um contrato de coluna. Concluir sem ter medido tudo e permitido (o
  // usuario manda), mas fica avisado - contrato entregue costuma estar 100%.
  const moverSituacao = (t, novaSituacao) => {
    if (t.situacao === novaSituacao) return;
    const patch = { situacao: novaSituacao, active: novaSituacao !== "concluido" && novaSituacao !== "pausado" ? true : t.active };
    if (novaSituacao === "concluido") {
      patch.active = false;
      if (!t.endDate) patch.endDate = today();
      const av = avancoContrato(t);
      if (av < 99.5) showToast(`${t.name} concluído com ${av.toFixed(0)}% medido. Confira as medições em aberto.`, "warn");
    }
    if (novaSituacao === "andamento" || novaSituacao === "contratado") patch.endDate = "";
    if (novaSituacao === "pausado") patch.active = false;
    update({ ...data, terceirizados: allTerc.map(x => x.id === t.id ? { ...x, ...patch } : x) });
  };

  const soltarNaColuna = col => {
    setColunaAlvo(null);
    const t = allTerc.find(x => x.id === arrastando);
    setArrastando(null);
    if (t && col) moverSituacao(t, col);
  };

  //  DOCUMENTOS DO TERCEIRIZADO 

  // Documentos de todos os contratos, achatados, para o painel de pendencias.
  const documentosPendentes = useMemo(() => {
    const lista = [];
    allTerc.forEach(t => (t.documentos || []).forEach(doc => {
      const dias = diasAte(doc.validade);
      if (dias === null) return;
      if (dias <= 30) lista.push({ ...doc, tercId: t.id, tercName: t.name, obraId: t.obraId, dias });
    }));
    return lista.sort((a, b) => a.dias - b.dias);
  }, [allTerc]);

  //  ETAPAS DO CONTRATO E MEDICOES 
  // "1.500,00" | "1500.50" | 1500 -> number. Decide pelo separador que aparece
  // por ultimo: quem vier depois e a virgula decimal, o outro e milhar.
  const num = v => {
    if (typeof v === "number") return v;
    const t = String(v ?? "").trim().replace(/[^\d,.-]/g, "");
    if (!t) return 0;
    const vi = t.lastIndexOf(","), pi = t.lastIndexOf(".");
    let n = t;
    if (vi >= 0 && pi >= 0) n = vi > pi ? t.replace(/\./g, "").replace(",", ".") : t.replace(/,/g, "");
    else if (vi >= 0) n = t.replace(",", ".");
    return Number(n) || 0;
  };
  const pct = v => Math.max(0, Math.min(100, Number(String(v ?? "").replace(",", ".")) || 0));

  const tercAtual = allTerc.find(t => t.id === tercSel) || null;
  const etapasTerc = tercAtual?.etapas || [];

  // Medicoes em ordem cronologica. O acumulado de uma etapa e o da ULTIMA
  // medicao que a mediu - por isso a ordem importa mais que o numero.
  const medicoesDo = id => (data.medicoesTerc || [])
    .filter(m => m.tercId === id)
    .sort((a, b) => (a.data + a.id).localeCompare(b.data + b.id));

  const medicoesTercAtual = tercSel ? medicoesDo(tercSel) : [];

  const acumuladoPorEtapa = useMemo(() => {
    const mapa = {};
    medicoesTercAtual.forEach(m => m.itens.forEach(i => { mapa[i.etapaId] = Number(i.pctAcum || 0); }));
    return mapa;
  }, [data.medicoesTerc, tercSel]);

  const somaEtapas   = etapasTerc.reduce((s, e) => s + Number(e.valor || 0), 0);
  const totalMedido  = medicoesTercAtual.reduce((s, m) => s + Number(m.total || 0), 0);
  // Avanco fisico ponderado pelo valor de cada etapa - nao pela contagem.
  const pctFisico    = somaEtapas > 0
    ? etapasTerc.reduce((s, e) => s + Number(e.valor || 0) * (acumuladoPorEtapa[e.id] || 0) / 100, 0) / somaEtapas * 100
    : 0;

  const salvarEtapa = () => {
    if (!tercAtual) return;
    const nome = String(etapaForm.nome || "").trim();
    if (!nome) { showToast("Informe o nome da etapa.", "error"); return; }
    const valor = num(etapaForm.valor);
    const etapas = etapaForm.id
      ? etapasTerc.map(e => e.id === etapaForm.id ? { ...e, nome, valor } : e)
      : [...etapasTerc, { id: uid(), nome, valor, ordem: etapasTerc.length }];
    update({ ...data, terceirizados: allTerc.map(t => t.id === tercSel ? { ...t, etapas } : t) });
    setEtapaForm({ id: "", nome: "", valor: "" });
    showToast(etapaForm.id ? "Etapa atualizada." : "Etapa adicionada ao contrato.");
  };

  const removerEtapa = etapa => {
    if (acumuladoPorEtapa[etapa.id] > 0) {
      showToast("Esta etapa já foi medida. Zere a medição antes de removê-la.", "error"); return;
    }
    if (!window.confirm(`Remover a etapa "${etapa.nome}"?`)) return;
    update({ ...data, terceirizados: allTerc.map(t => t.id === tercSel
      ? { ...t, etapas: etapasTerc.filter(e => e.id !== etapa.id).map((e, i) => ({ ...e, ordem: i })) } : t) });
    if (etapaForm.id === etapa.id) setEtapaForm({ id: "", nome: "", valor: "" });
  };

  const moverEtapa = (etapa, dir) => {
    const lista = [...etapasTerc];
    const i = lista.findIndex(e => e.id === etapa.id);
    const j = i + dir;
    if (i < 0 || j < 0 || j >= lista.length) return;
    [lista[i], lista[j]] = [lista[j], lista[i]];
    update({ ...data, terceirizados: allTerc.map(t => t.id === tercSel
      ? { ...t, etapas: lista.map((e, k) => ({ ...e, ordem: k })) } : t) });
  };

  // Sugere as etapas da especialidade e reparte o contrato por igual. E so um
  // ponto de partida: os valores sao editaveis um a um logo abaixo.
  const sugerirEtapas = () => {
    if (!tercAtual) return;
    if (etapasTerc.length && !window.confirm("Isso substitui as etapas atuais deste contrato. Continuar?")) return;
    if (medicoesTercAtual.length) { showToast("Este contrato já tem medições. Ajuste as etapas manualmente.", "error"); return; }
    const nomes = ETAPAS_SUGERIDAS[tercAtual.specialty] || ETAPAS_SUGERIDAS.outros;
    const fatia = Number(tercAtual.contractValue || 0) / nomes.length;
    update({ ...data, terceirizados: allTerc.map(t => t.id === tercSel
      ? { ...t, etapas: nomes.map((nome, i) => ({ id: uid(), nome, valor: Math.round(fatia * 100) / 100, ordem: i })) } : t) });
    showToast(`${nomes.length} etapas sugeridas. Ajuste os valores de cada uma.`);
  };

  const abrirMedicao = () => {
    if (!etapasTerc.length) { showToast("Subdivida o contrato em etapas antes de medir.", "error"); return; }
    // O formulario ja abre com o acumulado atual: voce so mexe no que avancou.
    setMedForm({ data: today(), observacao: "",
      pcts: Object.fromEntries(etapasTerc.map(e => [e.id, String(acumuladoPorEtapa[e.id] || 0)])) });
    setMedModal(true);
  };

  const itensDaMedicao = () => etapasTerc.map(e => {
    const anterior = Number(acumuladoPorEtapa[e.id] || 0);
    const acum = pct(medForm.pcts?.[e.id] ?? anterior);
    return { etapaId: e.id, pctAnterior: anterior, pctAcum: acum,
             valor: Number(e.valor || 0) * (acum - anterior) / 100 };
  });

  const salvarMedicao = () => {
    if (!tercAtual) return;
    const itens = itensDaMedicao().filter(i => Math.abs(i.pctAcum - i.pctAnterior) > 0.0001);
    if (!itens.length) { showToast("Nenhuma etapa avançou desde a última medição.", "warn"); return; }
    const total = itens.reduce((s, i) => s + i.valor, 0);
    const medicao = {
      id: uid(), tercId: tercSel, obraId: tercAtual.obraId || "",
      data: medForm.data || today(), numero: medicoesTercAtual.length + 1,
      itens, total, observacao: String(medForm.observacao || "").trim(), pagamentoId: "",
    };
    update({ ...data, medicoesTerc: [...(data.medicoesTerc || []), medicao] });
    setMedModal(false);
    showToast(`Medição ${medicao.numero} registrada: ${fmt(total)}.`);
  };

  // A ultima medicao pode ser desfeita sem ambiguidade. Uma do meio nao: os
  // acumulados seguintes foram calculados em cima dela.
  const removerMedicao = m => {
    const ultima = medicoesDo(m.tercId).slice(-1)[0];
    if (!ultima || ultima.id !== m.id) {
      showToast("Só a última medição pode ser removida - as seguintes partem dela.", "error"); return;
    }
    if (m.pagamentoId) { showToast("Esta medição já virou pagamento. Remova o pagamento primeiro.", "error"); return; }
    if (!window.confirm(`Remover a medição ${m.numero}?`)) return;
    update({ ...data, medicoesTerc: (data.medicoesTerc || []).filter(x => x.id !== m.id) });
    showToast("Medição removida.");
  };

  const pagarMedicao = m => {
    const t = allTerc.find(x => x.id === m.tercId);
    if (!t) return;
    if (m.pagamentoId) { showToast("Esta medição já foi paga.", "warn"); return; }
    if (!(m.total > 0)) { showToast("Medição sem valor a pagar.", "warn"); return; }
    const ret = calcRetencoes(m.total, t);
    const pag = { id: uid(), tercId: m.tercId, tercName: t.name, specialty: t.specialty,
      obraId: m.obraId, date: m.data, amount: m.total, medicaoId: m.id,
      description: `Medição ${m.numero} - ${fmtDateFull(m.data)}`,
      pagador: t.pagador === "empresa" ? "empresa" : "obra",
      issRetido: ret.issRetido, inssRetido: ret.inssRetido, liquido: ret.liquido };
    update({ ...data,
      pagsTerceiros: [...(data.pagsTerceiros || []), pag],
      medicoesTerc: (data.medicoesTerc || []).map(x => x.id === m.id ? { ...x, pagamentoId: pag.id } : x) });
    showToast(ret.retido > 0
      ? `Medição paga: ${fmt(m.total)} bruto, ${fmt(ret.liquido)} líquido ao prestador.`
      : `Pagamento de ${fmt(m.total)} registrado para ${t.name}.`);
  };

  // Medicao registrada e ainda nao paga e divida vencida com o terceiro. Ficava
  // invisivel: os KPIs so olhavam pagamento semanal e contrato.
  const medicoesAPagar = (data.medicoesTerc || []).filter(m => !m.pagamentoId && Number(m.total || 0) > 0);
  const totalAPagarMed = medicoesAPagar.reduce((s, m) => s + Number(m.total || 0), 0);

  // Avanco fisico de qualquer contrato, para o card do cadastro.
  const avancoDoContrato = t => {
    const etapas = t.etapas || [];
    const base = etapas.reduce((s, e) => s + Number(e.valor || 0), 0);
    if (!base) return null;
    const acum = {};
    medicoesDo(t.id).forEach(m => m.itens.forEach(i => { acum[i.etapaId] = Number(i.pctAcum || 0); }));
    return etapas.reduce((s, e) => s + Number(e.valor || 0) * (acum[e.id] || 0) / 100, 0) / base * 100;
  };

  const abrirMedicoesDe = id => { setTercSel(id); setView("medicoes"); };

  const paidThisWeekAmount = activeTerc.reduce((s, t) => {
    const p = thisWeekPay(t.id);
    return s + (p ? Number(p.amount) : 0);
  }, 0);

  //  JSX 
  return (
    <div className="anim" style={{ display:"flex", flexDirection:"column", gap:14 }}>

      {/* Header */}
      <div style={{
        background:`linear-gradient(135deg,${C.orange}22 0%,${C.card} 60%)`,
        border:`1px solid ${C.orange}44`, borderLeft:`5px solid ${C.orange}`,
        padding:"16px 18px", borderRadius:12,
      }}>
        <p style={{ fontSize:11, fontWeight:900, color:C.orange, textTransform:"uppercase", letterSpacing:1.2, marginBottom:4 }}>Subcontratados</p>
        <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize:"clamp(19px,8vw,34px)", letterSpacing:2, color:C.text, lineHeight:1 }}>Terceirizados</h2>
        <p style={{ color:C.muted, fontSize:13, marginTop:4 }}>Contratos, especialidades e pagamentos toda sexta-feira.</p>
      </div>

      {/* KPI bar */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
        {[
          ["Ativos",       activeTerc.length,     C.orange, "terc"],
          ["Custo/semana", fmt(totalWeekly),       C.yellow, "dollar"],
          ["Total contratos", fmt(totalContracts), C.green,  "dollar"],
          ["Total pago",   fmt(totalPaidAll),      C.blue,   "check"],
        ].map(([l,v,c,ic]) => (
          <div key={l} style={{ background:C.card, border:`1px solid ${C.border}`, borderTop:`3px solid ${c}`, padding:"12px 14px", borderRadius:10 }}>
            <p style={{ fontSize:10, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:.8 }}>{l}</p>
            <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, color:c, fontSize:26, lineHeight:1.1, marginTop:4 }}>{v}</p>
          </div>
        ))}
        {/* So aparece quando ha o que pagar - card fixo em zero vira ruido. */}
        {medicoesAPagar.length > 0 && (
          <button onClick={() => setView("medicoes")} style={{
            gridColumn:"1 / -1", textAlign:"left", cursor:"pointer",
            background:`${C.red}0E`, border:`1px solid ${C.red}55`, borderTop:`3px solid ${C.red}`,
            padding:"12px 14px", borderRadius:10,
          }}>
            <p style={{ fontSize:10, fontWeight:900, color:C.red, textTransform:"uppercase", letterSpacing:.8 }}>
              {medicoesAPagar.length} medição(ões) medida(s) e não paga(s)
            </p>
            <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, color:C.red, fontSize:26, lineHeight:1.1, marginTop:4 }}>
              {fmt(totalAPagarMed)}
            </p>
          </button>
        )}
      </div>

      {/* Sub-nav */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:6 }}>
        {[["kanban","Quadro"],["cadastro","Cadastro"],["medicoes","Medições"],["pagamentos","Pagamentos"]].map(([v,l]) => (
          <button key={v} onClick={() => setView(v)} style={{
            padding:"11px 0", border:`2px solid ${view===v ? C.orange : C.line}`,
            background: view===v ? `${C.orange}18` : "transparent",
            color: view===v ? C.orange : C.muted,
            fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:900, fontSize:12.5, letterSpacing:.3,
            cursor:"pointer", borderRadius:8,
          }}>{l}</button>
        ))}
      </div>

      {/*  VIEW: KANBAN  */}
      {view === "kanban" && (<>
        {/* Ação de novo contrato. O filtro de obra saiu: agora cada obra tem
            seu próprio quadro, então não há o que filtrar. */}
        <div style={{ display:"flex", justifyContent:"flex-end" }}>
          <Btn size="sm" onClick={() => { setForm({ ...emptyT }); setModal(true); }}>
            <Ic n="plus"/> Novo contrato
          </Btn>
        </div>

        {/* Painel de documentos vencendo - so aparece quando ha pendencia */}
        {documentosPendentes.length > 0 && (
          <div style={{ background:`${C.red}0C`, border:`1px solid ${C.red}44`, borderRadius:10, padding:"11px 13px" }}>
            <p style={{ fontSize:10.5, fontWeight:900, color:C.red, textTransform:"uppercase", letterSpacing:.8, marginBottom:7 }}>
              {documentosPendentes.length} documento(s) vencido(s) ou a vencer
            </p>
            <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
              {documentosPendentes.slice(0, 6).map(doc => (
                <div key={doc.id} style={{ display:"flex", justifyContent:"space-between", gap:8, fontSize:11.5 }}>
                  <span style={{ color:C.subtle, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                    <b>{doc.tercName}</b> · {docTercInfo(doc.tipo).l}
                  </span>
                  <span style={{ flexShrink:0, fontWeight:800, color: doc.dias < 0 ? C.red : doc.dias <= 7 ? C.orange : C.muted }}>
                    {doc.dias < 0 ? `vencido há ${Math.abs(doc.dias)}d` : doc.dias === 0 ? "vence hoje" : `${doc.dias}d`}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Colunas. Rolagem horizontal no celular; cada card arrasta entre colunas. */}
        {kanbansPorObra.length === 0 && (
          <p style={{ padding:"28px 12px", textAlign:"center", fontSize:12, color:C.muted }}>
            Nenhum terceirizado cadastrado ainda. Crie um contrato para o quadro da obra aparecer.
          </p>
        )}

        {/* Um quadro por obra. Só obras COM terceirizados aparecem. Ordem: mais
            terceiros primeiro; no empate, a obra mais no início da execução. */}
        {kanbansPorObra.map(bloco => {
          const colunas = distribuirColunas(bloco.lista);
          const valorObra = bloco.lista.reduce((s,t)=>s+Number(t.contractValue||0),0);
          return (
            <div key={bloco.obraId} style={{ marginBottom:18 }}>
              {/* Cabeçalho da obra */}
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:8,
                            flexWrap:"wrap", marginBottom:8, paddingBottom:6, borderBottom:`2px solid ${bloco.especial?C.muted:C.orange}` }}>
                <div style={{ minWidth:0 }}>
                  <p style={{ fontSize:13.5, fontWeight:900, color:C.text,
                              fontFamily:"'Inter Display','Inter',sans-serif" }}>{bloco.nome}</p>
                  <p style={{ fontSize:10, color:C.muted, marginTop:1 }}>
                    {bloco.qtd} terceirizado(s){!bloco.especial && ` · ${bloco.avanco.toFixed(0)}% de avanço médio`}
                  </p>
                </div>
                {valorObra > 0 && (
                  <span style={{ fontSize:11.5, fontWeight:800, color:C.yellowD, flexShrink:0 }}>{fmt(valorObra)} em contratos</span>
                )}
              </div>

              {/* Colunas de situação desta obra */}
              <div style={KB.scroll}>
                {COLS_KANBAN.map(col => {
                  const cards = colunas[col.v] || [];
                  const soma = cards.reduce((s, t) => s + Number(t.contractValue || 0), 0);
                  const alvoKey = `${bloco.obraId}::${col.v}`;
                  const ativa = colunaAlvo === alvoKey;
                  return (
                    <div key={col.v}
                      onDragOver={e => { e.preventDefault(); setColunaAlvo(alvoKey); }}
                      onDragLeave={() => setColunaAlvo(c => c === alvoKey ? null : c)}
                      onDrop={() => soltarNaColuna(col.v)}
                      style={KB.coluna(col.cor, ativa)}>
                      <div style={KB.colHead(col.cor)}>
                        <div style={{ minWidth:0 }}>
                          <b style={{ fontSize:11, fontWeight:800, color:C.text, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{col.l.toUpperCase()}</b>
                          <p style={{ fontSize:8.5, color:C.muted, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{col.dica}</p>
                        </div>
                        <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:2, flexShrink:0 }}>
                          <span style={KB.contador}>{cards.length}</span>
                          {soma > 0 && <span style={{ fontSize:8.5, fontWeight:700, color:C.yellowD, whiteSpace:"nowrap" }}>{fmt(soma)}</span>}
                        </div>
                      </div>
                      <div style={KB.colBody}>

                      {cards.map(t => {
                        const info = specInfo(t.specialty);
                        const av = avancoContrato(t);
                        const docBad = (t.documentos || []).some(d => { const dd = diasAte(d.validade); return dd !== null && dd <= 0; });
                        const docWarn = (t.documentos || []).some(d => { const dd = diasAte(d.validade); return dd !== null && dd > 0 && dd <= 30; });
                        const docInvalido = t.documento && !validarDocumento(t.documento, t.tipoPessoa);
                        return (
                          <div key={t.id} draggable
                            onDragStart={() => setArrastando(t.id)}
                            onDragEnd={() => { setArrastando(null); setColunaAlvo(null); }}
                            onClick={() => { setTercSel(t.id); setView("medicoes"); }}
                            style={{ ...KB.card(null), borderLeft:`3px solid ${info.color}`,
                                     opacity: arrastando === t.id ? .4 : 1 }}>
                            <div style={{ display:"flex", justifyContent:"space-between", gap:6 }}>
                              <div style={{ minWidth:0 }}>
                                <p style={{ fontSize:11.5, fontWeight:800, color:C.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{t.name}</p>
                                <p style={{ fontSize:9, color:info.color, fontWeight:700 }}>{info.l}</p>
                              </div>
                              {t.contractValue > 0 && (
                                <p style={{ fontSize:10, fontWeight:800, color:C.text, flexShrink:0 }}>{fmt(t.contractValue)}</p>
                              )}
                            </div>

                            {t.documento && (
                              <p style={{ fontSize:9, color:C.muted, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                                {maskDoc(t.documento, t.tipoPessoa)}
                              </p>
                            )}

                            {/* Barra de avanco */}
                            <div>
                              <div style={{ height:4, background:C.surface, borderRadius:99, overflow:"hidden" }}>
                                <div style={{ height:"100%", width:`${av}%`, background: av >= 100 ? C.green : col.cor, borderRadius:99 }}/>
                              </div>
                              <div style={{ display:"flex", justifyContent:"space-between", marginTop:2 }}>
                                <span style={{ fontSize:8.5, color:C.muted }}>{av.toFixed(0)}% medido</span>
                                {(t.etapas?.length > 0) && <span style={{ fontSize:8.5, color:C.muted }}>{t.etapas.length} etapa(s)</span>}
                              </div>
                            </div>

                            {/* Selos de alerta */}
                            {(docBad || docWarn || docInvalido) && (
                              <div style={{ display:"flex", gap:4, flexWrap:"wrap" }}>
                                {docInvalido && <span style={{ fontSize:8, fontWeight:900, color:C.red, background:`${C.red}14`, borderRadius:5, padding:"1px 5px" }}>DOC INVÁLIDO</span>}
                                {docBad && <span style={{ fontSize:8, fontWeight:900, color:C.red, background:`${C.red}14`, borderRadius:5, padding:"1px 5px" }}>CND VENCIDA</span>}
                                {!docBad && docWarn && <span style={{ fontSize:8, fontWeight:900, color:C.orange, background:`${C.orange}14`, borderRadius:5, padding:"1px 5px" }}>DOC A VENCER</span>}
                              </div>
                            )}

                            {/* Mover em telas sem drag (toque): setas discretas */}
                            <div style={{ display:"flex", gap:4, justifyContent:"flex-end" }} onClick={e => e.stopPropagation()}>
                              {COLS_KANBAN.map(c => c.v).indexOf(t.situacao) > 0 && (
                                <button title="Mover para a esquerda"
                                  onClick={() => { const i = COLS_KANBAN.findIndex(c => c.v === t.situacao); moverSituacao(t, COLS_KANBAN[i-1].v); }}
                                  style={{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:5, color:C.muted, cursor:"pointer", fontSize:10, padding:"1px 6px" }}>←</button>
                              )}
                              {COLS_KANBAN.map(c => c.v).indexOf(t.situacao) < COLS_KANBAN.length - 1 && (
                                <button title="Mover para a direita"
                                  onClick={() => { const i = COLS_KANBAN.findIndex(c => c.v === t.situacao); moverSituacao(t, COLS_KANBAN[i+1].v); }}
                                  style={{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:5, color:C.muted, cursor:"pointer", fontSize:10, padding:"1px 6px" }}>→</button>
                              )}
                            </div>
                          </div>
                        );
                      })}

                      {!cards.length && (
                        <p style={{ padding:"12px 6px", textAlign:"center", fontSize:9, color:C.muted,
                                    border:`1px dashed ${C.border}`, borderRadius:6, margin:"2px 0" }}>
                          {arrastando ? "Solte aqui" : "—"}
                        </p>
                      )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
        <p style={{ fontSize:10.5, color:C.muted, textAlign:"center" }}>
          Um quadro por obra, ordenados pelos que têm mais terceirizados e estão mais no início.
          Arraste os cards entre as colunas ou use as setas. Toque num card para abrir as medições.
        </p>
      </>)}

      {/*  VIEW: CADASTRO  */}
      {view === "cadastro" && (<>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
          <p style={{ fontSize:10, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:1 }}>
            {filteredTerc.length} terceirizado(s)
          </p>
          <Btn onClick={() => { setForm(emptyT); setModal(true); }} size="sm"><Ic n="plus"/> Novo</Btn>
        </div>

        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
          <Sel value={filterSpec} onChange={setFilterSpec} options={[{v:"all",l:"Todas especialidades"},...SPECIALTIES.map(s=>({v:s.v,l:s.emoji+" "+s.l}))]}/>
          <Sel value={filterObra} onChange={setFilterObra} options={[{v:"all",l:"Todas as obras"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>
        </div>

        {filteredTerc.length === 0 && (
          <div style={{ background:C.card, border:`1px solid ${C.border}`, padding:24, textAlign:"center", color:C.muted, borderRadius:10 }}>
            Nenhum terceirizado cadastrado.
          </div>
        )}

        {/* Agrupado por obra */}
        {data.obras
          .filter(o => filteredTerc.some(t => t.obraId===o.id))
          .map(obra => {
            const obraTerc = filteredTerc.filter(t => t.obraId===obra.id);
            const obraPago = obraTerc.reduce((s,t) => s+(data.pagsTerceiros||[]).filter(p=>p.tercId===t.id).reduce((s2,p)=>s2+Number(p.amount||0),0), 0);
            const obraWeekly = obraTerc.filter(t=>t.active!==false).reduce((s,t)=>s+Number(t.weeklyRate||0),0);
            return (
              <div key={obra.id}>
                {/* Cabeçalho da obra */}
                <div style={{
                  background:`linear-gradient(90deg,${C.orange}18,transparent)`,
                  borderLeft:`4px solid ${C.orange}`,borderBottom:`1px solid ${C.line}`,
                  padding:"8px 14px",borderRadius:"12px 12px 0 0",marginBottom:-1,
                  display:"flex",justifyContent:"space-between",alignItems:"center",
                }}>
                  <div>
                    <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:16,color:C.orange}}>{obra.name}</p>
                    <p style={{fontSize:11,color:C.muted,marginTop:1}}>{obraTerc.length} terceirizado(s)  {fmt(obraWeekly)}/semana  {fmt(obraPago)} pago total</p>
                  </div>
                  <Badge color={C.orange}>{obraTerc.filter(t=>t.active!==false).length} ativos</Badge>
                </div>

                {obraTerc.map(t => {
                  const sp = specInfo(t.specialty);
                  const pago = (data.pagsTerceiros||[]).filter(p=>p.tercId===t.id).reduce((s,p)=>s+Number(p.amount||0),0);
                  const saldo = Number(t.contractValue||0) - pago;
                  const pct = t.contractValue>0 ? Math.min((pago/t.contractValue)*100, 100) : 0;
                  const exp = expanded === t.id;
                  return (
                    <div key={t.id} style={{ background:C.card, border:`1px solid ${C.border}`, borderRadius: exp?"0":"0", overflow:"hidden", opacity:t.active===false?0.6:1, marginBottom:1 }}>
                      <button onClick={() => setExpanded(exp ? null : t.id)} style={{
                        width:"100%", background:"transparent", border:0, color:C.text,
                        padding:"12px 16px", textAlign:"left", cursor:"pointer",
                        borderLeft:`5px solid ${sp.color}`,
                      }}>
                        <div style={{ display:"flex", justifyContent:"space-between", gap:10 }}>
                          <div style={{ flex:1 }}>
                            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:3 }}>
                              <span style={{ fontSize:16 }}>{sp.emoji}</span>
                              <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:900, fontSize:17 }}>{t.name}</p>
                              {t.active === false && <Badge color={C.muted}>Inativo</Badge>}
                            </div>
                            <p style={{ color:C.muted, fontSize:11 }}>{sp.l}</p>
                            <div style={{ display:"flex", gap:4, flexWrap:"wrap", marginTop:3 }}>
                              {t.weeklyRate>0 && <Badge color={C.orange}>{fmt(t.weeklyRate)}/sem</Badge>}
                              {t.contractValue>0 && <Badge color={C.subtle}>Contrato: {fmt(t.contractValue)}</Badge>}
                              {(t.etapas||[]).length>0 && (
                                <Badge color={C.blue}>{(t.etapas||[]).length} etapas · {(avancoDoContrato(t)??0).toFixed(0)}% medido</Badge>
                              )}
                            </div>
                          </div>
                          <div style={{ textAlign:"right", flexShrink:0 }}>
                            <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize:18, color:saldo>=0?C.green:C.red, lineHeight:1 }}>{fmt(saldo)}</p>
                            <p style={{ fontSize:10, color:C.muted }}>saldo</p>
                          </div>
                        </div>
                        {t.contractValue>0 && (
                          <div style={{ marginTop:6 }}>
                            <div style={{ height:4, background:C.surface, borderRadius:99, overflow:"hidden" }}>
                              <div style={{ height:"100%", width:`${pct}%`, background:pct>90?C.red:C.green, borderRadius:99 }}/>
                            </div>
                          </div>
                        )}
                      </button>

                      {exp && (
                        <div style={{ borderTop:`1px solid ${C.line}`, padding:"12px 16px", background:C.surface, display:"flex", flexDirection:"column", gap:10 }}>
                          <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8 }}>
                            {[["Pago total",fmt(pago),C.blue],["Saldo",fmt(saldo),saldo>=0?C.green:C.red],["Semanal",fmt(t.weeklyRate),C.orange]].map(([l,v,c])=>(
                              <div key={l} style={{ background:C.card, border:`1px solid ${C.border}`, padding:"8px 10px", borderRadius:8 }}>
                                <p style={{ fontSize:9, color:C.muted, textTransform:"uppercase", fontWeight:700 }}>{l}</p>
                                <p style={{ fontSize:14, fontWeight:900, color:c }}>{v}</p>
                              </div>
                            ))}
                          </div>
                          {t.phone && <p style={{ fontSize:12, color:C.subtle }}> {t.phone}</p>}
                          {t.pixKey && <p style={{ fontSize:12, color:C.subtle }}>PIX: {t.pixKey}</p>}
                          {t.notes && <p style={{ fontSize:12, color:C.muted, fontStyle:"italic" }}>"{t.notes}"</p>}
                          <p style={{ fontSize:11, fontWeight:700, color:C.muted, textTransform:"uppercase" }}>Últimos pagamentos</p>
                          {(data.pagsTerceiros||[]).filter(p=>p.tercId===t.id).slice(-5).reverse().map(p=>(
                            <div key={p.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", borderBottom:`1px solid ${C.line}`, paddingBottom:6 }}>
                              <div>
                                <p style={{ fontSize:13, fontWeight:700 }}>{p.description}</p>
                                <p style={{ fontSize:11, color:C.muted }}>{fmtDateFull(p.date)}</p>
                              </div>
                              <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                                <p style={{ color:C.green, fontWeight:900 }}>{fmt(p.amount)}</p>
                                <Btn v="danger" size="sm" onClick={()=>removePay(p.id)}><Ic n="trash"/></Btn>
                              </div>
                            </div>
                          ))}
                          {!(data.pagsTerceiros||[]).some(p=>p.tercId===t.id) && (
                            <p style={{ fontSize:12, color:C.muted }}>Nenhum pagamento registrado.</p>
                          )}
                          <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                            <Btn size="sm" v="info" onClick={()=>abrirMedicoesDe(t.id)}>
                              <Ic n="medicoes"/> {(t.etapas||[]).length ? "Medições" : "Dividir em etapas"}
                            </Btn>
                            <Btn size="sm" v="warning" onClick={()=>{setPayModal(t);setPayAmount(String(t.weeklyRate||""));}}>
                              <Ic n="dollar"/> Registrar pagamento
                            </Btn>
                            <Btn size="sm" v="ghost" onClick={()=>editarTerc(t)}>
                              <Ic n="edit"/> Editar
                            </Btn>
                            <Btn size="sm" v={t.active===false?"success":"dark"} onClick={()=>toggleActive(t.id)}>
                              {t.active===false?"Reativar":"Inativar"}
                            </Btn>
                            <Btn size="sm" v="danger" onClick={()=>removeTerc(t.id)}><Ic n="trash"/></Btn>
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
                <div style={{height:8}}/>
              </div>
            );
          })
        }

        {/* Sem obra definida */}
        {filteredTerc.filter(t=>!t.obraId).length > 0 && (
          <div>
            <div style={{borderLeft:`4px solid ${C.muted}`,padding:"8px 14px",marginBottom:4}}>
              <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:14,color:C.muted}}>Sem obra definida</p>
            </div>
            {filteredTerc.filter(t=>!t.obraId).map(t=>{
              const sp=specInfo(t.specialty);
              return(
                <div key={t.id} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`4px solid ${sp.color}`,padding:"12px 14px",borderRadius:8,marginBottom:4}}>
                  <div style={{display:"flex",justifyContent:"space-between"}}>
                    <p style={{fontWeight:700}}>{sp.emoji} {t.name}</p>
                    <Btn size="sm" v="ghost" onClick={()=>editarTerc(t)}>
                      <Ic n="edit"/>
                    </Btn>
                  </div>
                  <p style={{fontSize:11,color:C.muted,marginTop:3}}>Nenhuma obra vinculada - edite para vincular</p>
                </div>
              );
            })}
          </div>
        )}
      </>)}

      {/*  VIEW: MEDICOES  */}
      {view === "medicoes" && (<>
        <Sel label="Contrato" value={tercSel} onChange={setTercSel}
          options={[{v:"",l:"Selecione o terceirizado..."},
            ...allTerc.map(t => ({ v:t.id, l:`${t.name} · ${specInfo(t.specialty).l}${t.obraId?` · ${obraName(t.obraId)}`:""}` }))]}/>

        {!tercSel && (
          <div style={{ padding:26, textAlign:"center", background:C.card, border:`1px solid ${C.border}`, borderRadius:10 }}>
            <p style={{ fontSize:12.5, color:C.muted, lineHeight:1.6 }}>
              Escolha um contrato para subdividir em etapas e medir o avanço.<br/>
              Ex.: eletricista → rasgo de parede, eletrodutos, enfiação...
            </p>
          </div>
        )}

        {tercAtual && (<>
          {/* Ficha de identificacao do contrato */}
          {(() => {
            const info = specInfo(tercAtual.specialty);
            const col = colKanban(tercAtual.situacao);
            const docOk = tercAtual.documento ? validarDocumento(tercAtual.documento, tercAtual.tipoPessoa) : null;
            return (
              <div style={{ background:C.card, border:`1px solid ${C.border}`, borderLeft:`5px solid ${info.color}`, borderRadius:10, padding:"13px 15px" }}>
                <div style={{ display:"flex", justifyContent:"space-between", gap:8, flexWrap:"wrap" }}>
                  <div style={{ minWidth:0 }}>
                    <p style={{ fontSize:16, fontWeight:900, color:C.text }}>{tercAtual.name}</p>
                    <p style={{ fontSize:11.5, color:info.color, fontWeight:700 }}>
                      {info.l} · {tercAtual.pagador === "empresa" ? "pago pela empresa" : obraName(tercAtual.obraId)}
                    </p>
                  </div>
                  <div style={{ display:"flex", gap:6, alignItems:"flex-start" }}>
                    <span style={{ fontSize:10, fontWeight:900, color:col.cor, background:`${col.cor}18`, borderRadius:99, padding:"4px 10px", whiteSpace:"nowrap" }}>{col.l}</span>
                    <Btn size="sm" v="ghost" onClick={()=>editarTerc(tercAtual)}>Editar</Btn>
                  </div>
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))", gap:"6px 14px", marginTop:10 }}>
                  {tercAtual.documento && (
                    <div>
                      <p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>{tercAtual.tipoPessoa==="PF"?"CPF":"CNPJ"}</p>
                      <p style={{ fontSize:12, color:C.text }}>{maskDoc(tercAtual.documento, tercAtual.tipoPessoa)}
                        <span style={{ marginLeft:6, fontSize:10, fontWeight:800, color: docOk?C.green:C.red }}>{docOk?"✓":"inválido"}</span>
                      </p>
                    </div>
                  )}
                  {tercAtual.razaoSocial && <div><p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>RAZÃO SOCIAL</p><p style={{ fontSize:12, color:C.text }}>{tercAtual.razaoSocial}</p></div>}
                  {tercAtual.responsavel && <div><p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>RESPONSÁVEL</p><p style={{ fontSize:12, color:C.text }}>{tercAtual.responsavel}</p></div>}
                  {tercAtual.phone && <div><p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>TELEFONE</p><p style={{ fontSize:12, color:C.text }}>{tercAtual.phone}</p></div>}
                  {(tercAtual.startDate || tercAtual.endDate) && <div><p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>PERÍODO</p><p style={{ fontSize:12, color:C.text }}>{tercAtual.startDate?fmtDateFull(tercAtual.startDate):"?"}{tercAtual.endDate?` → ${fmtDateFull(tercAtual.endDate)}`:""}</p></div>}
                  {(Number(tercAtual.retISS)>0 || Number(tercAtual.retINSS)>0) && <div><p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>RETENÇÕES</p><p style={{ fontSize:12, color:C.text }}>{Number(tercAtual.retISS)>0?`ISS ${tercAtual.retISS}% (${tercAtual.retISSQuem==="fonte"?"fonte":"prestador"})`:""}{Number(tercAtual.retISS)>0&&Number(tercAtual.retINSS)>0?" · ":""}{Number(tercAtual.retINSS)>0?`INSS ${tercAtual.retINSS}% (${tercAtual.retINSSQuem==="fonte"?"fonte":"prestador"})`:""}</p></div>}
                  {(() => {
                    const dd = diasDiarioTerc[tercAtual.id];
                    if (!dd || (dd.dias + dd.meios) === 0) return null;
                    return <div><p style={{ fontSize:9, fontWeight:900, color:C.muted, letterSpacing:.5 }}>PRESENÇA (DIÁRIO)</p><p style={{ fontSize:12, color:C.text }}>{dd.dias} dia(s){dd.meios?` + ${dd.meios} meio`:""} em obra</p></div>;
                  })()}
                </div>
                {(tercAtual.documentos || []).length > 0 && (
                  <div style={{ display:"flex", gap:5, flexWrap:"wrap", marginTop:10 }}>
                    {tercAtual.documentos.map(doc => {
                      const dias = diasAte(doc.validade);
                      const cor = dias===null?C.muted:dias<=0?C.red:dias<=30?C.orange:C.green;
                      return (
                        <span key={doc.id} style={{ fontSize:9.5, fontWeight:800, color:cor, background:`${cor}14`, borderRadius:6, padding:"3px 8px" }}>
                          {docTercInfo(doc.tipo).l.split(" ")[0]} {dias===null?"":dias<0?`vencida`:dias<=30?`${dias}d`:"ok"}
                        </span>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })()}

          {/* Curva de evolução: medido acumulado ao longo das medições */}
          {medicoesTercAtual.length > 1 && (
            <div style={{ background:C.card, border:`1px solid ${C.border}`, borderRadius:10, padding:"12px 14px" }}>
              <p style={{ fontSize:10, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:1, marginBottom:8 }}>Evolução do medido</p>
              <ResponsiveContainer width="100%" height={130}>
                <LineChart data={(() => { let ac=0; return medicoesTercAtual.map(m => { ac+=Number(m.total||0); return { nome:`M${m.numero}`, acumulado:Math.round(ac) }; }); })()}
                  margin={{ top:4, right:8, bottom:0, left:-14 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke={C.line}/>
                  <XAxis dataKey="nome" tick={{ fontSize:10, fill:C.muted }} axisLine={{ stroke:C.border }} tickLine={false}/>
                  <YAxis tick={{ fontSize:9, fill:C.muted }} axisLine={false} tickLine={false} tickFormatter={v=>`${(v/1000).toFixed(0)}k`}/>
                  <Tooltip formatter={v=>fmt(v)} contentStyle={{ background:C.card, border:`1px solid ${C.border}`, borderRadius:6, fontSize:12 }}/>
                  <Line type="monotone" dataKey="acumulado" stroke={C.blue} strokeWidth={2.5} dot={{ r:3, fill:C.blue }}/>
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Resumo do contrato */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:8 }}>
            {[
              ["Contrato", fmt(tercAtual.contractValue), C.green],
              ["Medido", fmt(totalMedido), C.blue],
              ["A medir", fmt(somaEtapas - totalMedido), (somaEtapas - totalMedido) >= 0 ? C.orange : C.red],
              ["Avanço físico", `${pctFisico.toFixed(1)}%`, C.yellow],
            ].map(([l,v,c]) => (
              <div key={l} style={{ background:C.card, border:`1px solid ${C.border}`, borderTop:`3px solid ${c}`, padding:"10px 12px", borderRadius:10 }}>
                <p style={{ fontSize:9.5, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:.8 }}>{l}</p>
                <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:800, color:c, fontSize:21, lineHeight:1.1, marginTop:3 }}>{v}</p>
              </div>
            ))}
          </div>

          <div style={{ height:7, background:C.surface, borderRadius:99, overflow:"hidden" }}>
            <div style={{ height:"100%", width:`${Math.min(pctFisico,100)}%`, background:C.yellow, borderRadius:99, transition:"width .25s" }}/>
          </div>

          {/* A soma das etapas precisa fechar com o contrato, senao a medicao
              mede uma coisa e o contrato vale outra. */}
          {etapasTerc.length > 0 && Math.abs(somaEtapas - Number(tercAtual.contractValue||0)) > 0.5 && (
            <div style={{ background:`${C.orange}12`, border:`1px solid ${C.orange}55`, borderRadius:8, padding:"9px 12px" }}>
              <p style={{ fontSize:11.5, color:C.orange, lineHeight:1.55 }}>
                As etapas somam <b>{fmt(somaEtapas)}</b> e o contrato é de <b>{fmt(tercAtual.contractValue)}</b> -
                diferença de {fmt(Math.abs(somaEtapas - Number(tercAtual.contractValue||0)))}.
                Ajuste os valores das etapas ou o valor do contrato no cadastro.
              </p>
            </div>
          )}

          {/* Etapas do contrato */}
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8, flexWrap:"wrap" }}>
            <p style={{ fontSize:10, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:1 }}>
              Etapas do contrato ({etapasTerc.length})
            </p>
            <div style={{ display:"flex", gap:6 }}>
              <Btn size="sm" v="ghost" onClick={sugerirEtapas}>Sugerir etapas</Btn>
              <Btn size="sm" onClick={abrirMedicao}><Ic n="plus"/> Nova medição</Btn>
            </div>
          </div>

          <div style={{ background:C.card, border:`1px solid ${C.border}`, borderRadius:10, overflow:"hidden" }}>
            {etapasTerc.map((e, i) => {
              const acum = acumuladoPorEtapa[e.id] || 0;
              return (
                <div key={e.id} style={{ padding:"10px 12px", borderTop:i?`1px solid ${C.line}`:0,
                                         display:"flex", alignItems:"center", gap:9 }}>
                  <div style={{ display:"flex", flexDirection:"column", gap:1 }}>
                    <button onClick={()=>moverEtapa(e,-1)} disabled={i===0} title="Subir"
                      style={{ background:"transparent", border:0, cursor:i===0?"default":"pointer",
                               color:i===0?C.line:C.muted, fontSize:10, lineHeight:1, padding:"1px 3px" }}>▲</button>
                    <button onClick={()=>moverEtapa(e,+1)} disabled={i===etapasTerc.length-1} title="Descer"
                      style={{ background:"transparent", border:0, cursor:i===etapasTerc.length-1?"default":"pointer",
                               color:i===etapasTerc.length-1?C.line:C.muted, fontSize:10, lineHeight:1, padding:"1px 3px" }}>▼</button>
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <p style={{ fontSize:13, fontWeight:700, color:C.text }}>{i+1}. {e.nome}</p>
                    <div style={{ height:4, background:C.surface, borderRadius:99, overflow:"hidden", marginTop:5 }}>
                      <div style={{ height:"100%", width:`${acum}%`, background:acum>=100?C.green:C.blue, borderRadius:99 }}/>
                    </div>
                  </div>
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <p style={{ fontSize:13, fontWeight:800, color:C.text }}>{fmt(e.valor)}</p>
                    <p style={{ fontSize:10, color:acum>=100?C.green:C.muted, fontWeight:700 }}>{acum.toFixed(1)}% medido</p>
                  </div>
                  <div style={{ display:"flex", gap:2, flexShrink:0 }}>
                    <button onClick={()=>setEtapaForm({ id:e.id, nome:e.nome, valor:String(e.valor) })}
                      style={{ background:"transparent", border:0, color:C.blue, cursor:"pointer", fontSize:10.5, fontWeight:700 }}>Editar</button>
                    <button onClick={()=>removerEtapa(e)}
                      style={{ background:"transparent", border:0, color:C.muted, cursor:"pointer", fontSize:13 }}>x</button>
                  </div>
                </div>
              );
            })}
            {!etapasTerc.length && (
              <p style={{ padding:20, textAlign:"center", fontSize:11.5, color:C.muted }}>
                Contrato ainda inteiro. Use "Sugerir etapas" ou cadastre uma abaixo.
              </p>
            )}
          </div>

          {/* Cadastro de etapa */}
          <div style={{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:10, padding:12,
                        display:"grid", gridTemplateColumns:formGrid(2), gap:9, alignItems:"end" }}>
            <Inp label={etapaForm.id?"Editar etapa":"Nova etapa"} value={etapaForm.nome}
              onChange={v=>setEtapaForm(f=>({...f,nome:v}))} placeholder="Ex.: Rasgo de parede"/>
            <Inp label="Valor da etapa" value={etapaForm.valor}
              onChange={v=>setEtapaForm(f=>({...f,valor:v}))} placeholder="0,00"/>
            <div style={{ display:"flex", gap:7, gridColumn:"1 / -1" }}>
              {etapaForm.id && <Btn v="ghost" full onClick={()=>setEtapaForm({id:"",nome:"",valor:""})}>Cancelar</Btn>}
              <Btn full onClick={salvarEtapa}><Ic n="check"/> {etapaForm.id?"Salvar etapa":"Adicionar etapa"}</Btn>
            </div>
          </div>

          {/* Historico de medicoes */}
          <p style={{ fontSize:10, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:1, marginTop:4 }}>
            Medições ({medicoesTercAtual.length})
          </p>
          <div style={{ display:"flex", flexDirection:"column", gap:7 }}>
            {[...medicoesTercAtual].reverse().map(m => (
              <div key={m.id} style={{ background:C.card, border:`1px solid ${C.border}`,
                                       borderLeft:`4px solid ${m.pagamentoId?C.green:C.orange}`, borderRadius:8, padding:"10px 13px" }}>
                <div style={{ display:"flex", justifyContent:"space-between", gap:9, flexWrap:"wrap" }}>
                  <div>
                    <p style={{ fontSize:13.5, fontWeight:900, color:C.text }}>
                      Medição {m.numero} · {fmtDateFull(m.data)}
                    </p>
                    <p style={{ fontSize:10.5, color:C.muted, marginTop:2 }}>
                      {m.itens.length} etapa(s) · {m.pagamentoId ? "paga" : "aguardando pagamento"}
                    </p>
                  </div>
                  <div style={{ textAlign:"right" }}>
                    <p style={{ fontSize:17, fontWeight:800, color:m.total>=0?C.green:C.red,
                                fontFamily:"'Inter Display','Inter',sans-serif" }}>{fmt(m.total)}</p>
                  </div>
                </div>
                <div style={{ marginTop:7, display:"flex", flexDirection:"column", gap:3 }}>
                  {m.itens.map(i => {
                    const et = etapasTerc.find(e => e.id === i.etapaId);
                    return (
                      <div key={i.etapaId} style={{ display:"flex", justifyContent:"space-between", gap:8, fontSize:11 }}>
                        <span style={{ color:C.subtle, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                          {et?.nome || "Etapa removida"}
                        </span>
                        <span style={{ color:C.muted, flexShrink:0 }}>
                          {i.pctAnterior.toFixed(0)}% → {i.pctAcum.toFixed(0)}% · <b style={{color:i.valor>=0?C.text:C.red}}>{fmt(i.valor)}</b>
                        </span>
                      </div>
                    );
                  })}
                </div>
                {m.observacao && <p style={{ fontSize:11, color:C.muted, fontStyle:"italic", marginTop:6 }}>"{m.observacao}"</p>}
                {/* Previa de retencao antes de pagar / decomposicao apos pago */}
                {(() => {
                  // Fonte da verdade: se ja pago, os valores gravados no
                  // pagamento; se nao, a previa pela config atual do contrato.
                  const pg = m.pagamentoId ? (data.pagsTerceiros || []).find(p => p.id === m.pagamentoId) : null;
                  const ret = calcRetencoes(m.total, tercAtual);
                  const iss     = pg ? Number(pg.issRetido || 0)  : ret.issRetido;
                  const inss    = pg ? Number(pg.inssRetido || 0) : ret.inssRetido;
                  const liquido = pg ? Number(pg.liquido ?? m.total) : ret.liquido;
                  if (iss + inss <= 0) return null;
                  return (
                    <div style={{ marginTop:7, background:C.surface, border:`1px solid ${C.border}`, borderRadius:6, padding:"7px 10px" }}>
                      <div style={{ display:"flex", justifyContent:"space-between", fontSize:10.5, color:C.muted }}>
                        <span>Bruto (custo da obra)</span><b style={{ color:C.text }}>{fmt(m.total)}</b>
                      </div>
                      {iss > 0 && <div style={{ display:"flex", justifyContent:"space-between", fontSize:10.5, color:C.muted }}>
                        <span>(-) ISS retido ({tercAtual.retISS}%)</span><span>{fmt(iss)}</span></div>}
                      {inss > 0 && <div style={{ display:"flex", justifyContent:"space-between", fontSize:10.5, color:C.muted }}>
                        <span>(-) INSS retido ({tercAtual.retINSS}%)</span><span>{fmt(inss)}</span></div>}
                      <div style={{ display:"flex", justifyContent:"space-between", fontSize:11.5, marginTop:3, borderTop:`1px solid ${C.line}`, paddingTop:3 }}>
                        <span style={{ fontWeight:800, color:C.text }}>Líquido ao prestador</span>
                        <b style={{ color:C.green }}>{fmt(liquido)}</b>
                      </div>
                    </div>
                  );
                })()}
                <div style={{ display:"flex", gap:7, marginTop:9, justifyContent:"flex-end" }}>
                  {!m.pagamentoId && <Btn size="sm" v="success" onClick={()=>pagarMedicao(m)}>Registrar pagamento</Btn>}
                  <Btn size="sm" v="ghost" onClick={()=>removerMedicao(m)}>Remover</Btn>
                </div>
              </div>
            ))}
            {!medicoesTercAtual.length && (
              <p style={{ padding:18, textAlign:"center", fontSize:11.5, color:C.muted,
                          background:C.card, border:`1px solid ${C.border}`, borderRadius:8 }}>
                Nenhuma medição neste contrato.
              </p>
            )}
          </div>
        </>)}
      </>)}

      {/*  VIEW: PAGAMENTOS  */}
      {view === "pagamentos" && (<>
        {/* Impostos retidos a recolher - mês da sexta atual. So aparece se ha
            retencao no periodo; e um lembrete de obrigacao, nao um card fixo. */}
        {(() => {
          const ym = friday.slice(0, 7);
          const doMes = (data.pagsTerceiros || []).filter(p => p.date?.startsWith(ym));
          const iss  = doMes.reduce((s, p) => s + Number(p.issRetido || 0), 0);
          const inss = doMes.reduce((s, p) => s + Number(p.inssRetido || 0), 0);
          if (iss + inss <= 0) return null;
          return (
            <div style={{ background:`${C.purple}0C`, border:`1px solid ${C.purple}44`, borderRadius:10, padding:"11px 14px" }}>
              <p style={{ fontSize:10, fontWeight:900, color:C.purple, textTransform:"uppercase", letterSpacing:.8 }}>
                Impostos retidos a recolher · {compLabel(ym)}
              </p>
              <div style={{ display:"flex", gap:16, marginTop:6, flexWrap:"wrap" }}>
                {iss > 0 && <div><p style={{ fontSize:9, color:C.muted, fontWeight:800 }}>ISS</p><p style={{ fontSize:17, fontWeight:800, color:C.text }}>{fmt(iss)}</p></div>}
                {inss > 0 && <div><p style={{ fontSize:9, color:C.muted, fontWeight:800 }}>INSS</p><p style={{ fontSize:17, fontWeight:800, color:C.text }}>{fmt(inss)}</p></div>}
                <div><p style={{ fontSize:9, color:C.muted, fontWeight:800 }}>TOTAL</p><p style={{ fontSize:17, fontWeight:800, color:C.purple }}>{fmt(iss + inss)}</p></div>
              </div>
              <p style={{ fontSize:10, color:C.muted, marginTop:5, lineHeight:1.4 }}>
                Valores que a empresa reteve dos prestadores e deve recolher à prefeitura (ISS) e à Receita (INSS).
              </p>
            </div>
          );
        })()}

        {/* Navegador de semana */}
        <div style={{ background:C.card, border:`1px solid ${C.border}`, borderTop:`3px solid ${C.orange}`, padding:"14px 16px", borderRadius:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
            <button onClick={()=>setWeekOffset(w=>w-1)} style={{ background:"transparent", border:`1px solid ${C.border}`, color:C.text, padding:"6px 14px", cursor:"pointer", borderRadius:8, fontWeight:900, fontSize:18 }}></button>
            <div style={{ textAlign:"center" }}>
              <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize:24, color:C.orange, letterSpacing:1, lineHeight:1 }}>
                 Sexta-feira
              </p>
              <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize:"clamp(18px,8vw,32px)", color:C.text, letterSpacing:1, lineHeight:1 }}>
                {fmtDateFull(friday)}
              </p>
              <p style={{ fontSize:11, color:C.muted, marginTop:2 }}>
                Semana: {fmtDateFull(weekStart)} → {fmtDateFull(weekEnd)}
              </p>
            </div>
            <button onClick={()=>setWeekOffset(w=>w+1)} style={{ background:"transparent", border:`1px solid ${C.border}`, color:C.text, padding:"6px 14px", cursor:"pointer", borderRadius:8, fontWeight:900, fontSize:18 }}></button>
          </div>

          {/* Status da semana */}
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:8, marginTop:4 }}>
            {[
              ["Pagos",      `${activeTerc.length - pendingCount}/${activeTerc.length}`, C.green ],
              ["Pendentes",  fmt(pendingTotal),  pendingCount>0 ? C.red : C.green ],
              ["Pago semana",fmt(paidThisWeekAmount), C.blue ],
            ].map(([l,v,c])=>(
              <div key={l} style={{ background:C.surface, padding:"8px 10px", borderRadius:8, textAlign:"center" }}>
                <p style={{ fontSize:9, color:C.muted, textTransform:"uppercase", fontWeight:900 }}>{l}</p>
                <p style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize:20, color:c, letterSpacing:.5 }}>{v}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Lista de terceirizados com status de pagamento */}
        {activeTerc.length === 0 && (
          <div style={{ background:C.card, border:`1px solid ${C.border}`, padding:24, textAlign:"center", color:C.muted, borderRadius:10 }}>
            Nenhum terceirizado ativo. Cadastre na aba Cadastro.
          </div>
        )}

        {activeTerc
          .filter(t => filterObra==="all" || t.obraId===filterObra)
          .sort((a,b) => {
            // Pendentes primeiro
            const pa = wasPaidThisWeek(a.id), pb = wasPaidThisWeek(b.id);
            if(pa !== pb) return pa ? 1 : -1;
            return a.name.localeCompare(b.name);
          })
          .map(t => {
            const sp = specInfo(t.specialty);
            const paid = wasPaidThisWeek(t.id);
            const paidEntry = thisWeekPay(t.id);
            return (
              <div key={t.id} style={{
                background: paid ? `${C.green}10` : C.card,
                border: `1px solid ${paid ? C.green+"44" : C.line}`,
                borderLeft: `5px solid ${paid ? C.green : C.orange}`,
                padding:"14px 16px", borderRadius:10,
                display:"flex", justifyContent:"space-between", alignItems:"center", gap:12,
              }}>
                <div style={{ flex:1 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                    <span style={{ fontSize:16 }}>{sp.emoji}</span>
                    <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:900, fontSize:17 }}>{t.name}</p>
                    {paid && <Badge color={C.green}>ok Pago</Badge>}
                  </div>
                  <p style={{ fontSize:12, color:C.muted }}>{sp.l}  {obraName(t.obraId)}</p>
                  {paid && paidEntry && (
                    <p style={{ fontSize:12, color:C.green, marginTop:3 }}>
                      {fmt(paidEntry.amount)}  {fmtDateFull(paidEntry.date)}
                    </p>
                  )}
                  {!paid && t.weeklyRate>0 && (
                    <p style={{ fontSize:12, color:C.orange, marginTop:3, fontWeight:700 }}>
                      Previsto: {fmt(t.weeklyRate)}
                    </p>
                  )}
                </div>
                <div style={{ flexShrink:0 }}>
                  {!paid ? (
                    <Btn v="warning" onClick={()=>{setPayModal(t);setPayAmount(String(t.weeklyRate||""));}}>
                      <Ic n="dollar"/> Pagar
                    </Btn>
                  ) : (
                    <Btn v="ghost" size="sm" onClick={()=>paidEntry&&removePay(paidEntry.id)}>
                      <Ic n="x"/> Desfazer
                    </Btn>
                  )}
                </div>
              </div>
            );
          })
        }

        <Sel value={filterObra} onChange={setFilterObra} options={[{v:"all",l:"Todas as obras"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>
      </>)}

      {/* Modal: cadastro */}
      {modal && (() => {
        const docLimpo = soDigitos(form.documento);
        const docOk = docLimpo.length === 0 ? null : validarDocumento(docLimpo, form.tipoPessoa);
        const secTitulo = t => (
          <p style={{ gridColumn:"1/-1", fontSize:10, fontWeight:900, color:C.muted,
                      textTransform:"uppercase", letterSpacing:1, marginTop:6,
                      borderTop:`1px solid ${C.line}`, paddingTop:11 }}>{t}</p>
        );
        return (
        <Modal title={form.id?"Editar terceirizado":"Novo terceirizado"} onClose={()=>setModal(false)} wide>
          <div style={{ display:"grid", gridTemplateColumns:formGrid(2), gap:12 }}>

            {/* IDENTIFICACAO */}
            <div style={{ gridColumn:"1/-1" }}><Inp label="Nome / Apelido *" value={form.name} onChange={F("name")} placeholder="Como você chama este contrato"/></div>
            <Sel label="Especialidade *" value={form.specialty} onChange={F("specialty")} options={SPECIALTIES.map(s=>({v:s.v,l:s.l}))}/>
            <Sel label="Obra *" value={form.obraId} onChange={F("obraId")} options={[{v:"",l:"Selecione"},...data.obras.map(o=>({v:o.id,l:o.name}))]}/>
            <Sel label="Situação" value={form.situacao} onChange={F("situacao")} options={COLS_KANBAN.map(c=>({v:c.v,l:c.l}))}/>
            <Sel label="Tipo de contrato" value={form.tipoContrato} onChange={F("tipoContrato")}
              options={[{v:"medicao",l:"Por medição"},{v:"empreitada",l:"Empreitada (global)"},{v:"semanal",l:"Semanal"},{v:"diaria",l:"Diária"}]}/>
            <div style={{ gridColumn:"1/-1" }}>
              <p style={{ fontSize:11, fontWeight:600, color:C.text, textTransform:"uppercase", letterSpacing:.8, marginBottom:5 }}>Pago por</p>
              <div style={{ display:"flex", gap:6 }}>
                {[["obra","A obra","Custo direto no DRE da obra"],
                  ["empresa","A empresa","Despesa administrativa (fora do custo da obra)"]].map(([v,l,dica]) => (
                  <button key={v} onClick={()=>F("pagador")(v)} style={{
                    flex:1, padding:"9px 8px", border:`2px solid ${form.pagador===v?C.orange:C.border}`,
                    background:form.pagador===v?`${C.orange}15`:"transparent", cursor:"pointer", borderRadius:6, textAlign:"left" }}>
                    <p style={{ fontSize:12.5, fontWeight:800, color:form.pagador===v?C.text:C.muted }}>{l}</p>
                    <p style={{ fontSize:9.5, color:C.muted, marginTop:2, lineHeight:1.3 }}>{dica}</p>
                  </button>
                ))}
              </div>
            </div>

            {secTitulo("Dados fiscais")}
            <div style={{ display:"flex", gap:6, gridColumn:"1/-1" }}>
              {[["PJ","Pessoa Jurídica (CNPJ)"],["PF","Pessoa Física (CPF)"]].map(([v,l]) => (
                <button key={v} onClick={()=>F("tipoPessoa")(v)} style={{
                  flex:1, padding:"9px 4px", border:`2px solid ${form.tipoPessoa===v?C.orange:C.border}`,
                  background:form.tipoPessoa===v?`${C.orange}15`:"transparent", color:form.tipoPessoa===v?C.text:C.muted,
                  fontWeight:800, fontSize:12, cursor:"pointer", borderRadius:6 }}>{l}</button>
              ))}
            </div>
            <div>
              {form.tipoPessoa === "PJ" ? (
                // PJ: busca na Receita e preenche razao social, contato e endereco.
                <CampoCNPJ label="CNPJ" value={form.documento}
                  onChange={v=>F("documento")(soDigitos(v))}
                  onEncontrado={d=>setForm(f=>({
                    ...f,
                    name:        f.name        || d.nome,
                    razaoSocial: f.razaoSocial || d.razaoSocial,
                    phone:       f.phone       || d.telefone,
                    email:       f.email       || d.email,
                    cep:         f.cep         || d.cep,
                    endereco:    f.endereco    || [d.logradouro, d.numero].filter(Boolean).join(", "),
                    cidade:      f.cidade      || d.cidade,
                    ufEnd:       f.ufEnd       || d.uf,
                  }))}/>
              ) : (
                <Inp label="CPF"
                  value={maskDoc(form.documento, form.tipoPessoa)}
                  onChange={v=>F("documento")(soDigitos(v))}
                  placeholder="000.000.000-00"/>
              )}
              {docOk === false && <p style={{ fontSize:10.5, color:C.red, marginTop:4, fontWeight:700 }}>Dígitos não conferem</p>}
              {docOk === true && <p style={{ fontSize:10.5, color:C.green, marginTop:4, fontWeight:700 }}>Válido</p>}
            </div>
            <Inp label={form.tipoPessoa==="PF"?"Nome completo (fiscal)":"Razão social"} value={form.razaoSocial} onChange={F("razaoSocial")}/>
            {form.tipoPessoa==="PJ" && <Inp label="Inscrição estadual" value={form.inscEstadual} onChange={F("inscEstadual")} placeholder="Isento, se não houver"/>}
            {form.tipoPessoa==="PJ" && <Inp label="Inscrição municipal" value={form.inscMunicipal} onChange={F("inscMunicipal")}/>}

            {secTitulo("Contrato e pagamento")}
            <Inp label="Valor do contrato (R$)" value={form.contractValue} onChange={F("contractValue")} placeholder="0,00"/>
            <Inp label="Valor semanal (R$)" value={form.weeklyRate} onChange={F("weeklyRate")} placeholder="Ex.: 2.000"/>
            <Inp label="Início" type="date" value={form.startDate} onChange={F("startDate")}/>
            <Inp label="Término previsto" type="date" value={form.endDate} onChange={F("endDate")}/>
            <div>
              <Inp label="Retenção ISS (%)" value={form.retISS} onChange={F("retISS")} placeholder="0"/>
              <div style={{ display:"flex", gap:4, marginTop:5 }}>
                {[["fonte","Retido na fonte"],["prestador","Prestador paga"]].map(([v,l]) => (
                  <button key={v} onClick={()=>F("retISSQuem")(v)} style={{
                    flex:1, padding:"5px 4px", border:`1.5px solid ${form.retISSQuem===v?C.orange:C.border}`,
                    background:form.retISSQuem===v?`${C.orange}15`:"transparent", color:form.retISSQuem===v?C.text:C.muted,
                    fontSize:10, fontWeight:700, cursor:"pointer", borderRadius:6 }}>{l}</button>
                ))}
              </div>
            </div>
            <div>
              <Inp label="Retenção INSS (%)" value={form.retINSS} onChange={F("retINSS")} placeholder="0"/>
              <div style={{ display:"flex", gap:4, marginTop:5 }}>
                {[["fonte","Retido na fonte"],["prestador","Prestador paga"]].map(([v,l]) => (
                  <button key={v} onClick={()=>F("retINSSQuem")(v)} style={{
                    flex:1, padding:"5px 4px", border:`1.5px solid ${form.retINSSQuem===v?C.orange:C.border}`,
                    background:form.retINSSQuem===v?`${C.orange}15`:"transparent", color:form.retINSSQuem===v?C.text:C.muted,
                    fontSize:10, fontWeight:700, cursor:"pointer", borderRadius:6 }}>{l}</button>
                ))}
              </div>
            </div>
            <Inp label="Chave PIX" value={form.pixKey} onChange={F("pixKey")}/>
            <Inp label="Banco" value={form.banco} onChange={F("banco")} placeholder="Ex.: 341 Itaú"/>
            <Inp label="Agência" value={form.agencia} onChange={F("agencia")}/>
            <Inp label="Conta" value={form.conta} onChange={F("conta")}/>

            {secTitulo("Contato")}
            <Inp label="Responsável" value={form.responsavel} onChange={F("responsavel")} placeholder="Quem atende pela empresa"/>
            <Inp label="Telefone" value={form.phone} onChange={F("phone")} placeholder="(81) 9XXXX-XXXX"/>
            <Inp label="E-mail" value={form.email} onChange={F("email")}/>
            <Inp label="CEP" value={maskCEP(form.cep)} onChange={v=>F("cep")(soDigitos(v))} placeholder="00000-000"/>
            <div style={{ gridColumn:"1/-1" }}><Inp label="Endereço" value={form.endereco} onChange={F("endereco")} placeholder="Rua, número, bairro"/></div>
            <Inp label="Cidade" value={form.cidade} onChange={F("cidade")}/>
            <Inp label="UF" value={form.ufEnd} onChange={v=>F("ufEnd")(v.toUpperCase().slice(0,2))} placeholder="PE"/>

            {secTitulo("Documentos com validade")}
            <div style={{ gridColumn:"1/-1", display:"flex", flexDirection:"column", gap:6 }}>
              {(form.documentos || []).map(doc => {
                const dias = diasAte(doc.validade);
                return (
                  <div key={doc.id} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8,
                                             background:C.surface, border:`1px solid ${C.border}`, borderRadius:6, padding:"7px 10px" }}>
                    <div style={{ minWidth:0 }}>
                      <p style={{ fontSize:12, fontWeight:700, color:C.text }}>{docTercInfo(doc.tipo).l}</p>
                      <p style={{ fontSize:10, color: dias!==null&&dias<=0?C.red:dias!==null&&dias<=30?C.orange:C.muted }}>
                        {doc.numero ? `${doc.numero} · ` : ""}vence {fmtDateFull(doc.validade)}
                        {dias!==null && (dias<0?` (vencido há ${Math.abs(dias)}d)`:dias===0?" (hoje)":` (${dias}d)`)}
                      </p>
                    </div>
                    <button onClick={()=>delDocNoForm(doc.id)} style={{ background:"transparent", border:0, color:C.muted, cursor:"pointer", fontSize:15, flexShrink:0 }}>×</button>
                  </div>
                );
              })}
              <div style={{ display:"grid", gridTemplateColumns:"1.2fr 1fr 1fr auto", gap:6, alignItems:"end" }}>
                <Sel label="Tipo" value={docForm.tipo} onChange={v=>setDocForm(d=>({...d,tipo:v}))} options={DOCS_TERC.map(d=>({v:d.v,l:d.l}))}/>
                <Inp label="Número" value={docForm.numero} onChange={v=>setDocForm(d=>({...d,numero:v}))} placeholder="Opcional"/>
                <Inp label="Validade" type="date" value={docForm.validade} onChange={v=>setDocForm(d=>({...d,validade:v}))}/>
                <Btn size="sm" onClick={addDocNoForm}><Ic n="plus"/></Btn>
              </div>
            </div>

            <div style={{ gridColumn:"1/-1" }}><Inp label="Observações" value={form.notes} onChange={F("notes")} multiline placeholder="Escopo, condições, o que combinaram..."/></div>
          </div>
          <div style={{ display:"flex", gap:8, marginTop:16 }}>
            <Btn v="ghost" onClick={()=>setModal(false)} full>Cancelar</Btn>
            <Btn onClick={saveTerc} full><Ic n="check"/> Salvar</Btn>
          </div>
        </Modal>
        );
      })()}

      {/* Modal: registrar pagamento */}
      {medModal && tercAtual && (
        <Modal title={`Medição ${medicoesTercAtual.length + 1} - ${tercAtual.name}`} onClose={()=>setMedModal(false)} wide>
          <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
            <p style={{ fontSize:11.5, color:C.muted, lineHeight:1.55 }}>
              Informe o percentual <b>acumulado</b> de cada etapa - o total executado até hoje, não o avanço da semana.
              O app calcula a diferença para a medição anterior e valoriza só o que avançou.
            </p>
            <Inp label="Data da medição" type="date" value={medForm.data} onChange={v=>setMedForm(f=>({...f,data:v}))}/>

            <div style={{ border:`1px solid ${C.border}`, borderRadius:8, overflow:"hidden" }}>
              {etapasTerc.map((e, i) => {
                const anterior = Number(acumuladoPorEtapa[e.id] || 0);
                const atual    = pct(medForm.pcts?.[e.id] ?? anterior);
                const delta    = atual - anterior;
                const valor    = Number(e.valor || 0) * delta / 100;
                return (
                  <div key={e.id} style={{ padding:"9px 11px", borderTop:i?`1px solid ${C.line}`:0,
                                           display:"grid", gridTemplateColumns:"minmax(0,1fr) 84px 96px", gap:8, alignItems:"center" }}>
                    <div style={{ minWidth:0 }}>
                      <p style={{ fontSize:12.5, fontWeight:700, color:C.text }}>{e.nome}</p>
                      <p style={{ fontSize:10, color:C.muted, marginTop:2 }}>
                        {fmt(e.valor)} · anterior {anterior.toFixed(1)}%
                      </p>
                    </div>
                    <input type="number" step="any" inputMode="decimal" min={0} max={100}
                      value={medForm.pcts?.[e.id] ?? ""}
                      onChange={ev=>setMedForm(f=>({...f, pcts:{...f.pcts, [e.id]:ev.target.value}}))}
                      style={{ width:"100%", boxSizing:"border-box", background:C.bg,
                               border:`1.5px solid ${delta<0?C.red:delta>0?C.green:C.line}`,
                               color:C.text, padding:"7px 8px", borderRadius:7, fontSize:13, textAlign:"right",
                               outline:"none", fontFamily:"'Inter',sans-serif" }}/>
                    <div style={{ textAlign:"right" }}>
                      <p style={{ fontSize:12.5, fontWeight:800, color:delta<0?C.red:delta>0?C.green:C.muted }}>{fmt(valor)}</p>
                      <p style={{ fontSize:9.5, color:C.muted }}>{delta>0?"+":""}{delta.toFixed(1)} p.p.</p>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Medir para tras e legitimo (corrigir medicao a maior), mas nunca
                deve passar despercebido. */}
            {itensDaMedicao().some(i => i.pctAcum < i.pctAnterior) && (
              <div style={{ background:`${C.orange}12`, border:`1px solid ${C.orange}55`, borderRadius:8, padding:"8px 11px" }}>
                <p style={{ fontSize:11, color:C.orange, lineHeight:1.5 }}>
                  Há etapa com percentual menor que o da medição anterior. Isso gera valor negativo -
                  um estorno de medição a maior. Se não é o caso, revise os percentuais.
                </p>
              </div>
            )}

            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8,
                          background:C.surface, border:`1px solid ${C.border}`, borderRadius:8, padding:"11px 13px" }}>
              <span style={{ fontSize:11, fontWeight:900, color:C.muted, textTransform:"uppercase", letterSpacing:.8 }}>Total desta medição</span>
              <b style={{ fontSize:21, color:C.green, fontFamily:"'Inter Display','Inter',sans-serif" }}>
                {fmt(itensDaMedicao().reduce((s,i)=>s+i.valor,0))}
              </b>
            </div>

            <Inp label="Observação" value={medForm.observacao} onChange={v=>setMedForm(f=>({...f,observacao:v}))}
              placeholder="Ex.: pendente o quadro do 2º pavimento"/>

            <div style={{ display:"flex", gap:8 }}>
              <Btn v="ghost" full onClick={()=>setMedModal(false)}>Cancelar</Btn>
              <Btn full onClick={salvarMedicao}><Ic n="check"/> Salvar medição</Btn>
            </div>
          </div>
        </Modal>
      )}

      {payModal && (
        <Modal title={`Pagamento - ${payModal.name}`} onClose={()=>{setPayModal(null);setPayAmount("");setPayDesc("");}}>
          <div style={{ background:C.card, border:`1px solid ${C.border}`, borderLeft:`4px solid ${C.orange}`, padding:"10px 14px", borderRadius:8, marginBottom:12 }}>
            <p style={{ fontSize:12, color:C.muted }}>{specInfo(payModal.specialty).emoji} {specInfo(payModal.specialty).l}  {obraName(payModal.obraId)}</p>
            <p style={{ fontSize:13, color:C.orange, fontWeight:700, marginTop:2 }}>Sexta-feira: {fmtDateFull(friday)}</p>
          </div>
          <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
            <Inp label="Valor (R$) *" type="number" value={payAmount} onChange={setPayAmount} placeholder={`Sugerido: ${fmt(payModal.weeklyRate)}`}/>
            <Inp label="Descrição" value={payDesc} onChange={setPayDesc} placeholder={`Pagamento semanal ${fmtDateFull(friday)}`}/>
            <div style={{ display:"flex", gap:8 }}>
              <Btn v="ghost" onClick={()=>setPayModal(null)} full>Cancelar</Btn>
              <Btn v="warning" onClick={()=>savePay(payModal)} full><Ic n="check"/> Confirmar pagamento</Btn>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

const compLabel = ym => {
  if (!ym) return "-";
  const [y, m] = ym.split("-");
  return `${fullMonth(Number(m)-1)} ${y}`;
};

// 
// HELPER - Relatório mensal completo por obra
// 

const calcRelatorioMensal = (data, year, month) => {
  const days   = getDays(year, month);
  const ym     = `${year}-${String(month+1).padStart(2,"0")}`;
  const per0   = days[0]  || "";
  const perF   = days[days.length-1] || "";

  return data.obras.map(obra => {
    // Mão de obra própria
    const moData = calcObraLaborCost(data, obra.id, days);

    // Terceirizados
    const tercCost = calcObraTercCost(data, obra.id, per0, perF);
    // A lista detalhada tem de bater com o total: só pagamentos que oneram a
    // obra (os pagos pela empresa aparecem no consolidado, não aqui).
    const tercDetalhes = (data.pagsTerceiros||[]).filter(p =>
      p.obraId === obra.id && p.pagador !== "empresa" && p.date && p.date.startsWith(ym)
    );

    // Rescisões vinculadas à obra no mês
    const rescDetalhes = (data.rescisoes||[]).filter(r =>
      r.obraName === obra.name && r.demissao && r.demissao.startsWith(ym)
    );
    const rescTotal = rescDetalhes.reduce((s,r) => s+Number(r.totalLiquido||0), 0);

    // Adiantamentos pagos no mês são apropriados conforme a obra do funcionário
    // na data do adiantamento, inclusive quando houve transferência no período.
    const employeeById = new Map((data.employees || []).map(e => [e.id, e]));
    const adiantDetalhes = (data.advances||[]).filter(a => {
      if (!a.date || !a.date.startsWith(ym)) return false;
      const employee = employeeById.get(a.empId);
      return employee && getEmployeeObraIdOnDate(data, employee, a.date) === obra.id;
    });
    const adiantTotal = adiantDetalhes.reduce((s,a)=>s+Number(a.amount||0),0);

    // Receita recebida no mês - usa medições estruturadas (prioritário) + payments livres
    const medDoMes = (data.medicoes||[]).filter(m =>
      m.obraId===obra.id && m.competencia===ym && m.recebido
    );
    const recMedicoes = medDoMes.reduce((s,m)=>s+Number(m.valorRecebido||0),0);
    const recPagamentos = (data.payments||[]).filter(p =>
      p.obraId===obra.id && p.date?.startsWith(ym)
    ).reduce((s,p)=>s+Number(p.amount||0),0);
    const received = recMedicoes + recPagamentos;
    const recDetalhes = [
      ...medDoMes.map(m=>({ id:m.id, date:m.dataPagamento, amount:m.valorRecebido, description:m.descricao||compLabel(m.competencia), tipo:"medicao" })),
      ...(data.payments||[]).filter(p=>p.obraId===obra.id&&p.date?.startsWith(ym)),
    ];

    // Receita esperada pelo contrato
    const { revenue: revenueEsperada } = calcObraRevenue(obra, moData.laborCost);

    // Presença por obra efetiva em cada dia. O ponto carimbado tem prioridade;
    // para registros antigos, a lotação é reconstruída pelo histórico de transferências.
    const presencaDias = (data.employees || []).reduce((s, e) =>
      s + days.filter(d => {
        if (!isEmployeeEmployedOnDate(e, d)) return false;
        const a = getAtt(data, e.id, d);
        const obraDoDia = a?.obraId || getEmployeeObraIdOnDate(data, e, d);
        return obraDoDia === obra.id && a?.status === "P";
      }).length, 0);
    const faltas = (data.employees || []).reduce((s, e) =>
      s + days.filter(d => {
        if (!isEmployeeEmployedOnDate(e, d)) return false;
        const a = getAtt(data, e.id, d);
        const obraDoDia = a?.obraId || getEmployeeObraIdOnDate(data, e, d);
        return obraDoDia === obra.id && a?.status === "F";
      }).length, 0);
    const employeeIdsInPeriod = new Set();
    (data.employees || []).forEach(e => days.forEach(d => {
      if (!isEmployeeEmployedOnDate(e, d)) return;
      const a = getAtt(data, e.id, d);
      const obraDoDia = a?.obraId || getEmployeeObraIdOnDate(data, e, d);
      if (obraDoDia === obra.id) employeeIdsInPeriod.add(e.id);
    }));
    const activeEmps = employeeIdsInPeriod.size;
    const activeTercs = (data.terceirizados||[]).filter(t=>t.active!==false&&t.obraId===obra.id).length;

    // DRE
    const totalDespesas  = moData.laborCost + moData.benefitCost + tercCost + rescTotal + adiantTotal;
    const margem         = received - (moData.laborCost + moData.benefitCost + tercCost + rescTotal);
    const margemEsperada = revenueEsperada - (moData.laborCost + moData.benefitCost + tercCost + rescTotal);
    const margemPct      = received > 0 ? (margem/received)*100 : 0;

    return {
      obra, moData, tercCost, tercDetalhes, rescTotal, rescDetalhes,
      adiantTotal, adiantDetalhes, received, recDetalhes,
      revenueEsperada, totalDespesas, margem, margemEsperada, margemPct,
      activeEmps, activeTercs, presencaDias, faltas,
    };
  });
};

// 
// Relatórios
// 

function Relatorios({ data }) {
  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState(new Date().getMonth());
  const [filterObra, setFilterObra] = useState("all");
  const [view, setView] = useState("custos"); // "custos" | "relatorio"

  const days = getDays(year, month);
  const obraName = id => data.obras.find(o => o.id === id)?.name || "-";
  const payrollHolidays = getPayrollHolidays(data, year);
  const holidaysInMonth = days.filter(d => payrollHolidays.includes(d) && prIsWeekdayIso(d));
  const periodStart = days[0] || "";
  const periodEnd = days[days.length - 1] || "";
  const transferenciasPeriodo = (data.changeLog || [])
    .filter(t => t.type === "transfer" && t.date && t.date >= periodStart && t.date <= periodEnd)
    .map(t => ({
      ...t,
      funcionario: t.empName || (data.employees || []).find(e => e.id === t.empId)?.name || "Funcionário",
      origem: t.from || obraName(t.fromId),
      destino: t.to || obraName(t.toId),
    }))
    .sort((a, b) => a.date.localeCompare(b.date));

  const obraCostRows = data.obras.map(o => {
    const employeeIdsInPeriod = new Set();
    const activeEmps = (data.employees || []).filter(e => e.active !== false && e.obra === o.id);

    let presentes = 0;
    let meiodia = 0;
    let faltas = 0;
    let semRegistro = 0;
    let laborCost = 0;
    let benefitCost = 0;
    let holidayPay = 0;

    (data.employees || []).forEach(e => {
      days.forEach(d => {
        if (!isEmployeeEmployedOnDate(e, d)) return;

        const a = getAtt(data, e.id, d);
        const obraDoDia = a?.obraId || getEmployeeObraIdOnDate(data, e, d);
        if (obraDoDia !== o.id) return;

        employeeIdsInPeriod.add(e.id);
        if (holidaysInMonth.includes(d)) return;

        const s = a?.status;
        if (s === "P") {
          presentes++;
          laborCost += Number(e.dailyRate || 0);
          benefitCost += Number(e.vtDaily || 0) + Number(e.vrDaily || 0);
        } else if (s === "M") {
          meiodia++;
          laborCost += Number(e.dailyRate || 0) * 0.5;
          benefitCost += (Number(e.vtDaily || 0) + Number(e.vrDaily || 0)) * 0.5;
        } else if (s === "F") {
          faltas++;
        } else {
          semRegistro++;
        }
      });

      holidaysInMonth.forEach(h => {
        if (!isEmployeeEmployedOnDate(e, h)) return;
        const a = getAtt(data, e.id, h);
        const obraDoDia = a?.obraId || getEmployeeObraIdOnDate(data, e, h);
        if (obraDoDia !== o.id) return;
        employeeIdsInPeriod.add(e.id);
        const rule = getHolidayPayRule(data, e, h, payrollHolidays);
        holidayPay += Number(rule.amount || 0);
      });
    });

    const areaM2 = Number(o.areaM2 || 0);
    laborCost += holidayPay;
    const totalCost = laborCost + benefitCost;
    const laborCostPerM2 = areaM2 > 0 ? laborCost / areaM2 : 0;
    const totalCostPerM2 = areaM2 > 0 ? totalCost / areaM2 : 0;

    return {
      id: o.id,
      name: o.name,
      areaM2,
      trabalhadores: employeeIdsInPeriod.size,
      trabalhadoresAtuais: activeEmps.length,
      presentes,
      meiodia,
      faltas,
      semRegistro,
      laborCost,
      benefitCost,
      holidayPay,
      totalCost,
      laborCostPerM2,
      totalCostPerM2,
    };
  });

  const filteredRows = obraCostRows.filter(r => filterObra === "all" || r.id === filterObra);

  const totals = filteredRows.reduce((acc, r) => ({
    areaM2: acc.areaM2 + r.areaM2,
    trabalhadores: acc.trabalhadores + r.trabalhadores,
    presentes: acc.presentes + r.presentes,
    meiodia: acc.meiodia + r.meiodia,
    faltas: acc.faltas + r.faltas,
    semRegistro: acc.semRegistro + r.semRegistro,
    laborCost: acc.laborCost + r.laborCost,
    benefitCost: acc.benefitCost + r.benefitCost,
    holidayPay: acc.holidayPay + r.holidayPay,
    totalCost: acc.totalCost + r.totalCost,
  }), {
    areaM2: 0,
    trabalhadores: 0,
    presentes: 0,
    meiodia: 0,
    faltas: 0,
    semRegistro: 0,
    laborCost: 0,
    benefitCost: 0,
    holidayPay: 0,
    totalCost: 0,
  });

  const totalLaborCostPerM2 = totals.areaM2 > 0 ? totals.laborCost / totals.areaM2 : 0;
  const totalCostPerM2 = totals.areaM2 > 0 ? totals.totalCost / totals.areaM2 : 0;

  const byObra = filteredRows.map(r => ({
    name: r.name,
    trabalhadores: r.trabalhadores,
    presentes: r.presentes,
    faltas: r.faltas,
    custo: r.laborCost,
    custoTotal: r.totalCost,
    custoM2: r.laborCostPerM2,
  }));

  const topCost = (data.employees || []).flatMap(e => {
    const porObra = new Map();
    const add = (obraId, valor) => {
      if (!obraId || !(valor > 0)) return;
      porObra.set(obraId, (porObra.get(obraId) || 0) + valor);
    };

    days.forEach(d => {
      if (!isEmployeeEmployedOnDate(e, d) || holidaysInMonth.includes(d)) return;
      const a = getAtt(data, e.id, d);
      const obraId = a?.obraId || getEmployeeObraIdOnDate(data, e, d);
      if (filterObra !== "all" && obraId !== filterObra) return;
      if (a?.status === "P") add(obraId, Number(e.dailyRate || 0));
      if (a?.status === "M") add(obraId, Number(e.dailyRate || 0) * 0.5);
    });

    holidaysInMonth.forEach(h => {
      if (!isEmployeeEmployedOnDate(e, h)) return;
      const a = getAtt(data, e.id, h);
      const obraId = a?.obraId || getEmployeeObraIdOnDate(data, e, h);
      if (filterObra !== "all" && obraId !== filterObra) return;
      add(obraId, Number(getHolidayPayRule(data, e, h, payrollHolidays).amount || 0));
    });

    return [...porObra.entries()].map(([obraId, total]) => ({
      name: e.name, obraId, obra: obraName(obraId), total,
    }));
  }).filter(i => i.total > 0).sort((a, b) => b.total - a.total).slice(0, 10);

  const exportObraCosts = () => {
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet([
      ["Relatório de gasto por obra", `${fullMonth(month)} ${year}`],
      ["Filtro", filterObra === "all" ? "Todas as obras" : obraName(filterObra)],
      [],
      [
        "Obra",
        "Área (m)",
        "Trabalhadores no período",
        "Presenças",
        "Meio dia",
        "Faltas",
        "Sem registro",
        "Mão de obra",
        "Feriados pagos",
        "VT/VR",
        "Total com benefícios",
        "Mão de obra por m",
        "Total por m",
      ],
      ...filteredRows.map(r => [
        r.name,
        r.areaM2,
        r.trabalhadores,
        r.presentes,
        r.meiodia,
        r.faltas,
        r.semRegistro,
        r.laborCost,
        r.holidayPay,
        r.benefitCost,
        r.totalCost,
        r.laborCostPerM2,
        r.totalCostPerM2,
      ]),
      [
        "TOTAL",
        totals.areaM2,
        totals.trabalhadores,
        totals.presentes,
        totals.meiodia,
        totals.faltas,
        totals.semRegistro,
        totals.laborCost,
        totals.holidayPay,
        totals.benefitCost,
        totals.totalCost,
        totalLaborCostPerM2,
        totalCostPerM2,
      ],
    ]);

    ws["!cols"] = [22, 10, 16, 10, 10, 10, 12, 14, 14, 12, 18, 18, 14].map(w => ({ wch: w }));
    XLSX.utils.book_append_sheet(wb, ws, "Gasto por Obra");

    const wsTransfers = XLSX.utils.aoa_to_sheet([
      [`Transferências de obra - ${fullMonth(month)} ${year}`],
      [],
      ["Data", "Funcionário", "Obra de origem", "Obra de destino"],
      ...transferenciasPeriodo.map(t => [t.date, t.funcionario, t.origem, t.destino]),
    ]);
    wsTransfers["!cols"] = [12, 24, 24, 24].map(w => ({ wch: w }));
    XLSX.utils.book_append_sheet(wb, wsTransfers, "Transferências");

    XLSX.writeFile(wb, `arcd-gasto-obra-${year}-${String(month + 1).padStart(2, "0")}.xlsx`);
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div>
        <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 30, letterSpacing: 2, color: C.yellow }}>Relatórios</h2>
        <p style={{ color: C.muted, fontSize: 13 }}>Indicadores mensais de presença, gasto por obra e custo de mão de obra por m.</p>

        {/* Toggle de view */}
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginTop:4 }}>
          {[["custos"," Indicadores"],["relatorio"," Relatório Mensal"]].map(([v,l])=>(
            <button key={v} onClick={()=>setView(v)} style={{
              padding:"10px 0", border:`2px solid ${view===v?C.yellow:C.line}`,
              background:view===v?`${C.yellow}18`:"transparent",
              color:view===v?C.yellow:C.muted,
              fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:14,letterSpacing:.5,
              cursor:"pointer",borderRadius:8,
            }}>{l}</button>
          ))}
        </div>

        {/* Seletor de período (compartilhado) */}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Sel value={String(year)} onChange={v => setYear(Number(v))} options={Array.from({ length: 4 }, (_, i) => new Date().getFullYear() - 1 + i).map(y => ({ v: String(y), l: String(y) }))} />
        <Sel value={String(month)} onChange={v => setMonth(Number(v))} options={Array.from({ length: 12 }, (_, i) => ({ v: String(i), l: fullMonth(i) }))} />
      </div>

      {/*  RELATÓRIO MENSAL COMPLETO  */}
      {view === "relatorio" && <RelatorioMensal data={data} year={year} month={month}/>}

      {/*  INDICADORES (view padrão)  */}
      {view === "custos" && <>
      <Sel
        label="Filtrar gasto por obra"
        value={filterObra}
        onChange={setFilterObra}
        options={[{ v: "all", l: "Todas as obras" }, ...data.obras.map(o => ({ v: o.id, l: o.name }))]}
      />

      <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 8 }}>
        {[
          ["Mão de obra", fmt(totals.laborCost), C.yellow],
          ["Custo / m", totals.areaM2 > 0 ? fmt(totalLaborCostPerM2) : "Sem área", totals.areaM2 > 0 ? C.green : C.muted],
          ["Total com VT/VR", fmt(totals.totalCost), C.blue],
          ["Área considerada", `${totals.areaM2.toLocaleString("pt-BR")} m`, C.subtle],
        ].map(([label, value, color]) => (
          <div key={label} style={{ background: C.card, border: `1px solid ${C.border}`, borderTop: `3px solid ${color}`, padding: 12 }}>
            <p style={{ color: C.muted, fontSize: 10, textTransform: "uppercase", fontWeight: 800, letterSpacing: .6 }}>{label}</p>
            <p style={{ color, fontFamily:"'Inter Display','Inter',sans-serif", fontSize: 22, fontWeight: 900 }}>{value}</p>
          </div>
        ))}
      </div>

      <Btn onClick={exportObraCosts} v="success" full>
        <Ic n="download" s={15} />
        Exportar gasto por obra
      </Btn>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, textTransform: "uppercase", marginBottom: 8 }}>Gasto de mão de obra por obra</h3>
        <div style={{ height: 260 }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={byObra}>
              <CartesianGrid stroke={C.border} vertical={false} />
              <XAxis dataKey="name" stroke={C.muted} fontSize={10} />
              <YAxis stroke={C.muted} fontSize={10} />
              <Tooltip contentStyle={{ background: C.card, border: `1px solid ${C.border}`, color: C.text }} formatter={v => fmt(v)} />
              <Bar dataKey="custo" name="Mão de obra" fill={C.yellow} />
              <Bar dataKey="custoTotal" name="Total c/ VT-VR" fill={C.blue} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, textTransform: "uppercase", marginBottom: 8 }}>Presenças e faltas por obra</h3>
        <div style={{ height: 250 }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={byObra}>
              <CartesianGrid stroke={C.border} vertical={false} />
              <XAxis dataKey="name" stroke={C.muted} fontSize={10} />
              <YAxis stroke={C.muted} fontSize={10} allowDecimals={false} />
              <Tooltip contentStyle={{ background: C.card, border: `1px solid ${C.border}`, color: C.text }} />
              <Bar dataKey="presentes" fill={C.green} />
              <Bar dataKey="faltas" fill={C.red} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {filteredRows.map(r => (
          <div key={r.id} style={{ background: C.card, border: `1px solid ${C.border}`, borderLeft: `4px solid ${C.yellow}`, padding: 12 }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "flex-start" }}>
              <div>
                <p style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight: 900, fontSize: 17 }}>{r.name}</p>
                <p style={{ color: C.muted, fontSize: 12 }}>
                  Área: {r.areaM2 > 0 ? `${r.areaM2.toLocaleString("pt-BR")} m` : "não cadastrada"}  {r.trabalhadores} trabalhador(es)
                </p>
                <p style={{ color: C.subtle, fontSize: 12 }}>
                  {r.presentes}P {r.meiodia}M {r.faltas}F {r.semRegistro}S/R
                </p>
              </div>
              <div style={{ textAlign: "right" }}>
                <p style={{ color: C.yellow, fontWeight: 900 }}>{fmt(r.laborCost)}</p>
                <p style={{ color: r.areaM2 > 0 ? C.green : C.muted, fontSize: 12, fontWeight: 800 }}>
                  {r.areaM2 > 0 ? `${fmt(r.laborCostPerM2)}/m` : "sem m"}
                </p>
              </div>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 6, marginTop: 10 }}>
              {[
                ["Feriados pagos", fmt(r.holidayPay), C.green],
                ["VT/VR", fmt(r.benefitCost), C.blue],
                ["Total", fmt(r.totalCost), C.yellow],
              ].map(([label, value, color]) => (
                <div key={label} style={{ background: C.surface, border: `1px solid ${C.border}`, padding: 8 }}>
                  <p style={{ fontSize: 10, color: C.muted, textTransform: "uppercase" }}>{label}</p>
                  <p style={{ color, fontWeight: 900 }}>{value}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, textTransform: "uppercase", marginBottom: 8 }}>Top custos do mês</h3>
        {topCost.length === 0 && <p style={{ color: C.muted, fontSize: 13 }}>Nenhum custo lançado no período.</p>}
        {topCost.map(i => (
          <div key={`${i.name}-${i.obraId}`} style={{ borderTop: `1px solid ${C.border}`, padding: "9px 0", display: "flex", justifyContent: "space-between" }}>
            <div><p style={{ fontWeight: 900 }}>{i.name}</p><p style={{ color: C.muted, fontSize: 12 }}>{i.obra}</p></div>
            <p style={{ color: C.yellow, fontWeight: 900 }}>{fmt(i.total)}</p>
          </div>
        ))}
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, textTransform: "uppercase", marginBottom: 8 }}>Alterações de obra no mês</h3>
        {transferenciasPeriodo.length === 0 && <p style={{ color: C.muted, fontSize: 13 }}>Nenhuma transferência registrada no período.</p>}
        {transferenciasPeriodo.map(t => (
          <div key={t.id || `${t.empId}-${t.date}-${t.destino}`} style={{ borderTop: `1px solid ${C.border}`, padding: "9px 0" }}>
            <div style={{ display:"flex", justifyContent:"space-between", gap:8 }}>
              <p style={{ fontWeight:900 }}>{t.funcionario}</p>
              <p style={{ color:C.muted, fontSize:11 }}>{fmtDateFull(t.date)}</p>
            </div>
            <p style={{ color:C.muted, fontSize:12, marginTop:2 }}>{t.origem} → <span style={{ color:C.yellow, fontWeight:800 }}>{t.destino}</span></p>
          </div>
        ))}
      </div>
      </> /* fim view==="custos" */}
    </div>
  );
}


// 
// RELATÓRIO MENSAL COMPLETO POR OBRA
// 

function RelatorioMensal({ data, year, month }) {
  const rows   = useMemo(() => calcRelatorioMensal(data, year, month), [data, year, month]);
  const period = `${fullMonth(month)} ${year}`;
  const monthDays = getDays(year, month);
  const monthStart = monthDays[0] || "";
  const monthEnd = monthDays[monthDays.length - 1] || "";
  const transferenciasPeriodo = (data.changeLog || [])
    .filter(t => t.type === "transfer" && t.date && t.date >= monthStart && t.date <= monthEnd)
    .map(t => ({
      ...t,
      funcionario: t.empName || (data.employees || []).find(e => e.id === t.empId)?.name || "Funcionário",
      origem: t.from || (data.obras || []).find(o => o.id === t.fromId)?.name || "-",
      destino: t.to || (data.obras || []).find(o => o.id === t.toId)?.name || "-",
    }))
    .sort((a, b) => a.date.localeCompare(b.date));

  // Totais consolidados
  const tot = rows.reduce((acc, r) => ({
    received:       acc.received       + r.received,
    revenueEsp:     acc.revenueEsp     + r.revenueEsperada,
    laborCost:      acc.laborCost      + r.moData.laborCost,
    benefitCost:    acc.benefitCost    + r.moData.benefitCost,
    tercCost:       acc.tercCost       + r.tercCost,
    rescTotal:      acc.rescTotal      + r.rescTotal,
    adiantTotal:    acc.adiantTotal    + r.adiantTotal,
    totalDespesas:  acc.totalDespesas  + r.totalDespesas,
    margem:         acc.margem         + r.margem,
  }), { received:0, revenueEsp:0, laborCost:0, benefitCost:0, tercCost:0, rescTotal:0, adiantTotal:0, totalDespesas:0, margem:0 });

  const fmt2 = n => Number(n||0).toFixed(2).replace(".",",");

  //  PDF 
  const gerarPDF = () => {
    const dreRow = (label, value, cls="") =>
      `<tr class="${cls}"><td>${label}</td><td class="val">${value>=0?"":"(-)"} R$ ${fmt2(Math.abs(value))}</td></tr>`;

    const obraBlocks = rows.map(r => `
      <div class="obra-block">
        <div class="obra-header">
          <div>
            <p class="obra-nome">${escapeHtml(r.obra.name)}</p>
            <p class="obra-sub">${CONTRACT_LABELS[r.obra.contractType]||"Contrato"}  ${r.activeEmps} func. ativos  ${r.activeTercs} terceiros  ${r.presencaDias} presenças</p>
          </div>
          <div class="margem-badge ${r.margem>=0?"pos":"neg"}">
            <p class="mb-label">Margem</p>
            <p class="mb-val">R$ ${fmt2(r.margem)}</p>
            <p class="mb-pct">${r.margemPct.toFixed(1)}%</p>
          </div>
        </div>
        <table class="dre">
          <thead><tr><th>Descrição</th><th class="val">Valor</th></tr></thead>
          <tbody>
            <tr class="section-header"><td colspan="2">RECEITAS</td></tr>
            ${dreRow("(+) Receita recebida", r.received, "entry")}
            ${dreRow("(+) Receita esperada (contrato)", r.revenueEsperada, "entry muted")}
            <tr class="section-header"><td colspan="2">DESPESAS</td></tr>
            ${dreRow("(-) Mão de obra própria", r.moData.laborCost, "entry desp")}
            ${dreRow("(-) Benefícios (VT/VR)", r.moData.benefitCost, "entry desp")}
            ${dreRow("(-) Terceirizados", r.tercCost, "entry desp")}
            ${r.rescTotal>0 ? dreRow("(-) Rescisões", r.rescTotal, "entry desp") : ""}
            ${r.adiantTotal>0 ? dreRow("(-) Adiantamentos", r.adiantTotal, "entry desp") : ""}
            <tr class="subtotal desp"><td>Total de Despesas</td><td class="val">R$ ${fmt2(r.totalDespesas)}</td></tr>
            <tr class="section-header"><td colspan="2">RESULTADO</td></tr>
            <tr class="result ${r.margem>=0?"pos":"neg"}"><td>Margem (Receb.  Desp.)</td><td class="val">R$ ${fmt2(r.margem)}</td></tr>
            <tr class="result-esp"><td>Margem Esperada</td><td class="val">R$ ${fmt2(r.margemEsperada)}</td></tr>
          </tbody>
        </table>
        ${r.tercDetalhes.length>0 ? `
          <p class="detail-title">Terceirizados pagos no mês:</p>
          <ul class="detail-list">${r.tercDetalhes.map(p=>`<li>${escapeHtml(p.tercName||"-")} - R$ ${fmt2(p.amount)} (${fmtDateFull(p.date)})</li>`).join("")}</ul>` : ""}
        ${r.rescDetalhes.length>0 ? `
          <p class="detail-title">Rescisões no mês:</p>
          <ul class="detail-list">${r.rescDetalhes.map(r=>`<li>${escapeHtml(r.empName||"-")} - R$ ${fmt2(r.totalLiquido)} (${fmtDateFull(r.demissao)})</li>`).join("")}</ul>` : ""}
      </div>`).join("");

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>Relatório Mensal - ${escapeHtml(period)}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Arial,sans-serif;color:#111;background:#fff;padding:28px;font-size:11px}
.print-btn{position:fixed;top:10px;right:10px;background:#080808;color:#f6d833;border:none;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer;z-index:99}
.page-header{display:flex;align-items:center;gap:16px;padding-bottom:14px;border-bottom:3px solid #080808;margin-bottom:20px}
.logo-box{background:#080808;color:#f6d833;padding:10px 16px;font-family:Georgia,serif;font-size:24px;font-weight:900;letter-spacing:2px;flex-shrink:0}
.company h1{font-size:17px;font-weight:900;letter-spacing:.5px}
.company p{font-size:10px;color:#666;margin-top:2px}
.period{font-size:20px;font-weight:900;text-align:right;flex:1;color:#080808}
.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0;page-break-inside:avoid}
.sum-card{border:1px solid #ddd;padding:10px 12px;border-top:3px solid #ccc}
.sum-card.green{border-top-color:#16a34a}.sum-card.red{border-top-color:#dc2626}.sum-card.blue{border-top-color:#2563eb}.sum-card.purple{border-top-color:#9333ea}
.sum-card .sc-label{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:#777}
.sum-card .sc-val{font-size:16px;font-weight:900;margin-top:4px}
h2{font-size:13px;font-weight:900;text-transform:uppercase;letter-spacing:.8px;margin:22px 0 10px;border-bottom:1.5px solid #080808;padding-bottom:5px}
.obra-block{margin-bottom:24px;page-break-inside:avoid;border:1px solid #e5e7eb;border-radius:2px;overflow:hidden}
.obra-header{background:#f9f9f9;display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border-bottom:1px solid #e5e7eb}
.obra-nome{font-size:14px;font-weight:900;letter-spacing:.3px}
.obra-sub{font-size:10px;color:#777;margin-top:3px}
.margem-badge{text-align:right;min-width:100px}
.margem-badge.pos .mb-val{color:#16a34a}.margem-badge.neg .mb-val{color:#dc2626}
.mb-label{font-size:9px;color:#999;text-transform:uppercase;font-weight:700}
.mb-val{font-size:16px;font-weight:900;margin-top:1px}
.mb-pct{font-size:10px;color:#999;margin-top:1px}
table.dre{width:100%;border-collapse:collapse;font-size:11px}
table.dre th{background:#080808;color:#fff;padding:6px 10px;text-align:left;font-weight:700;font-size:10px;text-transform:uppercase;letter-spacing:.5px}
table.dre th.val,table.dre td.val{text-align:right;min-width:110px}
table.dre td{padding:5px 10px;border-bottom:1px solid #f0f0f0}
.section-header td{background:#f3f4f6;font-weight:700;font-size:10px;text-transform:uppercase;letter-spacing:.7px;color:#555;padding:4px 10px}
.entry.desp td{color:#333}.entry.muted td{color:#999;font-style:italic}
.subtotal td{font-weight:900;background:#fef2f2;color:#dc2626;font-size:12px;border-top:2px solid #fca5a5}
.subtotal.desp td{background:#fef2f2}
.result td{font-weight:900;font-size:13px;border-top:2px solid #080808}
.result.pos td{color:#16a34a}.result.neg td{color:#dc2626}
.result-esp td{color:#9333ea;font-weight:700;font-size:11px;border-bottom:2px solid #080808}
.detail-title{font-size:10px;font-weight:700;color:#555;margin:8px 14px 3px;text-transform:uppercase;letter-spacing:.5px}
.detail-list{font-size:10px;color:#666;margin:0 14px 10px;padding-left:14px}
.detail-list li{margin-bottom:2px}
.consolidado table.dre{border:2px solid #080808}
.consolidado th{background:#080808}
.footer{margin-top:30px;text-align:center;font-size:9px;color:#bbb;border-top:1px solid #eee;padding-top:8px}
@media print{.print-btn{display:none!important} body{padding:18px}}
</style></head>
<body>
<button class="print-btn" onclick="window.print()"> Imprimir / PDF</button>
<div class="page-header">
  <div class="logo-box">ArcD</div>
  <div class="company">
    <h1>${escapeHtml(data.config.companyName||"ArcD Construtora")}</h1>
    ${data.config.cnpj?`<p>CNPJ: ${escapeHtml(data.config.cnpj)}</p>`:""}
    <p>Relatório Gerencial Mensal</p>
  </div>
  <div class="period">${escapeHtml(period)}</div>
</div>

<div class="summary">
  <div class="sum-card green"><p class="sc-label">Receita recebida</p><p class="sc-val">R$ ${fmt2(tot.received)}</p></div>
  <div class="sum-card blue"><p class="sc-label">Custo MO própria</p><p class="sc-val">R$ ${fmt2(tot.laborCost+tot.benefitCost)}</p></div>
  <div class="sum-card purple"><p class="sc-label">Terceiros + Rescisões</p><p class="sc-val">R$ ${fmt2(tot.tercCost+tot.rescTotal)}</p></div>
  <div class="sum-card ${tot.margem>=0?"green":"red"}"><p class="sc-label">Margem global</p><p class="sc-val">R$ ${fmt2(tot.margem)}</p></div>
</div>

<h2>Detalhamento por Obra</h2>
${obraBlocks}

${transferenciasPeriodo.length ? `
<h2>Alterações de obra no período</h2>
<table class="dre">
  <thead><tr><th>Data</th><th>Funcionário</th><th>Origem</th><th>Destino</th></tr></thead>
  <tbody>${transferenciasPeriodo.map(t => `<tr><td>${fmtDateFull(t.date)}</td><td>${escapeHtml(t.funcionario)}</td><td>${escapeHtml(t.origem)}</td><td>${escapeHtml(t.destino)}</td></tr>`).join("")}</tbody>
</table>` : ""}

<h2>Consolidado Geral - ${escapeHtml(period)}</h2>
<div class="consolidado">
<table class="dre">
  <thead><tr><th>Descrição</th><th class="val">Valor</th></tr></thead>
  <tbody>
    <tr class="section-header"><td colspan="2">RECEITAS</td></tr>
    ${dreRow("(+) Receita recebida total", tot.received, "entry")}
    ${dreRow("(+) Receita esperada total", tot.revenueEsp, "entry muted")}
    <tr class="section-header"><td colspan="2">DESPESAS</td></tr>
    ${dreRow("(-) Mão de obra própria", tot.laborCost, "entry desp")}
    ${dreRow("(-) Benefícios (VT/VR)", tot.benefitCost, "entry desp")}
    ${dreRow("(-) Terceirizados", tot.tercCost, "entry desp")}
    ${tot.rescTotal>0?dreRow("(-) Rescisões", tot.rescTotal, "entry desp"):""}
    ${tot.adiantTotal>0?dreRow("(-) Adiantamentos", tot.adiantTotal, "entry desp"):""}
    <tr class="subtotal desp"><td>Total de Despesas</td><td class="val">R$ ${fmt2(tot.totalDespesas)}</td></tr>
    <tr class="section-header"><td colspan="2">RESULTADO FINAL</td></tr>
    <tr class="result ${tot.margem>=0?"pos":"neg"}"><td><strong>Margem Global (Receb.  Desp.)</strong></td><td class="val"><strong>R$ ${fmt2(tot.margem)}</strong></td></tr>
  </tbody>
</table>
</div>

<div class="footer">Gerado por ArcD Ponto PRO  ${new Date().toLocaleString("pt-BR")}  ${escapeHtml(data.config.hrName||"")}</div>
</body></html>`;
    const w = window.open("","_blank"); w.document.write(html); w.document.close();
  };

  //  Excel 
  const exportXLS = () => {
    const wb = XLSX.utils.book_new();

    // Aba 1 - Resumo consolidado
    const ws1 = XLSX.utils.aoa_to_sheet([
      [`Relatório Mensal - ${period}`],
      [`Empresa: ${data.config.companyName||"ArcD"}`],
      [],
      ["Indicador","Valor"],
      ["Receita recebida",        tot.received],
      ["Receita esperada",        tot.revenueEsp],
      ["(-) Mão de obra própria", tot.laborCost],
      ["(-) Benefícios",          tot.benefitCost],
      ["(-) Terceirizados",       tot.tercCost],
      ["(-) Rescisões",           tot.rescTotal],
      ["(-) Adiantamentos",       tot.adiantTotal],
      ["Total despesas",          tot.totalDespesas],
      ["Margem global",           tot.margem],
    ]);
    ws1["!cols"] = [{wch:28},{wch:16}];
    XLSX.utils.book_append_sheet(wb, ws1, "Resumo");

    // Aba 2 - Detalhe por obra
    const header2 = ["Obra","Tipo Contrato","Recebido","Receita Esp.","MO Própria","Benefícios","Terceiros","Rescisões","Adiantamentos","Total Desp.","Margem","Margem %","Presenças","Faltas","Func.Ativos","Terceiros Ativos"];
    const body2 = rows.map(r=>[
      r.obra.name,
      CONTRACT_LABELS[r.obra.contractType]||r.obra.contractType,
      r.received, r.revenueEsperada,
      r.moData.laborCost, r.moData.benefitCost,
      r.tercCost, r.rescTotal, r.adiantTotal, r.totalDespesas,
      r.margem, r.margemPct.toFixed(1)+"%",
      r.presencaDias, r.faltas, r.activeEmps, r.activeTercs,
    ]);
    const total2 = ["TOTAL","",tot.received,tot.revenueEsp,tot.laborCost,tot.benefitCost,tot.tercCost,tot.rescTotal,tot.adiantTotal,tot.totalDespesas,tot.margem,"","","","",""];
    const ws2 = XLSX.utils.aoa_to_sheet([[`Detalhe por obra - ${period}`],[],header2,...body2,total2]);
    ws2["!cols"] = [22,16,12,12,12,12,12,12,12,12,12,10,10,8,10,12].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws2, "Por Obra");

    // Aba 3 - Pagamentos recebidos
    const h3=["Data","Obra","Valor","Descrição"];
    const b3=rows.flatMap(r=>r.recDetalhes.map(p=>[p.date, r.obra.name, p.amount, p.description]));
    const ws3=XLSX.utils.aoa_to_sheet([[`Pagamentos recebidos - ${period}`],[],h3,...b3]);
    ws3["!cols"]=[12,22,12,30].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws3, "Recebimentos");

    // Aba 4 - Terceiros
    const h4=["Data","Obra","Terceirizado","Especialidade","Valor","Descrição"];
    const b4=rows.flatMap(r=>r.tercDetalhes.map(p=>[p.date,r.obra.name,p.tercName||"-",p.specialty||"-",p.amount,p.description||"-"]));
    const ws4=XLSX.utils.aoa_to_sheet([[`Pagamentos terceiros - ${period}`],[],h4,...b4]);
    ws4["!cols"]=[12,22,20,14,12,28].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws4, "Terceiros");

    // Aba 5 - Rescisões
    const h5=["Obra","Funcionário","CPF","Admissão","Rescisão","Tipo","Total Líquido"];
    const b5=rows.flatMap(r=>r.rescDetalhes.map(rc=>[r.obra.name,rc.empName||"-",rc.empCPF||"-",rc.admissao,rc.demissao,TIPO_LABEL[rc.tipo]||rc.tipo,rc.totalLiquido]));
    if(b5.length>0){
      const ws5=XLSX.utils.aoa_to_sheet([[`Rescisões - ${period}`],[],h5,...b5]);
      ws5["!cols"]=[22,22,14,12,12,30,12].map(w=>({wch:w}));
      XLSX.utils.book_append_sheet(wb, ws5, "Rescisões");
    }

    const ws6 = XLSX.utils.aoa_to_sheet([
      [`Transferências de obra - ${period}`],
      [],
      ["Data", "Funcionário", "Obra de origem", "Obra de destino"],
      ...transferenciasPeriodo.map(t => [t.date, t.funcionario, t.origem, t.destino]),
    ]);
    ws6["!cols"] = [12,24,24,24].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, ws6, "Transferências");

    XLSX.writeFile(wb, `arcd-relatorio-${year}-${String(month+1).padStart(2,"0")}.xlsx`);
  };

  //  UI 
  return (
    <div style={{display:"flex",flexDirection:"column",gap:14}} className="anim">

      {/* Cabeçalho */}
      <div style={{
        background:`linear-gradient(135deg,${C.yellow} 0%,${C.yellowD} 55%,#4a3c0a 100%)`,
        color:C.ink, padding:"16px 20px", borderRadius:12,
        border:`1px solid ${C.yellow}`, boxShadow:`0 20px 50px ${C.yellow}18`,
      }}>
        <p style={{fontSize:11,fontWeight:900,letterSpacing:1.2,textTransform:"uppercase",opacity:.7}}>Relatório Gerencial</p>
        <h2 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(18px,8vw,32px)",letterSpacing:2,lineHeight:1,margin:"4px 0 8px"}}>{fullMonth(month)} {year}</h2>
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8,marginTop:10}}>
          {[
            ["Receita recebida", fmt(tot.received),  C.green],
            ["Margem global",    fmt(tot.margem),    tot.margem>=0?"#14532d":"#7f1d1d"],
            ["Total despesas",   fmt(tot.totalDespesas), C.red],
            ["Receita esperada", fmt(tot.revenueEsp), "#1e3a5f"],
          ].map(([l,v,c])=>(
            <div key={l} style={{background:"rgba(0,0,0,.18)",padding:"8px 12px",borderRadius:8}}>
              <p style={{fontSize:9,fontWeight:900,textTransform:"uppercase",opacity:.7}}>{l}</p>
              <p style={{fontWeight:900,fontSize:16,marginTop:2}}>{v}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Ações */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Btn onClick={gerarPDF} v="danger" full><Ic n="file"/> Relatório PDF</Btn>
        <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Excel Completo</Btn>
      </div>

      {/* Cards por obra */}
      {rows.map(r => {
        const margemColor = r.margem >= 0 ? C.green : C.red;
        return (
          <div key={r.obra.id} style={{
            background:C.card, border:`1px solid ${C.border}`,
            borderLeft:`5px solid ${margemColor}`, borderRadius:10, overflow:"hidden",
          }}>
            {/* Header da obra */}
            <div style={{padding:"12px 16px",borderBottom:`1px solid ${C.line}`,display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
              <div>
                <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:18,letterSpacing:.3}}>{r.obra.name}</p>
                <div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:4}}>
                  <Badge color={C.yellow}>{CONTRACT_LABELS[r.obra.contractType]||"Contrato"}</Badge>
                  <Badge color={C.blue}>{r.activeEmps} func.</Badge>
                  {r.activeTercs>0&&<Badge color={C.orange}>{r.activeTercs} terceiros</Badge>}
                  <Badge color={C.muted}>{r.presencaDias} presenças</Badge>
                </div>
              </div>
              <div style={{textAlign:"right",flexShrink:0}}>
                <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:22,color:margemColor,letterSpacing:.5,lineHeight:1}}>{fmt(r.margem)}</p>
                <p style={{fontSize:10,color:C.muted,marginTop:2}}>margem {r.margemPct.toFixed(0)}%</p>
              </div>
            </div>

            {/* DRE mini */}
            <div style={{padding:"10px 16px",display:"flex",flexDirection:"column",gap:0}}>
              {/* Receitas */}
              <p style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:.8,marginBottom:4}}>Receitas</p>
              {[
                ["Recebido no mês",  r.received,         C.green],
                ["Esperado (contrato)", r.revenueEsperada, C.subtle],
              ].map(([l,v,c])=>(
                <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"3px 0",borderBottom:`1px solid ${C.line}44`}}>
                  <p style={{fontSize:12,color:c}}>{l}</p>
                  <p style={{fontSize:12,color:c,fontWeight:700}}>{fmt(v)}</p>
                </div>
              ))}

              {/* Despesas */}
              <p style={{fontSize:9,fontWeight:900,color:C.muted,textTransform:"uppercase",letterSpacing:.8,marginTop:8,marginBottom:4}}>Despesas</p>
              {[
                ["(-) MO própria",       r.moData.laborCost,   C.orange],
                ["(-) Benefícios VT/VR", r.moData.benefitCost, C.muted],
                ["(-) Terceirizados",    r.tercCost,           C.purple, r.tercCost===0],
                ["(-) Rescisões",        r.rescTotal,          C.red,    r.rescTotal===0],
                ["(-) Adiantamentos",    r.adiantTotal,        C.muted,  r.adiantTotal===0],
              ].filter(([,,, skip])=>!skip).map(([l,v,c])=>(
                <div key={l} style={{display:"flex",justifyContent:"space-between",padding:"3px 0",borderBottom:`1px solid ${C.line}44`}}>
                  <p style={{fontSize:12,color:C.muted}}>{l}</p>
                  <p style={{fontSize:12,color:c,fontWeight:700}}>{fmt(v)}</p>
                </div>
              ))}

              {/* Totais */}
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginTop:10}}>
                <div style={{background:C.surface,border:`1px solid ${C.border}`,padding:"8px 10px",borderRadius:8}}>
                  <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>Total despesas</p>
                  <p style={{fontSize:15,color:C.red,fontWeight:900,marginTop:2}}>{fmt(r.totalDespesas)}</p>
                </div>
                <div style={{background:C.surface,border:`1px solid ${margemColor}44`,padding:"8px 10px",borderRadius:8}}>
                  <p style={{fontSize:9,color:C.muted,textTransform:"uppercase",fontWeight:700}}>Margem esp.</p>
                  <p style={{fontSize:15,color:r.margemEsperada>=0?C.green:C.red,fontWeight:900,marginTop:2}}>{fmt(r.margemEsperada)}</p>
                </div>
              </div>

              {/* Detalhe terceiros/rescisões se houver */}
              {r.tercDetalhes.length>0&&(
                <div style={{marginTop:8}}>
                  <p style={{fontSize:10,fontWeight:700,color:C.purple,textTransform:"uppercase",marginBottom:3}}>Terceiros pagos</p>
                  {r.tercDetalhes.map(p=>(
                    <div key={p.id} style={{display:"flex",justifyContent:"space-between",fontSize:11,color:C.muted,padding:"2px 0"}}>
                      <span>{p.tercName||"-"} <span style={{color:C.muted,fontSize:10}}>({fmtDateFull(p.date)})</span></span>
                      <span style={{color:C.purple,fontWeight:700}}>{fmt(p.amount)}</span>
                    </div>
                  ))}
                </div>
              )}
              {r.rescDetalhes.length>0&&(
                <div style={{marginTop:8}}>
                  <p style={{fontSize:10,fontWeight:700,color:C.red,textTransform:"uppercase",marginBottom:3}}>Rescisões</p>
                  {r.rescDetalhes.map(rc=>(
                    <div key={rc.id} style={{display:"flex",justifyContent:"space-between",fontSize:11,color:C.muted,padding:"2px 0"}}>
                      <span>{rc.empName||"-"} <span style={{color:C.muted,fontSize:10}}>({TIPO_LABEL[rc.tipo]||rc.tipo})</span></span>
                      <span style={{color:C.red,fontWeight:700}}>{fmt(rc.totalLiquido)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        );
      })}

      {/* Totais finais */}
      <div style={{background:C.card,border:`2px solid ${C.yellow}`,borderRadius:10,padding:"14px 16px"}}>
        <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:16,color:C.yellow,textTransform:"uppercase",letterSpacing:.5,marginBottom:10}}>Consolidado Geral - {fullMonth(month)} {year}</p>
        {[
          ["Receita recebida",  tot.received,          C.green],
          ["Receita esperada",  tot.revenueEsp,        C.subtle],
          ["MO própria",        tot.laborCost,         C.orange],
          ["Benefícios",        tot.benefitCost,       C.muted],
          ["Terceirizados",     tot.tercCost,          C.purple],
          ["Rescisões",         tot.rescTotal,         C.red],
          ["Adiantamentos",     tot.adiantTotal,       C.muted],
          ["Total despesas",    tot.totalDespesas,     C.red],
          ["Margem global",     tot.margem,            tot.margem>=0?C.green:C.red],
        ].map(([l,v,c])=>(
          <div key={l} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"5px 0",borderBottom:`1px solid ${C.line}44`}}>
            <p style={{fontSize:13,color:C.muted}}>{l}</p>
            <p style={{fontSize:13,color:c,fontWeight:900}}>{fmt(v)}</p>
          </div>
        ))}
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        <Btn onClick={gerarPDF} v="danger" full><Ic n="file"/> PDF</Btn>
        <Btn onClick={exportXLS} v="success" full><Ic n="download"/> Excel</Btn>
      </div>
    </div>
  );
}

// 
// Agente de IA - apoio operacional
// Funciona com análise local do app e, se existir backend /api/ai-agent,
// usa o endpoint de IA sem expor chave no navegador.
// 

const agentNormalize = value => String(value || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase();

const agentDateLabel = iso => fmtDateFull(iso) || "-";

const getAgentMonthCostByObra = (data, year = new Date().getFullYear(), month = new Date().getMonth()) => {
  const days = getDays(year, month);
  const holidays = getPayrollHolidays(data, year);
  const holidaysInMonth = days.filter(d => holidays.includes(d) && prIsWeekdayIso(d));

  return (data.obras || []).map(obra => {
    let laborCost = 0;
    let benefitCost = 0;
    let presentes = 0;
    let meiodia = 0;
    let faltas = 0;
    let semRegistro = 0;

    (data.employees || []).forEach(emp => {
      if (emp.obra !== obra.id && emp.lastObra !== obra.id) return;

      days.forEach(day => {
        if (!isEmployeeEmployedOnDate(emp, day)) return;
        if (holidaysInMonth.includes(day)) return;
        const status = attStatus(data, emp.id, day);

        if (status === "P") {
          presentes++;
          laborCost += Number(emp.dailyRate || 0);
          benefitCost += Number(emp.vtDaily || 0) + Number(emp.vrDaily || 0);
        } else if (status === "M") {
          meiodia++;
          laborCost += Number(emp.dailyRate || 0) * 0.5;
          benefitCost += (Number(emp.vtDaily || 0) + Number(emp.vrDaily || 0)) * 0.5;
        } else if (status === "F") {
          faltas++;
        } else if (emp.active !== false && emp.obra === obra.id) {
          semRegistro++;
        }
      });

      holidaysInMonth.forEach(h => {
        if (!isEmployeeEmployedOnDate(emp, h)) return;
        if (emp.obra !== obra.id) return;
        laborCost += Number(getHolidayPayRule(data, emp, h, holidays).amount || 0);
      });
    });

    const areaM2 = Number(obra.areaM2 || 0);
    const totalCost = laborCost + benefitCost;

    return {
      obraId: obra.id,
      obraName: obra.name,
      areaM2,
      laborCost,
      benefitCost,
      totalCost,
      laborCostPerM2: areaM2 > 0 ? laborCost / areaM2 : 0,
      totalCostPerM2: areaM2 > 0 ? totalCost / areaM2 : 0,
      presentes,
      meiodia,
      faltas,
      semRegistro,
    };
  }).sort((a, b) => b.totalCost - a.totalCost);
};

const buildAgentContext = data => {
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();
  const todayIso = today();
  const activeEmployees = (data.employees || []).filter(e => e.active !== false);
  const activeObras = (data.obras || []).filter(o => o.status !== "done");
  const attendanceSummary = getObraAttendanceSummary(data, todayIso);
  const completion = getAttendanceCompletionMessage(attendanceSummary);
  const costs = getAgentMonthCostByObra(data, currentYear, currentMonth);
  const noArea = activeObras.filter(o => !Number(o.areaM2 || 0));
  const noTeam = activeObras.filter(o => !activeEmployees.some(e => e.obra === o.id));
  const incompleteEmployees = activeEmployees.filter(e =>
    !e.name || !e.role || !e.obra || !e.startDate || !Number(e.dailyRate || 0)
  );
  const missingPointEmployees = completion.pendingObras.flatMap(o =>
    o.missingEmployees.map(e => ({ name: e.name, obra: o.obraName }))
  );
  const paymentInfo = getPayrollPaymentCalendar(
    currentYear,
    currentMonth,
    now.getDate() <= 15 ? "1" : "2",
    data
  );

  return {
    today: todayIso,
    companyName: data.config?.companyName || "ArcD Obras",
    totalObras: (data.obras || []).length,
    activeObras: activeObras.length,
    totalEmployees: (data.employees || []).length,
    activeEmployees: activeEmployees.length,
    pendingPointObras: completion.pendingObras.map(o => ({
      obraName: o.obraName,
      missingCount: o.missingCount,
      missingEmployees: o.missingEmployees.map(e => e.name),
    })),
    completedPointObras: completion.completedObras.map(o => o.obraName),
    allPointsDoneToday: completion.allDone,
    missingPointEmployees,
    noAreaObras: noArea.map(o => o.name),
    noTeamObras: noTeam.map(o => o.name),
    incompleteEmployees: incompleteEmployees.slice(0, 30).map(e => ({
      name: e.name,
      role: e.role || "sem função",
      obra: activeObras.find(o => o.id === e.obra)?.name || "sem obra",
      missing: [
        !e.role ? "função" : "",
        !e.obra ? "obra" : "",
        !e.startDate ? "data de admissão" : "",
        !Number(e.dailyRate || 0) ? "diária" : "",
      ].filter(Boolean),
    })),
    monthlyCosts: costs.slice(0, 10).map(c => ({
      obraName: c.obraName,
      laborCost: c.laborCost,
      totalCost: c.totalCost,
      areaM2: c.areaM2,
      laborCostPerM2: c.laborCostPerM2,
      totalCostPerM2: c.totalCostPerM2,
    })),
    paymentDate: paymentInfo.paymentDate,
    paymentBaseDate: paymentInfo.baseDate,
    paymentAdjusted: paymentInfo.adjusted,
    // Terceirizados
    activeTerc: (data.terceirizados||[]).filter(t=>t.active!==false).length,
    tercPendingThisWeek: (() => {
      const fri = getFridayOfWeek(0);
      const {start: ws} = getWeekRange(fri);
      return (data.terceirizados||[]).filter(t=>t.active!==false&&!(data.pagsTerceiros||[]).some(p=>p.tercId===t.id&&p.date>=ws&&p.date<=fri)).length;
    })(),
    tercWeeklyTotal: (data.terceirizados||[]).filter(t=>t.active!==false).reduce((s,t)=>s+Number(t.weeklyRate||0),0),
  };
};

const agentFormatPendingPoints = ctx => {
  if (ctx.allPointsDoneToday) {
    return `Todos os pontos de hoje (${agentDateLabel(ctx.today)}) estão cadastrados nas obras com equipe ativa.`;
  }

  if (!ctx.pendingPointObras.length) {
    return `Não encontrei obras com equipe ativa pendente de ponto em ${agentDateLabel(ctx.today)}.`;
  }

  return [
    `Existem ${ctx.pendingPointObras.length} obra(s) com ponto pendente hoje (${agentDateLabel(ctx.today)}):`,
    ...ctx.pendingPointObras.map(o => `- ${o.obraName}: ${o.missingCount} trabalhador(es) sem ponto - ${o.missingEmployees.join(", ")}`),
  ].join("\n");
};

const agentFormatCosts = ctx => {
  if (!ctx.monthlyCosts.length) return "Ainda não há custo de mão de obra lançado no mês atual.";

  return [
    "Resumo de gasto de mão de obra por obra no mês atual:",
    ...ctx.monthlyCosts.map(c => {
      const m2 = c.areaM2 > 0 ? `  ${fmt(c.laborCostPerM2)}/m mão de obra` : "  área m não cadastrada";
      return `- ${c.obraName}: ${fmt(c.laborCost)} mão de obra | ${fmt(c.totalCost)} com benefícios${m2}`;
    }),
  ].join("\n");
};

const agentFormatIncompletes = ctx => {
  const parts = [];

  if (ctx.incompleteEmployees.length) {
    parts.push("Funcionários ativos com cadastro incompleto:");
    parts.push(...ctx.incompleteEmployees.map(e => `- ${e.name}: falta ${e.missing.join(", ")}.`));
  }

  if (ctx.noAreaObras.length) {
    parts.push("\nObras sem metragem cadastrada:");
    parts.push(...ctx.noAreaObras.map(name => `- ${name}`));
  }

  if (ctx.noTeamObras.length) {
    parts.push("\nObras ativas sem equipe vinculada:");
    parts.push(...ctx.noTeamObras.map(name => `- ${name}`));
  }

  return parts.length ? parts.join("\n") : "Não encontrei pendências cadastrais relevantes nos dados atuais.";
};

const agentFormatPayroll = ctx => {
  const obs = ctx.paymentAdjusted
    ? `A data base ${agentDateLabel(ctx.paymentBaseDate)} foi ajustada para ${agentDateLabel(ctx.paymentDate)}.`
    : `A data de pagamento permanece em ${agentDateLabel(ctx.paymentDate)}.`;

  return [
    `Próximo pagamento calculado: ${agentDateLabel(ctx.paymentDate)}.`,
    obs,
    `Pontos de hoje: ${ctx.allPointsDoneToday ? "todos cadastrados" : `${ctx.pendingPointObras.length} obra(s) pendente(s)`}.`,
    "Os pontos permanecem abertos para correção, sem necessidade de autorização.",
  ].join("\n");
};

const agentFormatPriorities = ctx => {
  const priorities = [];

  if (ctx.pendingPointObras.length) priorities.push(`Concluir os registros de ponto de ${ctx.pendingPointObras.length} obra(s) pendente(s).`);
  if (ctx.noAreaObras.length) priorities.push(`Cadastrar metragem de ${ctx.noAreaObras.length} obra(s) para custo por m.`);
  if (ctx.incompleteEmployees.length) priorities.push(`Corrigir cadastro de ${ctx.incompleteEmployees.length} funcionário(s) ativo(s).`);
  if (!priorities.length) priorities.push("Não há alertas críticos. Mantenha os registros de ponto conferidos e atualizados.");

  return [
    "Prioridades sugeridas pelo agente:",
    ...priorities.map((p, i) => `${i + 1}. ${p}`),
  ].join("\n");
};

const generateLocalAgentAnswer = (data, question) => {
  const ctx = buildAgentContext(data);
  const q = agentNormalize(question);

  if (!q.trim()) return agentFormatPriorities(ctx);
  if (q.includes("ponto") || q.includes("falt") || q.includes("pendente") || q.includes("cadastrar")) return agentFormatPendingPoints(ctx);
  if (q.includes("custo") || q.includes("gasto") || q.includes("m2") || q.includes("metro") || q.includes("obra")) return agentFormatCosts(ctx);
  if (q.includes("cadastro") || q.includes("incompleto") || q.includes("diaria") || q.includes("metragem")) return agentFormatIncompletes(ctx);
  if (q.includes("folha") || q.includes("pagamento") || q.includes("feriado") || q.includes("salario")) return agentFormatPayroll(ctx);
  if (q.includes("prioridade") || q.includes("risco") || q.includes("alerta") || q.includes("resumo")) return agentFormatPriorities(ctx);

  return [
    "Análise geral do agente:",
    agentFormatPriorities(ctx),
    "",
    agentFormatPendingPoints(ctx),
    "",
    agentFormatPayroll(ctx),
  ].join("\n");
};

async function askRemoteAgentIfAvailable(data, question) {
  try {
    const response = await fetch("/api/ai-agent", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        question,
        context: buildAgentContext(data),
      }),
    });

    if (!response.ok) return null;
    const payload = await response.json().catch(() => null);
    return payload?.answer || null;
  } catch {
    return null;
  }
}

function AgenteIA({ data, showToast, onTab }) {
  const [input, setInput] = useState("");
  const [thinking, setThinking] = useState(false);
  const initialAnswer = useMemo(() => generateLocalAgentAnswer(data, "prioridades"), [data]);
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      text: "Sou o Agente IA da ArcD Obras. Posso ajudar com ponto pendente, folha, custo por obra, custo por m, cadastros incompletos e alertas operacionais.",
    },
    { role: "assistant", text: initialAnswer },
  ]);

  const ctx = useMemo(() => buildAgentContext(data), [data]);

  const quickPrompts = [
    "O que falta no ponto de hoje?",
    "Quais obras estão gastando mais?",
    "Quais cadastros estão incompletos?",
    "Resumo da folha e pagamento",
    "Quais são as prioridades de hoje?",
  ];

  const sendQuestion = async (question = input) => {
    const q = String(question || "").trim();
    if (!q) return;

    setInput("");
    setMessages(prev => [...prev, { role: "user", text: q }]);
    setThinking(true);

    const remote = await askRemoteAgentIfAvailable(data, q);
    const answer = remote || generateLocalAgentAnswer(data, q);

    setMessages(prev => [...prev, { role: "assistant", text: answer }]);
    setThinking(false);
  };

  const copyLastAnswer = () => {
    const last = [...messages].reverse().find(m => m.role === "assistant")?.text || "";
    if (!last) return;
    navigator.clipboard.writeText(last).then(() => showToast("Resposta copiada.")).catch(() => showToast("Erro ao copiar.", "error"));
  };

  const goToPendingPoint = () => {
    onTab?.("ponto");
    if (ctx.pendingPointObras.length) showToast("Abra a obra pendente no filtro do ponto.", "warn");
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div
        style={{
          background: `linear-gradient(135deg, ${C.yellow}, ${C.yellowD})`,
          color: C.bg,
          border: `1px solid ${C.yellow}`,
          padding: 16,
          borderRadius: 10,
          boxShadow: `0 16px 36px ${C.yellow}22`,
        }}
      >
        <p style={{ fontSize: 11, fontWeight: 900, letterSpacing: 1.2, textTransform: "uppercase", opacity: 0.78 }}>
          Assistente operacional
        </p>
        <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 36, letterSpacing: 2, lineHeight: 1 }}>
          Agente IA ArcD
        </h2>
        <p style={{ fontSize: 13, fontWeight: 700, maxWidth: 720 }}>
          Analisa ponto, folha, obras, pendências, custo por obra e custo de mão de obra por m.
        </p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 8 }}>
        {[
          [ctx.allPointsDoneToday ? "Ponto completo" : "Ponto pendente", ctx.allPointsDoneToday ? "Todas as obras" : `${ctx.pendingPointObras.length} obra(s)`, ctx.allPointsDoneToday ? C.green : C.red],
          ["Funcionários ativos", ctx.activeEmployees, C.yellow],
          ["Sem registro hoje", ctx.missingPointEmployees.length, ctx.missingPointEmployees.length ? C.red : C.green],
          ["Obras sem m", ctx.noAreaObras.length, ctx.noAreaObras.length ? C.orange : C.green],
        ].map(([label, value, color]) => (
          <div key={label} style={{ background: C.card, border: `1px solid ${C.border}`, borderTop: `3px solid ${color}`, padding: 12, borderRadius: 8 }}>
            <p style={{ color: C.muted, fontSize: 10, textTransform: "uppercase", fontWeight: 900 }}>{label}</p>
            <p style={{ color, fontFamily:"'Inter Display','Inter',sans-serif", fontSize: 23, fontWeight: 900 }}>{value}</p>
          </div>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Btn v="warning" onClick={goToPendingPoint} full><Ic n="clock" /> Ir para Ponto</Btn>
        <Btn v="ghost" onClick={() => onTab?.("relat")} full><Ic n="chart" /> Ver Relatórios</Btn>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14, borderRadius: 10 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, fontSize: 18, textTransform: "uppercase", marginBottom: 10 }}>
          Perguntas rápidas
        </h3>
        <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
          {quickPrompts.map(p => (
            <button
              key={p}
              onClick={() => sendQuestion(p)}
              style={{
                background: C.surface,
                color: C.text,
                border: `1px solid ${C.border}`,
                borderLeft: `3px solid ${C.yellow}`,
                padding: "8px 10px",
                borderRadius: 999,
                cursor: "pointer",
                fontSize: 12,
                fontWeight: 800,
              }}
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 12, borderRadius: 10, minHeight: 300 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, fontSize: 18, textTransform: "uppercase" }}>
            Conversa com o agente
          </h3>
          <Btn v="ghost" size="sm" onClick={copyLastAnswer}><Ic n="copy" /> Copiar</Btn>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 9, maxHeight: 390, overflowY: "auto", paddingRight: 3 }}>
          {messages.map((m, idx) => (
            <div
              key={`${m.role}-${idx}`}
              style={{
                alignSelf: m.role === "user" ? "flex-end" : "stretch",
                maxWidth: m.role === "user" ? "86%" : "100%",
                background: m.role === "user" ? C.yellow : C.surface,
                color: m.role === "user" ? C.bg : C.text,
                border: `1px solid ${m.role === "user" ? C.yellow : C.border}`,
                borderLeft: m.role === "assistant" ? `4px solid ${C.yellow}` : undefined,
                borderRadius: 8,
                padding: "10px 12px",
                whiteSpace: "pre-wrap",
                fontSize: 13,
                lineHeight: 1.35,
              }}
            >
              {m.text}
            </div>
          ))}
          {thinking && (
            <div style={{ color: C.yellow, fontSize: 12, fontWeight: 800, padding: "6px 2px" }}>
              Agente analisando dados...
            </div>
          )}
        </div>
      </div>

      <div className="fluid-grid" style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 8 }}>
        <Inp
          value={input}
          onChange={setInput}
          placeholder="Pergunte: quais obras faltam ponto? qual maior custo por m?"
        />
        <Btn onClick={() => sendQuestion()} disabled={thinking || !input.trim()}>
          <Ic n="brain" /> Enviar
        </Btn>
      </div>

      <p style={{ color: C.muted, fontSize: 11, lineHeight: 1.35 }}>
        O agente usa os dados já cadastrados no sistema. Se existir uma rota segura <strong>/api/ai-agent</strong>, ele usa IA generativa; caso contrário, responde com análise local automática, sem expor chaves no navegador.
      </p>
    </div>
  );
}

// 
// RESCISÃO - cálculo e PDF
// 

const TIPOS_RESCISAO = [
  { v: "sem_justa_causa",   l: "Dispensa sem justa causa (empregador)" },
  { v: "justa_causa",       l: "Dispensa por justa causa" },
  { v: "pedido_demissao",   l: "Pedido de demissão (funcionário)" },
  { v: "acordo_mutuo",      l: "Acordo mútuo (art. 484-A CLT)" },
  { v: "termino_contrato",  l: "Término de contrato de prazo determinado" },
  { v: "acordo_interno",    l: "Acordo interno - valor fixo x tempo ativo" },
];

const TIPO_LABEL = Object.fromEntries(TIPOS_RESCISAO.map(t => [t.v, t.l]));

const calcRescisao = (form) => {
  const { admissao, demissao, valorMensal, diasNoMes, tipo,
    incluirSaldo, incluir13, incluirFerias, incluirAviso,
    valorFixoAcordo, descAdiantamento, descOutros } = form;
  if (!admissao || !demissao) return null;

  const dataAdm = new Date(admissao + "T12:00:00");
  const dataDem = new Date(demissao + "T12:00:00");
  if (dataDem < dataAdm) return null;

  // Tempo de serviço
  let anos  = dataDem.getFullYear() - dataAdm.getFullYear();
  let meses = dataDem.getMonth()    - dataAdm.getMonth();
  let dias  = dataDem.getDate()     - dataAdm.getDate();
  if (dias < 0)  { meses--; dias += 30; }
  if (meses < 0) { anos--;  meses += 12; }
  const totalMeses = anos * 12 + meses;
  const diasResto  = dias;
  const avos13     = totalMeses + (diasResto >= 15 ? 1 : 0);
  const avosFerias = avos13;

  const vm          = Number(valorMensal || 0);
  const dd          = Number(diasNoMes   || 0);
  const descAdiant  = Number(descAdiantamento || 0);
  const descOut     = Number(descOutros       || 0);
  const totalDesc   = descAdiant + descOut;

  //  ACORDO INTERNO - cálculo especial 
  if (tipo === "acordo_interno") {
    const vf = Number(valorFixoAcordo || vm || 0);
    // Meses completos + fração proporcional de dias
    const mesesAtivos = totalMeses + (diasResto / 30);
    const totalBruto  = vf * mesesAtivos;
    const totalLiquido = Math.max(0, totalBruto - totalDesc);
    return {
      isAcordoInterno: true,
      anos, totalMeses, diasResto, avos13: 0, avosFerias: 0,
      mesesAtivos: Number(mesesAtivos.toFixed(4)),
      valorFixoAcordo: vf,
      saldoSalario: 0, dec13: 0, feriasBruto: 0, feriasTotal: 0, avisoPrevio: 0,
      totalBruto, totalDesc, totalLiquido,
    };
  }

  //  DEMAIS MODALIDADES 
  const saldoSalario = incluirSaldo  ? (vm / 30) * dd : 0;
  const dec13        = incluir13     ? (vm / 12) * avos13 : 0;
  const feriasBruto  = incluirFerias ? (vm / 12) * avosFerias : 0;
  const feriasTotal  = feriasBruto * (4 / 3);
  const aviso        = incluirAviso && tipo === "sem_justa_causa" ? vm       : 0;
  const avisoAcordo  = incluirAviso && tipo === "acordo_mutuo"    ? vm * 0.5 : 0;
  const avisoPrevio  = aviso + avisoAcordo;
  const totalBruto   = saldoSalario + dec13 + feriasTotal + avisoPrevio;
  const totalLiquido = Math.max(0, totalBruto - totalDesc);

  return {
    isAcordoInterno: false,
    anos, totalMeses, diasResto, avos13, avosFerias,
    saldoSalario, dec13, feriasBruto, feriasTotal, avisoPrevio,
    totalBruto, totalDesc, totalLiquido,
  };
};

function Rescisao({ data, update, showToast }) {
  const { formGrid } = useBreakpoint();
  const emptyForm = {
    empId: "", empName: "", empCPF: "", empFuncao: "", obraName: "",
    admissao: "", demissao: today(), valorMensal: "", diasNoMes: "",
    tipo: "sem_justa_causa",
    valorFixoAcordo: "",
    incluirSaldo: true, incluir13: true, incluirFerias: true,
    incluirAviso: false,
    descAdiantamento: "", descOutros: "", obsDesc: "",
    obs: "",
  };

  const [form, setForm]       = useState(emptyForm);
  const [history, setHistory] = useState(false); // toggle
  const F = k => v => setForm(f => ({ ...f, [k]: v }));

  // Ao selecionar funcionário da lista
  const selectEmp = empId => {
    if (!empId) { setForm(f => ({ ...f, empId:"", empName:"", empCPF:"", empFuncao:"", obraName:"", admissao:"", valorMensal:"", diasNoMes:"" })); return; }
    const emp = data.employees.find(e => e.id === empId);
    if (!emp) return;
    const obra = data.obras.find(o => o.id === emp.obra);
    const vm   = Number(emp.dailyRate || 0) * 26; // 26 dias úteis/mês
    const pendAdv = (data.advances||[]).filter(a => a.empId === empId).reduce((s,a)=>s+Number(a.amount||0),0);
    setForm(f => ({
      ...f,
      empId, empName: emp.name, empCPF: emp.cpf||"",
      empFuncao: emp.role||"", obraName: obra?.name||"",
      admissao: emp.startDate||"",
      valorMensal: String(Math.round(vm)),
      descAdiantamento: pendAdv > 0 ? String(pendAdv) : "",
    }));
  };

  const calc = calcRescisao(form);

  // Salvar rescisão
  const salvar = () => {
    if (!form.empName.trim() || !calc) { showToast("Preencha os dados obrigatórios.", "error"); return; }
    const rec = {
      id: uid(), ...form,
      ...calc,
      createdAt: new Date().toISOString(),
    };
    update({ ...data, rescisoes: [...(data.rescisoes||[]), rec] });
    showToast("Rescisão salva no histórico.");
  };

  // Gerar PDF
  // Aceita um registro do histórico. O registro salvo é {...form, ...calc},
  // logo carrega tanto os dados cadastrais quanto o cálculo - é o que permite
  // reemitir o PDF direto do histórico, sem reabrir o formulário.
  const gerarPDF = (registro = null) => {
    const fonte = registro || form;
    const c     = registro || calc;
    if (!c) { showToast("Complete o cálculo primeiro.", "error"); return; }
    const tempoStr = `${c.anos > 0 ? c.anos+"a " : ""}${c.totalMeses % 12}m ${c.diasResto}d`;
    const rows = c.isAcordoInterno
      ? [["Acordo interno - valor fixo x tempo ativo",
          `${fmt(c.valorFixoAcordo)} x ${c.mesesAtivos.toFixed(2)} meses`,
          c.totalBruto]]
      : [
          fonte.incluirSaldo  && ["Saldo de salário",   `${fonte.diasNoMes} dias em ${fmtDateFull(fonte.demissao)}`, c.saldoSalario],
          fonte.incluir13     && [`13º salário proporcional`, `${c.avos13}/12 avos`, c.dec13],
          fonte.incluirFerias && [`Férias proporcionais + 1/3`, `${c.avosFerias}/12 avos x 4/3`, c.feriasTotal],
          fonte.incluirAviso  && c.avisoPrevio > 0 && ["Aviso prévio", "30 dias", c.avisoPrevio],
        ].filter(Boolean);
    const descs = [
      Number(fonte.descAdiantamento||0) > 0 && ["Adiantamentos", Number(fonte.descAdiantamento)],
      Number(fonte.descOutros||0) > 0       && [fonte.obsDesc||"Outros descontos", Number(fonte.descOutros)],
    ].filter(Boolean);

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>Rescisão - ${escapeHtml(fonte.empName)}</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'Arial',sans-serif;color:#111;background:#fff;padding:32px;font-size:12px}
  .header{display:flex;align-items:center;gap:16px;padding-bottom:16px;border-bottom:3px solid #111;margin-bottom:20px}
  .logo-box{background:#080808;color:#f6d833;padding:10px 16px;font-family:Georgia,serif;font-size:26px;font-weight:900;letter-spacing:2px;flex-shrink:0}
  .company-info h1{font-size:18px;font-weight:900;letter-spacing:1px}
  .company-info p{font-size:11px;color:#555;margin-top:3px}
  h2{font-size:15px;font-weight:900;text-transform:uppercase;letter-spacing:1px;margin:18px 0 10px;border-bottom:1px solid #ccc;padding-bottom:5px}
  .info-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px 24px;margin-bottom:16px}
  .info-item p.lbl{font-size:10px;color:#777;text-transform:uppercase;font-weight:700;letter-spacing:.5px}
  .info-item p.val{font-size:13px;font-weight:600;margin-top:1px}
  table{width:100%;border-collapse:collapse;margin:12px 0}
  th{background:#111;color:#fff;padding:8px 10px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px}
  td{padding:8px 10px;border-bottom:1px solid #eee;font-size:12px}
  td.right{text-align:right;font-weight:700}
  tr.desc td{color:#c00}
  tr.subtotal td{background:#f5f5f5;font-weight:900;font-size:13px}
  tr.total td{background:#111;color:#fff;font-size:15px;font-weight:900;padding:12px 10px}
  .ext-valor{font-size:12px;color:#555;margin:10px 0 20px;font-style:italic}
  .declaracao{background:#f9f9f9;border:1px solid #ddd;padding:14px;margin:20px 0;font-size:11px;line-height:1.6}
  .signs{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:40px}
  .sign-box{border-top:1px solid #111;padding-top:8px;text-align:center}
  .sign-box p{font-size:11px;color:#333;margin-top:4px}
  .sign-box .name{font-weight:900;font-size:13px;margin-top:2px}
  .footer{margin-top:30px;text-align:center;font-size:10px;color:#aaa;border-top:1px solid #eee;padding-top:10px}
  @media print{button{display:none!important}}
</style>
</head>
<body>
<button onclick="window.print()" style="position:fixed;top:10px;right:10px;background:#111;color:#f6d833;border:none;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer;z-index:99"> Imprimir / PDF</button>

<div class="header">
  <div class="logo-box">ArcD</div>
  <div class="company-info">
    <h1>${escapeHtml(data.config.companyName||"ArcD Construtora")}</h1>
    ${data.config.cnpj?`<p>CNPJ: ${escapeHtml(data.config.cnpj)}</p>`:""}
    <p>Recibo de Rescisão de Contrato de Trabalho</p>
  </div>
</div>

<h2>Dados do Trabalhador</h2>
<div class="info-grid">
  <div class="info-item"><p class="lbl">Nome</p><p class="val">${escapeHtml(fonte.empName)}</p></div>
  <div class="info-item"><p class="lbl">CPF</p><p class="val">${escapeHtml(fonte.empCPF||"-")}</p></div>
  <div class="info-item"><p class="lbl">Função</p><p class="val">${escapeHtml(fonte.empFuncao||"-")}</p></div>
  <div class="info-item"><p class="lbl">Obra</p><p class="val">${escapeHtml(fonte.obraName||"-")}</p></div>
  <div class="info-item"><p class="lbl">Data de Admissão</p><p class="val">${fmtDateFull(fonte.admissao)||"-"}</p></div>
  <div class="info-item"><p class="lbl">Data de Rescisão</p><p class="val">${fmtDateFull(fonte.demissao)||"-"}</p></div>
  <div class="info-item"><p class="lbl">Tempo de Serviço</p><p class="val">${tempoStr}</p></div>
  <div class="info-item"><p class="lbl">Motivo</p><p class="val">${escapeHtml(TIPO_LABEL[fonte.tipo]||fonte.tipo)}</p></div>
  <div class="info-item"><p class="lbl">Valor Mensal</p><p class="val">R$ ${Number(fonte.valorMensal||0).toLocaleString("pt-BR",{minimumFractionDigits:2})}</p></div>
</div>

<h2>Demonstrativo de Valores</h2>
<table>
  <thead><tr><th>Verba</th><th>Base de Cálculo</th><th style="text-align:right">Valor (R$)</th></tr></thead>
  <tbody>
    ${rows.map(([v,b,val])=>`<tr><td>${escapeHtml(v)}</td><td style="color:#555">${escapeHtml(b)}</td><td class="right">R$ ${Number(val).toLocaleString("pt-BR",{minimumFractionDigits:2})}</td></tr>`).join("")}
    <tr class="subtotal"><td colspan="2">Subtotal de Vencimentos</td><td class="right">R$ ${c.totalBruto.toLocaleString("pt-BR",{minimumFractionDigits:2})}</td></tr>
    ${descs.map(([v,val])=>`<tr class="desc"><td>(-) ${escapeHtml(v)}</td><td></td><td class="right">R$ ${Number(val).toLocaleString("pt-BR",{minimumFractionDigits:2})}</td></tr>`).join("")}
    <tr class="total"><td colspan="2">TOTAL LÍQUIDO A RECEBER</td><td class="right">R$ ${c.totalLiquido.toLocaleString("pt-BR",{minimumFractionDigits:2})}</td></tr>
  </tbody>
</table>

<p class="ext-valor">Valor por extenso: <strong>${valorPorExtenso(c.totalLiquido)}</strong></p>

${fonte.obs?`<div class="declaracao"><strong>Observações:</strong> ${escapeHtml(fonte.obs)}</div>`:""}

<div class="declaracao">
  Declaro ter recebido da empresa <strong>${escapeHtml(data.config.companyName||"ArcD Construtora")}</strong> a importância acima discriminada,
  referente à rescisão do meu contrato de trabalho, dando plena, geral e irrevogável quitação de todos
  os valores acima mencionados, nada mais tendo a reclamar a qualquer título.
  <br><br>
  <strong>Caruaru - PE, ${new Date().toLocaleDateString("pt-BR",{day:"2-digit",month:"long",year:"numeric"})}</strong>
</div>

<div class="signs">
  <div class="sign-box">
    <p class="name">${escapeHtml(fonte.empName)}</p>
    <p>Trabalhador(a)</p>
    <p>CPF: ${escapeHtml(fonte.empCPF||"________________")}</p>
  </div>
  <div class="sign-box">
    <p class="name">${escapeHtml(data.config.hrName||"Responsável")}</p>
    <p>${escapeHtml(data.config.companyName||"ArcD Construtora")}</p>
    ${data.config.cnpj?`<p>CNPJ: ${escapeHtml(data.config.cnpj)}</p>`:""}
  </div>
</div>

<div class="footer">Documento gerado pelo ArcD Ponto PRO  ${new Date().toLocaleString("pt-BR")}  Via do empregador / Via do trabalhador</div>
</body></html>`;
    const w = window.open("","_blank");
    w.document.write(html);
    w.document.close();
  };

  // Valor por extenso (simplificado até 999.999,99)
  function valorPorExtenso(n) {
    if(!n||isNaN(n)) return "zero reais";
    const inteiro = Math.floor(n);
    const centavos = Math.round((n - inteiro)*100);
    const u = ["","um","dois","três","quatro","cinco","seis","sete","oito","nove","dez","onze","doze","treze","quatorze","quinze","dezesseis","dezessete","dezoito","dezenove"];
    const d = ["","","vinte","trinta","quarenta","cinquenta","sessenta","setenta","oitenta","noventa"];
    const c = ["","cem","duzentos","trezentos","quatrocentos","quinhentos","seiscentos","setecentos","oitocentos","novecentos"];
    function grupo(n) {
      if(n===0) return "";
      if(n===100) return "cem";
      const cent = Math.floor(n/100), dez = Math.floor((n%100)/10), un = n%10;
      const parts = [];
      if(cent) parts.push(c[cent]);
      if(dez>=2){ parts.push(d[dez]); if(un) parts.push(u[un]); }
      else if(dez===1||un) parts.push(u[Math.floor(n%100)>19?un:n%100]);
      return parts.join(" e ");
    }
    const mil = Math.floor(inteiro/1000), resto = inteiro%1000;
    const partes = [];
    if(mil>0) partes.push((mil===1?"mil":grupo(mil)+" mil"));
    if(resto>0) partes.push(grupo(resto)+(resto===1?" real":" reais"));
    if(partes.length===0) partes.push("zero reais");
    if(centavos>0) partes.push(grupo(centavos)+(centavos===1?" centavo":" centavos"));
    return partes.join(" e ");
  }

  const activeEmps = data.employees.filter(e => e.active !== false);
  const rescisoes  = (data.rescisoes||[]).slice().reverse();

  return (
    <div className="anim" style={{display:"flex",flexDirection:"column",gap:14}}>

      {/* Header */}
      <div style={{background:`linear-gradient(135deg,${C.red}22 0%,${C.card} 65%)`,border:`1px solid ${C.red}44`,borderLeft:`5px solid ${C.red}`,padding:"16px 18px",borderRadius:12}}>
        <p style={{fontSize:11,fontWeight:900,color:C.red,textTransform:"uppercase",letterSpacing:1.2,marginBottom:4}}>Documentos</p>
        <h2 style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(19px,5vw,34px)",letterSpacing:2,color:C.text,lineHeight:1}}>Cálculo de Rescisão</h2>
        <p style={{color:C.muted,fontSize:13,marginTop:4}}>Gere o cálculo e o PDF para assinatura do trabalhador.</p>
      </div>

      {/* Selecionar funcionário */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.yellow}`,padding:14,borderRadius:10,display:"flex",flexDirection:"column",gap:10}}>
        <p style={{fontSize:11,fontWeight:900,color:C.yellow,textTransform:"uppercase",letterSpacing:.8}}> Trabalhador</p>
        <Sel label="Selecionar da lista (ou preencha manualmente abaixo)"
          value={form.empId}
          onChange={selectEmp}
          options={[{v:"",l:"- Preenchimento manual -"},...activeEmps.map(e=>({v:e.id,l:`${e.name}${e.role?"  "+e.role:""}`}))]}
        />
        <div style={{display:"grid",gridTemplateColumns:formGrid(2),gap:10}}>
          <Inp label="Nome completo *" value={form.empName} onChange={F("empName")} placeholder="Nome do trabalhador"/>
          <Inp label="CPF" value={form.empCPF} onChange={v=>F("empCPF")(fmtCPF(v))} placeholder="000.000.000-00"/>
          <Inp label="Função" value={form.empFuncao} onChange={F("empFuncao")} placeholder="Pedreiro, servente..."/>
          <Inp label="Obra" value={form.obraName} onChange={F("obraName")} placeholder="Nome da obra"/>
        </div>
      </div>

      {/* Datas e valores */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.orange}`,padding:14,borderRadius:10,display:"flex",flexDirection:"column",gap:10}}>
        <p style={{fontSize:11,fontWeight:900,color:C.orange,textTransform:"uppercase",letterSpacing:.8}}> Período e Valores</p>
        <div style={{display:"grid",gridTemplateColumns:formGrid(2),gap:10}}>
          <Inp label="Data de admissão *"  type="date" value={form.admissao}    onChange={F("admissao")}/>
          <Inp label="Data de rescisão *"  type="date" value={form.demissao}    onChange={F("demissao")}/>
          <Inp label="Valor mensal (R$) *" type="number" value={form.valorMensal} onChange={F("valorMensal")} placeholder="Diária x 26 dias"/>
          <Inp label="Dias trabalhados no mês" type="number" value={form.diasNoMes} onChange={F("diasNoMes")} placeholder="Ex: 12"/>
        </div>
        <Sel label="Motivo da rescisão *" value={form.tipo} onChange={F("tipo")} options={TIPOS_RESCISAO}/>

        {/* Acordo interno - campo especial */}
        {form.tipo === "acordo_interno" && (
          <div style={{background:`${C.yellow}12`,border:`1px solid ${C.yellow}44`,borderLeft:`4px solid ${C.yellow}`,padding:"12px 14px",borderRadius:8,display:"flex",flexDirection:"column",gap:10}}>
            <p style={{fontSize:12,fontWeight:700,color:C.yellow}}> Acordo Interno - cálculo simplificado</p>
            <p style={{fontSize:12,color:C.subtle}}>
              Total = Valor fixo mensal x meses ativos (+ fração proporcional de dias).
            </p>
            <Inp
              label="Valor fixo mensal do acordo (R$) *"
              type="number"
              value={form.valorFixoAcordo}
              onChange={F("valorFixoAcordo")}
              placeholder={form.valorMensal ? `Sugerido: R$ ${Number(form.valorMensal).toLocaleString("pt-BR")}` : "Ex.: 3.000,00"}
            />
            {calc && calc.isAcordoInterno && (
              <div style={{background:`${C.yellow}20`,borderRadius:8,padding:"10px 14px"}}>
                <p style={{fontSize:13,color:C.yellow,fontWeight:900}}>
                  {fmt(Number(form.valorFixoAcordo||form.valorMensal||0))} x {calc.mesesAtivos.toFixed(2)} meses = {fmt(calc.totalBruto)}
                </p>
                <p style={{fontSize:11,color:C.subtle,marginTop:3}}>
                  ({calc.totalMeses} meses completos + {calc.diasResto} dias = {calc.mesesAtivos.toFixed(4)} meses)
                </p>
              </div>
            )}
          </div>
        )}

        {form.admissao && form.demissao && calc && (
          <div style={{background:`${C.yellow}12`,border:`1px solid ${C.yellow}33`,padding:"10px 14px",borderRadius:8}}>
            <p style={{fontSize:12,color:C.yellow,fontWeight:700}}>
               {calc.anos > 0 ? `${calc.anos} ano(s), ` : ""}{calc.totalMeses % 12} mês(es) e {calc.diasResto} dia(s) de serviço
               <span style={{color:C.subtle}}>{calc.avos13} avo(s) para 13º e férias</span>
            </p>
          </div>
        )}
      </div>

      {/* Verbas rescisórias - ocultar no acordo interno */}
      {form.tipo !== "acordo_interno" && (
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.green}`,padding:14,borderRadius:10,display:"flex",flexDirection:"column",gap:10}}>
        <p style={{fontSize:11,fontWeight:900,color:C.green,textTransform:"uppercase",letterSpacing:.8}}> Verbas rescisórias</p>
        {[
          ["incluirSaldo",  "Saldo de salário",              true],
          ["incluir13",     "13º salário proporcional",      true],
          ["incluirFerias", "Férias proporcionais + 1/3",    true],
          ["incluirAviso",  "Aviso prévio (30 dias)",        false],
        ].map(([key, label, def]) => (
          <label key={key} style={{display:"flex",alignItems:"center",gap:10,cursor:"pointer",padding:"8px 10px",background:form[key]?`${C.green}0d`:"transparent",borderRadius:8,border:`1px solid ${form[key]?C.green+"33":C.line}`}}>
            <div onClick={()=>F(key)(!form[key])} style={{width:20,height:20,border:`2px solid ${form[key]?C.green:C.muted}`,background:form[key]?C.green:"transparent",borderRadius:5,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,cursor:"pointer"}}>
              {form[key] && <span style={{color:C.ink,fontSize:13,fontWeight:900,lineHeight:1}}>ok</span>}
            </div>
            <div style={{flex:1}}>
              <p style={{fontSize:13,fontWeight:700,color:form[key]?C.text:C.muted}}>{label}</p>
              {calc && form[key] && (
                <p style={{fontSize:11,color:C.green,marginTop:1}}>
                  {key==="incluirSaldo"  && `${form.diasNoMes||0} dias x R$ ${Number((Number(form.valorMensal||0)/30)).toFixed(2)} = ${fmt(calc.saldoSalario)}`}
                  {key==="incluir13"     && `${calc.avos13}/12 x ${fmt(Number(form.valorMensal||0))} = ${fmt(calc.dec13)}`}
                  {key==="incluirFerias" && `${calc.avosFerias}/12 x ${fmt(Number(form.valorMensal||0))} x 4/3 = ${fmt(calc.feriasTotal)}`}
                  {key==="incluirAviso"  && (form.tipo==="sem_justa_causa"||form.tipo==="acordo_mutuo") && `${fmt(calc.avisoPrevio)}`}
                  {key==="incluirAviso"  && form.tipo!=="sem_justa_causa" && form.tipo!=="acordo_mutuo" && <span style={{color:C.red}}>não aplicável neste tipo de rescisão</span>}
                </p>
              )}
            </div>
          </label>
        ))}
      </div>
      )} {/* fim {form.tipo !== "acordo_interno"} */}

      {/* Descontos */}
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderTop:`3px solid ${C.red}`,padding:14,borderRadius:10,display:"flex",flexDirection:"column",gap:10}}>
        <p style={{fontSize:11,fontWeight:900,color:C.red,textTransform:"uppercase",letterSpacing:.8}}> Descontos</p>
        <div style={{display:"grid",gridTemplateColumns:formGrid(2),gap:10}}>
          <Inp label="Adiantamentos (R$)" type="number" value={form.descAdiantamento} onChange={F("descAdiantamento")} placeholder="0,00"/>
          <Inp label="Outros descontos (R$)" type="number" value={form.descOutros} onChange={F("descOutros")} placeholder="0,00"/>
        </div>
        {Number(form.descOutros||0)>0 && <Inp label="Descrição dos outros descontos" value={form.obsDesc} onChange={F("obsDesc")} placeholder="Ex.: materiais, equipamentos..."/>}
      </div>

      {/* Resultado */}
      {calc ? (
        <div style={{background:`linear-gradient(135deg,${C.yellow} 0%,${C.yellowD} 60%,#4a3c0a 100%)`,color:C.ink,padding:"18px 20px",borderRadius:12,border:`1px solid ${C.yellow}`}}>
          <p style={{fontSize:11,fontWeight:900,letterSpacing:1.2,textTransform:"uppercase",opacity:.75}}>Total líquido a receber</p>
          <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:"clamp(26px,11vw,48px)",letterSpacing:1,lineHeight:.95}}>{fmt(calc.totalLiquido)}</p>
          <p style={{fontSize:12,fontWeight:700,marginTop:6,opacity:.85}}>{valorPorExtenso(calc.totalLiquido)}</p>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginTop:14}}>
            {[
              ["Vencimentos",fmt(calc.totalBruto)],
              ["Descontos",  fmt(calc.totalDesc)],
              ["Líquido",    fmt(calc.totalLiquido)],
            ].map(([l,v])=>(
              <div key={l} style={{background:"rgba(0,0,0,.15)",padding:"8px 10px",borderRadius:8}}>
                <p style={{fontSize:9,fontWeight:900,textTransform:"uppercase",opacity:.7}}>{l}</p>
                <p style={{fontWeight:900,fontSize:15}}>{v}</p>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:20,textAlign:"center",color:C.muted,borderRadius:10}}>
          Preencha nome, datas e valor mensal para calcular.
        </div>
      )}

      {/* Observações e ações */}
      <Inp label="Observações (aparece no documento)" value={form.obs} onChange={F("obs")} multiline placeholder="Informações adicionais, acordos, pendências..."/>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
        <Btn v="ghost" onClick={()=>setForm(emptyForm)} full><Ic n="x"/> Limpar</Btn>
        <Btn v="danger" onClick={gerarPDF} full disabled={!calc}><Ic n="file"/> Gerar PDF</Btn>
      </div>
      <Btn onClick={salvar} full disabled={!calc}><Ic n="check"/> Salvar no histórico</Btn>

      {/* Histórico */}
      <button onClick={()=>setHistory(h=>!h)} style={{background:"transparent",border:`1px solid ${C.border}`,color:C.muted,padding:"10px 14px",cursor:"pointer",borderRadius:8,fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:14,textTransform:"uppercase",letterSpacing:.5,textAlign:"left"}}>
        {history?" Ocultar":" Ver"} histórico de rescisões ({rescisoes.length})
      </button>

      {history && rescisoes.length === 0 && (
        <div style={{background:C.card,border:`1px solid ${C.border}`,padding:16,textAlign:"center",color:C.muted,borderRadius:10}}>
          Nenhuma rescisão salva ainda.
        </div>
      )}

      {history && rescisoes.map(r => (
        <div key={r.id} style={{background:C.card,border:`1px solid ${C.border}`,borderLeft:`4px solid ${C.red}`,padding:"12px 16px",borderRadius:10}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
            <div>
              <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:900,fontSize:17}}>{r.empName}</p>
              <p style={{fontSize:11,color:C.muted,marginTop:2}}>
                {r.empFuncao&&`${r.empFuncao}  `}{r.obraName&&`${r.obraName}  `}
                {fmtDateFull(r.admissao)} → {fmtDateFull(r.demissao)}
              </p>
              <p style={{fontSize:11,color:C.subtle,marginTop:2}}>{TIPO_LABEL[r.tipo]||r.tipo}</p>
            </div>
            <div style={{textAlign:"right",flexShrink:0}}>
              <p style={{fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800,fontSize:22,color:C.yellow,letterSpacing:.5}}>{fmt(r.totalLiquido)}</p>
              <p style={{fontSize:10,color:C.muted}}>{new Date(r.createdAt).toLocaleDateString("pt-BR")}</p>
            </div>
          </div>
          <div style={{display:"flex",gap:6,marginTop:10}}>
            <Btn size="sm" v="ghost" onClick={()=>{setForm({...r});setHistory(false);}}>
              <Ic n="edit"/> Reabrir
            </Btn>
            <Btn size="sm" v="danger" onClick={()=>gerarPDF(r)}>
              <Ic n="file"/> PDF
            </Btn>
            <Btn size="sm" v="danger" onClick={()=>{
              if(!window.confirm("Remover esta rescisão do histórico?")) return;
              update({...data,rescisoes:(data.rescisoes||[]).filter(rc=>rc.id!==r.id)});
              showToast("Removida.");
            }}><Ic n="trash"/></Btn>
          </div>
        </div>
      ))}
    </div>
  );
}

// 
// Configurações
// 

function Config({ data, update, showToast, currentUser, onLogout }) {
  const { formGrid } = useBreakpoint();
  const [form, setForm] = useState(data.config);
  const [holidayYear, setHolidayYear] = useState(new Date().getFullYear());
  const setField = key => value => setForm(f => ({ ...f, [key]: value }));
  const holidays = getPayrollHolidays(data, holidayYear);

  const saveConfig = () => {
    update({ ...data, config: { ...data.config, ...form } });
    showToast("Configurações salvas.");
  };


  const exportBackup = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `arcd-obras-backup-${today()}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    showToast("Backup exportado.");
  };

  return (
    <div className="anim" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div>
        <h2 style={{ fontFamily:"'Inter Display','Inter',sans-serif",fontWeight:800, fontSize: 30, letterSpacing: 2, color: C.yellow }}>Configurações</h2>
        <p style={{ color: C.muted, fontSize: 13 }}>Dados da empresa, tributação, calendário e segurança.</p>
      </div>

      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, textTransform: "uppercase", marginBottom: 10 }}>Empresa</h3>
        <div style={{ display: "grid", gridTemplateColumns:formGrid(2), gap: 10 }}>
          <Inp label="Empresa" value={form.companyName} onChange={setField("companyName")} />
          <Inp label="Produto" value={form.productName} onChange={setField("productName")} />
          <CampoCNPJ value={form.cnpj} onChange={setField("cnpj")} onEncontrado={d=>setForm(f=>({...f, companyName: f.companyName||d.razaoSocial||d.nome }))}/>
          <Inp label="Responsável RH" value={form.hrName} onChange={setField("hrName")} />
          <Inp label="E-mail RH" value={form.hrEmail} onChange={setField("hrEmail")} />
          <Inp label="WhatsApp RH (c/ DDI)" value={form.hrPhone} onChange={setField("hrPhone")} placeholder="5581999990000" />
        </div>
        <div style={{ marginTop: 12 }}><Btn onClick={saveConfig}><Ic n="check" /> Salvar configurações</Btn></div>
      </div>

      {/* DRE - Alíquotas e tributação */}
      <div style={{ background:C.card, border:`1px solid ${C.border}`, borderRadius:8, padding:14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", fontWeight:700, color:C.yellow, textTransform:"uppercase", letterSpacing:.5, marginBottom:4, fontSize:13 }}>DRE - Tributação</h3>
        <p style={{ fontSize:11, color:C.muted, marginBottom:12 }}>Configure as alíquotas para o cálculo automático do DRE da empresa.</p>
        <div style={{ display:"grid", gridTemplateColumns:formGrid(2), gap:10 }}>
          <Inp label="ISS (%)" type="number" value={String(form.aliquotaISS||"")} onChange={v=>setField("aliquotaISS")(v)} placeholder="Ex.: 5"/>
          <Inp label="PIS (%)" type="number" value={String(form.aliquotaPIS||"")} onChange={v=>setField("aliquotaPIS")(v)} placeholder="Ex.: 0.65"/>
          <Inp label="COFINS (%)" type="number" value={String(form.aliquotaCOFINS||"")} onChange={v=>setField("aliquotaCOFINS")(v)} placeholder="Ex.: 3"/>
          <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,padding:"8px 12px",display:"flex",alignItems:"center"}}>
            <p style={{fontSize:11,color:C.muted}}>Simples Nacional: use ISS apenas (alíquota efetiva total)</p>
          </div>
          <Inp label="IR - Alíquota estimada (%)" type="number" value={String(form.aliquotaIR||"")} onChange={v=>setField("aliquotaIR")(v)} placeholder="Ex.: 15"/>
          <Inp label="CSLL - Alíquota estimada (%)" type="number" value={String(form.aliquotaCSLL||"")} onChange={v=>setField("aliquotaCSLL")(v)} placeholder="Ex.: 9"/>
        </div>
        {(Number(form.aliquotaISS||0)+Number(form.aliquotaPIS||0)+Number(form.aliquotaCOFINS||0))>0&&(
          <div style={{marginTop:10,background:`${C.yellow}10`,border:`1px solid ${C.yellow}33`,borderRadius:6,padding:"8px 12px"}}>
            <p style={{fontSize:11,color:C.text}}>
              Carga sobre faturamento: <strong style={{color:C.yellow}}>{(Number(form.aliquotaISS||0)+Number(form.aliquotaPIS||0)+Number(form.aliquotaCOFINS||0)).toFixed(2)}%</strong>
              {(Number(form.aliquotaIR||0)+Number(form.aliquotaCSLL||0))>0&&<>  Provisão IR+CSLL: <strong style={{color:C.yellow}}>{(Number(form.aliquotaIR||0)+Number(form.aliquotaCSLL||0)).toFixed(1)}%</strong></>}
            </p>
          </div>
        )}
        <div style={{marginTop:10}}><Btn onClick={saveConfig}><Ic n="check"/> Salvar alíquotas</Btn></div>
      </div>


      <div style={{ background: C.card, border: `1px solid ${C.border}`, padding: 14 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color: C.yellow, textTransform: "uppercase", marginBottom: 10 }}>Feriados considerados</h3>
        <Sel value={String(holidayYear)} onChange={v => setHolidayYear(Number(v))} options={Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - 1 + i).map(y => ({ v: String(y), l: String(y) }))} />
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(130px, 1fr))", gap: 6, marginTop: 10 }}>
          {holidays.map(h => <Badge key={h} color={C.blue}>{fmtDateFull(h)}</Badge>)}
        </div>
      </div>

      <div style={{ background:C.card, border:`1px solid ${C.border}`, padding:14, borderRadius:8 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color:C.yellow, textTransform:"uppercase", marginBottom:10, fontSize:13, fontWeight:700 }}>Backup</h3>
        <Btn v="ghost" onClick={exportBackup}><Ic n="download"/> Exportar backup JSON</Btn>
      </div>

      {/* Gestão de usuários */}
      <div style={{ background:C.card, border:`1px solid ${C.border}`, padding:14, borderRadius:8 }}>
        <h3 style={{ fontFamily:"'Inter Display','Inter',sans-serif", color:C.yellow, textTransform:"uppercase", marginBottom:12, fontSize:13, fontWeight:700 }}>Usuários e Permissões</h3>
        <GestaoUsuarios data={data} update={update} showToast={showToast} currentUser={currentUser}/>
      </div>

      {/* Logout */}
      <div style={{ background:C.surface, border:`1.5px solid ${C.border}`, padding:14, borderRadius:8 }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
          <div>
            <p style={{ fontWeight:700, fontSize:14, color:C.text }}>{currentUser?.nome||"-"}</p>
            <p style={{ fontSize:11, color:C.muted, marginTop:2 }}>{ROLES.find(r=>r.v===currentUser?.role)?.l||"-"}</p>
          </div>
          <Btn v="danger" size="sm" onClick={onLogout}>Sair</Btn>
        </div>
      </div>
    </div>
  );
}

